   ============================================================
   HERO SECTION — Phase 2
   ============================================================
   ============================================================ */

/* ----- Hero Container ----- */
.hero {
    min-height: 100vh;
    display: flex;
    align-items: center;
    padding: calc(var(--top-bar-height) + var(--nav-height) + 40px) 0 60px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

.hero__inner {
    display: flex;
    align-items: center;
    gap: 60px;
    width: 100%;
    position: relative;
    z-index: 2;
}

/* ----- Left Column ----- */
.hero__content {
    flex: 1 1 50%;
    display: flex;
    flex-direction: column;
    gap: 28px;
    animation: fadeUp 0.8s ease forwards;
}

/* Premium Badge — Always active with lime border + shadow */
.hero__badge {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 6px 20px 6px 16px;
    background: var(--color-off-white);
    border: 1px solid var(--color-lime);
    border-radius: 50px;
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    box-shadow: 0 4px 16px rgba(129, 199, 82, 0.2);
    width: fit-content;
    transition: var(--transition-smooth);
}

/* Optional: subtle hover if you want any interaction */
.hero__badge:hover {
    border-color: var(--color-lime-dark);
    box-shadow: 0 4px 20px rgba(129, 199, 82, 0.35);
}

/* Headline */
.hero__title {
    font-size: 3.8rem;
    font-weight: var(--font-weight-bold);
    line-height: 1.1;
    letter-spacing: -0.03em;
    color: var(--color-charcoal);
    max-width: 15ch;
}

.hero__title .XoHubSolutions-HighlightGreen,
.hero__title .highlight-lime {
    position: relative;
    display: inline-block;
}

.hero__title .XoHubSolutions-HighlightGreen::after,
.hero__title .highlight-lime::after {
    content: '';
    position: absolute;
    bottom: 4px;
    left: 0;
    width: 100%;
    height: 10px;
    background: rgba(129, 199, 82, 0.25);
    border-radius: 4px;
    z-index: -1;
}

/* Description */
.hero__description {
    font-size: 1.1rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    max-width: 46ch;
}

/* CTA Group */
.hero__cta-group {
    display: flex;
    align-items: center;
    gap: 16px;
    flex-wrap: wrap;
    margin-top: 4px;
}

.btn-large {
    padding: 14px 36px;
    font-size: 0.95rem;
    border-radius: 50px;
}

.btn-secondary {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 14px 32px;
    background: transparent;
    color: var(--color-charcoal);
    font-family: var(--font-primary);
    font-size: 0.95rem;
    font-weight: var(--font-weight-medium);
    border: 1.5px solid var(--color-gray-light);
    border-radius: 50px;
    cursor: pointer;
    transition: var(--transition-smooth);
}

.btn-secondary:hover {
    border-color: var(--color-purple);
    color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(124, 80, 204, 0.08);
}

.btn-secondary i {
    font-size: 0.7rem;
    transition: var(--transition-smooth);
}

.btn-secondary:hover i {
    transform: translateX(4px);
}

/* Trust Section */
.hero__trust {
    display: flex;
    align-items: center;
    gap: 16px;
    padding-top: 8px;
}

.trust-avatars {
    display: flex;
    align-items: center;
}

.avatar {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-white);
    border: 2px solid var(--color-white);
    margin-right: -10px;
    box-shadow: var(--shadow-soft);
    transition: var(--transition-smooth);
    cursor: help;
}

.avatar:hover {
    transform: translateY(-3px) scale(1.05);
    z-index: 10;
    box-shadow: 0 6px 20px rgba(26, 26, 46, 0.15);
}

.avatar:last-child {
    margin-right: 0;
}

.trust-text {
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.5;
}

.trust-text strong {
    color: var(--color-purple);
    font-weight: var(--font-weight-bold);
}

/* ============================================================
   Right Column — Premium Visual
   ============================================================ */
.hero__visual {
    flex: 1 1 50%;
    position: relative;
    min-height: 480px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Glow Orbs */
.visual-glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(80px);
    opacity: 0.3;
    pointer-events: none;
}

.visual-glow--purple {
    width: 400px;
    height: 400px;
    background: var(--color-purple);
    top: -60px;
    right: -80px;
    animation: pulseGlow 6s ease-in-out infinite alternate;
}

.visual-glow--lime {
    width: 300px;
    height: 300px;
    background: var(--color-lime);
    bottom: -40px;
    left: -60px;
    animation: pulseGlow 8s ease-in-out infinite alternate-reverse;
}

/* ----- Orbit Network ----- */
.orbit-container {
    position: relative;
    width: 340px;
    height: 340px;
    transition: transform 0.1s ease-out;
}

.orbit-circle {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border: 1px solid rgba(124, 58, 237, 0.15);
    border-radius: 50%;
}

.orbit-circle--1 {
    width: 280px;
    height: 280px;
    animation: orbitSpin 20s linear infinite;
}

.orbit-circle--2 {
    width: 200px;
    height: 200px;
    animation: orbitSpin 14s linear infinite reverse;
}

/* Orbit Nodes */
.orbit-node {
    position: absolute;
    width: 14px;
    height: 14px;
    background: var(--color-purple);
    border-radius: 50%;
    box-shadow: 0 0 20px rgba(124, 58, 237, 0.3);
    animation: nodePulse 2.5s ease-in-out infinite;
}

.orbit-node--1 {
    top: 10%;
    left: 50%;
    transform: translateX(-50%);
    animation-delay: 0s;
}

.orbit-node--2 {
    bottom: 10%;
    right: 15%;
    animation-delay: 0.6s;
}

.orbit-node--3 {
    top: 30%;
    left: 8%;
    animation-delay: 1.2s;
}

.orbit-node--4 {
    bottom: 30%;
    right: 8%;
    animation-delay: 1.8s;
}

.orbit-center-glow {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 40px;
    height: 40px;
    background: radial-gradient(circle, var(--color-lime) 0%, transparent 70%);
    border-radius: 50%;
    opacity: 0.4;
    animation: pulseGlow 3s ease-in-out infinite;
}

/* ----- Floating Glassmorphism Cards — FIXED: refined positioning ----- */
.floating-card {
    position: absolute;
    background: rgba(255, 255, 255, 0.75);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: 16px;
    padding: 16px 20px;
    box-shadow: var(--shadow-card);
    display: flex;
    align-items: center;
    gap: 14px;
    transition: var(--transition-smooth);
    min-width: 140px;
    animation: floatCard 4s ease-in-out infinite;
    z-index: 5;
}

.floating-card:hover {
    transform: translateY(-6px) scale(1.02) !important;
    box-shadow: var(--shadow-card-hover);
    border-color: var(--color-purple-light);
}

.floating-card .card-icon {
    width: 40px;
    height: 40px;
    border-radius: 12px;
    background: rgba(124, 58, 237, 0.08);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.floating-card .card-content h4 {
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.floating-card .card-content p {
    font-size: 0.68rem;
    color: var(--color-gray-mid);
    margin: 0;
}

/* Individual card positions — FIXED: better alignment */
.floating-card--1 {
    top: 5%;
    right: 2%;
    animation-delay: 0s;
}

.floating-card--2 {
    bottom: 15%;
    left: -4%;
    animation-delay: 1.2s;
}

.floating-card--3 {
    bottom: 2%;
    right: 15%;
    animation-delay: 2.4s;
}

.floating-card--4 {
    top: 22%;
    left: -2%;
    animation-delay: 0.6s;
}

/* ----- Circuit Lines (decorative) ----- */
.circuit-lines {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    background-image:
        linear-gradient(45deg, transparent 65%, rgba(192, 227, 74, 0.04) 70%, transparent 75%),
        linear-gradient(-45deg, transparent 65%, rgba(124, 58, 237, 0.04) 70%, transparent 75%),
        linear-gradient(90deg, transparent 80%, rgba(192, 227, 74, 0.03) 85%, transparent 90%),
        linear-gradient(180deg, transparent 80%, rgba(124, 58, 237, 0.03) 85%, transparent 90%);
    background-size: 60px 60px;
    opacity: 0.5;
}

