/* ============================================================
   ANIMATIONS
   ============================================================ */

/* Fade Up */
@keyframes fadeUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Float Cards */
@keyframes floatCard {

    0%,
    100% {
        transform: translateY(0px);
    }

    50% {
        transform: translateY(-10px);
    }
}

/* Orbit Spin */
@keyframes orbitSpin {
    from {
        transform: translate(-50%, -50%) rotate(0deg);
    }

    to {
        transform: translate(-50%, -50%) rotate(360deg);
    }
}

/* Node Pulse */
@keyframes nodePulse {

    0%,
    100% {
        transform: scale(1);
        opacity: 0.6;
    }

    50% {
        transform: scale(1.6);
        opacity: 1;
    }
}

/* Glow Pulse */
@keyframes pulseGlow {
    0% {
        opacity: 0.2;
        transform: scale(1);
    }

    100% {
        opacity: 0.4;
        transform: scale(1.1);
    }
}

/* ============================================================
   FOCUS STATES — Accessibility
   ============================================================ */
a:focus-visible,
button:focus-visible,
input:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 2px;
}

/* ============================================================
   UTILITY HELPERS
   ============================================================ */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    border: 0;
}


