/* ----- Network Container ----- */
.network-container {
    position: relative;
    width: 380px;
    height: 380px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Orbiting rings */
.network-ring {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border-radius: 50%;
    border: 1px solid rgba(124, 58, 237, 0.08);
}

.network-ring--1 {
    width: 320px;
    height: 320px;
    animation: orbitSpin 25s linear infinite;
    border-color: rgba(124, 58, 237, 0.06);
}

.network-ring--2 {
    width: 240px;
    height: 240px;
    animation: orbitSpin 18s linear infinite reverse;
    border-color: rgba(192, 227, 74, 0.08);
}

.network-ring--3 {
    width: 160px;
    height: 160px;
    animation: orbitSpin 12s linear infinite;
    border-color: rgba(124, 58, 237, 0.04);
    border-width: 1px;
}

/* ----- Network Center ----- */
