    top: 5%;
    right: 5%;
    animation-delay: 0s;
}

.network-node--2 {
    bottom: 5%;
    right: 20%;
    animation-delay: 0.6s;
}

.network-node--3 {
    bottom: 30%;
    left: 0%;
    animation-delay: 1.2s;
}

.network-node--4 {
    top: 20%;
    left: 2%;
    animation-delay: 1.8s;
}

.network-node--5 {
    top: 40%;
    right: 0%;
    animation-delay: 2.4s;
}

.network-node--6 {
    bottom: 10%;
    left: 25%;
    animation-delay: 3s;
}

/* Network lines SVG */
.network-lines {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1;
