    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 16px;
}

.cta-section__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.cta-section__title {
    font-size: 3rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 16px;
}

.cta-section__description {
    font-size: 1.1rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    margin-bottom: 28px;
    max-width: 48ch;
}

/* ----- Benefits ----- */
.cta-section__benefits {
    list-style: none;
    padding: 0;
    margin: 0 0 32px 0;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.cta-section__benefits li {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 0.95rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.benefit-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--color-lime);
    font-size: 1.1rem;
    flex-shrink: 0;
}

.benefit-text {
    line-height: 1.4;
}

/* ----- Buttons ----- */
.cta-section__buttons {
    display: flex;
    align-items: center;
    gap: 16px;
    flex-wrap: wrap;
}

.btn-cta-primary {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-cta-primary:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

.btn-cta-secondary {
    padding: 14px 32px;
    font-size: 0.95rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.btn-cta-secondary:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-3px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

.btn-cta-secondary i {
    transition: transform 0.3s ease;
}

.btn-cta-secondary:hover i {
    transform: translateX(4px);
}

/* ============================================================
   Right Column: Floating CTA Card
   ============================================================ */
.cta-section__card-wrapper {
    flex: 1 1 45%;
    display: flex;
    justify-content: flex-end;
}

.cta-card {
    position: relative;
    width: 100%;
    max-width: 440px;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: 24px;
    padding: 36px 32px 32px;
    box-shadow: 0 32px 80px rgba(26, 26, 46, 0.08), 0 8px 32px rgba(124, 58, 237, 0.04);
    transition: all 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    animation: floatCard 5s ease-in-out infinite;
}

.cta-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 40px 100px rgba(26, 26, 46, 0.12), 0 8px 32px rgba(124, 58, 237, 0.06);
}

/* Card glow effect */
.cta-card__glow {
    position: absolute;
    inset: -2px;
    border-radius: 24px;
    background: linear-gradient(135deg, rgba(192, 227, 74, 0.15), rgba(124, 58, 237, 0.10));
    z-index: -1;
    opacity: 0;
    transition: opacity 0.6s ease;
    pointer-events: none;
}

.cta-card:hover .cta-card__glow {
    opacity: 1;
}

/* ----- Card Header ----- */
.cta-card__header {
    text-align: center;
    margin-bottom: 24px;
}

.cta-card__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    border-radius: 16px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    color: var(--color-white);
    font-size: 1.4rem;
    margin-bottom: 16px;
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.2);
}

.cta-card__title {
    font-size: 1.3rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin-bottom: 8px;
}

.cta-card__description {
    font-size: 0.9rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0;
}

/* ----- Card Features ----- */
.cta-card__features {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin-bottom: 24px;
    padding: 20px 0;
    border-top: 1px solid var(--color-gray-light);
    border-bottom: 1px solid var(--color-gray-light);
}

.cta-card__feature {
    display: flex;
    align-items: center;
    gap: 12px;
}

.feature-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 10px;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-size: 0.85rem;
    flex-shrink: 0;
    transition: all 0.3s ease;
}

.cta-card__feature:hover .feature-icon {
    background: var(--color-purple);
    color: var(--color-white);
    transform: scale(1.05);
}

.feature-info {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.feature-label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.feature-value {
    font-size: 0.8rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

/* ----- Card Button ----- */
.cta-card__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    width: 100%;
    padding: 14px 28px;
    background: var(--color-purple);
    color: var(--color-white);
    font-family: var(--font-primary);
    font-size: 0.9rem;
    font-weight: var(--font-weight-semibold);
    border-radius: 50px;
    border: none;
    cursor: pointer;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    text-decoration: none;
    box-shadow: 0 4px 20px rgba(124, 58, 237, 0.25);
}

.cta-card__button:hover {
    background: var(--color-purple-dark);
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(124, 58, 237, 0.35);
}

.cta-card__button i {
    font-size: 0.7rem;
    transition: transform 0.3s ease;
}

.cta-card__button:hover i {
    transform: translateX(4px);
}

/* Focus states */
.cta-card__button:focus-visible,
.btn-cta-primary:focus-visible,
.btn-cta-secondary:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ============================================================
   KEYFRAMES — CTA Animations
   ============================================================ */
@keyframes floatOrb {

    0%,
    100% {
        transform: translateY(0px) scale(1);
    }

    50% {
        transform: translateY(-20px) scale(1.05);
    }
}

/* ============================================================
   PREMIUM FOOTER — Phase 13 (Final)
   ============================================================ */
.main-footer {
    position: relative;
    background: linear-gradient(180deg, #0F0E17, #1A1A2E, #16213E);
    color: rgba(255, 255, 255, 0.8);
    padding: 60px 0 0;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.footer__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.footer-bg__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(120px);
    opacity: 0.15;
    pointer-events: none;
}

.footer-bg__glow--1 {
    width: 500px;
    height: 500px;
    top: -200px;
    left: -100px;
    background: var(--color-purple);
    opacity: 0.10;
}

.footer-bg__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -150px;
    right: -50px;
    background: var(--color-lime);
    opacity: 0.08;
}

.footer-bg__glow--3 {
    width: 300px;
    height: 300px;
    top: 30%;
    right: 30%;
    background: var(--color-purple);
    opacity: 0.05;
}

.footer-bg__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.03);
    border: 1px solid rgba(124, 58, 237, 0.04);
}

.footer-bg__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 20%;
    animation: floatOrb 8s ease-in-out infinite;
}

.footer-bg__orb--2 {
    width: 150px;
    height: 150px;
    bottom: 20%;
    left: 15%;
    animation: floatOrb 10s ease-in-out infinite reverse;
}

.footer-bg__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.02);
    border: 1px solid rgba(192, 227, 74, 0.02);
}

.footer-bg__shape--1 {
    width: 180px;
    height: 180px;
    top: 15%;
    left: 40%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.footer-bg__shape--2 {
    width: 120px;
    height: 120px;
    bottom: 10%;
    right: 25%;
    border-radius: 70% 30% 30% 70% / 60% 40% 60% 40%;
}

.footer-bg__shape--3 {
    width: 80px;
    height: 80px;
    top: 45%;
    left: 10%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.footer-bg__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.3;
    pointer-events: none;
}

/* ----- Container ----- */
.footer__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   TOP FOOTER
   ============================================================ */
.footer__top {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr 1fr 1.5fr;
    gap: 32px 24px;
    padding-bottom: 40px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

/* ----- Brand Column ----- */
.footer__column--brand {
    grid-column: span 1;
}

.footer__logo {
    display: flex;
    align-items: center;
    gap: 10px;
    text-decoration: none;
    margin-bottom: 12px;
}

.footer__logo-image {
    width: 80%;
    height: 80%;
    border-radius: 12px;
    flex-shrink: 0;
    display: block;
}

.footer__logo-text {
    font-size: 1.4rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-white);
    letter-spacing: -0.02em;
}

.footer__logo-highlight {
    color: var(--color-purple);
}

.footer__tagline {
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-lime);
    margin-bottom: 12px;
    letter-spacing: 0.02em;
}

.footer__description {
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: rgba(255, 255, 255, 0.6);
    line-height: 1.7;
    max-width: 32ch;
    margin: 0;
}

/* ----- Footer Columns ----- */
.footer__column-title {
    font-size: 0.85rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-white);
    margin: 0 0 14px 0;
    letter-spacing: 0.02em;
}

.footer__links {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.footer__links li a {
    font-size: 0.82rem;
    font-weight: var(--font-weight-regular);
    color: rgba(255, 255, 255, 0.6);
    text-decoration: none;
    transition: all 0.3s ease;
    position: relative;
    display: inline-block;
}

.footer__links li a::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 1.5px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    transition: width 0.3s ease;
}

.footer__links li a:hover {
    color: var(--color-white);
}

.footer__links li a:hover::after {
    width: 100%;
}

/* ----- Contact Column ----- */
.footer__contact-list {
    list-style: none;
    padding: 0;
    margin: 0 0 18px 0;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.footer__contact-list li {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    font-size: 0.82rem;
    font-weight: var(--font-weight-regular);
    color: rgba(255, 255, 255, 0.6);
    line-height: 1.5;
}

.footer__contact-list li a {
    color: rgba(255, 255, 255, 0.6);
    text-decoration: none;
    transition: color 0.3s ease;
}

.footer__contact-list li a:hover {
    color: var(--color-lime);
}

.contact-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    color: var(--color-lime);
    font-size: 0.75rem;
    flex-shrink: 0;
    margin-top: 2px;
}

/* ----- Social Icons ----- */
.footer__social {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 4px;
}

.social-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.06);
    color: rgba(255, 255, 255, 0.6);
    font-size: 0.85rem;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    text-decoration: none;
}

.social-link:hover {
    transform: translateY(-4px) scale(1.05);
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.3);
}

.social-link:nth-child(1):hover {
    background: #1877F2;
    border-color: #1877F2;
}

.social-link:nth-child(2):hover {
    background: #E4405F;
    border-color: #E4405F;
}

.social-link:nth-child(3):hover {
    background: #0A66C2;
    border-color: #0A66C2;
}

.social-link:nth-child(4):hover {
    background: #181717;
    border-color: #181717;
}

.social-link:nth-child(5):hover {
    background: #FF0000;
    border-color: #FF0000;
}

.social-link:nth-child(6):hover {
    background: #000000;
    border-color: #000000;
}

.social-link:nth-child(7):hover {
    background: #1769FF;
    border-color: #1769FF;
}

.social-link:nth-child(8):hover {
    background: #EA4C89;
    border-color: #EA4C89;
}

/* ============================================================
   NEWSLETTER & TRUST BADGES
   ============================================================ */
.footer__newsletter {
    padding: 40px 0 32px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.newsletter__content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 32px;
    flex-wrap: wrap;
}

.newsletter__header {
    display: flex;
    align-items: center;
    gap: 16px;
    flex: 1;
    min-width: 280px;
}

.newsletter__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    border-radius: 14px;
    background: rgba(192, 227, 74, 0.1);
    color: var(--color-lime);
    font-size: 1.2rem;
    flex-shrink: 0;
}

.newsletter__title {
    font-size: 1.1rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-white);
    margin: 0 0 2px 0;
}

.newsletter__description {
    font-size: 0.82rem;
    font-weight: var(--font-weight-regular);
    color: rgba(255, 255, 255, 0.5);
    margin: 0;
    line-height: 1.5;
}

/* ----- Newsletter Form ----- */
.newsletter__form {
    flex: 1;
    min-width: 280px;
    max-width: 460px;
}

.newsletter__input-group {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 50px;
    padding: 4px 4px 4px 18px;
    transition: all 0.3s ease;
}

.newsletter__input-group:focus-within {
    border-color: var(--color-lime);
    box-shadow: 0 0 0 4px rgba(192, 227, 74, 0.06);
}

.newsletter__input {
    flex: 1;
    padding: 10px 0;
    background: transparent;
    border: none;
    outline: none;
    font-family: var(--font-primary);
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-white);
    min-width: 0;
}

.newsletter__input::placeholder {
    color: rgba(255, 255, 255, 0.3);
}

.newsletter__button {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 24px;
    background: var(--color-lime);
    color: var(--color-charcoal);
    font-family: var(--font-primary);
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    border: none;
    border-radius: 50px;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    white-space: nowrap;
    flex-shrink: 0;
}

.newsletter__button:hover {
    background: var(--color-lime-dark);
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(192, 227, 74, 0.3);
}

.newsletter__button i {
    font-size: 0.65rem;
    transition: transform 0.3s ease;
}

.newsletter__button:hover i {
    transform: translateX(4px);
}

/* Form validation states */
.newsletter__error,
.newsletter__success {
    display: none;
    font-size: 0.75rem;
    margin-top: 8px;
    padding: 6px 12px;
    border-radius: 8px;
}

.newsletter__error {
    color: #F87171;
    background: rgba(248, 113, 113, 0.08);
}

.newsletter__success {
    color: #34D399;
    background: rgba(52, 211, 153, 0.08);
}

.newsletter__error.visible,
.newsletter__success.visible {
    display: block;
}

/* ----- Trust Badges ----- */
.footer__trust-badges {
    display: flex;
    flex-wrap: wrap;
    gap: 16px 32px;
    padding-top: 24px;
    margin-top: 24px;
    border-top: 1px solid rgba(255, 255, 255, 0.04);
}

.trust-badge {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: rgba(255, 255, 255, 0.5);
}

.trust-badge__icon {
    color: var(--color-lime);
    font-size: 0.85rem;
}

.trust-badge__text {
    color: rgba(255, 255, 255, 0.5);
}

/* ============================================================
   BOTTOM FOOTER
   ============================================================ */
.footer__bottom {
    background: rgba(0, 0, 0, 0.2);
    padding: 16px 0;
    margin-top: 0;
}

.footer__bottom-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
}

.footer__copyright p,
.footer__credit p {
    font-size: 0.75rem;
    font-weight: var(--font-weight-regular);
    color: rgba(255, 255, 255, 0.3);
    margin: 0;
}

.credit-heart {
    color: #EF4444;
    display: inline-block;
    animation: heartBeat 1.5s ease-in-out infinite;
}

.footer__bottom-links {
    display: flex;
    align-items: center;
    gap: 8px;
}

.footer__bottom-links a {
    font-size: 0.72rem;
    font-weight: var(--font-weight-regular);
    color: rgba(255, 255, 255, 0.25);
    text-decoration: none;
    transition: color 0.3s ease;
}

.footer__bottom-links a:hover {
    color: var(--color-lime);
}

.footer__bottom-divider {
    color: rgba(255, 255, 255, 0.1);
    font-size: 0.6rem;
}

/* ============================================================
   BACK TO TOP BUTTON
   ============================================================ */
.back-to-top {
    position: fixed;
    bottom: 30px;
    right: 30px;
    z-index: 999;
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: var(--color-lime);
    color: var(--color-charcoal);
    border: none;
    cursor: pointer;
    font-size: 1.1rem;
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.35);
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
    opacity: 0;
    visibility: hidden;
    transform: translateY(20px) scale(0.8);
    display: flex;
    align-items: center;
    justify-content: center;
}

.back-to-top.visible {
    opacity: 1;
    visibility: visible;
    transform: translateY(0) scale(1);
}

.back-to-top:hover {
    background: var(--color-lime-dark);
    transform: translateY(-4px) scale(1.05);
    box-shadow: 0 8px 32px rgba(192, 227, 74, 0.45);
}

.back-to-top:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ============================================================
   KEYFRAMES — Footer Animations
   ============================================================ */
@keyframes heartBeat {

    0%,
    100% {
        transform: scale(1);
    }

    50% {
        transform: scale(1.2);
    }
