}

/* ============================================================
   FEATURED FOUNDER CARD
   ============================================================ */
.founder-card {
    display: flex;
    align-items: center;
    gap: 48px;
    background: rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    padding: 40px 44px 40px 40px;
    box-shadow: var(--shadow-glass);
    margin-bottom: 52px;
    position: relative;
    overflow: hidden;
    transition: all 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.founder-card::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 24px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0.15;
    pointer-events: none;
}

.founder-card>* {
    position: relative;
    z-index: 2;
}

/* ----- Founder Visual ----- */
.founder-card__visual {
    flex-shrink: 0;
}

.founder-card__image-wrapper {
    position: relative;
    width: 180px;
    height: 180px;
}

.founder-card__image {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--color-purple), var(--color-purple-dark));
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.2);
}

.founder-card__initial {
    font-size: 4rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-white);
    letter-spacing: -0.02em;
}

.founder-card__glow-ring {
    position: absolute;
    inset: -8px;
    border-radius: 50%;
    border: 2px solid transparent;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple)) border-box;
    -webkit-mask: linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0);
    mask: linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    animation: spinRing 8s linear infinite;
}

/* Decorative floating shapes */
.founder-card__deco {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.1);
}

.founder-card__deco--1 {
    width: 30px;
    height: 30px;
    top: -10px;
    right: -10px;
    animation: floatOrb 4s ease-in-out infinite;
}

.founder-card__deco--2 {
    width: 20px;
    height: 20px;
    bottom: -5px;
    left: -5px;
    animation: floatOrb 5s ease-in-out infinite reverse;
}

.founder-card__deco--3 {
    width: 16px;
    height: 16px;
    top: 50%;
    right: -20px;
    animation: floatOrb 3s ease-in-out infinite 1s;
}

/* ----- Founder Content ----- */
.founder-card__content {
    flex: 1;
    min-width: 0;
}

.founder-card__header {
    margin-bottom: 12px;
}

.founder-card__name {
    font-size: 2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0;
    letter-spacing: -0.02em;
}

.founder-card__position {
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.founder-card__bio {
    font-size: 0.95rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    margin: 0 0 16px 0;
    max-width: 48ch;
}

/* Founder Tags */
.founder-card__tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 18px;
}

.founder-tag {
    padding: 4px 14px;
    background: rgba(124, 58, 237, 0.06);
    border: 1px solid rgba(124, 58, 237, 0.08);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    letter-spacing: 0.02em;
}

/* Founder Actions */
.founder-card__actions {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 16px;
}

.btn-founder {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
}

.btn-founder:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

.btn-founder-secondary {
    padding: 10px 28px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.btn-founder-secondary:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

.btn-founder-secondary i {
    transition: transform 0.3s ease;
}

.btn-founder-secondary:hover i {
    transform: translateX(4px);
}

/* Founder Social */
.founder-card__social {
    display: flex;
    gap: 8px;
}

.founder-card__social .social-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.5);
    border: 1px solid var(--color-gray-light);
    color: var(--color-gray-mid);
    font-size: 0.8rem;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    text-decoration: none;
}

.founder-card__social .social-link:hover {
    transform: translateY(-3px) scale(1.05);
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.2);
}

/* ============================================================
   LEADERSHIP GRID
   ============================================================ */
.leadership-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
    margin-bottom: 48px;
}

/* ----- Leader Card ----- */
.leader-card {
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    padding: 28px 24px 24px;
    text-align: center;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
}

.leader-card::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 20px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0;
    transition: opacity 0.5s ease;
    pointer-events: none;
}

.leader-card::after {
    content: '';
    position: absolute;
    inset: 1px;
    border-radius: 19px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    z-index: 1;
    transition: background 0.5s ease;
    pointer-events: none;
}

.leader-card:hover::before {
    opacity: 1;
}

.leader-card:hover::after {
    background: rgba(255, 255, 255, 0.8);
}

.leader-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.leader-card>* {
    position: relative;
    z-index: 3;
}

/* Leader Image */
.leader-card__image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    margin: 0 auto 14px;
    background: linear-gradient(135deg, var(--color-purple-light), var(--color-purple));
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.12);
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.leader-card:hover .leader-card__image {
    transform: scale(1.05);
    box-shadow: 0 12px 32px rgba(124, 58, 237, 0.2);
}

.leader-card__initial {
    font-size: 1.4rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-white);
    letter-spacing: -0.02em;
}

/* Alternate colors for variety */
.leader-card:nth-child(2) .leader-card__image {
    background: linear-gradient(135deg, var(--color-lime), var(--color-lime-dark));
}

.leader-card:nth-child(3) .leader-card__image {
    background: linear-gradient(135deg, #0EA5E9, #0284C7);
}

/* Leader Content */
.leader-card__name {
    font-size: 1rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0 0 2px 0;
}

.leader-card__position {
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    display: block;
    margin-bottom: 8px;
}

.leader-card__bio {
    font-size: 0.82rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0 0 14px 0;
}

/* Leader Social */
.leader-card__social {
    display: flex;
    justify-content: center;
    gap: 6px;
}

.leader-card__social .social-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.5);
    border: 1px solid var(--color-gray-light);
    color: var(--color-gray-mid);
    font-size: 0.7rem;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    text-decoration: none;
}

.leader-card__social .social-link:hover {
    transform: translateY(-3px) scale(1.05);
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.15);
}

/* ============================================================
   TEAM HIGHLIGHTS
   ============================================================ */
.team-highlights {
    text-align: center;
    margin-bottom: 48px;
    padding: 32px 0 28px;
    border-top: 1px solid var(--color-gray-light);
    border-bottom: 1px solid var(--color-gray-light);
}

.team-highlights__badge {
    display: inline-block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin-bottom: 16px;
    padding: 4px 16px;
    background: rgba(124, 58, 237, 0.06);
    border-radius: 50px;
}

.team-highlights__grid {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 10px 16px;
}

.highlight-badge {
    padding: 6px 18px;
    background: var(--color-off-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 50px;
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    cursor: default;
}

.highlight-badge:hover {
    transform: translateY(-3px) scale(1.02);
    border-color: var(--color-lime);
    box-shadow: 0 8px 24px rgba(192, 227, 74, 0.12);
    background: var(--color-white);
}

/* ============================================================
   CULTURE QUOTE
   ============================================================ */
.culture-quote {
    max-width: 720px;
    margin: 0 auto;
}

.culture-quote__card {
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    padding: 36px 40px 32px;
    text-align: center;
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
    transition: all 0.4s ease;
}

.culture-quote__card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.3;
}

.culture-quote__card:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.culture-quote__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    border-radius: 14px;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-size: 1.2rem;
    margin-bottom: 14px;
}

.culture-quote__text {
    font-size: 1.3rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.6;
    margin: 0 0 12px 0;
    font-style: italic;
}

.culture-quote__author {
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    font-style: normal;
}

/* ============================================================
   KEYFRAMES
   ============================================================ */
@keyframes spinRing {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

