/* ============================================================
   TIMELINE
   ============================================================ */
.timeline {
    position: relative;
    max-width: 1000px;
    margin: 0 auto;
    padding: 20px 0 40px;
}

/* ----- Central Line ----- */
.timeline__line {
    position: absolute;
    top: 40px;
    bottom: 40px;
    left: 50%;
    width: 3px;
    background: var(--color-gray-light);
    transform: translateX(-50%);
    border-radius: 4px;
    overflow: hidden;
    z-index: 1;
}

.timeline__line-fill {
    height: 0%;
    width: 100%;
    background: linear-gradient(180deg, var(--color-lime), var(--color-purple));
    border-radius: 4px;
    transition: height 1.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.timeline__line-fill.animated {
    height: 100%;
}

/* ----- Timeline Item ----- */
.timeline__item {
    position: relative;
    display: flex;
    align-items: center;
    margin-bottom: 48px;
    z-index: 2;
    opacity: 0;
    transform: translateY(30px);
    transition: opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94),
        transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.timeline__item.visible {
    opacity: 1;
    transform: translateY(0);
}

/* Left-aligned items */
.timeline__item--left {
    flex-direction: row;
    padding-right: calc(50% + 30px);
    text-align: right;
}

.timeline__item--left .timeline__card {
    margin-left: auto;
}

/* Right-aligned items */
.timeline__item--right {
    flex-direction: row-reverse;
    padding-left: calc(50% + 30px);
    text-align: left;
}

.timeline__item--right .timeline__card {
    margin-right: auto;
}

/* ----- Timeline Node ----- */
.timeline__node {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    flex-direction: column;
    align-items: center;
    z-index: 3;
    width: 60px;
}

.timeline__node-dot {
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: var(--color-white);
    border: 3px solid var(--color-gray-light);
    transition: all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
    position: relative;
    z-index: 2;
}

.timeline__item.visible .timeline__node-dot {
    border-color: var(--color-lime);
    background: var(--color-lime);
    box-shadow: 0 0 0 6px rgba(192, 227, 74, 0.15);
}

.timeline__node-glow {
    position: absolute;
    inset: -10px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(192, 227, 74, 0.1) 0%, transparent 70%);
    opacity: 0;
    transition: opacity 0.6s ease;
}

.timeline__item.visible .timeline__node-glow {
    opacity: 1;
    animation: pulseGlow 2.5s ease-in-out infinite;
}

.timeline__year {
    font-size: 0.65rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    margin-top: 6px;
    background: var(--color-white);
    padding: 2px 10px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    transition: all 0.4s ease;
}

.timeline__item.visible .timeline__year {
    border-color: var(--color-lime);
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.05);
}

/* ----- Timeline Card ----- */
.timeline__card {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    padding: 20px 24px 20px 20px;
    background: rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    max-width: 380px;
    position: relative;
    overflow: hidden;
}

.timeline__card::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 18px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0;
    transition: opacity 0.5s ease;
    pointer-events: none;
}

.timeline__card::after {
    content: '';
    position: absolute;
    inset: 1px;
    border-radius: 17px;
    background: rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    z-index: 1;
    transition: background 0.5s ease;
    pointer-events: none;
}

.timeline__card:hover::before {
    opacity: 1;
}

.timeline__card:hover::after {
    background: rgba(255, 255, 255, 0.85);
}

.timeline__card:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.timeline__card>* {
    position: relative;
    z-index: 3;
}

/* ----- Card Icon ----- */
.timeline__card-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    min-width: 44px;
    border-radius: 12px;
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
    font-size: 1.1rem;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.timeline__card:hover .timeline__card-icon {
    background: var(--color-purple);
    color: var(--color-white);
    transform: scale(1.05);
}

/* Alternate icon colors for variety */
.timeline__item:nth-child(1) .timeline__card:hover .timeline__card-icon {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

.timeline__item:nth-child(3) .timeline__card:hover .timeline__card-icon {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

.timeline__item:nth-child(5) .timeline__card:hover .timeline__card-icon {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

/* ----- Card Content ----- */
.timeline__card-content {
    flex: 1;
    min-width: 0;
}

.timeline__card-title {
    font-size: 0.98rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0 0 4px 0;
}

.timeline__card-description {
    font-size: 0.82rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0;
}

/* ============================================================
   TIMELINE PROGRESS
   ============================================================ */
.timeline__progress {
    margin-top: 40px;
    padding: 24px 32px 20px;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 16px;
    text-align: center;
    box-shadow: var(--shadow-glass);
}

.progress-label {
    display: block;
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.04em;
