}

.work-culture__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.work-culture__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.work-culture__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   SPLIT GRID
   ============================================================ */
.work-culture__grid {
    display: grid;
    grid-template-columns: 40fr 60fr;
    gap: 50px;
    align-items: stretch;
    margin-bottom: 48px;
}

/* ============================================================
   LEFT COLUMN — Premium Illustration
   ============================================================ */
.work-culture__visual {
    position: relative;
    min-height: 480px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 24px;
    border: 1px solid var(--color-gray-light);
    overflow: hidden;
    box-shadow: var(--shadow-glass);
}

/* Central Node */
.culture-visual__center {
    position: relative;
    width: 80px;
    height: 80px;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 4;
}

.culture-visual__center-glow {
    position: absolute;
    inset: -30px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(124, 58, 237, 0.08) 0%, transparent 70%);
    animation: pulseGlow 3s ease-in-out infinite;
}

.culture-visual__center-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--color-purple), var(--color-purple-dark));
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-white);
    font-size: 1.6rem;
    box-shadow: 0 8px 32px rgba(124, 58, 237, 0.25);
    z-index: 2;
}

/* Orbiting Rings */
.culture-visual__ring {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border-radius: 50%;
    border: 1px solid rgba(124, 58, 237, 0.06);
    pointer-events: none;
}

.culture-visual__ring--1 {
    width: 300px;
    height: 300px;
    animation: orbitSpin 22s linear infinite;
}

.culture-visual__ring--2 {
    width: 220px;
    height: 220px;
    animation: orbitSpin 16s linear infinite reverse;
    border-color: rgba(192, 227, 74, 0.06);
}

.culture-visual__ring--3 {
    width: 150px;
    height: 150px;
    animation: orbitSpin 10s linear infinite;
    border-color: rgba(124, 58, 237, 0.04);
}

/* Orbiting Nodes */
.culture-visual__node {
    position: absolute;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-purple);
    font-size: 1rem;
    box-shadow: 0 4px 16px rgba(26, 26, 46, 0.04);
    transition: all 0.4s ease;
    z-index: 5;
    animation: floatNode 4s ease-in-out infinite;
}

.culture-visual__node:hover {
    transform: scale(1.12);
    border-color: var(--color-lime);
    box-shadow: 0 8px 24px rgba(192, 227, 74, 0.12);
}

.culture-visual__node--1 {
    top: 8%;
    right: 5%;
    animation-delay: 0s;
    color: var(--color-lime-dark);
}

.culture-visual__node--2 {
    bottom: 10%;
    right: 20%;
    animation-delay: 0.8s;
    color: #0EA5E9;
}

.culture-visual__node--3 {
    bottom: 25%;
    left: 2%;
    animation-delay: 1.6s;
    color: #F59E0B;
}

.culture-visual__node--4 {
    top: 20%;
    left: 5%;
    animation-delay: 2.4s;
    color: #EF4444;
}

.culture-visual__node--5 {
    top: 40%;
    right: 2%;
    animation-delay: 3.2s;
    color: #EC4899;
}

.culture-visual__node--6 {
    bottom: 8%;
    left: 20%;
    animation-delay: 4s;
    color: #34D399;
}

/* Floating Glass Cards */
.culture-visual__float {
    position: absolute;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.25);
    border-radius: 12px;
    padding: 8px 14px;
    box-shadow: 0 8px 24px rgba(26, 26, 46, 0.04);
    display: flex;
    align-items: center;
    gap: 8px;
    z-index: 3;
    animation: floatCard 5s ease-in-out infinite;
}

.culture-visual__float .float-emoji {
    font-size: 0.9rem;
}

.culture-visual__float .float-label {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.culture-visual__float--1 {
    top: 6%;
    left: 6%;
    animation-delay: 0s;
}

.culture-visual__float--2 {
    bottom: 6%;
    right: 6%;
    animation-delay: 1.5s;
}

.culture-visual__float--3 {
    top: 30%;
    right: 4%;
    animation-delay: 0.8s;
}

.culture-visual__float--4 {
    bottom: 25%;
    left: 4%;
    animation-delay: 2.2s;
}

/* ============================================================
   RIGHT COLUMN — Content
   ============================================================ */
.work-culture__content {
    display: flex;
    flex-direction: column;
    gap: 28px;
}

/* ----- Introduction ----- */
.work-culture__intro {
    padding: 0 4px;
}

.work-culture__intro-title {
    font-size: 1.4rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 8px 0;
    letter-spacing: -0.02em;
}

.work-culture__intro-description {
    font-size: 0.95rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    margin: 0;
}

/* ----- Culture Cards Grid ----- */
.work-culture__cards {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}

/* ----- Culture Card ----- */
.culture-card {
    padding: 20px 18px 18px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 16px;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
}

.culture-card::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 16px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0;
    transition: opacity 0.5s ease;
    pointer-events: none;
}

.culture-card::after {
    content: '';
    position: absolute;
    inset: 1px;
    border-radius: 15px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    z-index: 1;
    transition: background 0.5s ease;
    pointer-events: none;
}

.culture-card:hover::before {
    opacity: 1;
}

.culture-card:hover::after {
    background: rgba(255, 255, 255, 0.85);
}

.culture-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.06);
}

.culture-card>* {
    position: relative;
    z-index: 3;
}

/* Card Icon */
.culture-card__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 10px;
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
    font-size: 1rem;
    margin-bottom: 10px;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.culture-card:hover .culture-card__icon {
    background: var(--color-purple);
    color: var(--color-white);
    transform: scale(1.05);
}

/* Alternate icon colors for variety */
.culture-card:nth-child(1):hover .culture-card__icon,
.culture-card:nth-child(3):hover .culture-card__icon,
.culture-card:nth-child(5):hover .culture-card__icon {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

/* Card Title */
.culture-card__title {
    font-size: 0.9rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0 0 4px 0;
}

/* Card Description */
.culture-card__description {
    font-size: 0.78rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.5;
    margin: 0;
}

/* ============================================================
   CULTURE QUOTE BANNER
   ============================================================ */
.culture-quote-banner {
    background: linear-gradient(135deg, rgba(124, 58, 237, 0.03), rgba(192, 227, 74, 0.03));
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    padding: 40px 48px 36px;
    text-align: center;
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
    transition: all 0.4s ease;
}

.culture-quote-banner::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 20px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0.08;
    pointer-events: none;
}

.culture-quote-banner>* {
    position: relative;
    z-index: 2;
}

.culture-quote-banner:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.culture-quote-banner__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    border-radius: 14px;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-size: 1.2rem;
    margin-bottom: 14px;
    transition: all 0.4s ease;
}

.culture-quote-banner:hover .culture-quote-banner__icon {
    background: var(--color-purple);
    color: var(--color-white);
    transform: scale(1.05);
}

.culture-quote-banner__text {
    font-size: 1.3rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.6;
    margin: 0 0 8px 0;
    font-style: italic;
}

.culture-quote-banner__author {
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    font-style: normal;
}

/* ============================================================
   KEYFRAMES — Additional Animations
   ============================================================ */
@keyframes floatNode {

    0%,
    100% {
        transform: translateY(0px) scale(1);
    }

    50% {
        transform: translateY(-8px) scale(1.05);
    }
}

/* ============================================================
