.highlight-item__text {
    font-size: 0.72rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
}

/* ============================================================
   RIGHT COLUMN — Premium Visual Composition
   ============================================================ */
.careers-hero__visual {
    flex: 1 1 45%;
    position: relative;
    min-height: 520px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ----- Main Dashboard Card ----- */
.careers-visual__dashboard {
    position: relative;
    width: 100%;
    max-width: 400px;
    background: rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: 24px;
    padding: 22px 24px 20px;
    box-shadow: 0 32px 80px rgba(26, 26, 46, 0.08);
    z-index: 5;
    transition: all 0.4s ease;
}

.careers-visual__dashboard:hover {
    transform: translateY(-4px);
    box-shadow: 0 40px 100px rgba(26, 26, 46, 0.12);
}

/* Dashboard Header */
.dashboard__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
}

.dashboard__dots {
    display: flex;
    gap: 5px;
}

.dashboard__dots .dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
}

.dashboard__dots .dot:nth-child(1) {
    background: #F87171;
}

.dashboard__dots .dot:nth-child(2) {
    background: #FBBF24;
}

.dashboard__dots .dot:nth-child(3) {
    background: #34D399;
}

.dashboard__title {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    letter-spacing: 0.03em;
}

/* Dashboard Stats */
.dashboard__stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 8px;
    margin-bottom: 14px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--color-gray-light);
}

.dash-stat {
    text-align: center;
}

.dash-stat__value {
    display: block;
    font-size: 1.1rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
}

.dash-stat__label {
    display: block;
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

/* Dashboard Progress */
.dashboard__progress {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 14px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--color-gray-light);
}

.progress-item {
    display: flex;
    align-items: center;
    gap: 8px;
}

.progress-label {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    min-width: 60px;
}

.progress-bar {
    flex: 1;
    height: 4px;
    background: var(--color-gray-light);
    border-radius: 4px;
    overflow: hidden;
}

.progress-fill {
    display: block;
    height: 100%;
    border-radius: 4px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
}

/* Dashboard Jobs */
.dashboard__jobs {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.job-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 6px 10px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 8px;
    border: 1px solid var(--color-gray-light);
    transition: all 0.3s ease;
}

.job-item:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.2);
    transform: translateX(4px);
}

.job-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #34D399;
    flex-shrink: 0;
}

.job-title {
    flex: 1;
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.job-tag {
    font-size: 0.5rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-lime-dark);
    padding: 2px 10px;
    border-radius: 50px;
    background: rgba(192, 227, 74, 0.08);
    border: 1px solid rgba(192, 227, 74, 0.1);
}

/* Dashboard Footer */
.dashboard__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 14px;
    border-top: 1px solid var(--color-gray-light);
}

.dash-apply {
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
}

.dash-status {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: #34D399;
    display: flex;
    align-items: center;
    gap: 6px;
}

.dash-status::before {
    content: '';
    display: inline-block;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #34D399;
    animation: pulseDot 2s ease-in-out infinite;
}

/* ----- Floating Code Window ----- */
.careers-visual__code {
    position: absolute;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, 0.25);
    border-radius: 14px;
    padding: 0;
    box-shadow: 0 16px 48px rgba(26, 26, 46, 0.06);
    z-index: 4;
    width: 200px;
    overflow: hidden;
    animation: floatCard 5s ease-in-out infinite;
    top: 5%;
    right: -8%;
}

.careers-visual__code .code-header {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 12px;
    background: rgba(0, 0, 0, 0.04);
    border-bottom: 1px solid var(--color-gray-light);
}

.careers-visual__code .code-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
}

.careers-visual__code .code-dot--1 {
    background: #F87171;
}

.careers-visual__code .code-dot--2 {
    background: #FBBF24;
}

.careers-visual__code .code-dot--3 {
    background: #34D399;
}

.careers-visual__code .code-title {
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin-left: 4px;
}

.careers-visual__code .code-body {
    padding: 10px 12px;
    display: flex;
    flex-direction: column;
    gap: 1px;
    font-family: 'Courier New', monospace;
}

.careers-visual__code .code-line {
    font-size: 0.55rem;
    color: var(--color-charcoal);
    line-height: 1.6;
    white-space: nowrap;
}

.careers-visual__code .code-keyword {
    color: var(--color-purple);
    font-weight: 600;
}

.careers-visual__code .code-var {
    color: #0EA5E9;
}

.careers-visual__code .code-string {
    color: var(--color-lime-dark);
}

.careers-visual__code .code-key {
    color: #F59E0B;
}

.careers-visual__code .code-indent {
    padding-left: 12px;
}

/* ----- Floating Node Cards ----- */
.careers-visual__node {
    position: absolute;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.25);
    border-radius: 14px;
    padding: 10px 16px;
    box-shadow: 0 12px 36px rgba(26, 26, 46, 0.04);
    display: flex;
    align-items: center;
    gap: 10px;
    z-index: 4;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
    animation: floatCard 4.5s ease-in-out infinite;
}

.careers-visual__node:hover {
    transform: translateY(-4px) scale(1.02);
    box-shadow: 0 20px 56px rgba(124, 58, 237, 0.06);
}

.careers-visual__node i {
    font-size: 0.9rem;
    color: var(--color-purple);
}

.careers-visual__node .node-label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.careers-visual__node--1 {
    bottom: 25%;
    left: -6%;
    animation-delay: 0.8s;
}

.careers-visual__node--1 i {
    color: #0EA5E9;
}

.careers-visual__node--2 {
    bottom: 5%;
    right: 12%;
    animation-delay: 2s;
}

.careers-visual__node--2 i {
    color: #EC4899;
}

.careers-visual__node--3 {
    top: 30%;
    left: -4%;
    animation-delay: 1.4s;
}

.careers-visual__node--3 i {
    color: #F59E0B;
}

/* ----- Center Pulse Orb ----- */
.careers-visual__orb {
    position: absolute;
    width: 120px;
    height: 120px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(124, 58, 237, 0.06) 0%, transparent 70%);
    animation: pulseGlow 3.5s ease-in-out infinite;
    z-index: 1;
    pointer-events: none;
}

/* ============================================================
   KEYFRAMES — Additional Animations
   ============================================================ */
@keyframes floatParticle {

    0%,
    100% {
        transform: translateY(0px) translateX(0px);
        opacity: 0.3;
    }

    50% {
        transform: translateY(-20px) translateX(10px);
        opacity: 0.8;
    }
}

