.join-visual__node--2 {
    bottom: 10%;
    right: 18%;
    animation-delay: 0.8s;
}
.join-visual__node--2 i { color: #EC4899; }

.join-visual__node--3 {
    bottom: 28%;
    left: 2%;
    animation-delay: 1.6s;
}
.join-visual__node--3 i { color: #F59E0B; }

.join-visual__node--4 {
    top: 22%;
    left: 4%;
    animation-delay: 2.4s;
}
.join-visual__node--4 i { color: #8B5CF6; }

.join-visual__node--5 {
