}

.join-visual__float .float-emoji {
    font-size: 0.9rem;
}

.join-visual__float .float-label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.join-visual__float--1 {
