    left: 8%;
    animation-delay: 0s;
}

.join-visual__float--2 {
    bottom: 8%;
    right: 8%;
    animation-delay: 1.5s;
}

.join-visual__float--3 {
    top: 35%;
    right: 5%;
    animation-delay: 0.8s;
}

/* ============================================================
   RIGHT COLUMN — Feature Cards
   ============================================================ */
.why-join__cards {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}

/* ----- Join Card ----- */
.join-card {
    padding: 20px 18px 18px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 16px;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
}

.join-card::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 16px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0;
    transition: opacity 0.5s ease;
    pointer-events: none;
}

.join-card::after {
    content: '';
    position: absolute;
    inset: 1px;
    border-radius: 15px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    z-index: 1;
    transition: background 0.5s ease;
    pointer-events: none;
}

.join-card:hover::before {
    opacity: 1;
}

.join-card:hover::after {
    background: rgba(255, 255, 255, 0.85);
}

.join-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.06);
}

.join-card > * {
    position: relative;
    z-index: 3;
}

/* Card Icon */
.join-card__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 10px;
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
    font-size: 1rem;
    margin-bottom: 10px;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.join-card:hover .join-card__icon {
    background: var(--color-purple);
    color: var(--color-white);
    transform: scale(1.05);
}

/* Alternate icon colors for variety */
.join-card:nth-child(1):hover .join-card__icon,
.join-card:nth-child(3):hover .join-card__icon,
.join-card:nth-child(5):hover .join-card__icon {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

/* Card Title */
.join-card__title {
    font-size: 0.9rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0 0 4px 0;
}

/* Card Description */
.join-card__description {
    font-size: 0.78rem;
