    z-index: 3;
}

/* ----- Card Header ----- */
.job-card__header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    margin-bottom: 10px;
    gap: 12px;
}

.job-card__title-group {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}

.job-card__title {
    font-size: 1.05rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.job-card__badge {
    font-size: 0.5rem;
    font-weight: var(--font-weight-semibold);
    padding: 2px 10px;
    border-radius: 50px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.job-card__badge--featured {
    background: rgba(192, 227, 74, 0.12);
    color: var(--color-lime-dark);
    border: 1px solid rgba(192, 227, 74, 0.15);
}

.job-card__badge--new {
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
    border: 1px solid rgba(124, 58, 237, 0.1);
}

.job-card__meta {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 4px;
    flex-shrink: 0;
}

.job-card__department {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.job-card__type {
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    padding: 2px 10px;
    border-radius: 50px;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.job-card__type--fulltime {
    background: rgba(52, 211, 153, 0.08);
    color: #34D399;
    border: 1px solid rgba(52, 211, 153, 0.1);
}

.job-card__type--parttime {
    background: rgba(251, 191, 36, 0.08);
    color: #FBBF24;
    border: 1px solid rgba(251, 191, 36, 0.1);
}

.job-card__type--remote {
    background: rgba(14, 165, 233, 0.08);
    color: #0EA5E9;
    border: 1px solid rgba(14, 165, 233, 0.1);
}

.job-card__type--contract {
    background: rgba(244, 67, 54, 0.08);
    color: #F44336;
    border: 1px solid rgba(244, 67, 54, 0.1);
}

/* ----- Card Description ----- */
.job-card__description {
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0 0 12px 0;
    flex: 1;
}

/* ----- Card Tags ----- */
.job-card__tags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin-bottom: 14px;
}

.job-tag {
    padding: 3px 12px;
    background: rgba(124, 58, 237, 0.04);
    border: 1px solid rgba(124, 58, 237, 0.06);
    border-radius: 50px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    letter-spacing: 0.02em;
    transition: all 0.3s ease;
}

.job-card:hover .job-tag {
    background: rgba(124, 58, 237, 0.06);
    border-color: rgba(124, 58, 237, 0.08);
}

/* ----- Card Footer ----- */
.job-card__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 14px;
    border-top: 1px solid var(--color-gray-light);
    flex-wrap: wrap;
    gap: 10px;
}

.job-card__info {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px;
}

.job-card__location {
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
}

.job-card__location i {
    font-size: 0.6rem;
    margin-right: 4px;
    color: var(--color-purple);
}

.job-card__level {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    padding: 2px 10px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
}

.job-card__salary {
    font-size: 0.72rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

.job-card__date {
    font-size: 0.65rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
}

/* ----- Apply Button ----- */
.btn-job-apply {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 20px;
    background: var(--color-purple);
    color: var(--color-white);
    border-radius: 50px;
    font-family: var(--font-primary);
    font-size: 0.78rem;
    font-weight: var(--font-weight-semibold);
    text-decoration: none;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    box-shadow: 0 4px 16px rgba(124, 58, 237, 0.15);
    border: none;
    cursor: pointer;
}

.btn-job-apply:hover {
    background: var(--color-purple-dark);
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.25);
}

.btn-job-apply i {
    font-size: 0.6rem;
    transition: transform 0.3s ease;
}

.btn-job-apply:hover i {
    transform: translateX(4px);
}

/* ============================================================
   LOAD MORE
   ============================================================ */
.open-positions__load-more {
    text-align: center;
    margin-bottom: 48px;
}

.btn-load-more {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 14px 36px;
    background: var(--color-off-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 50px;
    font-family: var(--font-primary);
    font-size: 0.9rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    cursor: pointer;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.btn-load-more:hover {
    border-color: var(--color-purple);
    color: var(--color-purple);
    transform: translateY(-3px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.06);
}

.btn-load-more i {
    font-size: 0.7rem;
    transition: transform 0.3s ease;
}

.btn-load-more:hover i {
    transform: translateX(4px);
}

/* ============================================================
   RECRUITMENT BANNER
   ============================================================ */
.open-positions__banner {
    background: linear-gradient(135deg, rgba(124, 58, 237, 0.04), rgba(192, 227, 74, 0.04));
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    padding: 44px 48px 40px;
    text-align: center;
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
    transition: all 0.4s ease;
    max-width: 900px;
    margin: 0 auto;
}

.open-positions__banner::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 20px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0.08;
    pointer-events: none;
}

.open-positions__banner > * {
    position: relative;
    z-index: 2;
}

.open-positions__banner:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.banner-content .banner-title {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 8px 0;
    letter-spacing: -0.02em;
}

.banner-content .banner-description {
    font-size: 0.95rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    max-width: 560px;
    margin: 0 auto 20px;
}

.banner-buttons {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    flex-wrap: wrap;
}

.btn-banner-primary {
    padding: 12px 32px;
    font-size: 0.9rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
}

.btn-banner-primary:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

.btn-banner-secondary {
    padding: 12px 32px;
    font-size: 0.9rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.btn-banner-secondary:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

.btn-banner-secondary i {
    transition: transform 0.3s ease;
}

.btn-banner-secondary:hover i {
    transform: translateX(4px);
}

/* ============================================================
   HIRING PROCESS — Careers Page (Phase 5)
   ============================================================ */
#hiring-process {
    padding: 80px 0 80px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.hiring-process__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.hiring-process__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.hiring-process__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    left: -80px;
    background: var(--color-lime);
    opacity: 0.04;
}

.hiring-process__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    right: -60px;
    background: var(--color-purple);
    opacity: 0.04;
}

.hiring-process__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.hiring-process__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.hiring-process__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.hiring-process__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.hiring-process__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.hiring-process__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.hiring-process__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.hiring-process__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#hiring-process .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#hiring-process .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#hiring-process .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#hiring-process .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#hiring-process .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

/* ----- Container ----- */
.hiring-process__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.hiring-process__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.hiring-process__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.hiring-process__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.hiring-process__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.hiring-process__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   TIMELINE
   ============================================================ */
.hiring-process__timeline {
    position: relative;
    max-width: 1000px;
    margin: 0 auto 48px;
    padding: 20px 0 10px;
}

/* ----- Central Line ----- */
.hp-timeline__line {
    position: absolute;
    top: 50px;
    bottom: 40px;
    left: 50%;
    width: 3px;
    background: var(--color-gray-light);
    transform: translateX(-50%);
    border-radius: 4px;
    overflow: hidden;
    z-index: 1;
}

.hp-timeline__line-fill {
    height: 0%;
    width: 100%;
    background: linear-gradient(180deg, var(--color-lime), var(--color-purple));
    border-radius: 4px;
    transition: height 1.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.hp-timeline__line-fill.animated {
    height: 100%;
}

/* ----- Timeline Step ----- */
.hp-step {
    position: relative;
    display: flex;
    align-items: center;
    margin-bottom: 40px;
    z-index: 2;
    opacity: 0;
    transform: translateY(30px);
    transition: opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94),
                transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.hp-step.visible {
    opacity: 1;
    transform: translateY(0);
}

/* Left-aligned steps */
.hp-step--left {
    flex-direction: row;
    padding-right: calc(50% + 36px);
    text-align: right;
}

.hp-step--left .hp-step__card {
    margin-left: auto;
}

/* Right-aligned steps */
.hp-step--right {
    flex-direction: row-reverse;
    padding-left: calc(50% + 36px);
    text-align: left;
}

.hp-step--right .hp-step__card {
    margin-right: auto;
}

/* ----- Step Node ----- */
.hp-step__node {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    flex-direction: column;
    align-items: center;
    z-index: 3;
    width: 60px;
}

.hp-step__node-dot {
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: var(--color-white);
    border: 3px solid var(--color-gray-light);
    transition: all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
    position: relative;
    z-index: 2;
}

.hp-step.visible .hp-step__node-dot {
    border-color: var(--color-lime);
    background: var(--color-lime);
    box-shadow: 0 0 0 6px rgba(192, 227, 74, 0.15);
}

.hp-step__node-glow {
    position: absolute;
    inset: -10px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(192, 227, 74, 0.1) 0%, transparent 70%);
    opacity: 0;
    transition: opacity 0.6s ease;
}

.hp-step.visible .hp-step__node-glow {
    opacity: 1;
    animation: pulseGlow 2.5s ease-in-out infinite;
}

.hp-step__number {
    font-size: 0.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    margin-top: 6px;
    background: var(--color-white);
    padding: 2px 10px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    transition: all 0.4s ease;
}

.hp-step.visible .hp-step__number {
    border-color: var(--color-lime);
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.05);
}

/* ----- Step Card ----- */
.hp-step__card {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    padding: 18px 22px 18px 20px;
    background: rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 16px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    max-width: 380px;
    position: relative;
    overflow: hidden;
}

.hp-step__card::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 16px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0;
    transition: opacity 0.5s ease;
    pointer-events: none;
}

.hp-step__card::after {
    content: '';
    position: absolute;
    inset: 1px;
    border-radius: 15px;
    background: rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    z-index: 1;
    transition: background 0.5s ease;
    pointer-events: none;
}

.hp-step__card:hover::before {
    opacity: 1;
}

.hp-step__card:hover::after {
    background: rgba(255, 255, 255, 0.85);
}

.hp-step__card:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.hp-step__card > * {
    position: relative;
    z-index: 3;
}

/* ----- Step Icon ----- */
.hp-step__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    min-width: 40px;
    border-radius: 10px;
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
    font-size: 1rem;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.hp-step__card:hover .hp-step__icon {
    background: var(--color-purple);
    color: var(--color-white);
    transform: scale(1.05);
}

/* Alternate icon colors */
.hp-step:nth-child(1) .hp-step__card:hover .hp-step__icon,
.hp-step:nth-child(3) .hp-step__card:hover .hp-step__icon,
.hp-step:nth-child(5) .hp-step__card:hover .hp-step__icon {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

/* ----- Step Content ----- */
.hp-step__content {
    flex: 1;
    min-width: 0;
}

.hp-step__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0 0 4px 0;
}

.hp-step__description {
    font-size: 0.8rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0;
}

/* ============================================================
   TIMELINE BANNER
   ============================================================ */
.hiring-process__banner {
    background: linear-gradient(135deg, rgba(124, 58, 237, 0.04), rgba(192, 227, 74, 0.04));
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    padding: 36px 40px 32px;
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
    transition: all 0.4s ease;
    max-width: 900px;
    margin: 0 auto 48px;
}

.hiring-process__banner::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 20px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0.08;
    pointer-events: none;
}

.hiring-process__banner > * {
    position: relative;
    z-index: 2;
}

.hiring-process__banner:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.hp-banner__header {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    margin-bottom: 18px;
}

.hp-banner__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    min-width: 48px;
    border-radius: 14px;
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
    font-size: 1.2rem;
    transition: all 0.4s ease;
}

.hiring-process__banner:hover .hp-banner__icon {
    background: var(--color-purple);
    color: var(--color-white);
    transform: scale(1.05);
}

.hp-banner__title {
    font-size: 1.3rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 4px 0;
    letter-spacing: -0.02em;
}

.hp-banner__description {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    margin: 0;
}

.hp-banner__description strong {
    color: var(--color-purple);
    font-weight: var(--font-weight-semibold);
}

.hp-banner__highlights {
    display: flex;
    flex-wrap: wrap;
    gap: 12px 24px;
}

.hp-highlight {
