    left: 50%;
    transform: translate(-50%, -50%);
    animation-delay: 0.8s;
}

.faq-visual__node {
    position: absolute;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.8);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
