    flex-direction: column;
    gap: 10px;
}

/* ----- FAQ Item ----- */
.faq-item {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 14px;
    overflow: hidden;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
}

.faq-item:hover {
    border-color: rgba(124, 58, 237, 0.08);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.04);
}

.faq-item--highlight {
    border-color: rgba(192, 227, 74, 0.15);
    background: rgba(255, 255, 255, 0.5);
}

.faq-item--highlight:hover {
    border-color: rgba(192, 227, 74, 0.25);
}

.faq-item.active {
    border-color: rgba(124, 58, 237, 0.12);
    background: rgba(255, 255, 255, 0.7);
    box-shadow: 0 8px 32px rgba(124, 58, 237, 0.04);
}

.faq-item.active--highlight {
    border-color: rgba(192, 227, 74, 0.25);
}

/* ----- Trigger Button ----- */
.faq-item__trigger {
    display: flex;
    align-items: center;
    gap: 14px;
    width: 100%;
    padding: 16px 20px 16px 18px;
    background: transparent;
    border: none;
    cursor: pointer;
    font-family: var(--font-primary);
    font-size: 0.92rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: left;
    transition: all 0.3s ease;
    position: relative;
    z-index: 2;
}

.faq-item__trigger:hover {
    color: var(--color-purple);
}

.faq-item.active .faq-item__trigger {
    color: var(--color-purple);
}

.faq-item--highlight.active .faq-item__trigger {
    color: var(--color-lime-dark);
}

/* Trigger Icon */
.faq-item__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    min-width: 32px;
    border-radius: 8px;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-size: 0.8rem;
    transition: all 0.4s ease;
}

.faq-item__trigger:hover .faq-item__icon {
    background: rgba(124, 58, 237, 0.1);
    transform: scale(1.05);
}

.faq-item.active .faq-item__icon {
    background: var(--color-purple);
    color: var(--color-white);
}

.faq-item--highlight.active .faq-item__icon {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

/* Trigger Question */
.faq-item__question {
    flex: 1;
    min-width: 0;
}

/* Trigger Indicator */
.faq-item__indicator {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    min-width: 28px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.04);
    color: var(--color-gray-mid);
    font-size: 0.75rem;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
    flex-shrink: 0;
}

.faq-item__trigger:hover .faq-item__indicator {
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
}

.faq-item.active .faq-item__indicator {
    background: var(--color-purple);
    color: var(--color-white);
    transform: rotate(45deg);
}

.faq-item--highlight.active .faq-item__indicator {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

/* ----- Answer ----- */
.faq-item__answer {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94),
                opacity 0.4s ease,
                padding 0.3s ease;
    opacity: 0;
    padding: 0 20px 0 20px;
}

.faq-item.active .faq-item__answer {
    max-height: 200px;
    opacity: 1;
    padding: 0 20px 20px 20px;
}

.faq-item__answer-content {
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    padding-top: 4px;
    border-top: 1px solid var(--color-gray-light);
}

.faq-item.active .faq-item__answer-content {
    border-top-color: rgba(124, 58, 237, 0.06);
}

.faq-item--highlight.active .faq-item__answer-content {
    border-top-color: rgba(192, 227, 74, 0.12);
}

/* Focus states for accessibility */
.faq-item__trigger:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: -2px;
    border-radius: 14px;
}

.btn-faq-intro:focus-visible,
