    border-radius: 28px;
    padding: 48px 48px 44px;
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
    transition: all 0.4s ease;
}

.careers-cta__banner::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 28px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0.06;
    pointer-events: none;
}

.careers-cta__banner:hover {
    transform: translateY(-4px);
    box-shadow: 0 24px 64px rgba(124, 58, 237, 0.06);
}

.careers-cta__banner > * {
    position: relative;
    z-index: 2;
}

/* ============================================================
   LEFT CONTENT
   ============================================================ */
.careers-cta__content {
    display: flex;
    flex-direction: column;
    gap: 28px;
}

/* ----- Career Highlights ----- */
.careers-cta__highlights {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px 20px;
}

.cta-highlight {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 14px 16px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 14px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    cursor: default;
}

.cta-highlight:hover {
    background: rgba(255, 255, 255, 0.6);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateY(-3px);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.04);
}

.cta-highlight__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    min-width: 36px;
    border-radius: 10px;
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
    font-size: 0.9rem;
    transition: all 0.4s ease;
}

.cta-highlight:hover .cta-highlight__icon {
    background: var(--color-purple);
    color: var(--color-white);
    transform: scale(1.05);
}

.cta-highlight__info {
    flex: 1;
    min-width: 0;
}

.cta-highlight__title {
    font-size: 0.88rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0 0 2px 0;
}

.cta-highlight__description {
    font-size: 0.72rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.4;
    margin: 0;
}

/* ----- CTA Buttons ----- */
.careers-cta__buttons {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

.btn-cta-primary {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-cta-primary:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

.btn-cta-secondary {
    padding: 14px 32px;
    font-size: 0.95rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.btn-cta-secondary:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-3px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

.btn-cta-secondary i {
    transition: transform 0.3s ease;
}

.btn-cta-secondary:hover i {
    transform: translateX(4px);
}

.btn-cta-outline {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 14px 28px;
    background: transparent;
    color: var(--color-charcoal);
    font-family: var(--font-primary);
    font-size: 0.9rem;
    font-weight: var(--font-weight-medium);
    border: 1.5px solid var(--color-gray-light);
    border-radius: 50px;
    cursor: pointer;
    text-decoration: none;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.btn-cta-outline:hover {
    border-color: var(--color-purple);
    color: var(--color-purple);
    transform: translateY(-3px);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.08);
    background: rgba(124, 58, 237, 0.02);
}

.btn-cta-outline i {
    font-size: 0.8rem;
    transition: transform 0.3s ease;
}

.btn-cta-outline:hover i {
    transform: translateX(4px);
}

/* ----- Note ----- */
.careers-cta__note {
    font-size: 0.82rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin: 0;
    padding-top: 4px;
}

.cta-note__link {
    color: var(--color-purple);
    font-weight: var(--font-weight-semibold);
    text-decoration: none;
    transition: all 0.3s ease;
    border-bottom: 1.5px solid transparent;
}

.cta-note__link:hover {
    color: var(--color-purple-dark);
    border-bottom-color: var(--color-purple);
}

/* ============================================================
   RIGHT VISUAL
   ============================================================ */
.careers-cta__visual {
    position: relative;
    min-height: 320px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ----- Central Node ----- */
.cta-visual__center {
    position: relative;
    width: 80px;
    height: 80px;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 4;
}

.cta-visual__center-glow {
    position: absolute;
    inset: -30px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(192, 227, 74, 0.1) 0%, transparent 70%);
    animation: pulseGlow 3s ease-in-out infinite;
}

.cta-visual__center-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--color-lime), var(--color-lime-dark));
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-charcoal);
    font-size: 1.6rem;
    box-shadow: 0 8px 32px rgba(192, 227, 74, 0.25);
    z-index: 2;
}

/* ----- Orbiting Rings ----- */
.cta-visual__ring {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border-radius: 50%;
    border: 1px solid rgba(124, 58, 237, 0.06);
    pointer-events: none;
}

.cta-visual__ring--1 {
    width: 300px;
    height: 300px;
    animation: orbitSpin 22s linear infinite;
}

.cta-visual__ring--2 {
    width: 220px;
    height: 220px;
    animation: orbitSpin 16s linear infinite reverse;
    border-color: rgba(192, 227, 74, 0.06);
}

.cta-visual__ring--3 {
    width: 150px;
    height: 150px;
    animation: orbitSpin 10s linear infinite;
    border-color: rgba(124, 58, 237, 0.04);
}

/* ----- Orbiting Nodes ----- */
.cta-visual__node {
    position: absolute;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    border: 1px solid var(--color-gray-light);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-purple);
    font-size: 0.9rem;
    box-shadow: 0 4px 16px rgba(26, 26, 46, 0.04);
    transition: all 0.4s ease;
    z-index: 5;
    animation: floatNode 4.5s ease-in-out infinite;
}

.cta-visual__node:hover {
    transform: scale(1.12);
    border-color: var(--color-lime);
    box-shadow: 0 8px 24px rgba(192, 227, 74, 0.1);
}

.cta-visual__node--1 {
    top: 6%;
    right: 6%;
    animation-delay: 0s;
    color: #0EA5E9;
}
.cta-visual__node--2 {
    bottom: 8%;
    right: 22%;
    animation-delay: 0.8s;
    color: #EC4899;
}
.cta-visual__node--3 {
    bottom: 25%;
    left: 2%;
    animation-delay: 1.6s;
    color: #F59E0B;
}
.cta-visual__node--4 {
    top: 20%;
    left: 4%;
    animation-delay: 2.4s;
    color: #8B5CF6;
}
.cta-visual__node--5 {
    top: 42%;
    right: 2%;
    animation-delay: 3.2s;
    color: #34D399;
}
.cta-visual__node--6 {
    bottom: 6%;
    left: 20%;
    animation-delay: 4s;
    color: #F472B6;
}

/* ----- Floating Glass Cards ----- */
.cta-visual__float {
    position: absolute;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.25);
    border-radius: 12px;
    padding: 6px 14px;
    box-shadow: 0 8px 24px rgba(26, 26, 46, 0.04);
    display: flex;
    align-items: center;
    gap: 8px;
    z-index: 3;
    animation: floatCard 5.5s ease-in-out infinite;
}

.cta-visual__float .float-emoji {
    font-size: 0.9rem;
}

.cta-visual__float .float-label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.cta-visual__float--1 {
    top: 8%;
    left: 5%;
    animation-delay: 0s;
}

.cta-visual__float--2 {
    bottom: 8%;
    right: 5%;
    animation-delay: 1.8s;
}

.cta-visual__float--3 {
    top: 35%;
    right: 3%;
    animation-delay: 0.9s;
}

/* ----- Decorative Shapes ----- */
.cta-visual__deco {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.03);
    border: 1px solid rgba(192, 227, 74, 0.03);
}

.cta-visual__deco--1 {
    width: 100px;
    height: 100px;
    top: 15%;
    right: 30%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.cta-visual__deco--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 30%;
    border-radius: 70% 30% 30% 70% / 60% 40% 60% 40%;
}

.cta-visual__deco--3 {
    width: 50px;
    height: 50px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
    background: rgba(124, 58, 237, 0.02);
    border-color: rgba(124, 58, 237, 0.02);
}

/* ----- Focus States ----- */
.btn-cta-primary:focus-visible,
.btn-cta-secondary:focus-visible,
.btn-cta-outline:focus-visible,
.cta-note__link:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================== START CSS ==================== */
/* --- CSS Custom Properties --- */

/* --- Hero Section --- */
.case-studies-hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 120px 0 80px;
  background: var(--bg-white);
  isolation: isolate;
}

/* --- Background Layers --- */
.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.bg-mesh-gradient {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 20% 30%, rgba(163, 230, 53, 0.10) 0%, transparent 60%),
    radial-gradient(ellipse 70% 55% at 75% 60%, rgba(168, 85, 247, 0.09) 0%, transparent 60%),
    radial-gradient(ellipse 50% 40% at 60% 20%, rgba(163, 230, 53, 0.05) 0%, transparent 55%),
    radial-gradient(ellipse 65% 50% at 30% 75%, rgba(168, 85, 247, 0.06) 0%, transparent 55%);
  animation: meshShift 18s ease-in-out infinite alternate;
}

@keyframes meshShift {
  0% {
    transform: scale(1) translate(0, 0);
  }
  33% {
    transform: scale(1.04) translate(-1%, 1%);
  }
  66% {
    transform: scale(1.02) translate(1%, -0.5%);
  }
  100% {
    transform: scale(1.03) translate(0.5%, 0.5%);
  }
}

.bg-tech-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(163, 230, 53, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(168, 85, 247, 0.04) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse 70% 60% at center, black 20%, transparent 70%);
  -webkit-mask-image: radial-gradient(ellipse 70% 60% at center, black 20%, transparent 70%);
}

.bg-circuit-lines {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(135deg, transparent 45%, rgba(168, 85, 247, 0.03) 45%, rgba(168, 85, 247, 0.03) 46%, transparent 46%),
    linear-gradient(225deg, transparent 45%, rgba(163, 230, 53, 0.03) 45%, rgba(163, 230, 53, 0.03) 46%, transparent 46%),
    linear-gradient(315deg, transparent 48%, rgba(168, 85, 247, 0.02) 48%, rgba(168, 85, 247, 0.02) 49%, transparent 49%);
  background-size: 200px 180px, 180px 200px, 220px 190px;
  background-position: 10% 20%, 75% 50%, 40% 70%;
  animation: circuitDrift 25s linear infinite;
}

@keyframes circuitDrift {
  0% {
    background-position: 10% 20%, 75% 50%, 40% 70%;
  }
  100% {
    background-position: 12% 22%, 77% 52%, 42% 72%;
  }
}

.bg-hexagon-outlines {
  position: absolute;
  inset: 0;
  background-image:
    url("data:image/svg+xml,%3Csvg width='80' height='90' viewBox='0 0 80 90' xmlns='http://www.w3.org/2000/svg'%3E%3Cpolygon points='40,5 72,23 72,61 40,79 8,61 8,23' fill='none' stroke='rgba(168,85,247,0.06)' stroke-width='1.5'/%3E%3C/svg%3E");
  background-size: 140px 158px;
  background-position: 5% 10%;
  mask-image: radial-gradient(ellipse 65% 55% at 60% 40%, black 15%, transparent 65%);
  -webkit-mask-image: radial-gradient(ellipse 65% 55% at 60% 40%, black 15%, transparent 65%);
  opacity: 0.7;
}

.bg-radial-glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(100px);
  opacity: 0.5;
  animation: glowPulse 6s ease-in-out infinite alternate;
}

.bg-radial-glow--green {
  width: 500px;
  height: 500px;
  background: var(--brand-green-glow);
  top: -15%;
  left: -10%;
  animation-delay: 0s;
}

.bg-radial-glow--purple {
  width: 450px;
  height: 450px;
  background: var(--brand-purple-glow);
  bottom: -10%;
  right: -8%;
  animation-delay: 3s;
}

@keyframes glowPulse {
  0% {
    opacity: 0.35;
    transform: scale(1);
  }
  100% {
    opacity: 0.6;
    transform: scale(1.15);
  }
}

/* Floating Particles */
.bg-particles {
  position: absolute;
  inset: 0;
}

.particle {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  animation: particleFloat linear infinite;
}

.particle--green {
  background: rgba(163, 230, 53, 0.45);
  box-shadow: 0 0 8px rgba(163, 230, 53, 0.5);
}

.particle--purple {
  background: rgba(168, 85, 247, 0.4);
  box-shadow: 0 0 8px rgba(168, 85, 247, 0.5);
}

@keyframes particleFloat {
  0% {
    transform: translateY(0) translateX(0) scale(1);
    opacity: 0;
  }
  10% {
    opacity: 0.7;
  }
  90% {
    opacity: 0.6;
  }
  100% {
    transform: translateY(-110vh) translateX(40px) scale(0.3);
    opacity: 0;
  }
}

/* --- Hero Container --- */
.hero-container {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 40px;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
  margin-bottom: 70px;
}

/* --- Left Content --- */
.hero-content {
  animation: fadeUpContent 0.9s ease-out forwards;
}

@keyframes fadeUpContent {
  from {
    opacity: 0;
    transform: translateY(35px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-label {
  display: inline-block;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--brand-purple-deep);
  background: rgba(168, 85, 247, 0.08);
  padding: 8px 18px;
  border-radius: 50px;
  margin-bottom: 24px;
  border: 1px solid rgba(168, 85, 247, 0.2);
}

.hero-heading {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: clamp(2.4rem, 5vw, 3.8rem);
  font-weight: 800;
  line-height: 1.15;
  color: var(--text-charcoal);
  margin: 0 0 20px 0;
  letter-spacing: -0.03em;
}

.text-gradient {
  background: linear-gradient(135deg, var(--brand-green-deep) 0%, var(--brand-purple) 60%, var(--brand-purple-deep) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  color: transparent;
}

.hero-description {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 1.1rem;
  line-height: 1.7;
  color: var(--text-muted);
  margin: 0 0 36px 0;
  max-width: 540px;
}

/* --- CTA Buttons --- */
.hero-cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 1rem;
  font-weight: 600;
  padding: 15px 28px;
  border-radius: 60px;
  cursor: pointer;
  border: none;
  transition: all var(--transition-smooth);
  outline: none;
  position: relative;
  overflow: hidden;
}

.btn--primary {
  background: linear-gradient(135deg, var(--brand-green), var(--brand-green-deep));
  color: #1a1a1a;
  box-shadow: 0 6px 28px rgba(163, 230, 53, 0.35), 0 2px 8px rgba(132, 204, 22, 0.25);
}

.btn--primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 36px rgba(163, 230, 53, 0.5), 0 4px 14px rgba(132, 204, 22, 0.35);
}

.btn--primary:focus-visible {
  outline: 3px solid var(--brand-green);
  outline-offset: 3px;
}

.btn--primary::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.25), transparent);
  border-radius: 60px;
  opacity: 0;
  transition: opacity 0.3s;
}

.btn--primary:hover::after {
  opacity: 1;
}

.btn--secondary {
  background: transparent;
  color: var(--text-charcoal);
  border: 2px solid rgba(168, 85, 247, 0.3);
  box-shadow: 0 2px 12px rgba(168, 85, 247, 0.06);
}

.btn--secondary:hover {
  border-color: var(--brand-purple);
  background: rgba(168, 85, 247, 0.04);
  transform: translateY(-3px);
  box-shadow: 0 8px 28px rgba(168, 85, 247, 0.18);
}

.btn--secondary:focus-visible {
  outline: 3px solid var(--brand-purple);
  outline-offset: 3px;
}

.btn-icon {
  transition: transform 0.3s ease;
}

.btn:hover .btn-icon {
  transform: translateX(4px);
}

.btn--secondary:hover .btn-icon {
  transform: rotate(90deg);
}

/* --- Right Visual / Illustration --- */
.hero-visual {
  animation: fadeUpContent 0.9s ease-out 0.2s forwards;
  opacity: 0;
}

@keyframes fadeUpContent {
  from {
    opacity: 0;
    transform: translateY(35px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.illustration-container {
  position: relative;
  width: 100%;
  height: 500px;
}

/* Connection Lines SVG */
.connection-lines {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
}

/* Floating Cards */
.float-card {
  position: absolute;
  z-index: 1;
  animation: floatCard 6s ease-in-out infinite;
}

.float-card--1 {
  top: 5%;
  left: 5%;
  animation-delay: 0s;
}
.float-card--2 {
  top: 0%;
  right: 8%;
  animation-delay: 1.5s;
}
.float-card--3 {
  top: 28%;
  right: 15%;
  animation-delay: 3s;
}
.float-card--4 {
  bottom: 22%;
  left: 12%;
  animation-delay: 2s;
}
.float-card--5 {
  bottom: 30%;
  right: 5%;
  animation-delay: 4.5s;
}

@keyframes floatCard {
  0%, 100% {
    transform: translateY(0) rotate(0deg);
  }
  25% {
    transform: translateY(-12px) rotate(0.5deg);
  }
  50% {
    transform: translateY(-4px) rotate(-0.3deg);
  }
  75% {
    transform: translateY(-16px) rotate(0.2deg);
  }
}

.glass-card-inner {
  background: var(--glass-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--glass-border);
  border-radius: var(--card-radius);
  box-shadow: var(--glass-shadow);
  padding: 18px 20px;
  transition: all var(--transition-bounce);
}

.glass-card-inner:hover {
  transform: translateY(-6px);
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.1), 0 4px 16px rgba(0, 0, 0, 0.05);
  border-color: rgba(168, 85, 247, 0.35);
}

/* Dashboard Card */
.float-card--dashboard {
  width: 210px;
}

.dashboard-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.dashboard-dots {
  display: flex;
  gap: 5px;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.dot--red {
  background: #EF4444;
}

.dot--yellow {
  background: #F59E0B;
}

.dot--green {
  background: #10B981;
}

.dashboard-title {
  font-family: 'Inter', sans-serif;
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.02em;
}

.dashboard-chart {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  height: 60px;
  margin-bottom: 12px;
}

.chart-bar {
  flex: 1;
  height: var(--h);
  background: linear-gradient(180deg, var(--brand-green), rgba(163, 230, 53, 0.4));
  border-radius: 4px 4px 0 0;
  animation: barRise 1.8s ease-out var(--delay) both;
}

@keyframes barRise {
  from {
    height: 0;
    opacity: 0;
  }
  to {
    height: var(--h);
    opacity: 1;
  }
}

.dashboard-stats {
  display: flex;
  gap: 16px;
}

.mini-stat-value {
  display: block;
  font-family: 'Inter', sans-serif;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text-charcoal);
}

.mini-stat-label {
  font-family: 'Inter', sans-serif;
  font-size: 0.65rem;
  color: var(--text-muted);
}

/* Browser Card */
.float-card--browser {
  width: 200px;
}

.browser-topbar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.browser-dots {
  display: flex;
  gap: 5px;
  flex-shrink: 0;
}

.browser-url {
  font-family: 'Inter', sans-serif;
  font-size: 0.65rem;
  color: var(--text-muted);
  background: rgba(0, 0, 0, 0.04);
  padding: 3px 10px;
  border-radius: 6px;
  flex: 1;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
}

.browser-content {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.code-line {
  height: 4px;
  border-radius: 2px;
  background: rgba(0, 0, 0, 0.08);
}

.code-line--1 {
  width: 70%;
}

.code-line--2 {
  width: 90%;
}

.code-line--3 {
  width: 50%;
}

.code-line--4 {
  width: 75%;
}

.code-snippet {
  font-family: 'SF Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: 0.65rem;
  padding: 8px 10px;
  background: rgba(0, 0, 0, 0.03);
  border-radius: 8px;
  margin-top: 4px;
  border-left: 3px solid var(--brand-green);
}

.code-keyword {
  color: #A855F7;
  font-weight: 600;
}

.code-var {
  color: #1E1E24;
}

.code-string {
  color: #84CC16;
}

/* Mobile Mockup Card */
.float-card--mobile {
  width: 150px;
}

.mobile-notch {
  width: 40px;
  height: 5px;
  background: rgba(0, 0, 0, 0.15);
  border-radius: 3px;
  margin: 0 auto 12px;
}

.mobile-screen {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.mobile-app-header {
  display: flex;
  align-items: center;
  gap: 8px;
}

.mobile-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--brand-green), var(--brand-purple));
}

.mobile-app-line {
  height: 4px;
  border-radius: 2px;
  background: rgba(0, 0, 0, 0.1);
}

.mobile-app-line--short {
  width: 50px;
}

.mobile-app-line--tiny {
  width: 30px;
}

.mobile-card {
  height: 28px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.04);
}

.mobile-card--1 {
  background: rgba(163, 230, 53, 0.1);
}

.mobile-card--2 {
  background: rgba(168, 85, 247, 0.08);
}

.mobile-chart-ring {
  display: flex;
  justify-content: center;
  margin-top: 4px;
}

/* AI / Tech Card */
.float-card--ai {
  width: 130px;
  text-align: center;
}

.ai-icon-wrapper {
  display: flex;
  justify-content: center;
  margin-bottom: 8px;
}

.ai-hexagon {
  display: flex;
  align-items: center;
  justify-content: center;
  animation: hexSpin 12s linear infinite;
}

@keyframes hexSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.ai-label {
  font-family: 'Inter', sans-serif;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--brand-purple-deep);
  letter-spacing: 0.04em;
}

.ai-pulse-ring {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid rgba(168, 85, 247, 0.4);
  margin: 8px auto 0;
  animation: aiPulse 2s ease-out infinite;
}

@keyframes aiPulse {
  0% {
    transform: scale(0.8);
    opacity: 0.8;
  }
  100% {
    transform: scale(2);
    opacity: 0;
  }
}

/* Tech Card */
.float-card--tech {
  width: 160px;
  text-align: center;
}

.tech-icons-row {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 8px;
}

.tech-icon-circle {
  width: 22px;
  height: 22px;
  border-radius: 50%;
}

.tech-icon-circle--green {
  background: linear-gradient(135deg, var(--brand-green), var(--brand-green-deep));
  box-shadow: 0 0 12px var(--brand-green-glow);
}

.tech-icon-circle--purple {
  background: linear-gradient(135deg, var(--brand-purple), var(--brand-purple-deep));
  box-shadow: 0 0 12px var(--brand-purple-glow);
}

.tech-label {
  font-family: 'Inter', sans-serif;
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.05em;
}

/* --- Trust Indicators --- */
.trust-indicators {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  animation: fadeUpContent 0.9s ease-out 0.4s forwards;
  opacity: 0;
}

.trust-card {
  background: var(--glass-bg);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid var(--glass-border);
  border-radius: var(--card-radius);
  padding: 28px 20px;
  text-align: center;
  box-shadow: var(--glass-shadow);
  transition: all var(--transition-bounce);
  cursor: default;
}

.trust-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 22px 55px rgba(0, 0, 0, 0.1), 0 6px 18px rgba(0, 0, 0, 0.05);
  border-color: rgba(163, 230, 53, 0.4);
}

.trust-icon-wrapper {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(163, 230, 53, 0.12), rgba(168, 85, 247, 0.12));
  margin-bottom: 14px;
  color: var(--brand-purple-deep);
  transition: all var(--transition-smooth);
}

.trust-card:hover .trust-icon-wrapper {
  color: var(--brand-green-deep);
  background: linear-gradient(135deg, rgba(163, 230, 53, 0.2), rgba(168, 85, 247, 0.2));
  transform: scale(1.08);
}

.trust-number {
  display: block;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 2.4rem;
  font-weight: 800;
  color: var(--text-charcoal);
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}

.trust-label {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: 0.01em;
}

/* --- Focus States for Accessibility --- */
.case-studies-hero *:focus-visible {
  outline: 2px solid var(--brand-purple);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ==================== START CSS ==================== */
/* --- Success Metrics Section --- */
.success-metrics {
  position: relative;
  padding: 100px 0 90px;
  background: var(--bg-white, #FAFBFC);
  overflow: hidden;
  isolation: isolate;
}

/* --- Background Layers --- */
.metrics-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.metrics-mesh-gradient {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 55% 45% at 15% 25%, rgba(168, 85, 247, 0.07) 0%, transparent 55%),
    radial-gradient(ellipse 60% 50% at 80% 70%, rgba(163, 230, 53, 0.08) 0%, transparent 55%),
    radial-gradient(ellipse 45% 40% at 50% 50%, rgba(168, 85, 247, 0.04) 0%, transparent 60%),
    radial-gradient(ellipse 50% 45% at 70% 20%, rgba(163, 230, 53, 0.05) 0%, transparent 55%);
  animation: metricsMeshShift 20s ease-in-out infinite alternate;
}

@keyframes metricsMeshShift {
  0% {
    transform: scale(1) translate(0, 0);
  }
  33% {
    transform: scale(1.03) translate(1%, -0.5%);
  }
  66% {
    transform: scale(1.02) translate(-0.5%, 1%);
  }
  100% {
    transform: scale(1.04) translate(0.5%, -0.5%);
  }
}

.metrics-tech-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(163, 230, 53, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(168, 85, 247, 0.03) 1px, transparent 1px);
  background-size: 55px 55px;
  mask-image: radial-gradient(ellipse 65% 55% at center, black 18%, transparent 68%);
  -webkit-mask-image: radial-gradient(ellipse 65% 55% at center, black 18%, transparent 68%);
}

.metrics-circuit-lines {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(150deg, transparent 47%, rgba(168, 85, 247, 0.025) 47%, rgba(168, 85, 247, 0.025) 48%, transparent 48%),
    linear-gradient(210deg, transparent 46%, rgba(163, 230, 53, 0.025) 46%, rgba(163, 230, 53, 0.025) 47%, transparent 47%),
    linear-gradient(330deg, transparent 48.5%, rgba(168, 85, 247, 0.02) 48.5%, rgba(168, 85, 247, 0.02) 49.5%, transparent 49.5%);
  background-size: 190px 170px, 210px 180px, 180px 200px;
  background-position: 8% 30%, 70% 60%, 35% 75%;
  animation: metricsCircuitDrift 28s linear infinite;
}

@keyframes metricsCircuitDrift {
  0% {
    background-position: 8% 30%, 70% 60%, 35% 75%;
  }
  100% {
    background-position: 10% 32%, 72% 62%, 37% 77%;
  }
}

.metrics-hexagon-outlines {
  position: absolute;
  inset: 0;
  background-image:
    url("data:image/svg+xml,%3Csvg width='70' height='78' viewBox='0 0 70 78' xmlns='http://www.w3.org/2000/svg'%3E%3Cpolygon points='35,4 63,19 63,55 35,70 7,55 7,19' fill='none' stroke='rgba(168,85,247,0.05)' stroke-width='1.2'/%3E%3C/svg%3E");
  background-size: 120px 135px;
  background-position: 75% 15%;
  mask-image: radial-gradient(ellipse 60% 50% at 65% 35%, black 12%, transparent 60%);
  -webkit-mask-image: radial-gradient(ellipse 60% 50% at 65% 35%, black 12%, transparent 60%);
  opacity: 0.65;
}

.metrics-radial-glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(110px);
  opacity: 0.4;
  animation: metricsGlowPulse 7s ease-in-out infinite alternate;
}

.metrics-radial-glow--green {
  width: 420px;
  height: 420px;
  background: rgba(163, 230, 53, 0.3);
  top: -12%;
  right: -8%;
  animation-delay: 0s;
}

.metrics-radial-glow--purple {
  width: 380px;
  height: 380px;
  background: rgba(168, 85, 247, 0.28);
  bottom: -10%;
  left: -6%;
  animation-delay: 3.5s;
}

@keyframes metricsGlowPulse {
  0% {
    opacity: 0.3;
    transform: scale(1);
  }
  100% {
    opacity: 0.55;
    transform: scale(1.18);
  }
}

/* --- Floating Particles --- */
.metrics-particles {
  position: absolute;
  inset: 0;
}

.metrics-particle {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  animation: metricsParticleFloat linear infinite;
}

.metrics-particle--green {
  background: rgba(163, 230, 53, 0.4);
  box-shadow: 0 0 7px rgba(163, 230, 53, 0.45);
}

.metrics-particle--purple {
  background: rgba(168, 85, 247, 0.35);
  box-shadow: 0 0 7px rgba(168, 85, 247, 0.4);
}

@keyframes metricsParticleFloat {
  0% {
    transform: translateY(0) translateX(0) scale(1);
    opacity: 0;
  }
  10% {
    opacity: 0.65;
  }
  90% {
    opacity: 0.55;
  }
  100% {
    transform: translateY(-105vh) translateX(35px) scale(0.25);
    opacity: 0;
  }
}

/* --- Container --- */
.metrics-container {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 40px;
}

/* --- Section Header --- */
.metrics-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 60px;
  animation: fadeUpMetrics 0.8s ease-out forwards;
}

@keyframes fadeUpMetrics {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.metrics-label {
  display: inline-block;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #9333EA;
  background: rgba(168, 85, 247, 0.07);
  padding: 8px 20px;
  border-radius: 50px;
  margin-bottom: 20px;
  border: 1px solid rgba(168, 85, 247, 0.18);
}

.metrics-heading {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: clamp(2rem, 4.2vw, 3.2rem);
  font-weight: 800;
  line-height: 1.2;
  color: #1E1E24;
  margin: 0 0 16px 0;
  letter-spacing: -0.03em;
}

.text-gradient {
  background: linear-gradient(135deg, #84CC16 0%, #A855F7 60%, #9333EA 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  color: transparent;
}

.metrics-description {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 1.05rem;
  line-height: 1.7;
  color: #5A5A6E;
  margin: 0;
}

/* --- Statistics Grid --- */
.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
  margin-bottom: 60px;
}

/* --- Metric Card --- */
.metric-card {
  position: relative;
  background: rgba(255, 255, 255, 0.52);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid rgba(255, 255, 255, 0.65);
  border-radius: 20px;
  padding: 30px 22px 26px;
  text-align: center;
  box-shadow: 0 8px 38px rgba(0, 0, 0, 0.05), 0 2px 8px rgba(0, 0, 0, 0.03);
  transition: all 0.45s cubic-bezier(0.34, 1.56, 0.64, 1);
  overflow: hidden;
  animation: fadeUpMetrics 0.8s ease-out forwards;
  animation-delay: calc(var(--card-index, 0) * 0.08s);
  opacity: 0;
}

.metric-card:nth-child(1) { --card-index: 1; }
.metric-card:nth-child(2) { --card-index: 2; }
.metric-card:nth-child(3) { --card-index: 3; }
.metric-card:nth-child(4) { --card-index: 4; }
.metric-card:nth-child(5) { --card-index: 5; }
.metric-card:nth-child(6) { --card-index: 6; }
.metric-card:nth-child(7) { --card-index: 7; }
.metric-card:nth-child(8) { --card-index: 8; }

.metric-card:hover {
  transform: translateY(-10px);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.09), 0 4px 14px rgba(0, 0, 0, 0.04);
  border-color: rgba(163, 230, 53, 0.4);
}

.metric-card:hover .metric-glow {
  opacity: 1;
}

.metric-glow {
  position: absolute;
  inset: 0;
  border-radius: 20px;
  background: radial-gradient(ellipse 60% 40% at 50% 30%, rgba(163, 230, 53, 0.12), transparent 65%),
    radial-gradient(ellipse 50% 35% at 50% 70%, rgba(168, 85, 247, 0.1), transparent 65%);
  opacity: 0;
  transition: opacity 0.45s ease;
  pointer-events: none;
}

.metric-icon-wrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 50px;
  height: 50px;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(163, 230, 53, 0.1), rgba(168, 85, 247, 0.1));
  margin-bottom: 14px;
  color: #9333EA;
  transition: all 0.35s ease;
}

.metric-card:hover .metric-icon-wrap {
  color: #84CC16;
  background: linear-gradient(135deg, rgba(163, 230, 53, 0.18), rgba(168, 85, 247, 0.18));
  transform: scale(1.1);
}

.metric-number {
  display: block;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 2.3rem;
  font-weight: 800;
  color: #1E1E24;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
  line-height: 1;
}

.metric-title {
  display: block;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 0.9rem;
  font-weight: 700;
  color: #1E1E24;
  margin-bottom: 4px;
  letter-spacing: -0.01em;
}

.metric-desc {
  display: block;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 0.75rem;
  font-weight: 500;
  color: #5A5A6E;
  letter-spacing: 0.01em;
}

/* --- Achievement Banner --- */
.achievement-banner {
  position: relative;
  background: rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.7);
  border-radius: 24px;
  padding: 44px 48px;
  box-shadow: 0 10px 45px rgba(0, 0, 0, 0.06), 0 2px 10px rgba(0, 0, 0, 0.03);
  overflow: hidden;
  animation: fadeUpMetrics 0.8s ease-out 0.5s forwards;
  opacity: 0;
}

.achievement-banner-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.banner-glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.35;
}

.banner-glow--left {
  width: 280px;
  height: 280px;
  background: rgba(168, 85, 247, 0.2);
  top: -40%;
  left: -8%;
}

.banner-glow--right {
  width: 260px;
  height: 260px;
  background: rgba(163, 230, 53, 0.18);
  bottom: -35%;
  right: -6%;
}

.achievement-banner-content {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 36px;
  flex-wrap: wrap;
}

.achievement-banner-text {
  flex: 1;
  min-width: 260px;
}

.achievement-banner-heading {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: clamp(1.35rem, 2.5vw, 1.8rem);
  font-weight: 800;
  color: #1E1E24;
  margin: 0 0 10px 0;
  letter-spacing: -0.02em;
  line-height: 1.25;
}

.achievement-banner-description {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 0.95rem;
  line-height: 1.65;
  color: #5A5A6E;
  margin: 0;
  max-width: 560px;
}

.achievement-banner-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 14px 28px;
  border-radius: 60px;
  cursor: pointer;
  border: none;
  background: linear-gradient(135deg, #A3E635, #84CC16);
  color: #1a1a1a;
  box-shadow: 0 6px 26px rgba(163, 230, 53, 0.32), 0 2px 8px rgba(132, 204, 22, 0.22);
  transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1.2);
  white-space: nowrap;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}

.achievement-banner-btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 34px rgba(163, 230, 53, 0.48), 0 4px 14px rgba(132, 204, 22, 0.32);
}

.achievement-banner-btn:focus-visible {
  outline: 3px solid #A3E635;
  outline-offset: 3px;
}

.achievement-banner-btn::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.25), transparent);
  border-radius: 60px;
  opacity: 0;
  transition: opacity 0.3s;
}

.achievement-banner-btn:hover::after {
  opacity: 1;
}

.achievement-banner-btn svg {
  transition: transform 0.3s ease;
}

.achievement-banner-btn:hover svg {
  transform: translateX(4px);
}

/* --- Focus States --- */
.success-metrics *:focus-visible {
  outline: 2px solid #A855F7;
  outline-offset: 2px;
  border-radius: 4px;
}

/* ==================================================
START: Featured Case Studies Section
================================================== */
/* --- Featured Case Studies Section --- */
.featured-case-studies {
  position: relative;
  padding: 100px 0 90px;
  background: var(--bg-white, #FAFBFC);
  overflow: hidden;
  isolation: isolate;
}

/* --- Background Layers --- */
.featured-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.featured-mesh-gradient {
  position: absolute;
