}

.showcase-radial-glow--green {
  width: 420px;
  height: 420px;
  background: rgba(163, 230, 53, 0.25);
  top: -10%;
  left: -5%;
  animation-delay: 0s;
}

.showcase-radial-glow--purple {
  width: 380px;
  height: 380px;
  background: rgba(168, 85, 247, 0.22);
  bottom: -10%;
  right: -5%;
  animation-delay: 4s;
}

@keyframes showcaseGlowPulse {
  0% { opacity: 0.28; transform: scale(1); }
  100% { opacity: 0.48; transform: scale(1.16); }
}

/* --- Floating Particles --- */
.showcase-particles {
  position: absolute;
  inset: 0;
}

.showcase-particle {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  animation: showcaseParticleFloat linear infinite;
}

.showcase-particle--green {
  background: rgba(163, 230, 53, 0.35);
  box-shadow: 0 0 6px rgba(163, 230, 53, 0.4);
}

.showcase-particle--purple {
  background: rgba(168, 85, 247, 0.3);
  box-shadow: 0 0 6px rgba(168, 85, 247, 0.35);
}

@keyframes showcaseParticleFloat {
  0% { transform: translateY(0) translateX(0) scale(1); opacity: 0; }
  10% { opacity: 0.6; }
  90% { opacity: 0.5; }
  100% { transform: translateY(-105vh) translateX(30px) scale(0.2); opacity: 0; }
}

/* --- Container --- */
.showcase-container {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 40px;
}

/* --- Section Header --- */
.showcase-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 60px;
}

.showcase-label {
  display: inline-block;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #9333EA;
  background: rgba(168, 85, 247, 0.07);
  padding: 8px 20px;
  border-radius: 50px;
  margin-bottom: 20px;
  border: 1px solid rgba(168, 85, 247, 0.18);
}

.showcase-heading {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: clamp(2rem, 4.2vw, 3.2rem);
  font-weight: 800;
  line-height: 1.2;
  color: #1E1E24;
  margin: 0 0 16px 0;
  letter-spacing: -0.03em;
}

.showcase-description {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 1.05rem;
  line-height: 1.7;
  color: #5A5A6E;
  margin: 0;
}

/* --- Main Layout --- */
.showcase-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 50px;
  align-items: center;
  margin-bottom: 50px;
}

/* Image Area */
.showcase-image-area {
  position: relative;
  border-radius: 24px;
  overflow: hidden;
  height: 100%;
  min-height: 420px;
}

.showcase-image-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, rgba(163, 230, 53, 0.08), rgba(168, 85, 247, 0.1));
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: rgba(168, 85, 247, 0.3);
  transition: transform 0.5s ease;
}

.showcase-image-placeholder:hover {
  transform: scale(1.02);
}

.showcase-image-text {
  font-family: 'Inter', sans-serif;
  font-size: 0.9rem;
  font-weight: 600;
  color: #9333EA;
  margin-top: 12px;
  letter-spacing: 0.04em;
}

.showcase-industry-badge {
  position: absolute;
  top: 20px;
  left: 20px;
  font-family: 'Inter', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #9333EA;
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  padding: 6px 14px;
  border-radius: 50px;
  border: 1px solid rgba(168, 85, 247, 0.25);
  z-index: 1;
}

/* Content Area */
.showcase-content {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.showcase-project-title {
  font-family: 'Inter', sans-serif;
  font-size: 2rem;
  font-weight: 800;
  color: #1E1E24;
  margin: 0;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.showcase-overview {
  font-family: 'Inter', sans-serif;
  font-size: 1rem;
  line-height: 1.7;
  color: #5A5A6E;
  margin: 0;
}

/* Information Cards Grid */
.showcase-info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.info-card {
  background: rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.65);
  border-radius: 18px;
  padding: 20px 18px;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.04);
  transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.info-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.08);
  border-color: rgba(163, 230, 53, 0.4);
}

.info-card-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(163, 230, 53, 0.1), rgba(168, 85, 247, 0.1));
  color: #9333EA;
  margin-bottom: 12px;
}

.info-card-title {
  font-family: 'Inter', sans-serif;
  font-size: 0.95rem;
  font-weight: 700;
  color: #1E1E24;
  margin: 0 0 6px 0;
}

.info-card-text {
  font-family: 'Inter', sans-serif;
  font-size: 0.82rem;
  line-height: 1.5;
  color: #5A5A6E;
  margin: 0;
}

.info-card-tech {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tech-tag {
  font-family: 'Inter', sans-serif;
  font-size: 0.68rem;
  font-weight: 600;
  background: rgba(163, 230, 53, 0.08);
  color: #1E1E24;
  padding: 3px 10px;
  border-radius: 50px;
  border: 1px solid rgba(163, 230, 53, 0.2);
}

.info-card-results {
  list-style: none;
  margin: 0;
  padding: 0;
}

.info-card-results li {
  font-family: 'Inter', sans-serif;
  font-size: 0.8rem;
  color: #5A5A6E;
  padding: 2px 0 2px 14px;
  position: relative;
}

.info-card-results li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 10px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #A3E635;
}

/* --- Key Metrics Row --- */
.showcase-metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 40px;
}

.metric-item {
  text-align: center;
  background: rgba(255, 255, 255, 0.45);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 18px;
  padding: 24px 16px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.04);
  transition: all 0.35s ease;
}

.metric-item:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.08);
  border-color: rgba(163, 230, 53, 0.4);
}

.metric-value {
  display: block;
  font-family: 'Inter', sans-serif;
  font-size: 2.2rem;
  font-weight: 800;
  color: #1E1E24;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}

.metric-label {
  font-family: 'Inter', sans-serif;
  font-size: 0.8rem;
  font-weight: 500;
  color: #5A5A6E;
}

/* --- CTA Buttons --- */
.showcase-cta {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-showcase {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: 'Inter', sans-serif;
  font-size: 1rem;
  font-weight: 600;
  padding: 15px 30px;
  border-radius: 60px;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1.2);
}

.btn-showcase--primary {
  background: linear-gradient(135deg, #A3E635, #84CC16);
  color: #1a1a1a;
  box-shadow: 0 6px 24px rgba(163, 230, 53, 0.35);
}

.btn-showcase--primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 34px rgba(163, 230, 53, 0.5);
}

.btn-showcase--secondary {
  background: transparent;
  color: #1E1E24;
  border: 2px solid rgba(168, 85, 247, 0.35);
  box-shadow: 0 2px 12px rgba(168, 85, 247, 0.08);
}

.btn-showcase--secondary:hover {
  border-color: #A855F7;
  background: rgba(168, 85, 247, 0.04);
  transform: translateY(-3px);
  box-shadow: 0 8px 28px rgba(168, 85, 247, 0.2);
}

.btn-showcase svg {
  transition: transform 0.3s ease;
}

.btn-showcase:hover svg {
  transform: translateX(4px);
}

.btn-showcase--secondary:hover svg {
  transform: rotate(90deg);
}

/* Focus states */
.case-showcase *:focus-visible {
  outline: 2px solid #A855F7;
  outline-offset: 2px;
  border-radius: 4px;
}

/* --------------------------------------
   Scroll-triggered animation classes
-------------------------------------- */
.showcase-layout,
.showcase-metrics,
.showcase-cta {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}

.showcase-layout.is-visible,
.showcase-metrics.is-visible,
.showcase-cta.is-visible {
  opacity: 1;
  transform: translateY(0);
}

