  box-shadow: 0 0 5px rgba(168, 85, 247, 0.35);
}

@keyframes faqParticleFloat {
  0% { transform: translateY(0) translateX(0) scale(1); opacity: 0; }
  10% { opacity: 0.55; }
  90% { opacity: 0.45; }
  100% { transform: translateY(-100vh) translateX(25px) scale(0.2); opacity: 0; }
}

/* Container */
.faq-container {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 860px;
  margin: 0 auto;
  padding: 0 40px;
}

/* Section Header */
.faq-header {
  text-align: center;
  max-width: 720px;
  margin: 0 auto 60px;
}

.faq-label {
  display: inline-block;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #9333EA;
  background: rgba(168, 85, 247, 0.07);
  padding: 8px 20px;
  border-radius: 50px;
  margin-bottom: 20px;
  border: 1px solid rgba(168, 85, 247, 0.18);
}

.faq-heading {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: clamp(2rem, 4.2vw, 3.2rem);
  font-weight: 800;
  line-height: 1.2;
  color: #1E1E24;
  margin: 0 0 16px 0;
  letter-spacing: -0.03em;
}

.faq-description {
  font-family: 'Inter', sans-serif;
  font-size: 1.05rem;
  line-height: 1.7;
  color: #5A5A6E;
  margin: 0;
}

/* Accordion */
.faq-accordion {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 50px;
}

/* FAQ Item */
.faq-item {
  background: rgba(255, 255, 255, 0.48);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.65);
  border-radius: 18px;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.04);
  transition: border-color 0.3s, box-shadow 0.3s;
  overflow: hidden;
}

.faq-item:hover {
  border-color: rgba(163, 230, 53, 0.4);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.06);
}

/* Question Button */
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 24px;
  font-family: 'Inter', sans-serif;
  font-size: 1.05rem;
  font-weight: 700;
  color: #1E1E24;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
  letter-spacing: -0.01em;
  transition: color 0.3s;
}

.faq-question:hover {
  color: #A855F7;
}

.faq-question:focus-visible {
  outline: 2px solid #A855F7;
  outline-offset: -2px;
  border-radius: 4px;
}

.faq-question-text {
  flex: 1;
}

/* Chevron Icon */
.faq-chevron {
  flex-shrink: 0;
  color: #A855F7;
  transition: transform 0.35s ease;
}

.faq-item.active .faq-chevron {
  transform: rotate(180deg);
}

/* Answer Wrapper */
.faq-answer-wrapper {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.active .faq-answer-wrapper {
  max-height: 300px; /* large enough, overridden by JS */
}

.faq-answer {
  padding: 0 24px 20px;
  font-family: 'Inter', sans-serif;
  font-size: 0.95rem;
  line-height: 1.65;
  color: #5A5A6E;
}

/* Contact Banner */
.faq-banner {
  position: relative;
  background: rgba(255, 255, 255, 0.45);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid rgba(255, 255, 255, 0.65);
  border-radius: 24px;
  padding: 46px 48px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.05);
  overflow: hidden;
}

.faq-banner-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.faq-banner-glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.25;
}

.faq-banner-glow--left {
  width: 260px;
  height: 260px;
  background: rgba(168, 85, 247, 0.18);
  top: -30%;
  left: -6%;
}

.faq-banner-glow--right {
  width: 240px;
  height: 240px;
  background: rgba(163, 230, 53, 0.15);
  bottom: -25%;
  right: -5%;
}

.faq-banner-content {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 36px;
  flex-wrap: wrap;
}

.faq-banner-text {
  flex: 1;
  min-width: 250px;
}

.faq-banner-title {
  font-family: 'Inter', sans-serif;
  font-size: clamp(1.35rem, 2.5vw, 1.75rem);
  font-weight: 800;
  color: #1E1E24;
  margin: 0 0 10px 0;
  letter-spacing: -0.02em;
  line-height: 1.25;
}

.faq-banner-desc {
  font-family: 'Inter', sans-serif;
  font-size: 0.95rem;
  line-height: 1.65;
  color: #5A5A6E;
  margin: 0;
  max-width: 540px;
}

.faq-banner-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  flex-shrink: 0;
}

/* Buttons */
.faq-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: 'Inter', sans-serif;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 14px 28px;
  border-radius: 60px;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1.2);
  white-space: nowrap;
}

.faq-btn--primary {
  background: linear-gradient(135deg, #A3E635, #84CC16);
  color: #1a1a1a;
  box-shadow: 0 6px 24px rgba(163, 230, 53, 0.35);
}

.faq-btn--primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 34px rgba(163, 230, 53, 0.5);
}

.faq-btn--secondary {
  background: transparent;
  color: #1E1E24;
  border: 2px solid rgba(168, 85, 247, 0.35);
  box-shadow: 0 2px 12px rgba(168, 85, 247, 0.08);
}

.faq-btn--secondary:hover {
  border-color: #A855F7;
  background: rgba(168, 85, 247, 0.04);
  transform: translateY(-3px);
  box-shadow: 0 8px 28px rgba(168, 85, 247, 0.2);
}

.faq-btn svg {
  transition: transform 0.3s ease;
}

.faq-btn:hover svg {
  transform: translateX(4px);
}

.faq-btn--secondary:hover svg {
  transform: rotate(90deg);
}

/* Focus states */
.faq-section *:focus-visible {
  outline: 2px solid #A855F7;
  outline-offset: 2px;
  border-radius: 4px;
}

/* ==================================================
START: Final Call To Action Section
================================================== */
/* --- Final CTA Section --- */
.cta-final {
  position: relative;
  padding: 110px 0 100px;
  background: var(--bg-white, #FAFBFC);
  overflow: hidden;
  isolation: isolate;
}

/* Background Layers */
.cta-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.cta-mesh-gradient {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 50% 40% at 25% 35%, rgba(163, 230, 53, 0.08) 0%, transparent 55%),
    radial-gradient(ellipse 60% 50% at 70% 60%, rgba(168, 85, 247, 0.07) 0%, transparent 55%),
    radial-gradient(ellipse 40% 35% at 50% 25%, rgba(163, 230, 53, 0.05) 0%, transparent 60%);
  animation: ctaMeshShift 20s ease-in-out infinite alternate;
}

@keyframes ctaMeshShift {
  0% { transform: scale(1) translate(0, 0); }
  100% { transform: scale(1.04) translate(0.4%, -0.3%); }
}

.cta-tech-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(163, 230, 53, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(168, 85, 247, 0.03) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse 60% 50% at center, black 18%, transparent 65%);
  -webkit-mask-image: radial-gradient(ellipse 60% 50% at center, black 18%, transparent 65%);
}

.cta-circuit-lines {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(135deg, transparent 47%, rgba(168, 85, 247, 0.025) 47%, rgba(168, 85, 247, 0.025) 48%, transparent 48%),
    linear-gradient(225deg, transparent 46%, rgba(163, 230, 53, 0.025) 46%, rgba(163, 230, 53, 0.025) 47%, transparent 47%);
  background-size: 200px 180px, 190px 200px;
  background-position: 10% 30%, 75% 65%;
  animation: ctaCircuitDrift 26s linear infinite;
}

@keyframes ctaCircuitDrift {
  from { background-position: 10% 30%, 75% 65%; }
  to { background-position: 12% 32%, 77% 67%; }
}

.cta-hexagon-outlines {
  position: absolute;
  inset: 0;
  background-image:
    url("data:image/svg+xml,%3Csvg width='70' height='78' viewBox='0 0 70 78' xmlns='http://www.w3.org/2000/svg'%3E%3Cpolygon points='35,4 63,19 63,55 35,70 7,55 7,19' fill='none' stroke='rgba(168,85,247,0.05)' stroke-width='1.3'/%3E%3C/svg%3E");
  background-size: 130px 145px;
  background-position: 80% 20%;
  mask-image: radial-gradient(ellipse 55% 45% at 65% 30%, black 12%, transparent 55%);
  -webkit-mask-image: radial-gradient(ellipse 55% 45% at 65% 30%, black 12%, transparent 55%);
  opacity: 0.65;
}

.cta-radial-glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(110px);
  opacity: 0.4;
  animation: ctaGlowPulse 8s ease-in-out infinite alternate;
}

.cta-radial-glow--green {
  width: 450px;
  height: 450px;
  background: rgba(163, 230, 53, 0.25);
  top: -15%;
  right: -10%;
  animation-delay: 0s;
}

.cta-radial-glow--purple {
  width: 400px;
  height: 400px;
  background: rgba(168, 85, 247, 0.22);
  bottom: -12%;
  left: -8%;
  animation-delay: 4s;
}

@keyframes ctaGlowPulse {
  0% { opacity: 0.3; transform: scale(1); }
  100% { opacity: 0.55; transform: scale(1.15); }
}

/* Floating Particles */
.cta-particles {
  position: absolute;
  inset: 0;
}

.cta-particle {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  animation: ctaParticleFloat linear infinite;
}

.cta-particle--green {
  background: rgba(163, 230, 53, 0.4);
  box-shadow: 0 0 7px rgba(163, 230, 53, 0.5);
}

.cta-particle--purple {
  background: rgba(168, 85, 247, 0.35);
  box-shadow: 0 0 7px rgba(168, 85, 247, 0.45);
}

@keyframes ctaParticleFloat {
  0% { transform: translateY(0) translateX(0) scale(1); opacity: 0; }
  10% { opacity: 0.65; }
  90% { opacity: 0.55; }
  100% { transform: translateY(-105vh) translateX(30px) scale(0.25); opacity: 0; }
}

/* Container */
.cta-container {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 40px;
}

/* Grid Layout */
.cta-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

/* Left Content */
.cta-content {
  animation: ctaFadeUp 0.9s ease-out forwards;
}

@keyframes ctaFadeUp {
  from { opacity: 0; transform: translateY(35px); }
  to { opacity: 1; transform: translateY(0); }
}

.cta-label {
  display: inline-block;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #9333EA;
  background: rgba(168, 85, 247, 0.08);
  padding: 8px 20px;
  border-radius: 50px;
  margin-bottom: 20px;
  border: 1px solid rgba(168, 85, 247, 0.2);
}

.cta-heading {
