  font-weight: 800;
  line-height: 1.15;
  color: #1E1E24;
  margin: 0 0 18px 0;
  letter-spacing: -0.03em;
}

.cta-description {
  font-family: 'Inter', sans-serif;
  font-size: 1.05rem;
  line-height: 1.7;
  color: #5A5A6E;
  margin: 0 0 28px 0;
}

/* Checklist */
.cta-checklist {
  list-style: none;
  margin: 0 0 32px 0;
  padding: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.cta-checklist-item {
  font-family: 'Inter', sans-serif;
  font-size: 0.9rem;
  font-weight: 600;
  color: #1E1E24;
