}

.visual-card {
  background: rgba(255, 255, 255, 0.45);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.65);
  border-radius: 28px;
  padding: 40px 30px;
  box-shadow: 0 12px 45px rgba(0, 0, 0, 0.06);
  transition: transform 0.4s ease;
  height: 100%;
