    display: inline-block;
}

.portfolio-hero__title .highlight-lime::after {
    content: '';
    position: absolute;
    bottom: 2px;
    left: 0;
    width: 100%;
    height: 10px;
    background: rgba(192, 227, 74, 0.25);
    border-radius: 4px;
    z-index: -1;
}

.portfolio-hero__description {
    font-size: 1.1rem;
