}

/* ============================================================
   TWO-COLUMN GRID
   ============================================================ */
.portfolio-faq__grid {
    display: grid;
    grid-template-columns: 35fr 65fr;
    gap: 48px;
    align-items: start;
}

/* ============================================================
   LEFT COLUMN — Intro & Contact
   ============================================================ */
.portfolio-faq__intro {
    position: sticky;
    top: calc(var(--top-bar-height) + var(--nav-height) + 30px);
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.faq-intro__card {
    padding: 32px 28px 28px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    text-align: center;
}

.faq-intro__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    border-radius: 14px;
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
    font-size: 1.4rem;
    margin-bottom: 14px;
    transition: all 0.4s ease;
}

.faq-intro__icon:hover {
    transform: scale(1.05);
    background: var(--color-purple);
    color: var(--color-white);
}

.faq-intro__title {
    font-size: 1.2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 8px 0;
    letter-spacing: -0.02em;
}

.faq-intro__description {
    font-size: 0.88rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    margin: 0 0 20px 0;
}

.faq-intro__buttons {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.btn-faq-contact {
    width: 100%;
    justify-content: center;
    padding: 12px 24px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
}

.btn-faq-contact:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

.btn-faq-schedule {
    width: 100%;
    justify-content: center;
    padding: 12px 24px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.btn-faq-schedule:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

.btn-faq-schedule i {
    transition: transform 0.3s ease;
}

.btn-faq-schedule:hover i {
    transform: translateX(4px);
}

/* ----- Left Visual Decoration ----- */
.faq-intro__visual {
    position: relative;
    height: 100px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid var(--color-gray-light);
    overflow: hidden;
}

.faq-visual__orb {
    position: absolute;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(124, 58, 237, 0.04) 0%, transparent 70%);
    animation: pulseGlow 4s ease-in-out infinite;
}

.faq-visual__orb--1 {
    width: 60px;
    height: 60px;
    top: -20px;
    right: -20px;
    animation-delay: 0s;
}

.faq-visual__orb--2 {
    width: 45px;
    height: 45px;
    bottom: -10px;
    left: -10px;
    animation-delay: 1.5s;
}

.faq-visual__orb--3 {
    width: 30px;
    height: 30px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    animation-delay: 0.8s;
}

.faq-visual__node {
    position: absolute;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.8);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-purple);
    font-size: 0.7rem;
    box-shadow: 0 4px 16px rgba(26, 26, 46, 0.04);
    animation: floatNode 4s ease-in-out infinite;
}

.faq-visual__node--1 {
    top: 15%;
    right: 20%;
    animation-delay: 0s;
}

.faq-visual__node--2 {
    bottom: 15%;
    left: 25%;
    animation-delay: 1.2s;
}

.faq-visual__node--3 {
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    animation-delay: 2.4s;
}

/* ============================================================
   RIGHT COLUMN — Accordion
   ============================================================ */
.portfolio-faq__accordion {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

/* ----- FAQ Item ----- */
.faq-item {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 14px;
    overflow: hidden;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
}

.faq-item:hover {
    border-color: rgba(124, 58, 237, 0.08);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.04);
}

.faq-item--highlight {
    border-color: rgba(192, 227, 74, 0.15);
    background: rgba(255, 255, 255, 0.5);
}

.faq-item--highlight:hover {
    border-color: rgba(192, 227, 74, 0.25);
}

.faq-item.active {
    border-color: rgba(124, 58, 237, 0.12);
    background: rgba(255, 255, 255, 0.7);
    box-shadow: 0 8px 32px rgba(124, 58, 237, 0.04);
}

.faq-item.active--highlight {
    border-color: rgba(192, 227, 74, 0.25);
}

/* ----- Trigger Button ----- */
.faq-item__trigger {
    display: flex;
    align-items: center;
    gap: 14px;
    width: 100%;
    padding: 16px 20px 16px 18px;
    background: transparent;
    border: none;
    cursor: pointer;
    font-family: var(--font-primary);
    font-size: 0.92rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: left;
    transition: all 0.3s ease;
    position: relative;
    z-index: 2;
}

.faq-item__trigger:hover {
    color: var(--color-purple);
}

.faq-item.active .faq-item__trigger {
    color: var(--color-purple);
}

.faq-item--highlight.active .faq-item__trigger {
    color: var(--color-lime-dark);
}

/* Trigger Icon */
.faq-item__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    min-width: 32px;
    border-radius: 8px;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-size: 0.8rem;
    transition: all 0.4s ease;
}

.faq-item__trigger:hover .faq-item__icon {
    background: rgba(124, 58, 237, 0.1);
    transform: scale(1.05);
}

.faq-item.active .faq-item__icon {
    background: var(--color-purple);
    color: var(--color-white);
}

.faq-item--highlight.active .faq-item__icon {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

/* Trigger Question */
.faq-item__question {
    flex: 1;
    min-width: 0;
}

/* Trigger Indicator */
.faq-item__indicator {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    min-width: 28px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.04);
    color: var(--color-gray-mid);
    font-size: 0.75rem;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
    flex-shrink: 0;
}

.faq-item__trigger:hover .faq-item__indicator {
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
}

.faq-item.active .faq-item__indicator {
    background: var(--color-purple);
    color: var(--color-white);
    transform: rotate(45deg);
}

.faq-item--highlight.active .faq-item__indicator {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

/* ----- Answer ----- */
.faq-item__answer {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94),
                opacity 0.4s ease,
                padding 0.3s ease;
    opacity: 0;
    padding: 0 20px 0 20px;
}

.faq-item.active .faq-item__answer {
    max-height: 300px;
    opacity: 1;
    padding: 0 20px 20px 20px;
}

.faq-item__answer-content {
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    padding-top: 4px;
    border-top: 1px solid var(--color-gray-light);
}

.faq-item.active .faq-item__answer-content {
    border-top-color: rgba(124, 58, 237, 0.06);
}

.faq-item--highlight.active .faq-item__answer-content {
    border-top-color: rgba(192, 227, 74, 0.12);
}

/* Focus states for accessibility */
.faq-item__trigger:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: -2px;
    border-radius: 14px;
}

.btn-faq-contact:focus-visible,
.btn-faq-schedule:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Portfolio FAQ Section
================================================== */

