/* ==================================================
END: Advanced Search & Smart Filters
================================================== */

/* ==================================================
START: Latest Articles Grid & Enterprise Content Feed
================================================== */

/* ----- Container ----- */
#blog-feed {
    padding: 80px 0 80px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.blog-feed__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.blog-feed__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.blog-feed__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.blog-feed__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.blog-feed__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.blog-feed__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.blog-feed__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.blog-feed__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.blog-feed__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.blog-feed__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.blog-feed__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.blog-feed__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#blog-feed .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#blog-feed .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#blog-feed .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#blog-feed .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#blog-feed .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#blog-feed .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#blog-feed .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.blog-feed__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.blog-feed__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.blog-feed__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.blog-feed__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.blog-feed__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.blog-feed__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   ARTICLE GRID
   ============================================================ */
.blog-feed__grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 28px;
    max-width: 1140px;
    margin: 0 auto 40px;
}

/* ============================================================
   FEED CARD
   ============================================================ */
.feed-card {
    background: var(--color-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    overflow: hidden;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
    display: flex;
    flex-direction: column;
    position: relative;
}

.feed-card:hover {
    transform: translateY(-8px);
    border-color: rgba(124, 58, 237, 0.10);
    box-shadow: 0 20px 60px rgba(124, 58, 237, 0.06);
}

.feed-card[data-featured="true"] {
    border-color: rgba(192, 227, 74, 0.15);
}

.feed-card[data-featured="true"]:hover {
    border-color: rgba(192, 227, 74, 0.25);
}

/* ----- Card Image ----- */
.feed-card__image {
    position: relative;
    overflow: hidden;
    aspect-ratio: 16/9;
    background: var(--color-off-white);
}

.feed-card__placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.feed-card:hover .feed-card__placeholder {
    transform: scale(1.06);
}

/* Placeholder variations */
.feed-card__placeholder--1 {
    background: linear-gradient(135deg, #2D1B69, #7C3AED);
}
.feed-card__placeholder--2 {
    background: linear-gradient(135deg, #1A1A2E, #10A37F);
}
.feed-card__placeholder--3 {
    background: linear-gradient(135deg, #1A1A2E, #2D1B69);
}
.feed-card__placeholder--4 {
    background: linear-gradient(135deg, #1A3A2A, #34D399);
}
.feed-card__placeholder--5 {
    background: linear-gradient(135deg, #1A2A4A, #6366F1);
}
.feed-card__placeholder--6 {
    background: linear-gradient(135deg, #1A1A2E, #F59E0B);
}
.feed-card__placeholder--7 {
    background: linear-gradient(135deg, #0D4A6B, #0EA5E9);
}
.feed-card__placeholder--8 {
    background: linear-gradient(135deg, #4A1A2A, #F472B6);
}
.feed-card__placeholder--9 {
    background: linear-gradient(135deg, #1A3A2A, #34D399);
}
.feed-card__placeholder--10 {
    background: linear-gradient(135deg, #2D1B69, #7C3AED);
}
.feed-card__placeholder--11 {
    background: linear-gradient(135deg, #1A2A4A, #6366F1);
}
.feed-card__placeholder--12 {
    background: linear-gradient(135deg, #1A1A2E, #F59E0B);
}

.placeholder-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    color: rgba(255, 255, 255, 0.9);
    z-index: 2;
    position: relative;
}

.placeholder-content i {
    font-size: 2.4rem;
    opacity: 0.8;
}

.placeholder-content span {
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.05em;
    text-transform: uppercase;
    opacity: 0.5;
}

.placeholder-shapes {
    position: absolute;
    inset: 0;
    overflow: hidden;
    z-index: 1;
}

.placeholder-shapes .shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    pointer-events: none;
}

.placeholder-shapes .shape--1 {
    width: 120px;
    height: 120px;
    top: -30px;
    right: -30px;
}

.placeholder-shapes .shape--2 {
    width: 80px;
    height: 80px;
    bottom: 20px;
    left: 20px;
}

.placeholder-shapes .shape--3 {
    width: 60px;
    height: 60px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* Featured Badge */
.feed-card__featured-badge {
    position: absolute;
    top: 14px;
    left: 14px;
    padding: 4px 12px;
    background: rgba(192, 227, 74, 0.9);
    border-radius: 50px;
    font-size: 0.55rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    letter-spacing: 0.03em;
    text-transform: uppercase;
    z-index: 5;
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.2);
}

/* Hover Overlay */
.feed-card__overlay {
    position: absolute;
    inset: 0;
    background: rgba(26, 26, 46, 0.6);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    opacity: 0;
    transition: opacity 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    z-index: 3;
}

.feed-card:hover .feed-card__overlay {
    opacity: 1;
}

.overlay-bookmark,
.overlay-share {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.15);
    border: 1px solid rgba(255, 255, 255, 0.2);
    color: var(--color-white);
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    transform: translateY(10px);
}

.feed-card:hover .overlay-bookmark,
.feed-card:hover .overlay-share {
    transform: translateY(0);
}

.overlay-bookmark:hover,
.overlay-share:hover {
    background: var(--color-white);
    color: var(--color-purple);
    transform: translateY(-4px) scale(1.05);
}

.overlay-bookmark.active {
    background: var(--color-lime);
    color: var(--color-charcoal);
    border-color: var(--color-lime);
}

/* ----- Card Content ----- */
.feed-card__content {
    padding: 20px 22px 22px;
    display: flex;
    flex-direction: column;
    flex: 1;
}

/* Meta Row */
.feed-card__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px 10px;
    margin-bottom: 10px;
}

.feed-card__category {
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: 2px 10px;
    background: rgba(124, 58, 237, 0.06);
    border-radius: 50px;
}

.feed-card__tech {
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    padding: 2px 8px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid var(--color-gray-light);
    border-radius: 50px;
}

.feed-card__difficulty {
    font-size: 0.5rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    padding: 2px 10px;
    border-radius: 50px;
}

.feed-card__difficulty--beginner {
    background: rgba(52, 211, 153, 0.08);
    color: #34D399;
    border: 1px solid rgba(52, 211, 153, 0.1);
}

.feed-card__difficulty--intermediate {
    background: rgba(251, 191, 36, 0.08);
    color: #FBBF24;
    border: 1px solid rgba(251, 191, 36, 0.1);
}

.feed-card__difficulty--advanced {
    background: rgba(244, 67, 54, 0.08);
    color: #F44336;
    border: 1px solid rgba(244, 67, 54, 0.1);
}

/* Title Group */
.feed-card__title-group {
    flex: 1;
}

.feed-card__title {
    font-size: 1.1rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.3;
    margin: 0 0 8px 0;
}

.feed-card__excerpt {
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0 0 12px 0;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    /* Standard property for line clamping (for compatible browsers/lints) */
    line-clamp: 2;
    /* Standard property for compatibility */
    line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

/* Tags */
.feed-card__tags {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-bottom: 14px;
}

.feed-card__tags span {
    padding: 2px 10px;
    background: rgba(124, 58, 237, 0.06);
    border: 1px solid rgba(124, 58, 237, 0.06);
    border-radius: 50px;
    font-size: 0.5rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.02em;
    transition: all 0.3s ease;
}

.feed-card__tags span:hover {
    background: rgba(124, 58, 237, 0.1);
    border-color: rgba(124, 58, 237, 0.1);
}

/* Footer */
.feed-card__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 14px;
    border-top: 1px solid var(--color-gray-light);
    margin-bottom: 12px;
}

.feed-card__author {
    display: flex;
    align-items: center;
    gap: 8px;
}

.feed-card__avatar {
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--color-purple), var(--color-purple-dark));
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.feed-card__avatar span {
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-white);
}

.feed-card__author-name {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.feed-card__stats {
    display: flex;
    align-items: center;
    gap: 12px;
}

.feed-card__stats .stat {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 4px;
}

.feed-card__stats .stat i {
    font-size: 0.6rem;
}

/* Actions */
.feed-card__actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 8px;
}

.feed-card__info {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
}

.feed-card__info i {
    font-size: 0.6rem;
    margin-right: 2px;
}

.feed-card__link {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-decoration: none;
    transition: all 0.3s ease;
}

.feed-card__link i {
    font-size: 0.6rem;
    transition: transform 0.3s ease;
}

.feed-card__link:hover {
    color: var(--color-purple-dark);
}

.feed-card__link:hover i {
    transform: translateX(4px);
}

/* ============================================================
   LOAD MORE
   ============================================================ */
.blog-feed__load-more {
    text-align: center;
    padding: 8px 0;
    max-width: 820px;
    margin: 0 auto;
}

.btn-load-more-feed {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 14px 36px;
    background: var(--color-off-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 50px;
    font-family: var(--font-primary);
    font-size: 0.9rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    cursor: pointer;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.btn-load-more-feed:hover {
    border-color: var(--color-purple);
    color: var(--color-purple);
    transform: translateY(-3px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.06);
}

.btn-load-more-feed i {
    font-size: 0.7rem;
    transition: transform 0.3s ease;
}

.btn-load-more-feed:hover i {
    transform: translateY(4px);
}

.feed-loading-spinner {
    display: none;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 20px 0;
}

.feed-loading-spinner.visible {
    display: flex;
}

.feed-loading-spinner .spinner-dot {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--color-purple);
    animation: searchDotPulse 1.2s ease-in-out infinite;
}

.feed-loading-spinner .spinner-dot:nth-child(2) {
    animation-delay: 0.2s;
}

.feed-loading-spinner .spinner-dot:nth-child(3) {
    animation-delay: 0.4s;
}

/* ============================================================
   PAGINATION
   ============================================================ */
.blog-feed__pagination {
    max-width: 820px;
    margin: 24px auto 0;
    display: flex;
    justify-content: center;
}

.pagination {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
}

.page-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 16px;
    background: var(--color-off-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 10px;
    font-family: var(--font-primary);
