}

.page-ellipsis {
    padding: 8px 4px;
    font-size: 0.82rem;
    color: var(--color-gray-mid);
}

/* ============================================================
   EMPTY STATE
   ============================================================ */
.blog-feed__empty {
    text-align: center;
    padding: 60px 20px;
