    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.trending-content__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.trending-content__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.trending-content__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.trending-content__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.trending-content__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.trending-content__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#trending-content .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#trending-content .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#trending-content .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#trending-content .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#trending-content .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#trending-content .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#trending-content .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.trending-content__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.trending-content__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.trending-content__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.trending-content__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.trending-content__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.trending-content__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   FEATURED TRENDING ARTICLE
   ============================================================ */
.trending-content__featured {
    margin-bottom: 48px;
}

.trending-featured {
    display: grid;
    grid-template-columns: 40fr 60fr;
    gap: 32px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.trending-featured:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

/* ----- Featured Image ----- */
.trending-featured__image {
    position: relative;
    overflow: hidden;
    min-height: 300px;
}

.trending-featured__placeholder--featured {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A1A2E, #7C3AED);
    position: relative;
    overflow: hidden;
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.trending-featured:hover .trending-featured__placeholder--featured {
    transform: scale(1.04);
}

.trending-featured__placeholder--featured .placeholder-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    color: rgba(255, 255, 255, 0.9);
    z-index: 2;
    position: relative;
}

.trending-featured__placeholder--featured .placeholder-content i {
    font-size: 3.6rem;
    opacity: 0.8;
}

.trending-featured__placeholder--featured .placeholder-content span {
    font-size: 1rem;
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.05em;
    text-transform: uppercase;
    opacity: 0.5;
}

.trending-featured__placeholder--featured .placeholder-shapes {
    position: absolute;
    inset: 0;
    overflow: hidden;
    z-index: 1;
}

.trending-featured__placeholder--featured .placeholder-shapes .shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.05);
    pointer-events: none;
}

.trending-featured__placeholder--featured .placeholder-shapes .shape--1 {
    width: 160px;
    height: 160px;
    top: -40px;
    right: -40px;
}

.trending-featured__placeholder--featured .placeholder-shapes .shape--2 {
    width: 100px;
    height: 100px;
    bottom: 30px;
    left: 30px;
}

.trending-featured__placeholder--featured .placeholder-shapes .shape--3 {
    width: 80px;
    height: 80px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.trending-featured__badge {
    position: absolute;
    top: 16px;
    left: 16px;
    padding: 4px 14px;
    background: rgba(251, 191, 36, 0.9);
    border-radius: 50px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    letter-spacing: 0.03em;
    text-transform: uppercase;
    z-index: 5;
    box-shadow: 0 4px 16px rgba(251, 191, 36, 0.2);
}

/* ----- Featured Content ----- */
.trending-featured__content {
    padding: 32px 36px 32px 0;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.trending-featured__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px 16px;
}

.trending-featured__category {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: 2px 12px;
    background: rgba(124, 58, 237, 0.08);
    border-radius: 50px;
}

.trending-featured__time,
.trending-featured__date {
    font-size: 0.72rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 4px;
}

.trending-featured__time i,
.trending-featured__date i {
    font-size: 0.6rem;
}

.trending-featured__title {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    line-height: 1.2;
    margin: 0;
    letter-spacing: -0.02em;
}

.trending-featured__excerpt {
    font-size: 0.95rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    margin: 0;
}

.trending-featured__stats {
    display: flex;
    align-items: center;
    gap: 16px;
}

.trending-featured__stats .stat {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 4px;
}

.trending-featured__stats .stat i {
    font-size: 0.7rem;
}

.trending-featured__tags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.trending-featured__tags span {
    padding: 3px 12px;
    background: rgba(124, 58, 237, 0.06);
    border: 1px solid rgba(124, 58, 237, 0.08);
    border-radius: 50px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.02em;
}

.btn-trending-read {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
    width: fit-content;
}

.btn-trending-read:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

/* ============================================================
   THREE CONTENT COLUMNS
   ============================================================ */
.trending-content__columns {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 28px;
    margin-bottom: 48px;
}

/* ----- Column ----- */
.trending-column {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 22px 20px 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.trending-column:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.trending-column__header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 16px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--color-gray-light);
}

.trending-column__icon {
    font-size: 1.2rem;
}

.trending-column__title {
    font-size: 1rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

/* ----- Trending Item ----- */
.trending-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 8px;
    border-radius: 10px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    border-bottom: 1px solid var(--color-gray-light);
}

.trending-item:last-child {
    border-bottom: none;
}

.trending-item:hover {
    background: rgba(255, 255, 255, 0.5);
    transform: translateX(4px);
}

.trending-item__thumb {
    width: 40px;
    height: 40px;
    min-width: 40px;
    border-radius: 8px;
    flex-shrink: 0;
    background: linear-gradient(135deg, #7C3AED, #A78BFA);
}

.trending-item:nth-child(2) .trending-item__thumb {
    background: linear-gradient(135deg, #0EA5E9, #38BDF8);
}
.trending-item:nth-child(3) .trending-item__thumb {
    background: linear-gradient(135deg, #34D399, #6EE7B7);
}
.trending-item:nth-child(4) .trending-item__thumb {
    background: linear-gradient(135deg, #F59E0B, #FBBF24);
}
.trending-item:nth-child(5) .trending-item__thumb {
    background: linear-gradient(135deg, #EF4444, #F87171);
}

.trending-item__content {
    flex: 1;
    min-width: 0;
}

.trending-item__category {
    font-size: 0.5rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.trending-item__title {
    font-size: 0.82rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.3;
    margin: 2px 0;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.trending-item__meta {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
}

.trending-item__meta i {
    font-size: 0.5rem;
    margin-right: 2px;
}

.trending-item__badge {
    font-size: 0.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-gray-mid);
    background: rgba(255, 255, 255, 0.3);
    padding: 2px 8px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    flex-shrink: 0;
}

.trending-item__badge--popular {
    background: rgba(251, 191, 36, 0.08);
    color: #FBBF24;
    border-color: rgba(251, 191, 36, 0.1);
}

.trending-item__badge--editors {
    background: rgba(244, 67, 54, 0.08);
    color: #F44336;
    border-color: rgba(244, 67, 54, 0.1);
}

.trending-item--featured {
    background: rgba(255, 255, 255, 0.3);
    border-radius: 10px;
}

/* ============================================================
   POPULAR TOPICS CLOUD
   ============================================================ */
.trending-content__topics {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 28px 32px 24px;
    box-shadow: var(--shadow-glass);
    margin-bottom: 48px;
}

.topics-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.topics-header__icon {
    font-size: 1.4rem;
}

.topics-header__title {
    font-size: 1.05rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.topics-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
}

.topics-cloud {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 12px 20px;
}

.topic-item {
    display: inline-block;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    cursor: default;
    padding: 4px 8px;
    border-radius: 8px;
    position: relative;
}

.topic-item::after {
    content: attr(data-count);
    font-size: 0.5rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 1px 6px;
    border-radius: 50px;
    margin-left: 4px;
    transition: all 0.3s ease;
}

.topic-item:hover {
    color: var(--color-purple);
    transform: translateY(-3px) scale(1.05);
}

.topic-item:hover::after {
    background: var(--color-purple);
    color: var(--color-white);
}

.topic-item--xl {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
}
.topic-item--lg {
    font-size: 1.25rem;
    font-weight: var(--font-weight-semibold);
}
.topic-item--md {
    font-size: 1rem;
}
.topic-item--sm {
    font-size: 0.85rem;
}

/* ============================================================
   EDITOR'S CHOICE CAROUSEL
   ============================================================ */
.trending-content__carousel {
    margin-bottom: 48px;
}

.carousel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 20px;
}

.carousel-header__left {
    display: flex;
    align-items: center;
    gap: 12px;
}

.carousel-header__icon {
    font-size: 1.3rem;
}

.carousel-header__title {
    font-size: 1.1rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.carousel-header__right {
    display: flex;
    gap: 8px;
}

.carousel-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: var(--color-off-white);
    border: 1px solid var(--color-gray-light);
    color: var(--color-charcoal);
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.carousel-btn:hover {
    border-color: var(--color-purple);
    color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(124, 58, 237, 0.04);
}

.carousel-btn:disabled {
    opacity: 0.3;
    cursor: not-allowed;
    transform: none;
}

.carousel-track-wrapper {
    overflow: hidden;
    border-radius: 18px;
}

.carousel-track {
    display: flex;
    gap: 20px;
    transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

/* ----- Carousel Card ----- */
.carousel-card {
    min-width: calc(33.333% - 14px);
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 16px;
    overflow: hidden;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
    display: flex;
    flex-direction: column;
}

.carousel-card:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.08);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.carousel-card__image {
    position: relative;
    aspect-ratio: 16/9;
    overflow: hidden;
    background: var(--color-off-white);
}

.carousel-card__placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    color: rgba(255, 255, 255, 0.8);
    transition: transform 0.5s ease;
}

.carousel-card:hover .carousel-card__placeholder {
    transform: scale(1.04);
}

.carousel-card__placeholder--1 {
    background: linear-gradient(135deg, #1A1A2E, #7C3AED);
}
.carousel-card__placeholder--2 {
    background: linear-gradient(135deg, #1A1A2E, #2D1B69);
}
.carousel-card__placeholder--3 {
    background: linear-gradient(135deg, #1A2A4A, #6366F1);
}
.carousel-card__placeholder--4 {
    background: linear-gradient(135deg, #1A3A2A, #34D399);
}
.carousel-card__placeholder--5 {
    background: linear-gradient(135deg, #1A1A1A, #10A37F);
}
.carousel-card__placeholder--6 {
    background: linear-gradient(135deg, #4A1A2A, #F472B6);
}

.carousel-card__badge {
    position: absolute;
    top: 10px;
    left: 10px;
    padding: 3px 10px;
    background: rgba(192, 227, 74, 0.9);
    border-radius: 50px;
    font-size: 0.5rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    letter-spacing: 0.03em;
    text-transform: uppercase;
    z-index: 5;
}

.carousel-card__content {
    padding: 14px 16px 16px;
    display: flex;
    flex-direction: column;
    flex: 1;
}

.carousel-card__category {
    font-size: 0.55rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 4px;
}

.carousel-card__title {
    font-size: 0.9rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.3;
    margin: 0 0 8px 0;
}

.carousel-card__author {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 8px;
}

.carousel-card__avatar {
    width: 24px;
    height: 24px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--color-purple), var(--color-purple-dark));
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.5rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-white);
}

.carousel-card__author-name {
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.carousel-card__meta {
    font-size: 0.65rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin-bottom: 10px;
}

.carousel-card__meta i {
    font-size: 0.55rem;
    margin-right: 2px;
}

.carousel-card__link {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-decoration: none;
    transition: all 0.3s ease;
    margin-top: auto;
}

.carousel-card__link i {
    font-size: 0.55rem;
    transition: transform 0.3s ease;
}

.carousel-card__link:hover {
    color: var(--color-purple-dark);
}

.carousel-card__link:hover i {
    transform: translateX(4px);
}

/* Carousel Indicators */
.carousel-indicators {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    margin-top: 16px;
}

.indicator-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--color-gray-light);
    cursor: pointer;
    transition: all 0.3s ease;
}

.indicator-dot:hover {
    background: var(--color-purple);
    transform: scale(1.2);
}

.indicator-dot.active {
    background: var(--color-purple);
    width: 24px;
    border-radius: 4px;
}

/* ============================================================
   TRENDING METRICS
   ============================================================ */
.trending-content__metrics {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 32px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
}

.metrics-grid {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 16px;
}

.trending-metric {
    text-align: center;
    padding: 8px 4px;
    transition: all 0.3s ease;
}

.trending-metric:hover {
    transform: translateY(-3px);
}

.trending-metric__icon {
    display: block;
    font-size: 1.4rem;
    margin-bottom: 4px;
}

.trending-metric__label {
    display: block;
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.trending-metric__value {
    display: block;
    font-size: 1.1rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin-top: 2px;
}

/* ============================================================
   VIEW ALL BUTTON
   ============================================================ */
.trending-content__view-all {
    text-align: center;
}

.btn-view-trending {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-view-trending:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

/* ----- Focus States ----- */
.trending-featured__link:focus-visible,
.btn-trending-read:focus-visible,
.carousel-card__link:focus-visible,
.btn-view-trending:focus-visible,
.carousel-btn:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Trending Articles, Popular Topics & Editor's Choice
================================================== */

/* ==================================================
START: Newsletter, Community & Content Subscription Hub
================================================== */

/* ----- Container ----- */
#community-subscription {
