    opacity: 0.06;
    pointer-events: none;
}

.community-subscription__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.community-subscription__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
