   ============================================================ */
.meet-authors__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.meet-authors__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.meet-authors__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.meet-authors__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.meet-authors__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   FEATURED AUTHOR
   ============================================================ */
.meet-authors__featured {
    margin-bottom: 48px;
}

.featured-author {
    display: flex;
    align-items: center;
    gap: 40px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    padding: 36px 40px 36px 36px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.featured-author:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

/* ----- Featured Image ----- */
.featured-author__image {
    flex-shrink: 0;
}

.featured-author__placeholder {
    width: 140px;
    height: 140px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--color-purple), var(--color-purple-dark));
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 8px 32px rgba(124, 58, 237, 0.15);
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.featured-author:hover .featured-author__placeholder {
    transform: scale(1.02);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.2);
}

.featured-author__initial {
    font-size: 3.2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-white);
    letter-spacing: -0.02em;
}

/* ----- Featured Content ----- */
.featured-author__content {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.featured-author__header {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.featured-author__name {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0;
    letter-spacing: -0.02em;
}

.featured-author__position {
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.featured-author__bio {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    margin: 0;
}

/* Expertise Tags */
.featured-author__expertise {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.expertise-tag {
    padding: 3px 12px;
    background: rgba(124, 58, 237, 0.06);
    border: 1px solid rgba(124, 58, 237, 0.08);
    border-radius: 50px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.02em;
    transition: all 0.3s ease;
}

.expertise-tag:hover {
    background: rgba(124, 58, 237, 0.1);
    border-color: rgba(124, 58, 237, 0.12);
}

/* Stats */
.featured-author__stats {
    display: flex;
    align-items: center;
    gap: 16px 24px;
    padding: 8px 0 2px;
}

.featured-author__stats .stat-item {
    display: flex;
    align-items: baseline;
    gap: 4px;
}

.featured-author__stats .stat-value {
    font-size: 1.1rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
}

.featured-author__stats .stat-label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
}

.featured-author__stats .stat-divider {
    width: 1.5px;
    height: 20px;
    background: var(--color-gray-light);
}

/* Social */
.featured-author__social {
    display: flex;
    gap: 8px;
}

.featured-author__social .social-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.5);
    border: 1px solid var(--color-gray-light);
    color: var(--color-gray-mid);
    font-size: 0.8rem;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    text-decoration: none;
}

.featured-author__social .social-link:hover {
    transform: translateY(-3px) scale(1.05);
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.15);
}

.btn-featured-author {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
    width: fit-content;
}

.btn-featured-author:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

/* ============================================================
   AUTHOR GRID
   ============================================================ */
.meet-authors__grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
    max-width: 1100px;
    margin: 0 auto 40px;
}

/* ----- Author Card ----- */
.author-card {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 24px 20px 20px;
    text-align: center;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
    display: flex;
    flex-direction: column;
    align-items: center;
}

.author-card:hover {
    transform: translateY(-6px);
    border-color: rgba(124, 58, 237, 0.08);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

/* ----- Author Image ----- */
.author-card__image {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--color-purple), var(--color-purple-dark));
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 12px;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
    flex-shrink: 0;
}

.author-card:hover .author-card__image {
    transform: scale(1.05);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.15);
}

.author-card__initial {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-white);
}

/* Alternate colors */
