    background: linear-gradient(135deg, #0EA5E9, #0284C7);
}
.author-card:nth-child(3) .author-card__image {
    background: linear-gradient(135deg, #34D399, #059669);
}
.author-card:nth-child(4) .author-card__image {
    background: linear-gradient(135deg, #F59E0B, #D97706);
}
.author-card:nth-child(5) .author-card__image {
    background: linear-gradient(135deg, #EC4899, #BE185D);
}
.author-card:nth-child(6) .author-card__image {
    background: linear-gradient(135deg, #8B5CF6, #6D28D9);
}

/* ----- Card Content ----- */
.author-card__name {
    font-size: 1rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0 0 2px 0;
}

.author-card__position {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    display: block;
    margin-bottom: 10px;
}

.author-card__expertise {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 4px;
    margin-bottom: 10px;
}

.author-card__expertise span {
    padding: 2px 10px;
    background: rgba(124, 58, 237, 0.06);
    border: 1px solid rgba(124, 58, 237, 0.06);
    border-radius: 50px;
    font-size: 0.5rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.02em;
}

.author-card__bio {
    font-size: 0.78rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.5;
    flex: 1;
    margin: 0 0 14px 0;
}

.author-card__stats {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    padding: 10px 0 0;
    border-top: 1px solid var(--color-gray-light);
    width: 100%;
    margin-bottom: 14px;
}

.author-card__stats .stat-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1px;
}

.author-card__stats .stat-value {
    font-size: 0.9rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
}

.author-card__stats .stat-label {
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.author-card__link {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-decoration: none;
