}

.author-card__link:hover {
    color: var(--color-purple-dark);
}

.author-card__link:hover i {
    transform: translateX(4px);
}

/* ============================================================
   AUTHOR STATISTICS
   ============================================================ */
.meet-authors__stats {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 32px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
