}

.stat-card__number {
    font-size: 2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 2px;
}

.stat-card__number .stat-number {
    display: inline-block;
}

.stat-card__number .stat-suffix {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.stat-card__number .stat-label--weekly {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
}

.stat-card__label {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ============================================================
   CONTRIBUTION TYPES
   ============================================================ */
.meet-authors__contributions {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 20px 24px 18px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 16px;
    box-shadow: var(--shadow-glass);
    text-align: center;
}

.contributions-label {
    display: block;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin-bottom: 12px;
}

.contributions-grid {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 8px 14px;
}

.contribution-badge {
    padding: 4px 16px;
    background: var(--color-off-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 50px;
    font-size: 0.75rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    cursor: default;
}

.contribution-badge:hover {
    transform: translateY(-2px);
    border-color: var(--color-lime);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.08);
    background: var(--color-white);
}

/* ============================================================
   VIEW ALL BUTTON
   ============================================================ */
.meet-authors__view-all {
    text-align: center;
}

.btn-view-authors {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-view-authors:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

/* ----- Focus States ----- */
.btn-featured-author:focus-visible,
.author-card__link:focus-visible,
.btn-view-authors:focus-visible,
.featured-author__social .social-link:focus-visible {
