}

.impact-stat__number .stat-suffix {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.impact-stat__number .stat-label--weekly {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
}

.impact-stat__label {
    font-size: 0.8rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ============================================================
   TRUST & QUALITY INDICATORS
   ============================================================ */
.blog-impact__trust {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 20px 24px 18px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 16px;
    box-shadow: var(--shadow-glass);
}

.trust-grid {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 12px 24px;
}

.trust-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.82rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    cursor: default;
}

.trust-item:hover {
    color: var(--color-purple);
    transform: translateY(-2px);
}

.trust-item__icon {
    color: var(--color-lime);
    font-size: 0.85rem;
}

.trust-item__text {
    line-height: 1.2;
}

/* ============================================================
   CONTENT JOURNEY
   ============================================================ */
.blog-impact__journey {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 32px 20px;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.blog-impact__journey:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.journey-header {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-bottom: 20px;
}

.journey-header__icon {
    font-size: 1.4rem;
}

.journey-header__title {
    font-size: 1.05rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.journey-steps {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    flex-wrap: wrap;
}

.journey-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 10px 16px;
    background: rgba(255, 255, 255, 0.5);
    border: 1px solid var(--color-gray-light);
    border-radius: 12px;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    min-width: 80px;
}

.journey-step:hover {
    background: rgba(255, 255, 255, 0.85);
    border-color: var(--color-lime);
    transform: translateY(-4px) scale(1.02);
    box-shadow: 0 8px 24px rgba(192, 227, 74, 0.06);
}

.journey-step__icon {
    font-size: 1.3rem;
    color: var(--color-purple);
}

.journey-step__label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.journey-arrow {
    color: var(--color-gray-light);
    font-size: 0.8rem;
}

.journey-arrow i {
    transition: transform 0.3s ease;
}

.journey-steps:hover .journey-arrow i {
    animation: journeyArrowPulse 1.2s ease-in-out infinite;
}

@keyframes journeyArrowPulse {
    0%, 100% { transform: translateX(0); }
    50% { transform: translateX(4px); }
}

/* ============================================================
   FINAL CALL-TO-ACTION
   ============================================================ */
.blog-impact__cta {
    max-width: 820px;
    margin: 0 auto 40px;
}

.cta-card {
    position: relative;
    background: rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    padding: 44px 48px 40px;
    box-shadow: var(--shadow-glass);
    text-align: center;
    transition: all 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    overflow: hidden;
}

.cta-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 24px 64px rgba(124, 58, 237, 0.08);
}

.cta-card__glow {
    position: absolute;
    inset: -2px;
    border-radius: 24px;
    background: linear-gradient(135deg, rgba(192, 227, 74, 0.12), rgba(124, 58, 237, 0.08));
    z-index: 0;
    opacity: 0;
    transition: opacity 0.6s ease;
    pointer-events: none;
}

.cta-card:hover .cta-card__glow {
    opacity: 1;
}

.cta-card__content {
    position: relative;
    z-index: 2;
}

.cta-card__header {
    margin-bottom: 24px;
}

.cta-card__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 60px;
    height: 60px;
    border-radius: 16px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    color: var(--color-white);
    font-size: 1.6rem;
    margin-bottom: 16px;
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.15);
}

.cta-card__title {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 8px 0;
    letter-spacing: -0.02em;
}

.cta-card__description {
    font-size: 0.95rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    max-width: 520px;
    margin: 0 auto;
}

.cta-card__buttons {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    flex-wrap: wrap;
}

.btn-cta-primary {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-cta-primary:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

.btn-cta-secondary {
    padding: 14px 32px;
    font-size: 0.95rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.btn-cta-secondary:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-3px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

.btn-cta-secondary i {
    transition: transform 0.3s ease;
}

.btn-cta-secondary:hover i {
    transform: translateX(4px);
}

/* ============================================================
   QUICK LINKS
   ============================================================ */
.blog-impact__quick-links {
    max-width: 820px;
    margin: 0 auto;
}

.quick-links-grid {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 12px;
}

.quick-link {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 16px 12px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 14px;
    text-decoration: none;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
}

.quick-link:hover {
    transform: translateY(-6px);
    border-color: rgba(124, 58, 237, 0.10);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.06);
    background: rgba(255, 255, 255, 0.7);
}

.quick-link__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.quick-link:hover .quick-link__icon {
    transform: scale(1.1);
    color: var(--color-lime-dark);
}

.quick-link__text {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: center;
    line-height: 1.2;
}

/* ----- Focus States ----- */
.btn-cta-primary:focus-visible,
.btn-cta-secondary:focus-visible,
.quick-link:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Blog Statistics, Knowledge Impact & Final CTA
================================================== */

/* ==================================================
START: Documentation Hero Banner
================================================== */

/* ----- Container ----- */
#docs-hero {
