    height: 450px;
    bottom: -120px;
    left: -80px;
    background: var(--color-lime);
    opacity: 0.05;
}

.docs-hero__glow--3 {
    width: 300px;
    height: 300px;
    top: 30%;
    left: 40%;
    background: var(--color-purple);
    opacity: 0.03;
}

.docs-hero__glow--4 {
    width: 250px;
    height: 250px;
    bottom: 30%;
    right: 25%;
    background: var(--color-lime);
    opacity: 0.04;
}

.docs-hero__orb {
