    pointer-events: none;
}

/* Floating Particles */
#docs-hero .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 8s ease-in-out infinite;
}

#docs-hero .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 6%;
