}

#docs-hero .particle--3 {
    width: 6px;
    height: 6px;
    top: 22%;
    left: 85%;
    animation-delay: 3s;
}

#docs-hero .particle--4 {
    width: 10px;
    height: 10px;
    top: 85%;
    left: 10%;
    animation-delay: 0.8s;
}

#docs-hero .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 3%;
    animation-delay: 2.2s;
}

#docs-hero .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 95%;
    animation-delay: 3.8s;
}

/* ----- Container ----- */
.docs-hero__inner {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    gap: 60px;
}

/* ============================================================
   LEFT COLUMN — Content
   ============================================================ */
.docs-hero__content {
