/* ----- Buttons ----- */
.docs-hero__buttons {
    display: flex;
    align-items: center;
    gap: 16px;
    flex-wrap: wrap;
    margin-top: 4px;
}

.btn-docs-primary {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-docs-primary:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

.btn-docs-secondary {
    padding: 14px 32px;
    font-size: 0.95rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.btn-docs-secondary:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-3px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

.btn-docs-secondary i {
    transition: transform 0.3s ease;
}

.btn-docs-secondary:hover i {
    transform: translateX(4px);
}

/* ----- Search Bar ----- */
.docs-hero__search {
    margin-top: 4px;
}

.search-container {
    display: flex;
    align-items: center;
    background: rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1.5px solid var(--color-gray-light);
    border-radius: 50px;
    padding: 4px 4px 4px 18px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-soft);
    gap: 6px;
}

.search-container:focus-within {
    border-color: var(--color-purple);
    box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.06);
}

.search-icon {
    color: var(--color-gray-mid);
    font-size: 0.9rem;
    flex-shrink: 0;
}

.search-input {
    flex: 1;
    padding: 12px 8px;
    background: transparent;
    border: none;
    outline: none;
    font-family: var(--font-primary);
    font-size: 0.9rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-charcoal);
    min-width: 0;
}

.search-input::placeholder {
    color: var(--color-gray-mid);
