    align-items: baseline;
    gap: 4px;
}

.docs-hero__stats .stat-number {
    font-size: 1.2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    display: inline-block;
}

.docs-hero__stats .stat-suffix {
    font-size: 1rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
}

.docs-hero__stats .stat-label {
    font-size: 0.75rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
}

.docs-hero__stats .stat-label--weekly {
    color: var(--color-lime-dark);
    font-weight: var(--font-weight-semibold);
}

.docs-hero__stats .stat-divider {
    width: 1.5px;
    height: 22px;
    background: var(--color-gray-light);
    flex-shrink: 0;
}

/* ============================================================
   RIGHT COLUMN — Premium Visual Composition
   ============================================================ */
.docs-hero__visual {
    flex: 1 1 45%;
    position: relative;
    min-height: 520px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ----- Documentation Mockup ----- */
.docs-visual__mockup {
    position: relative;
    width: 100%;
    max-width: 480px;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: 18px;
    box-shadow: 0 32px 80px rgba(26, 26, 46, 0.08);
    overflow: hidden;
    display: flex;
    z-index: 5;
    transition: all 0.4s ease;
}

.docs-visual__mockup:hover {
    transform: translateY(-4px);
    box-shadow: 0 40px 100px rgba(26, 26, 46, 0.12);
}

/* Sidebar */
.mockup__sidebar {
    width: 140px;
    background: rgba(124, 58, 237, 0.04);
    padding: 16px 14px;
    flex-shrink: 0;
    border-right: 1px solid var(--color-gray-light);
}

.sidebar__header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 14px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--color-gray-light);
}

.sidebar__icon {
    color: var(--color-purple);
    font-size: 0.9rem;
}

.sidebar__title {
    font-size: 0.8rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

.sidebar__nav {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.sidebar__item {
    padding: 6px 10px;
    border-radius: 6px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    transition: all 0.3s ease;
    cursor: default;
}

.sidebar__item:hover {
    color: var(--color-charcoal);
    background: rgba(124, 58, 237, 0.04);
}

.sidebar__item--active {
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.06);
}

/* Content */
.mockup__content {
    flex: 1;
    padding: 16px 18px;
}

.content__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
}

.content__title {
    font-size: 0.85rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

.content__badge {
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-lime-dark);
    padding: 2px 10px;
    background: rgba(192, 227, 74, 0.08);
    border-radius: 50px;
    border: 1px solid rgba(192, 227, 74, 0.1);
}

.content__body {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.content__paragraph {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.content__line {
    display: block;
    height: 6px;
    background: var(--color-gray-light);
    border-radius: 4px;
}

.content__line:nth-child(1) {
    width: 85%;
}
.content__line:nth-child(2) {
    width: 95%;
}
.content__line--short {
    width: 60%;
}

.content__code {
    padding: 10px 12px;
    background: var(--color-charcoal);
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    gap: 2px;
    font-family: 'Courier New', monospace;
}

.code-line {
    font-size: 0.6rem;
    color: rgba(255, 255, 255, 0.8);
}

.code-keyword {
    color: var(--color-lime);
}

.content__actions {
    display: flex;
    gap: 8px;
    margin-top: 4px;
}

.action-btn {
    padding: 4px 14px;
    border-radius: 6px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    cursor: default;
}

.action-btn--primary {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

.action-btn--secondary {
    background: rgba(255, 255, 255, 0.3);
    color: var(--color-gray-mid);
    border: 1px solid var(--color-gray-light);
}

/* ----- Featured Resources (Floating Cards) ----- */
.docs-visual__resource {
    position: absolute;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, 0.25);
    border-radius: 12px;
    padding: 8px 14px;
    box-shadow: 0 16px 48px rgba(26, 26, 46, 0.06);
    display: flex;
    align-items: center;
    gap: 10px;
    z-index: 4;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
    animation: floatCard 5s ease-in-out infinite;
    max-width: 150px;
}

.docs-visual__resource:hover {
    transform: translateY(-4px) scale(1.02);
    box-shadow: 0 24px 64px rgba(124, 58, 237, 0.08);
}

.resource-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    min-width: 28px;
    border-radius: 8px;
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
    font-size: 0.7rem;
    transition: all 0.3s ease;
}

.docs-visual__resource:hover .resource-icon {
    background: var(--color-purple);
    color: var(--color-white);
    transform: scale(1.05);
}

.resource-content {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.resource-label {
    font-size: 0.45rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.resource-value {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

/* Resource positions */
.docs-visual__resource--1 {
    top: 2%;
    right: -10%;
    animation-delay: 0s;
}
.docs-visual__resource--2 {
    bottom: 22%;
    left: -12%;
    animation-delay: 1.2s;
}
.docs-visual__resource--3 {
    bottom: 2%;
    right: 12%;
    animation-delay: 2.4s;
}
.docs-visual__resource--4 {
    top: 28%;
    left: -10%;
    animation-delay: 0.6s;
}
.docs-visual__resource--5 {
    top: 12%;
    left: -6%;
    animation-delay: 1.8s;
}
.docs-visual__resource--6 {
    bottom: 12%;
    right: -8%;
    animation-delay: 3s;
}

/* ----- Decorative Tech Icons ----- */
.docs-visual__tech {
    position: absolute;
    font-size: 1.8rem;
    color: rgba(124, 58, 237, 0.06);
    pointer-events: none;
    z-index: 1;
    animation: floatNode 7s ease-in-out infinite;
}

.docs-visual__tech--1 {
    top: 6%;
    left: 4%;
    font-size: 2.2rem;
    color: rgba(255, 45, 45, 0.05);
    animation-delay: 0s;
}
.docs-visual__tech--2 {
    bottom: 10%;
    right: 3%;
    font-size: 2.4rem;
    color: rgba(97, 218, 251, 0.05);
    animation-delay: 2s;
}
.docs-visual__tech--3 {
    top: 45%;
    left: 2%;
    font-size: 2rem;
    color: rgba(51, 153, 51, 0.05);
    animation-delay: 3.5s;
}
.docs-visual__tech--4 {
    top: 35%;
    right: 2%;
    font-size: 2rem;
    color: rgba(51, 51, 153, 0.05);
    animation-delay: 1.2s;
}

/* ----- Center Pulse Orb ----- */
.docs-visual__orb {
    position: absolute;
    width: 120px;
    height: 120px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(124, 58, 237, 0.05) 0%, transparent 70%);
    animation: pulseGlow 3.5s ease-in-out infinite;
    z-index: 1;
    pointer-events: none;
}

/* ----- Focus States ----- */
.btn-docs-primary:focus-visible,
.btn-docs-secondary:focus-visible,
.search-submit:focus-visible,
.search-clear:focus-visible,
.search-voice:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

.search-input:focus-visible {
    outline: none;
}

/* ==================================================
END: Documentation Hero Banner
================================================== */

/* ==================================================
START: Documentation Categories Hub
================================================== */

/* ----- Container ----- */
#docs-categories {
    padding: 80px 0 80px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.docs-categories__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.docs-categories__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.docs-categories__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.docs-categories__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.docs-categories__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.docs-categories__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.docs-categories__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.docs-categories__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.docs-categories__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.docs-categories__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.docs-categories__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.docs-categories__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#docs-categories .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#docs-categories .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#docs-categories .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#docs-categories .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#docs-categories .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#docs-categories .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#docs-categories .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.docs-categories__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.docs-categories__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.docs-categories__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.docs-categories__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.docs-categories__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.docs-categories__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   FEATURED CATEGORY
   ============================================================ */
.docs-categories__featured {
    margin-bottom: 40px;
}

.featured-category {
    display: flex;
    align-items: center;
    gap: 32px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    padding: 32px 36px 32px 32px;
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.featured-category::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: 24px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    z-index: 0;
    opacity: 0.06;
    pointer-events: none;
}

.featured-category:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.featured-category > * {
    position: relative;
    z-index: 2;
}

.featured-category__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 72px;
    height: 72px;
    border-radius: 20px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    color: var(--color-white);
    font-size: 2rem;
    flex-shrink: 0;
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.15);
}

.featured-category__content {
    flex: 1;
    min-width: 0;
}

.featured-category__badge {
    display: inline-block;
    font-size: 0.55rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-lime-dark);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    background: rgba(192, 227, 74, 0.1);
    padding: 2px 12px;
    border-radius: 50px;
    margin-bottom: 6px;
}

.featured-category__title {
    font-size: 1.4rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 6px 0;
    letter-spacing: -0.02em;
}

.featured-category__description {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0 0 12px 0;
    max-width: 48ch;
}

.featured-category__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px 18px;
    margin-bottom: 14px;
}

.featured-category__count,
.featured-category__time,
.featured-category__update {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 6px;
}

.featured-category__count i,
.featured-category__time i,
.featured-category__update i {
    font-size: 0.7rem;
}

.featured-category__difficulty {
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    padding: 2px 12px;
    border-radius: 50px;
    background: rgba(52, 211, 153, 0.08);
    color: #34D399;
    border: 1px solid rgba(52, 211, 153, 0.1);
}

.btn-featured-docs {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
}

.btn-featured-docs:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

/* Featured Category Visual */
.featured-category__visual {
    position: relative;
    width: 100px;
    height: 100px;
    flex-shrink: 0;
}

.featured-visual__orb {
    position: absolute;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(124, 58, 237, 0.06) 0%, transparent 70%);
    animation: pulseGlow 3.5s ease-in-out infinite;
}

.featured-visual__orb--1 {
    width: 80px;
    height: 80px;
    top: 10px;
    left: 10px;
    animation-delay: 0s;
}

.featured-visual__orb--2 {
    width: 50px;
    height: 50px;
    bottom: 10px;
    right: 10px;
    animation-delay: 1.5s;
}

.featured-visual__node {
    position: absolute;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.8);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-purple);
    font-size: 0.8rem;
    box-shadow: 0 4px 16px rgba(26, 26, 46, 0.04);
    animation: floatNode 4s ease-in-out infinite;
}

.featured-visual__node--1 {
    top: 8px;
    left: 45px;
    animation-delay: 0s;
}

.featured-visual__node--2 {
    bottom: 10px;
    right: 20px;
    animation-delay: 1.2s;
}

.featured-visual__node--3 {
    top: 40px;
    right: 5px;
    animation-delay: 2.4s;
}

/* ============================================================
   FILTER BAR
   ============================================================ */
.docs-categories__filters {
    margin-bottom: 32px;
    padding: 4px 0;
}

.filter-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 8px 12px;
}

.filter-pill {
    padding: 6px 18px;
    background: var(--color-off-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 50px;
    font-family: var(--font-primary);
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-soft);
}

.filter-pill:hover {
    border-color: rgba(124, 58, 237, 0.15);
    color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(124, 58, 237, 0.04);
}

.filter-pill.active {
    background: linear-gradient(135deg, var(--color-lime), var(--color-lime-dark));
    border-color: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.25);
}

.filter-pill:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 2px;
}

/* ============================================================
   CATEGORIES GRID
   ============================================================ */
.docs-categories__grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
    max-width: 1100px;
    margin: 0 auto 40px;
}

/* ============================================================
   CATEGORY CARD
   ============================================================ */
.category-card {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 24px 22px 22px;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.category-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0;
    transition: opacity 0.4s ease;
}

.category-card:hover {
    transform: translateY(-6px);
    border-color: rgba(124, 58, 237, 0.08);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.category-card:hover::before {
    opacity: 1;
}

/* ----- Card Icon ----- */
.category-card__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    border-radius: 12px;
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
    font-size: 1.2rem;
    margin-bottom: 12px;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.category-card:hover .category-card__icon {
    background: var(--color-purple);
    color: var(--color-white);
    transform: scale(1.05);
}

/* Alternate icon colors */
.category-card:nth-child(2):hover .category-card__icon,
.category-card:nth-child(5):hover .category-card__icon,
.category-card:nth-child(8):hover .category-card__icon,
.category-card:nth-child(11):hover .category-card__icon,
.category-card:nth-child(14):hover .category-card__icon,
.category-card:nth-child(17):hover .category-card__icon {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

/* ----- Card Title ----- */
.category-card__title {
    font-size: 1rem;
    font-weight: var(--font-weight-semibold);
