/* ============================================================
   QUICK START TIMELINE
   ============================================================ */
.quick-start__timeline {
    position: relative;
    max-width: 1100px;
    margin: 0 auto 48px;
    padding: 20px 0 30px;
}

.timeline-steps {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    position: relative;
    z-index: 2;
}

.timeline-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    flex: 1;
    min-width: 0;
}

.timeline-step__node {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-bottom: 12px;
    position: relative;
}

.timeline-step__number {
    font-size: 0.55rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    background: var(--color-white);
    padding: 2px 8px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-bottom: 6px;
    transition: all 0.4s ease;
}

.timeline-step.active .timeline-step__number {
    border-color: var(--color-lime);
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.05);
}

.timeline-step__dot {
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: var(--color-white);
    border: 2.5px solid var(--color-gray-light);
    transition: all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
    position: relative;
    z-index: 2;
}

.timeline-step.active .timeline-step__dot {
    border-color: var(--color-lime);
    background: var(--color-lime);
    box-shadow: 0 0 0 6px rgba(192, 227, 74, 0.15);
}

.timeline-step__content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
}

.timeline-step__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.timeline-step.active .timeline-step__icon {
    color: var(--color-lime-dark);
    transform: scale(1.1);
}

.timeline-step__title {
    font-size: 0.78rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
    line-height: 1.3;
}

.timeline-step__description {
    font-size: 0.65rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin: 0;
    line-height: 1.3;
    display: none;
}

.timeline-step__time {
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 4px;
}

.timeline-step__time i {
    font-size: 0.5rem;
}

/* Timeline Connector */
.timeline-connector {
    position: absolute;
    top: 50px;
    left: 10%;
    right: 10%;
    height: 2.5px;
    background: var(--color-gray-light);
    border-radius: 4px;
    overflow: hidden;
    z-index: 1;
}

.timeline-connector__fill {
    height: 100%;
    width: 0%;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    border-radius: 4px;
    transition: width 1.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.timeline-connector__fill.animated {
    width: 100%;
}

