    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
    width: fit-content;
}

.btn-featured-guide:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

/* ============================================================
   QUICK RESOURCES
   ============================================================ */
.quick-start__resources {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.quick-start__resources:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.resources-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 16px;
}

.resources-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.resources-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.resources-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px 12px;
}

.resource-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    text-decoration: none;
    color: var(--color-charcoal);
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.resource-item:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.resource-item__icon {
    color: var(--color-lime);
    font-size: 0.85rem;
    flex-shrink: 0;
}

.resource-item__label {
    font-size: 0.75rem;
    font-weight: var(--font-weight-medium);
    line-height: 1.2;
}

/* ============================================================
   ONBOARDING PROGRESS
   ============================================================ */
.quick-start__progress {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
}

.progress-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
}

.progress-stat {
    text-align: center;
    padding: 4px 8px;
    transition: all 0.3s ease;
}

.progress-stat:hover {
    transform: translateY(-3px);
}

.progress-stat__number {
    font-size: 2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 2px;
}

.progress-stat__number .stat-number {
    display: inline-block;
}

.progress-stat__number .stat-suffix {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.progress-stat__number .stat-label--weekly {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
}

.progress-stat__label {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ============================================================
   VIEW ALL BUTTON
   ============================================================ */
.quick-start__view-all {
    text-align: center;
}

.btn-view-guides {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-view-guides:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

/* ----- Focus States ----- */
.guide-card__link:focus-visible,
.btn-featured-guide:focus-visible,
.btn-view-guides:focus-visible,
.resource-item:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Quick Start Guides & Developer Onboarding
================================================== */

/* ==================================================
START: Documentation Explorer & Interactive Navigation
================================================== */

/* ----- Container ----- */
#docs-explorer {
    padding: 80px 0 80px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.docs-explorer__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.docs-explorer__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.docs-explorer__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.docs-explorer__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.docs-explorer__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.docs-explorer__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.docs-explorer__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.docs-explorer__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.docs-explorer__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.docs-explorer__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.docs-explorer__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.docs-explorer__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#docs-explorer .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#docs-explorer .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#docs-explorer .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#docs-explorer .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#docs-explorer .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#docs-explorer .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#docs-explorer .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.docs-explorer__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.docs-explorer__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.docs-explorer__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.docs-explorer__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.docs-explorer__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.docs-explorer__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   THREE-COLUMN EXPLORER
   ============================================================ */
.docs-explorer__container {
    display: grid;
    grid-template-columns: 260px 1fr 260px;
    gap: 30px;
    margin-bottom: 48px;
    align-items: start;
}

/* ============================================================
   LEFT SIDEBAR
   ============================================================ */
.docs-explorer__sidebar {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 20px 16px 18px;
    box-shadow: var(--shadow-glass);
    position: sticky;
    top: calc(var(--top-bar-height) + var(--nav-height) + 30px);
    max-height: calc(100vh - var(--top-bar-height) - var(--nav-height) - 60px);
    overflow-y: auto;
}

.sidebar-search {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 16px;
    padding: 6px 10px;
    background: var(--color-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 10px;
    transition: all 0.3s ease;
}

.sidebar-search:focus-within {
    border-color: var(--color-purple);
    box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.06);
}

.sidebar-search__input {
    flex: 1;
    border: none;
    outline: none;
    background: transparent;
    font-family: var(--font-primary);
    font-size: 0.8rem;
    color: var(--color-charcoal);
}

.sidebar-search__input::placeholder {
    color: var(--color-gray-mid);
}

.sidebar-search__btn {
    background: none;
    border: none;
    color: var(--color-gray-mid);
    cursor: pointer;
    transition: all 0.3s ease;
    padding: 4px;
}

.sidebar-search__btn:hover {
    color: var(--color-purple);
}

/* Tree Navigation */
.tree-category {
    margin-bottom: 4px;
}

.tree-category__toggle {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    padding: 8px 10px;
    background: transparent;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    font-family: var(--font-primary);
    font-size: 0.82rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    transition: all 0.3s ease;
    text-align: left;
}

.tree-category__toggle:hover {
    background: rgba(124, 58, 237, 0.04);
    color: var(--color-purple);
}

.tree-category__icon {
    font-size: 0.85rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.tree-category__label {
    flex: 1;
}

.tree-category__arrow {
    font-size: 0.6rem;
    transition: transform 0.3s ease;
    color: var(--color-gray-mid);
}

.tree-category__toggle[aria-expanded="true"] .tree-category__arrow {
    transform: rotate(180deg);
}

.tree-subcategories {
    list-style: none;
    padding: 0;
    margin: 0 0 4px 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
    padding-left: 28px;
}

.tree-subcategories li {
    margin: 2px 0;
}

.tree-link {
    display: block;
    padding: 5px 10px;
    border-radius: 6px;
    font-size: 0.75rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    text-decoration: none;
    transition: all 0.3s ease;
}

.tree-link:hover {
    background: rgba(124, 58, 237, 0.04);
    color: var(--color-charcoal);
}

.tree-link.active {
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-weight: var(--font-weight-medium);
}

/* ============================================================
   MAIN DOCUMENTATION PREVIEW
   ============================================================ */
.doc-preview {
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 28px 30px 30px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.doc-preview:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

/* Breadcrumb */
.doc-preview__breadcrumb {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px 8px;
    font-size: 0.75rem;
    color: var(--color-gray-mid);
    margin-bottom: 16px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--color-gray-light);
}

.doc-preview__breadcrumb a {
    color: var(--color-gray-mid);
    text-decoration: none;
    transition: color 0.3s ease;
}

.doc-preview__breadcrumb a:hover {
    color: var(--color-purple);
}

.doc-preview__breadcrumb .separator {
    color: var(--color-gray-light);
}

.doc-preview__breadcrumb .current {
    color: var(--color-charcoal);
    font-weight: var(--font-weight-medium);
}

/* Header */
.doc-preview__header {
    margin-bottom: 20px;
}

.doc-preview__title {
    font-size: 1.8rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 8px 0;
    letter-spacing: -0.02em;
}

.doc-preview__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px 16px;
}

.meta-item {
    font-size: 0.75rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 4px;
}

.meta-item i {
    font-size: 0.7rem;
}

.difficulty {
    padding: 2px 10px;
    border-radius: 50px;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    font-size: 0.6rem;
    letter-spacing: 0.03em;
}

.difficulty--beginner {
    background: rgba(52, 211, 153, 0.08);
    color: #34D399;
    border: 1px solid rgba(52, 211, 153, 0.1);
}

.difficulty--intermediate {
    background: rgba(251, 191, 36, 0.08);
    color: #FBBF24;
    border: 1px solid rgba(251, 191, 36, 0.1);
}

.difficulty--advanced {
    background: rgba(244, 67, 54, 0.08);
    color: #F44336;
    border: 1px solid rgba(244, 67, 54, 0.1);
}

/* Body */
.doc-preview__body {
    font-size: 0.9rem;
    line-height: 1.7;
    color: var(--color-charcoal);
}

.doc-preview__body h2 {
    font-size: 1.4rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 24px 0 12px;
    letter-spacing: -0.02em;
}

.doc-preview__body p {
    margin: 0 0 14px;
    color: var(--color-gray-mid);
}

.doc-preview__body ul {
    margin: 0 0 14px;
    padding-left: 20px;
    list-style: none;
}

.doc-preview__body ul li {
    position: relative;
    padding-left: 20px;
    margin-bottom: 4px;
    color: var(--color-gray-mid);
}

.doc-preview__body ul li::before {
    content: '›';
    position: absolute;
    left: 0;
    color: var(--color-lime);
    font-weight: bold;
}

.doc-preview__note {
    display: flex;
    gap: 12px;
    padding: 14px 18px;
    border-radius: 12px;
    margin: 16px 0;
    align-items: flex-start;
}

.doc-preview__note--info {
    background: rgba(14, 165, 233, 0.04);
    border: 1px solid rgba(14, 165, 233, 0.1);
}

.doc-preview__note--warning {
    background: rgba(251, 191, 36, 0.04);
    border: 1px solid rgba(251, 191, 36, 0.1);
}

.note-icon {
    font-size: 1.1rem;
    color: var(--color-gray-mid);
    flex-shrink: 0;
    margin-top: 2px;
}

.doc-preview__note--info .note-icon {
    color: #0EA5E9;
}

.doc-preview__note--warning .note-icon {
    color: #FBBF24;
}

.note-text {
    font-size: 0.85rem;
    color: var(--color-gray-mid);
    line-height: 1.5;
}

.note-text strong {
    color: var(--color-charcoal);
}

.doc-preview__code {
    background: var(--color-charcoal);
    border-radius: 10px;
    margin: 16px 0;
    overflow: hidden;
}

.code-header {
    padding: 8px 14px;
    background: rgba(255, 255, 255, 0.05);
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.code-language {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: rgba(255, 255, 255, 0.3);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.doc-preview__code pre {
    padding: 14px 16px;
    margin: 0;
    overflow-x: auto;
}

.doc-preview__code code {
    font-family: 'Courier New', monospace;
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.8);
    white-space: pre;
}

/* Related Guides */
.doc-preview__related {
    margin-top: 24px;
    padding-top: 20px;
    border-top: 1px solid var(--color-gray-light);
}

.doc-preview__related h3 {
    font-size: 0.9rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0 0 10px;
}

.doc-preview__related ul {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 16px;
    list-style: none;
    padding: 0;
    margin: 0;
}

.doc-preview__related ul li a {
    font-size: 0.8rem;
    color: var(--color-purple);
    text-decoration: none;
    transition: color 0.3s ease;
}

.doc-preview__related ul li a:hover {
    color: var(--color-purple-dark);
    text-decoration: underline;
}

/* Navigation */
.doc-preview__nav {
    display: flex;
    justify-content: space-between;
    margin-top: 24px;
    padding-top: 18px;
    border-top: 1px solid var(--color-gray-light);
}

.doc-preview__nav a {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.8rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-decoration: none;
    transition: all 0.3s ease;
}

.doc-preview__nav a:hover {
    color: var(--color-purple);
}

.nav-prev i {
    font-size: 0.7rem;
}
.nav-next i {
    font-size: 0.7rem;
}

/* ============================================================
   RIGHT INFORMATION PANEL
   ============================================================ */
.docs-explorer__panel {
    position: sticky;
    top: calc(var(--top-bar-height) + var(--nav-height) + 30px);
}

.info-panel {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 20px 18px 18px;
    box-shadow: var(--shadow-glass);
}

.info-panel__title {
    font-size: 0.8rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin: 0 0 12px;
}

.info-panel__toc {
    list-style: none;
    padding: 0;
    margin: 0 0 16px;
}

.toc-link {
    display: block;
    padding: 4px 0 4px 10px;
    font-size: 0.78rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    text-decoration: none;
    border-left: 2px solid transparent;
    transition: all 0.3s ease;
}

.toc-link:hover {
    color: var(--color-charcoal);
    border-left-color: var(--color-gray-light);
}

.toc-link.active {
    color: var(--color-purple);
    border-left-color: var(--color-purple);
    font-weight: var(--font-weight-medium);
}

.info-panel__progress {
    margin-bottom: 16px;
    padding: 12px 0 10px;
    border-top: 1px solid var(--color-gray-light);
    border-bottom: 1px solid var(--color-gray-light);
}

.progress-label {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    display: block;
    margin-bottom: 4px;
}

.progress-bar {
    height: 4px;
    background: var(--color-gray-light);
    border-radius: 4px;
    overflow: hidden;
    margin: 4px 0 2px;
}

.progress-fill {
    display: block;
    height: 100%;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    border-radius: 4px;
    transition: width 1s ease;
}

.progress-text {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
}

.info-panel__section {
    margin-bottom: 14px;
}

.info-panel__section h5 {
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin: 0 0 6px;
}

.recent-list,
.popular-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.recent-list li,
.popular-list li {
    margin: 2px 0;
}

.recent-list li a,
.popular-list li a {
    display: block;
    padding: 3px 0;
    font-size: 0.72rem;
    color: var(--color-gray-mid);
    text-decoration: none;
    transition: all 0.3s ease;
}

.recent-list li a:hover,
.popular-list li a:hover {
    color: var(--color-purple);
}

.info-panel__actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6px;
    margin-top: 8px;
}

.action-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 6px 8px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid var(--color-gray-light);
    border-radius: 8px;
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    cursor: pointer;
    transition: all 0.3s ease;
    font-family: var(--font-primary);
}

.action-btn:hover {
    background: var(--color-white);
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.action-btn i {
    font-size: 0.6rem;
}

/* ============================================================
   QUICK ACTIONS
   ============================================================ */
.docs-explorer__actions {
    max-width: 900px;
    margin: 0 auto 40px;
}

.quick-actions-grid {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 12px;
}

.quick-action {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 14px 10px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 14px;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    cursor: default;
    box-shadow: var(--shadow-glass);
}

.quick-action:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.08);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.04);
    background: rgba(255, 255, 255, 0.6);
}

.quick-action__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.quick-action:hover .quick-action__icon {
    color: var(--color-lime-dark);
    transform: scale(1.1);
}

.quick-action__label {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-align: center;
    line-height: 1.2;
}

/* ============================================================
   DOCUMENTATION INSIGHTS
   ============================================================ */
.docs-explorer__insights {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
}

.insights-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
}

.insight-stat {
    text-align: center;
    padding: 4px 8px;
    transition: all 0.3s ease;
}

.insight-stat:hover {
    transform: translateY(-3px);
}

.insight-stat__number {
    font-size: 2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 2px;
}

.insight-stat__number .stat-number {
    display: inline-block;
}

.insight-stat__number .stat-suffix {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.insight-stat__number .stat-label--weekly {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
}

.insight-stat__label {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ============================================================
   VIEW ALL BUTTON
   ============================================================ */
.docs-explorer__view-all {
    text-align: center;
}

.btn-view-docs-explorer {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-view-docs-explorer:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

/* ----- Focus States ----- */
.tree-link:focus-visible,
.tree-category__toggle:focus-visible,
.sidebar-search__input:focus-visible,
.action-btn:focus-visible,
.btn-view-docs-explorer:focus-visible,
.doc-preview__nav a:focus-visible,
.doc-preview__related ul li a:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Documentation Explorer & Interactive Navigation
================================================== */

/* ==================================================
START: Featured Documentation, Popular Guides & Recently Updated
================================================== */

/* ----- Container ----- */
#featured-docs {
    padding: 80px 0 80px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.featured-docs__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.featured-docs__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.featured-docs__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.featured-docs__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.featured-docs__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.featured-docs__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.featured-docs__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.featured-docs__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.featured-docs__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.featured-docs__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.featured-docs__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.featured-docs__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#featured-docs .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#featured-docs .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#featured-docs .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#featured-docs .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#featured-docs .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#featured-docs .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#featured-docs .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.featured-docs__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.featured-docs__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 40px;
}

.featured-docs__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.featured-docs__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.featured-docs__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.featured-docs__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   FILTER BAR
   ============================================================ */
.featured-docs__filters {
    margin-bottom: 32px;
    padding: 4px 0;
}

.filter-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 8px 12px;
}

.filter-pill {
    padding: 6px 18px;
    background: var(--color-off-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 50px;
    font-family: var(--font-primary);
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-soft);
}

.filter-pill:hover {
    border-color: rgba(124, 58, 237, 0.15);
    color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(124, 58, 237, 0.04);
}

.filter-pill.active {
    background: linear-gradient(135deg, var(--color-lime), var(--color-lime-dark));
    border-color: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.25);
}

.filter-pill:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 2px;
}

/* ============================================================
   FEATURED DOCUMENTATION CARD
   ============================================================ */
.featured-docs__featured {
    margin-bottom: 48px;
}

.featured-guide {
    display: grid;
    grid-template-columns: 35fr 65fr;
    gap: 32px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.featured-guide:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

/* ----- Featured Image ----- */
.featured-guide__image {
    position: relative;
    overflow: hidden;
    min-height: 280px;
}

.featured-guide__placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #2D1B69, #7C3AED);
    position: relative;
    overflow: hidden;
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.featured-guide:hover .featured-guide__placeholder {
    transform: scale(1.04);
}

.featured-guide__placeholder .placeholder-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    color: rgba(255, 255, 255, 0.9);
    z-index: 2;
    position: relative;
}

.featured-guide__placeholder .placeholder-content i {
    font-size: 3.2rem;
    opacity: 0.8;
}

.featured-guide__placeholder .placeholder-content span {
    font-size: 1rem;
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.05em;
    text-transform: uppercase;
    opacity: 0.5;
}

.featured-guide__placeholder .placeholder-shapes {
    position: absolute;
    inset: 0;
    overflow: hidden;
    z-index: 1;
}

.featured-guide__placeholder .placeholder-shapes .shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.05);
    pointer-events: none;
}

.featured-guide__placeholder .placeholder-shapes .shape--1 {
    width: 140px;
    height: 140px;
    top: -40px;
    right: -40px;
}

.featured-guide__placeholder .placeholder-shapes .shape--2 {
    width: 90px;
    height: 90px;
    bottom: 20px;
    left: 20px;
}

.featured-guide__placeholder .placeholder-shapes .shape--3 {
    width: 70px;
    height: 70px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.featured-guide__badge {
    position: absolute;
    top: 16px;
    left: 16px;
    padding: 4px 14px;
    background: rgba(192, 227, 74, 0.9);
    border-radius: 50px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    letter-spacing: 0.03em;
    text-transform: uppercase;
    z-index: 5;
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.2);
}

/* ----- Featured Content ----- */
.featured-guide__content {
    padding: 32px 36px 32px 0;
    display: flex;
    flex-direction: column;
    gap: 14px;
    justify-content: center;
}

.featured-guide__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px 14px;
}

.featured-guide__category {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: 2px 12px;
    background: rgba(124, 58, 237, 0.08);
    border-radius: 50px;
}

.featured-guide__difficulty {
    font-size: 0.55rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    padding: 2px 10px;
    border-radius: 50px;
    background: rgba(251, 191, 36, 0.08);
    color: #FBBF24;
    border: 1px solid rgba(251, 191, 36, 0.1);
}

.featured-guide__time,
.featured-guide__update {
    font-size: 0.72rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 4px;
}

.featured-guide__time i,
.featured-guide__update i {
    font-size: 0.6rem;
}

.featured-guide__title {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0;
    letter-spacing: -0.02em;
}

.featured-guide__description {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    margin: 0;
}

.featured-guide__tech {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.featured-guide__tech span {
    padding: 2px 12px;
    background: rgba(124, 58, 237, 0.06);
    border: 1px solid rgba(124, 58, 237, 0.08);
    border-radius: 50px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.02em;
}

.btn-featured-guide {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
    width: fit-content;
}

.btn-featured-guide:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

/* ============================================================
   THREE CONTENT COLUMNS
   ============================================================ */
.featured-docs__columns {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
    margin-bottom: 48px;
}

/* ----- Column ----- */
.docs-column {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 20px 18px 16px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.docs-column:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.docs-column__header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 14px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--color-gray-light);
}

.docs-column__icon {
    font-size: 1.1rem;
}

.docs-column__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

/* ----- Docs Item ----- */
.docs-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 8px 6px;
    border-radius: 10px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    border-bottom: 1px solid var(--color-gray-light);
}

.docs-item:last-child {
    border-bottom: none;
}

.docs-item:hover {
    background: rgba(255, 255, 255, 0.5);
    transform: translateX(4px);
}

.docs-item__thumb {
    width: 36px;
    height: 36px;
    min-width: 36px;
    border-radius: 8px;
    flex-shrink: 0;
    background: linear-gradient(135deg, #7C3AED, #A78BFA);
}

.docs-item:nth-child(2) .docs-item__thumb {
    background: linear-gradient(135deg, #0EA5E9, #38BDF8);
}
.docs-item:nth-child(3) .docs-item__thumb {
    background: linear-gradient(135deg, #34D399, #6EE7B7);
}
.docs-item:nth-child(4) .docs-item__thumb {
    background: linear-gradient(135deg, #F59E0B, #FBBF24);
}
.docs-item:nth-child(5) .docs-item__thumb {
    background: linear-gradient(135deg, #EF4444, #F87171);
}

.docs-item__content {
    flex: 1;
    min-width: 0;
}

.docs-item__category {
    font-size: 0.5rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.docs-item__title {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.3;
    margin: 2px 0;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.docs-item__meta {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.55rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
}

.docs-item__meta i {
    font-size: 0.5rem;
    margin-right: 2px;
}

.docs-item__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
    flex-shrink: 0;
}

.docs-item__badge--popular {
    color: #F59E0B;
}

.docs-item__badge--updated {
    color: #0EA5E9;
}

.docs-item--featured {
    background: rgba(255, 255, 255, 0.2);
    border-radius: 10px;
}

.docs-item--popular {
    background: rgba(255, 255, 255, 0.15);
    border-radius: 10px;
}

.docs-item--updated {
    background: rgba(255, 255, 255, 0.15);
    border-radius: 10px;
}

/* ============================================================
   RECENTLY UPDATED TIMELINE
   ============================================================ */
.featured-docs__timeline {
    max-width: 900px;
    margin: 0 auto 48px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.featured-docs__timeline:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.timeline-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
}

.timeline-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.timeline-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.timeline-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

.timeline-items {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.timeline-item {
    display: flex;
    gap: 20px;
    padding: 12px 16px;
    background: rgba(255, 255, 255, 0.2);
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    transition: all 0.3s ease;
}

.timeline-item:hover {
    background: rgba(255, 255, 255, 0.5);
    border-color: rgba(192, 227, 74, 0.1);
    transform: translateX(4px);
}

.timeline-item__date {
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    min-width: 80px;
    flex-shrink: 0;
    padding-top: 2px;
}

.timeline-item__content {
    flex: 1;
    min-width: 0;
}

.timeline-item__category {
    font-size: 0.5rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.timeline-item__title {
    font-size: 0.88rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 2px 0 4px;
}

.timeline-item__summary {
    font-size: 0.78rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin: 0 0 6px;
    line-height: 1.5;
}

.timeline-item__version {
    display: inline-block;
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.06);
    padding: 1px 10px;
    border-radius: 50px;
    border: 1px solid rgba(192, 227, 74, 0.1);
    margin-right: 12px;
}

.timeline-item__link {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-decoration: none;
    transition: all 0.3s ease;
}

.timeline-item__link:hover {
    color: var(--color-purple-dark);
}

.timeline-item__link i {
    font-size: 0.55rem;
    transition: transform 0.3s ease;
}

.timeline-item__link:hover i {
    transform: translateX(4px);
}

/* ============================================================
   DOCUMENTATION METRICS
   ============================================================ */
.featured-docs__metrics {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
}

.metrics-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
}

.metric-stat {
    text-align: center;
    padding: 4px 8px;
    transition: all 0.3s ease;
}

.metric-stat:hover {
    transform: translateY(-3px);
}

.metric-stat__number {
    font-size: 2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 2px;
}

.metric-stat__number .stat-number {
    display: inline-block;
}

.metric-stat__number .stat-suffix {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.metric-stat__number .stat-label--weekly {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
}

.metric-stat__label {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ============================================================
   VIEW ALL BUTTON
   ============================================================ */
.featured-docs__view-all {
    text-align: center;
}

.btn-view-docs-featured {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-view-docs-featured:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

/* ----- Focus States ----- */
.btn-featured-guide:focus-visible,
.btn-view-docs-featured:focus-visible,
.filter-pill:focus-visible,
.timeline-item__link:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Featured Documentation, Popular Guides & Recently Updated
================================================== */

/* ==================================================
START: API Documentation Center & Interactive Endpoint Explorer
================================================== */

/* ----- Container ----- */
#api-docs {
    padding: 80px 0 80px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.api-docs__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.api-docs__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.api-docs__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.api-docs__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.api-docs__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.api-docs__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.api-docs__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.api-docs__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.api-docs__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.api-docs__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.api-docs__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.api-docs__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#api-docs .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#api-docs .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#api-docs .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#api-docs .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#api-docs .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#api-docs .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#api-docs .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.api-docs__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.api-docs__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.api-docs__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.api-docs__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.api-docs__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.api-docs__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   FEATURED API CARD
   ============================================================ */
.api-docs__featured {
    margin-bottom: 48px;
}

.api-featured {
    display: flex;
    align-items: center;
    gap: 32px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    padding: 32px 36px 32px 32px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.api-featured:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.api-featured__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 64px;
    height: 64px;
    border-radius: 18px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    color: var(--color-white);
    font-size: 1.6rem;
    flex-shrink: 0;
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.15);
}

.api-featured__content {
    flex: 1;
    min-width: 0;
}

.api-featured__header {
    display: flex;
    align-items: center;
    gap: 12px 20px;
    flex-wrap: wrap;
    margin-bottom: 8px;
}

.api-featured__title {
    font-size: 1.4rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0;
}

.api-featured__badges {
    display: flex;
    align-items: center;
    gap: 8px;
}

.api-status {
    padding: 2px 12px;
    border-radius: 50px;
    font-size: 0.55rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.api-status--stable {
    background: rgba(52, 211, 153, 0.08);
    color: #34D399;
    border: 1px solid rgba(52, 211, 153, 0.1);
}

.api-status--beta {
    background: rgba(251, 191, 36, 0.08);
    color: #FBBF24;
    border: 1px solid rgba(251, 191, 36, 0.1);
}

.api-status--deprecated {
    background: rgba(244, 67, 54, 0.08);
    color: #F44336;
    border: 1px solid rgba(244, 67, 54, 0.1);
}

.api-version {
    padding: 2px 10px;
    border-radius: 50px;
    font-size: 0.5rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    border: 1px solid var(--color-gray-light);
}

.api-featured__info {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px 20px;
    margin-bottom: 10px;
}

.info-item {
    font-size: 0.78rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 6px;
}

.info-item code {
    padding: 2px 8px;
    background: var(--color-charcoal);
    color: rgba(255, 255, 255, 0.8);
    border-radius: 4px;
    font-family: 'Courier New', monospace;
    font-size: 0.7rem;
}

.info-item i {
    font-size: 0.7rem;
    color: var(--color-purple);
}

.api-featured__description {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0 0 14px 0;
    max-width: 48ch;
}

.btn-api-featured {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
}

.btn-api-featured:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

/* ============================================================
   API WORKSPACE — Three Columns
   ============================================================ */
.api-docs__workspace {
    display: grid;
    grid-template-columns: 260px 1fr 280px;
    gap: 24px;
    margin-bottom: 48px;
    align-items: start;
}

/* ============================================================
   LEFT PANEL — Categories
   ============================================================ */
.api-workspace__sidebar {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 18px 14px 16px;
    box-shadow: var(--shadow-glass);
    position: sticky;
    top: calc(var(--top-bar-height) + var(--nav-height) + 30px);
    max-height: calc(100vh - var(--top-bar-height) - var(--nav-height) - 60px);
    overflow-y: auto;
}

.api-sidebar__search {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 10px;
    background: var(--color-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 10px;
    margin-bottom: 14px;
    transition: all 0.3s ease;
}

.api-sidebar__search:focus-within {
    border-color: var(--color-purple);
    box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.06);
}

.api-search__input {
    flex: 1;
    border: none;
    outline: none;
    background: transparent;
    font-family: var(--font-primary);
    font-size: 0.78rem;
    color: var(--color-charcoal);
}

.api-search__input::placeholder {
    color: var(--color-gray-mid);
}

.api-search__btn {
    background: none;
    border: none;
    color: var(--color-gray-mid);
    cursor: pointer;
    transition: all 0.3s ease;
    padding: 4px;
}

.api-search__btn:hover {
    color: var(--color-purple);
}

.api-sidebar__categories {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.api-category {
    margin-bottom: 2px;
}

.api-category__toggle {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    padding: 6px 8px;
    background: transparent;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    font-family: var(--font-primary);
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    transition: all 0.3s ease;
    text-align: left;
}

.api-category__toggle:hover {
    background: rgba(124, 58, 237, 0.04);
    color: var(--color-purple);
}

.api-category__icon {
    font-size: 0.8rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.api-category__label {
    flex: 1;
}

.api-category__arrow {
    font-size: 0.55rem;
    transition: transform 0.3s ease;
    color: var(--color-gray-mid);
}

.api-category__toggle[aria-expanded="true"] .api-category__arrow {
    transform: rotate(180deg);
}

.api-endpoints {
    list-style: none;
    padding: 0;
    margin: 0 0 4px 0;
    overflow: hidden;
    padding-left: 28px;
}

.api-endpoints li {
    margin: 2px 0;
}

.api-endpoint-link {
    display: block;
    padding: 4px 10px;
    border-radius: 6px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    text-decoration: none;
    transition: all 0.3s ease;
    font-family: 'Courier New', monospace;
}

.api-endpoint-link:hover {
    background: rgba(124, 58, 237, 0.04);
    color: var(--color-charcoal);
}

.api-endpoint-link.active {
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-weight: var(--font-weight-medium);
}

/* ============================================================
   CENTER PANEL — Endpoints
   ============================================================ */
.api-workspace__endpoints {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 20px 20px 18px;
    box-shadow: var(--shadow-glass);
    min-height: 400px;
}

.endpoint-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--color-gray-light);
    margin-bottom: 16px;
}

.endpoint-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

.endpoint-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
}

.endpoint-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

/* ----- Endpoint Item ----- */
.endpoint-item {
    border: 1px solid var(--color-gray-light);
    border-radius: 12px;
    overflow: hidden;
    transition: all 0.3s ease;
    background: rgba(255, 255, 255, 0.2);
}

.endpoint-item:hover {
    border-color: rgba(124, 58, 237, 0.08);
}

.endpoint-item.active {
    border-color: rgba(124, 58, 237, 0.12);
    background: rgba(255, 255, 255, 0.5);
}

.endpoint-item__header {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    cursor: pointer;
    transition: all 0.3s ease;
}

.endpoint-item__header:hover {
    background: rgba(124, 58, 237, 0.02);
}

.endpoint-method {
    padding: 2px 10px;
    border-radius: 4px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-bold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    flex-shrink: 0;
}

.endpoint-method--get {
    background: rgba(52, 211, 153, 0.08);
    color: #34D399;
    border: 1px solid rgba(52, 211, 153, 0.1);
}

.endpoint-method--post {
    background: rgba(14, 165, 233, 0.08);
    color: #0EA5E9;
    border: 1px solid rgba(14, 165, 233, 0.1);
}

.endpoint-method--put {
    background: rgba(251, 191, 36, 0.08);
    color: #FBBF24;
    border: 1px solid rgba(251, 191, 36, 0.1);
}

.endpoint-method--patch {
    background: rgba(168, 85, 247, 0.08);
    color: #A855F7;
    border: 1px solid rgba(168, 85, 247, 0.1);
}

.endpoint-method--delete {
    background: rgba(244, 67, 54, 0.08);
    color: #F44336;
    border: 1px solid rgba(244, 67, 54, 0.1);
}

.endpoint-url {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    font-family: 'Courier New', monospace;
    flex: 1;
}

.endpoint-status {
    font-size: 0.5rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    padding: 2px 10px;
    border-radius: 50px;
}

.endpoint-status--active {
    background: rgba(52, 211, 153, 0.08);
    color: #34D399;
    border: 1px solid rgba(52, 211, 153, 0.1);
}

.endpoint-status--deprecated {
    background: rgba(244, 67, 54, 0.08);
    color: #F44336;
    border: 1px solid rgba(244, 67, 54, 0.1);
}

.endpoint-toggle {
    background: none;
    border: none;
    color: var(--color-gray-mid);
    cursor: pointer;
    transition: all 0.3s ease;
    padding: 4px;
}

.endpoint-toggle:hover {
    color: var(--color-purple);
}

.endpoint-item.active .endpoint-toggle i {
    transform: rotate(180deg);
}

/* ----- Endpoint Body ----- */
.endpoint-item__body {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94), padding 0.3s ease;
    padding: 0 14px;
}

.endpoint-item.active .endpoint-item__body {
    max-height: 1200px;
    padding: 0 14px 16px;
}

.endpoint-description {
    font-size: 0.82rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin: 0 0 10px 0;
}

.endpoint-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px 18px;
    padding: 8px 12px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 8px;
    margin-bottom: 12px;
}

.endpoint-meta span {
    font-size: 0.7rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 4px;
}

.endpoint-meta span i {
    font-size: 0.6rem;
    color: var(--color-purple);
}

.endpoint-details {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.detail-section {
    background: rgba(255, 255, 255, 0.3);
    border-radius: 8px;
    padding: 10px 12px;
}

.detail-section__title {
    display: block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin-bottom: 4px;
}

.detail-section pre {
    margin: 0;
    padding: 0;
    overflow-x: auto;
}

.detail-section code {
    font-family: 'Courier New', monospace;
    font-size: 0.7rem;
    color: var(--color-charcoal);
    white-space: pre-wrap;
    word-break: break-word;
    line-height: 1.5;
}

/* ----- Endpoint Actions ----- */
.endpoint-actions {
    display: flex;
    gap: 8px;
    margin-top: 12px;
    padding-top: 12px;
    border-top: 1px solid var(--color-gray-light);
}

.btn-copy,
.btn-try {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 16px;
    border: 1px solid var(--color-gray-light);
    border-radius: 8px;
    background: var(--color-white);
    font-family: var(--font-primary);
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    cursor: pointer;
    transition: all 0.3s ease;
}

.btn-copy:hover {
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.btn-try {
    background: var(--color-lime);
    color: var(--color-charcoal);
    border-color: var(--color-lime);
}

.btn-try:hover {
    background: var(--color-lime-dark);
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.3);
}

/* ============================================================
   RIGHT PANEL — Endpoint Details (Sticky)
   ============================================================ */
.api-workspace__details {
    position: sticky;
    top: calc(var(--top-bar-height) + var(--nav-height) + 30px);
}

.api-details-panel {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    padding: 20px 18px 18px;
    box-shadow: var(--shadow-glass);
}

.api-details-panel__title {
    font-size: 0.75rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin: 0 0 12px 0;
}

.api-details-panel__method {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 10px;
    padding: 8px 12px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 8px;
}

.method-badge {
    padding: 2px 10px;
    border-radius: 4px;
    font-size: 0.55rem;
    font-weight: var(--font-weight-bold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.method-badge--get {
    background: rgba(52, 211, 153, 0.08);
    color: #34D399;
    border: 1px solid rgba(52, 211, 153, 0.1);
}

.method-badge--post {
    background: rgba(14, 165, 233, 0.08);
    color: #0EA5E9;
    border: 1px solid rgba(14, 165, 233, 0.1);
}

.method-url {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    font-family: 'Courier New', monospace;
}

.api-details-panel__status {
    display: flex;
    gap: 8px;
    margin-bottom: 14px;
}

.status-badge {
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    padding: 2px 10px;
    border-radius: 50px;
}

.status-badge--active {
    background: rgba(52, 211, 153, 0.08);
    color: #34D399;
    border: 1px solid rgba(52, 211, 153, 0.1);
}

.status-badge--stable {
    background: rgba(14, 165, 233, 0.08);
    color: #0EA5E9;
    border: 1px solid rgba(14, 165, 233, 0.1);
}

.api-details-panel__section {
    margin-bottom: 14px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--color-gray-light);
}

.api-details-panel__section:last-child {
    margin-bottom: 0;
    padding-bottom: 0;
    border-bottom: none;
}

.section-label {
    display: block;
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin-bottom: 4px;
}

.section-text {
    font-size: 0.78rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-charcoal);
    margin: 0;
}

.param-list {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.param-list li {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.7rem;
}

.param-name {
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    font-family: 'Courier New', monospace;
    min-width: 60px;
}

.param-type {
    color: var(--color-gray-mid);
    font-size: 0.6rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.param-required {
    color: #F87171;
    font-size: 0.5rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.code-list {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.code-list li {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 0.7rem;
    color: var(--color-gray-mid);
}

.code {
    display: inline-block;
    min-width: 36px;
    padding: 1px 8px;
    border-radius: 4px;
    background: rgba(255, 255, 255, 0.3);
    font-family: 'Courier New', monospace;
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: center;
}

.quick-links {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.quick-link {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-decoration: none;
    padding: 3px 10px;
    background: rgba(124, 58, 237, 0.04);
    border: 1px solid rgba(124, 58, 237, 0.06);
    border-radius: 50px;
    transition: all 0.3s ease;
}

.quick-link:hover {
    background: rgba(124, 58, 237, 0.08);
    border-color: rgba(124, 58, 237, 0.1);
}

/* ============================================================
   SDK DOWNLOADS
   ============================================================ */
.api-docs__sdks {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.api-docs__sdks:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.sdks-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
}

.sdks-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.sdks-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.sdks-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

.sdks-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 10px 12px;
}

.sdk-card {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.sdk-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.sdk-card__icon {
    font-size: 1.3rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.sdk-card__info {
    flex: 1;
    min-width: 0;
}

.sdk-card__name {
    display: block;
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.sdk-card__version {
    display: block;
    font-size: 0.5rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
}

.sdk-card__actions {
    display: flex;
    gap: 4px;
}

.sdk-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border-radius: 6px;
    border: 1px solid var(--color-gray-light);
    color: var(--color-gray-mid);
    background: var(--color-white);
    transition: all 0.3s ease;
    text-decoration: none;
    font-size: 0.6rem;
}

.sdk-btn:hover {
    border-color: var(--color-purple);
    color: var(--color-purple);
}

/* ============================================================
   QUICK ACTIONS
   ============================================================ */
.api-docs__quick-actions {
    max-width: 900px;
    margin: 0 auto 40px;
}

.quick-actions-grid {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 12px;
}

.quick-action-btn {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 14px 10px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 14px;
    text-decoration: none;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
}

.quick-action-btn:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.08);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.04);
    background: rgba(255, 255, 255, 0.6);
}

.quick-action-btn__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.quick-action-btn:hover .quick-action-btn__icon {
    color: var(--color-lime-dark);
    transform: scale(1.1);
}

.quick-action-btn__label {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-align: center;
    line-height: 1.2;
}

/* ============================================================
   API METRICS
   ============================================================ */
.api-docs__metrics {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
}

.api-metrics-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
}

.api-metric {
    text-align: center;
    padding: 4px 8px;
    transition: all 0.3s ease;
}

.api-metric:hover {
    transform: translateY(-3px);
}

.api-metric__number {
    font-size: 2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 2px;
}

.api-metric__number .stat-number {
    display: inline-block;
}

.api-metric__number .stat-suffix {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.api-metric__number .stat-label--version {
    font-size: 1.8rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
}

.api-metric__label {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ============================================================
   VIEW ALL BUTTON
   ============================================================ */
.api-docs__view-all {
    text-align: center;
}

.btn-view-api {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-view-api:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

/* ----- Focus States ----- */
.api-endpoint-link:focus-visible,
.api-category__toggle:focus-visible,
.btn-api-featured:focus-visible,
.btn-view-api:focus-visible,
.sdk-btn:focus-visible,
.quick-action-btn:focus-visible,
.btn-copy:focus-visible,
.btn-try:focus-visible,
.quick-link:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

.api-search__input:focus-visible {
    outline: none;
}

/* ==================================================
END: API Documentation Center & Interactive Endpoint Explorer
================================================== */

/* ==================================================
START: Code Examples, Interactive Snippets & Developer Playground
================================================== */

/* ----- Container ----- */
#code-playground {
    padding: 80px 0 80px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.code-playground__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.code-playground__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.code-playground__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.code-playground__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.code-playground__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.code-playground__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.code-playground__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.code-playground__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.code-playground__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.code-playground__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.code-playground__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.code-playground__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#code-playground .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#code-playground .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#code-playground .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#code-playground .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#code-playground .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#code-playground .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#code-playground .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.code-playground__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.code-playground__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.code-playground__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.code-playground__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.code-playground__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.code-playground__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   FEATURED CODE EXAMPLE
   ============================================================ */
.code-playground__featured {
    margin-bottom: 40px;
}

.featured-example {
    display: flex;
    align-items: center;
    gap: 28px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    padding: 28px 32px 28px 28px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.featured-example:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.featured-example__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    border-radius: 16px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-purple));
    color: var(--color-white);
    font-size: 1.4rem;
    flex-shrink: 0;
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.15);
}

.featured-example__content {
    flex: 1;
    min-width: 0;
}

.featured-example__header {
    display: flex;
    align-items: center;
    gap: 12px 20px;
    flex-wrap: wrap;
    margin-bottom: 6px;
}

.featured-example__title {
    font-size: 1.2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0;
}

.featured-example__badges {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.tech-badge {
    padding: 2px 12px;
    border-radius: 50px;
    font-size: 0.55rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.tech-badge--laravel {
    background: rgba(255, 45, 45, 0.08);
    color: #FF2D20;
    border: 1px solid rgba(255, 45, 45, 0.1);
}

.tech-badge--php {
