}

.btn-featured-example:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

/* ============================================================
   LANGUAGE SELECTOR TABS
   ============================================================ */
.code-playground__tabs {
    margin-bottom: 20px;
    padding: 4px 0;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
}

.code-playground__tabs::-webkit-scrollbar {
    display: none;
}

.tabs-scroll {
    display: flex;
    gap: 6px;
    min-width: max-content;
    padding: 2px 4px;
}

.lang-tab {
    padding: 6px 18px;
    background: var(--color-off-white);
    border: 1px solid var(--color-gray-light);
    border-radius: 50px;
    font-family: var(--font-primary);
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    white-space: nowrap;
    box-shadow: var(--shadow-soft);
}

.lang-tab:hover {
    border-color: rgba(124, 58, 237, 0.15);
    color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(124, 58, 237, 0.04);
}

.lang-tab.active {
    background: linear-gradient(135deg, var(--color-purple), var(--color-purple-dark));
    border-color: var(--color-purple);
    color: var(--color-white);
    box-shadow: 0 4px 20px rgba(124, 58, 237, 0.25);
}

.lang-tab:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 2px;
}

/* ============================================================
   CODE WORKSPACE
   ============================================================ */
.code-playground__workspace {
    margin-bottom: 48px;
}

.code-workspace {
    background: var(--color-charcoal);
    border-radius: 18px;
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.code-workspace:hover {
    box-shadow: 0 24px 80px rgba(0, 0, 0, 0.2);
}

/* Workspace Header */
.code-workspace__header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    background: rgba(255, 255, 255, 0.04);
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    flex-wrap: wrap;
}

.workspace-dots {
    display: flex;
    gap: 6px;
    flex-shrink: 0;
}

.workspace-dots .dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

.workspace-dots .dot:nth-child(1) {
    background: #F87171;
}
.workspace-dots .dot:nth-child(2) {
    background: #FBBF24;
}
.workspace-dots .dot:nth-child(3) {
    background: #34D399;
}

.workspace-file {
    font-size: 0.75rem;
    font-weight: var(--font-weight-medium);
    color: rgba(255, 255, 255, 0.5);
    font-family: 'Courier New', monospace;
    flex: 1;
    min-width: 0;
}

.workspace-lang {
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    color: rgba(255, 255, 255, 0.3);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    padding: 2px 10px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 4px;
    flex-shrink: 0;
}

.workspace-actions {
    display: flex;
    align-items: center;
    gap: 4px;
    flex-wrap: wrap;
    margin-left: auto;
}

.workspace-btn {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 4px 12px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 6px;
    color: rgba(255, 255, 255, 0.4);
    font-family: var(--font-primary);
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    cursor: pointer;
    transition: all 0.3s ease;
    white-space: nowrap;
}

.workspace-btn:hover {
    background: rgba(255, 255, 255, 0.08);
    color: rgba(255, 255, 255, 0.8);
    border-color: rgba(255, 255, 255, 0.1);
}

.workspace-btn--copy:hover {
    background: rgba(192, 227, 74, 0.1);
    color: var(--color-lime);
    border-color: rgba(192, 227, 74, 0.15);
}

.workspace-btn--run {
    background: rgba(192, 227, 74, 0.08);
    color: var(--color-lime);
    border-color: rgba(192, 227, 74, 0.1);
}

.workspace-btn--run:hover {
    background: rgba(192, 227, 74, 0.15);
    color: var(--color-lime);
    transform: scale(1.02);
}

/* Workspace Body */
.code-workspace__body {
    padding: 0;
    max-height: 520px;
    overflow-y: auto;
}

.code-workspace__body::-webkit-scrollbar {
    width: 6px;
}

.code-workspace__body::-webkit-scrollbar-track {
    background: rgba(255, 255, 255, 0.02);
}

.code-workspace__body::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.08);
    border-radius: 4px;
}

.code-workspace__body::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.12);
}

.code-container {
    padding: 16px 20px;
}

.code-block {
    display: none;
    margin: 0;
    font-family: 'Courier New', monospace;
    font-size: 0.8rem;
    line-height: 1.8;
    color: rgba(255, 255, 255, 0.85);
    white-space: pre-wrap;
    word-break: break-word;
}

.code-block.active {
    display: block;
}

.code-block code {
    font-family: 'Courier New', monospace;
    font-size: 0.8rem;
    line-height: 1.8;
    color: rgba(255, 255, 255, 0.85);
}

/* Syntax highlighting */
.hl-comment {
    color: rgba(255, 255, 255, 0.25);
    font-style: italic;
}

.hl-keyword {
    color: #A78BFA;
}

.hl-class {
    color: #34D399;
}

.hl-var {
    color: #FBBF24;
}

.hl-string {
    color: #F472B6;
}

.hl-method {
    color: #60A5FA;
}

.hl-number {
    color: #F472B6;
}

.hl-key {
    color: #FBBF24;
}

.hl-type {
    color: #34D399;
}

/* Workspace Footer */
.code-workspace__footer {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 8px 16px;
    background: rgba(255, 255, 255, 0.02);
    border-top: 1px solid rgba(255, 255, 255, 0.04);
}

.workspace-status {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: #34D399;
    display: flex;
    align-items: center;
    gap: 4px;
}

.workspace-status::before {
    content: '';
    display: inline-block;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #34D399;
    animation: pulseDot 2s ease-in-out infinite;
}

.workspace-lines,
.workspace-characters {
    font-size: 0.6rem;
    font-weight: var(--font-weight-regular);
    color: rgba(255, 255, 255, 0.2);
    font-family: 'Courier New', monospace;
}

/* ============================================================
   SDK EXAMPLES GRID
   ============================================================ */
.code-playground__sdks {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.code-playground__sdks:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.sdks-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
}

.sdks-header__icon {
    font-size: 1.2rem;
