}

.sdk-example__complexity {
    font-size: 0.45rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    padding: 1px 8px;
    border-radius: 50px;
    display: inline-block;
    margin-top: 2px;
}

.complexity--beginner {
    background: rgba(52, 211, 153, 0.08);
    color: #34D399;
    border: 1px solid rgba(52, 211, 153, 0.1);
}

.complexity--intermediate {
    background: rgba(251, 191, 36, 0.08);
    color: #FBBF24;
    border: 1px solid rgba(251, 191, 36, 0.1);
}

.complexity--advanced {
    background: rgba(244, 67, 54, 0.08);
    color: #F44336;
    border: 1px solid rgba(244, 67, 54, 0.1);
}

.sdk-example__link {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    text-decoration: none;
    transition: all 0.3s ease;
    flex-shrink: 0;
}

.sdk-example__link i {
    font-size: 0.55rem;
    transition: transform 0.3s ease;
}

.sdk-example__link:hover {
    color: var(--color-purple-dark);
}

.sdk-example__link:hover i {
    transform: translateX(4px);
}

/* ============================================================
   DEVELOPER RESOURCES
   ============================================================ */
.code-playground__resources {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 20px 24px 16px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 16px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.code-playground__resources:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.resources-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 14px;
}

.resources-header__icon {
    font-size: 1.1rem;
    color: var(--color-purple);
}

.resources-header__title {
    font-size: 0.9rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.resources-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px 12px;
}

.resource-card {
    display: flex;
