    gap: 8px;
    padding: 8px 12px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    text-decoration: none;
    color: var(--color-charcoal);
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.resource-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.resource-card__icon {
    color: var(--color-lime);
    font-size: 0.8rem;
    flex-shrink: 0;
}

.resource-card__label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    line-height: 1.2;
}

/* ============================================================
   CODE METRICS
   ============================================================ */
.code-playground__metrics {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
}

.code-metrics-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
}

.code-metric {
    text-align: center;
    padding: 4px 8px;
    transition: all 0.3s ease;
}

.code-metric:hover {
    transform: translateY(-3px);
}

.code-metric__number {
    font-size: 2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 2px;
}

.code-metric__number .stat-number {
    display: inline-block;
}

.code-metric__number .stat-suffix {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.code-metric__number .stat-label--weekly {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
}

.code-metric__label {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ============================================================
   QUICK ACTIONS
   ============================================================ */
.code-playground__quick-actions {
    max-width: 900px;
    margin: 0 auto 40px;
}

.quick-actions-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
}

.quick-action-btn {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 14px 10px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 14px;
    text-decoration: none;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
