.quick-action-btn__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.quick-action-btn:hover .quick-action-btn__icon {
    color: var(--color-lime-dark);
    transform: scale(1.1);
}

.quick-action-btn__label {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-align: center;
    line-height: 1.2;
}

/* ============================================================
   VIEW ALL BUTTON
   ============================================================ */
.code-playground__view-all {
    text-align: center;
}

.btn-view-examples {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-view-examples:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

/* ----- Focus States ----- */
.lang-tab:focus-visible,
.workspace-btn:focus-visible,
.btn-featured-example:focus-visible,
.btn-view-examples:focus-visible,
.sdk-example__link:focus-visible,
.resource-card:focus-visible,
.quick-action-btn:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Code Examples, Interactive Snippets & Developer Playground
================================================== */

/* ==================================================
START: Downloads Center, SDK Library & Developer Resources
================================================== */

/* ----- Container ----- */
#downloads-center {
    padding: 80px 0 80px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.downloads-center__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.downloads-center__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.downloads-center__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.downloads-center__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.downloads-center__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.downloads-center__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.downloads-center__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.downloads-center__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.downloads-center__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.downloads-center__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.downloads-center__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.downloads-center__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#downloads-center .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#downloads-center .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#downloads-center .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#downloads-center .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#downloads-center .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#downloads-center .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#downloads-center .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.downloads-center__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.downloads-center__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.downloads-center__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.downloads-center__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.downloads-center__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.downloads-center__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   SECTION HEADER (Reusable)
   ============================================================ */
.section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.section-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.section-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.section-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

/* ============================================================
   FEATURED RESOURCE
   ============================================================ */
.downloads-center__featured {
    margin-bottom: 48px;
}

.featured-resource {
    display: grid;
    grid-template-columns: 35fr 65fr;
    gap: 32px;
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.featured-resource:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

/* ----- Featured Image ----- */
.featured-resource__image {
    position: relative;
    overflow: hidden;
    min-height: 260px;
}

.featured-resource__placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #6366F1);
    position: relative;
    overflow: hidden;
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.featured-resource:hover .featured-resource__placeholder {
    transform: scale(1.04);
}

.featured-resource__placeholder .placeholder-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    color: rgba(255, 255, 255, 0.9);
    z-index: 2;
    position: relative;
}

.featured-resource__placeholder .placeholder-content i {
    font-size: 3.2rem;
    opacity: 0.8;
}

.featured-resource__placeholder .placeholder-content span {
    font-size: 1rem;
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.05em;
    text-transform: uppercase;
    opacity: 0.5;
}

.featured-resource__placeholder .placeholder-shapes {
    position: absolute;
    inset: 0;
    overflow: hidden;
    z-index: 1;
}

.featured-resource__placeholder .placeholder-shapes .shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.05);
    pointer-events: none;
}

.featured-resource__placeholder .placeholder-shapes .shape--1 {
    width: 140px;
    height: 140px;
    top: -40px;
    right: -40px;
}

.featured-resource__placeholder .placeholder-shapes .shape--2 {
    width: 90px;
    height: 90px;
    bottom: 20px;
    left: 20px;
}

.featured-resource__placeholder .placeholder-shapes .shape--3 {
    width: 70px;
    height: 70px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.featured-resource__badge {
    position: absolute;
    top: 16px;
    left: 16px;
    padding: 4px 14px;
    background: rgba(192, 227, 74, 0.9);
    border-radius: 50px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    letter-spacing: 0.03em;
    text-transform: uppercase;
    z-index: 5;
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.2);
}

/* ----- Featured Content ----- */
.featured-resource__content {
    padding: 32px 36px 32px 0;
    display: flex;
    flex-direction: column;
    gap: 14px;
    justify-content: center;
}

.featured-resource__title {
    font-size: 1.4rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0;
    letter-spacing: -0.02em;
}

.featured-resource__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px 16px;
}

.meta-item {
    font-size: 0.72rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 4px;
}

.meta-item i {
    font-size: 0.65rem;
    color: var(--color-purple);
}

.featured-resource__description {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0;
}

.featured-resource__actions {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    margin-top: 4px;
}

.btn-download-featured {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
}

.btn-download-featured:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.4);
}

.btn-docs-featured {
    padding: 10px 28px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.btn-docs-featured:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ============================================================
   SDK LIBRARY
   ============================================================ */
.downloads-center__sdks {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.downloads-center__sdks:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.sdks-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px 16px;
}

.sdk-card {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 12px 16px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.sdk-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.sdk-card__icon {
    font-size: 1.5rem;
    color: var(--color-purple);
    flex-shrink: 0;
    width: 36px;
    text-align: center;
}

.sdk-card__info {
    flex: 1;
    min-width: 0;
}

.sdk-card__name {
    display: block;
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.sdk-card__meta {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 10px;
    font-size: 0.6rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin-top: 2px;
}

.sdk-card__actions {
    display: flex;
    gap: 4px;
    flex-shrink: 0;
}

.sdk-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    border-radius: 6px;
    border: 1px solid var(--color-gray-light);
    color: var(--color-gray-mid);
    background: var(--color-white);
    transition: all 0.3s ease;
    text-decoration: none;
    font-size: 0.6rem;
}

.sdk-btn:hover {
    border-color: var(--color-purple);
    color: var(--color-purple);
}

.sdk-btn--download:hover {
    border-color: var(--color-lime);
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.04);
}

/* ============================================================
   DOWNLOADS LIBRARY
   ============================================================ */
.downloads-center__library {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.downloads-center__library:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.library-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 8px 16px;
}

.library-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.library-item:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.library-item__icon {
    font-size: 1.1rem;
    color: var(--color-purple);
    flex-shrink: 0;
    width: 28px;
    text-align: center;
}

.library-item__info {
    flex: 1;
    min-width: 0;
}

.library-item__name {
    display: block;
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.library-item__meta {
    display: block;
    font-size: 0.6rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

.library-item__btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    border-radius: 6px;
    border: 1px solid var(--color-gray-light);
    color: var(--color-gray-mid);
    background: var(--color-white);
    transition: all 0.3s ease;
    text-decoration: none;
    font-size: 0.7rem;
    flex-shrink: 0;
}

.library-item__btn:hover {
    border-color: var(--color-lime);
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.04);
}

/* ============================================================
   DEVELOPER TOOLKIT
   ============================================================ */
.downloads-center__toolkit {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.downloads-center__toolkit:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.toolkit-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px 12px;
}

.toolkit-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    text-decoration: none;
    color: var(--color-charcoal);
}

.toolkit-item:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.toolkit-item__icon {
    font-size: 0.95rem;
    color: var(--color-lime);
    flex-shrink: 0;
}

.toolkit-item__label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    line-height: 1.2;
}

/* ============================================================
   RESOURCE STATISTICS
   ============================================================ */
.downloads-center__metrics {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
}

.metrics-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
}

.metric-stat {
    text-align: center;
    padding: 4px 8px;
    transition: all 0.3s ease;
}

.metric-stat:hover {
    transform: translateY(-3px);
}

.metric-stat__number {
    font-size: 2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 2px;
}

.metric-stat__number .stat-number {
    display: inline-block;
}

.metric-stat__number .stat-suffix {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.metric-stat__number .stat-label--weekly {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
}

.metric-stat__label {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ============================================================
   QUICK ACTIONS
   ============================================================ */
.downloads-center__quick-actions {
    max-width: 900px;
    margin: 0 auto 40px;
}

.quick-actions-grid {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 12px;
}

.quick-action-btn {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 14px 10px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    border: 1px solid var(--color-gray-light);
    border-radius: 14px;
    text-decoration: none;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: var(--shadow-glass);
}

.quick-action-btn:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.08);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.04);
    background: rgba(255, 255, 255, 0.6);
}

.quick-action-btn__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.quick-action-btn:hover .quick-action-btn__icon {
    color: var(--color-lime-dark);
    transform: scale(1.1);
}

.quick-action-btn__label {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    text-align: center;
    line-height: 1.2;
}

/* ============================================================
   VIEW ALL BUTTON
   ============================================================ */
.downloads-center__view-all {
    text-align: center;
}

.btn-view-resources {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-view-resources:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

/* ----- Focus States ----- */
.btn-download-featured:focus-visible,
.btn-docs-featured:focus-visible,
.sdk-btn:focus-visible,
.library-item__btn:focus-visible,
.toolkit-item:focus-visible,
.quick-action-btn:focus-visible,
.btn-view-resources:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Downloads Center, SDK Library & Developer Resources
================================================== */

