    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.support-hub__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.support-hub__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.support-hub__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.support-hub__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.support-hub__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.support-hub__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   SECTION HEADER (Reusable)
   ============================================================ */
.section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.section-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.section-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.section-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

/* ============================================================
   SUPPORT SEARCH
   ============================================================ */
.support-hub__search {
    max-width: 780px;
    margin: 0 auto 48px;
}

.support-search {
    background: rgba(255, 255, 255, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    padding: 20px 24px 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.support-search:hover {
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.06);
    border-color: rgba(124, 58, 237, 0.06);
}

.support-search__wrapper {
    display: flex;
    align-items: center;
    background: var(--color-white);
    border-radius: 16px;
    border: 1px solid var(--color-gray-light);
    transition: all 0.3s ease;
}

.support-search__wrapper:focus-within {
    border-color: var(--color-purple);
    box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.08);
}

.support-search__icon {
    padding: 0 16px;
    color: var(--color-gray-mid);
    font-size: 0.95rem;
}

.support-search__input {
    flex: 1;
    padding: 14px 0;
    border: none;
    outline: none;
    background: transparent;
    font-size: 0.95rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-charcoal);
}

.support-search__input::placeholder {
    color: var(--color-gray-light);
}

.support-search__btn {
    padding: 10px 24px;
    margin: 4px;
    border: none;
    border-radius: 12px;
    background: var(--color-lime);
    color: var(--color-charcoal);
    font-weight: var(--font-weight-semibold);
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    gap: 8px;
    white-space: nowrap;
}

.support-search__btn:hover {
    background: var(--color-lime-dark);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.3);
    transform: translateY(-2px);
}

.support-search__recent {
    margin-top: 12px;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px 10px;
}

.support-search__recent-label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
}

.support-search__recent-tag {
    font-size: 0.7rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.06);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid rgba(124, 58, 237, 0.08);
    transition: all 0.3s ease;
    cursor: default;
}

.support-search__recent-tag:hover {
    background: rgba(124, 58, 237, 0.12);
    border-color: rgba(124, 58, 237, 0.15);
}

/* ============================================================
   FAQ ACCORDION
   ============================================================ */
.support-hub__faq {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.support-hub__faq:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.faq-accordion {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.faq-item {
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: rgba(255, 255, 255, 0.3);
    overflow: hidden;
    transition: all 0.3s ease;
}

.faq-item:hover {
    background: rgba(255, 255, 255, 0.6);
    border-color: rgba(124, 58, 237, 0.06);
}

.faq-item__trigger {
    width: 100%;
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 12px 16px;
    padding: 14px 20px;
    background: transparent;
    border: none;
    cursor: pointer;
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: left;
    transition: all 0.3s ease;
}

.faq-item__trigger:hover {
    background: rgba(124, 58, 237, 0.02);
}

.faq-item__category {
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.08);
    padding: 2px 12px;
    border-radius: 50px;
    white-space: nowrap;
}

.faq-item__question {
    font-weight: var(--font-weight-medium);
    font-size: 0.85rem;
}

.faq-item__icon {
    font-size: 0.8rem;
    color: var(--color-gray-mid);
    transition: transform 0.3s ease;
}

.faq-item__trigger[aria-expanded="true"] .faq-item__icon {
    transform: rotate(180deg);
}

.faq-item__content {
    max-height: 0;
    overflow: hidden;
    padding: 0 20px;
    transition: max-height 0.4s ease, padding 0.4s ease;
    color: var(--color-gray-mid);
    font-size: 0.88rem;
    line-height: 1.6;
}

.faq-item__trigger[aria-expanded="true"] + .faq-item__content {
    max-height: 400px;
    padding: 0 20px 18px;
}

.faq-item__content p {
    margin: 0 0 12px;
}

.faq-item__content a {
    color: var(--color-purple);
    text-decoration: none;
    font-weight: var(--font-weight-medium);
}

.faq-item__content a:hover {
    text-decoration: underline;
}

.faq-item__content code {
    background: rgba(124, 58, 237, 0.06);
    padding: 1px 6px;
    border-radius: 4px;
    font-size: 0.8rem;
    color: var(--color-purple);
}

.faq-item__actions {
    display: flex;
    gap: 12px;
    margin-top: 4px;
}

.faq-item__vote,
.faq-item__copy {
    background: transparent;
    border: none;
    font-size: 0.7rem;
    color: var(--color-gray-mid);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border-radius: 6px;
    transition: all 0.2s ease;
}

.faq-item__vote:hover,
.faq-item__copy:hover {
    background: rgba(124, 58, 237, 0.04);
    color: var(--color-purple);
}

/* ============================================================
   TROUBLESHOOTING CENTER
   ============================================================ */
.support-hub__troubleshooting {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.support-hub__troubleshooting:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.troubleshooting-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
}

.trouble-card {
    display: grid;
    grid-template-columns: auto 1fr auto auto;
    align-items: center;
    gap: 10px 12px;
    padding: 12px 16px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.trouble-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.trouble-card__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.trouble-card__info {
    flex: 1;
    min-width: 0;
}

.trouble-card__name {
    display: block;
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.trouble-card__desc {
    display: block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

.trouble-card__severity {
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    padding: 2px 10px;
    border-radius: 50px;
    flex-shrink: 0;
}

.trouble-card__severity--high {
    background: rgba(239, 68, 68, 0.08);
    color: #dc2626;
}

.trouble-card__severity--medium {
    background: rgba(245, 158, 11, 0.08);
    color: #d97706;
}

.trouble-card__severity--low {
    background: rgba(16, 185, 129, 0.08);
    color: #059669;
}

.trouble-card__btn {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.06);
    padding: 4px 14px;
    border-radius: 50px;
    text-decoration: none;
    transition: all 0.3s ease;
    white-space: nowrap;
    flex-shrink: 0;
}

.trouble-card__btn:hover {
    background: var(--color-purple);
    color: var(--color-white);
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.2);
}

/* ============================================================
   DIAGNOSTICS PANEL
   ============================================================ */
.support-hub__diagnostics {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.support-hub__diagnostics:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.diagnostics-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
}

.diagnostic-card {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.diagnostic-card:hover {
    background: rgba(255, 255, 255, 0.7);
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.04);
}

.diagnostic-card__icon {
    font-size: 1.2rem;
    flex-shrink: 0;
}

.diagnostic-card--success .diagnostic-card__icon {
    color: #059669;
}

.diagnostic-card--warning .diagnostic-card__icon {
    color: #d97706;
}

.diagnostic-card--info .diagnostic-card__icon {
    color: #2563eb;
}

.diagnostic-card__info {
    flex: 1;
    min-width: 0;
}

.diagnostic-card__name {
    display: block;
    font-size: 0.78rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.diagnostic-card__status {
    display: block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

.diagnostic-card__indicator {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    flex-shrink: 0;
}

.diagnostic-card--success .diagnostic-card__indicator {
    background: #059669;
    box-shadow: 0 0 8px rgba(5, 150, 105, 0.3);
}

.diagnostic-card--warning .diagnostic-card__indicator {
    background: #d97706;
    box-shadow: 0 0 8px rgba(217, 119, 6, 0.3);
}

.diagnostic-card--info .diagnostic-card__indicator {
    background: #2563eb;
    box-shadow: 0 0 8px rgba(37, 99, 235, 0.3);
}

/* ============================================================
   SUPPORT OPTIONS
   ============================================================ */
.support-hub__options {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.support-hub__options:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.support-options-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
}

.support-option {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.support-option:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.support-option__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.support-option__info {
    flex: 1;
    min-width: 0;
}

.support-option__name {
    display: block;
    font-size: 0.78rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.support-option__desc {
    display: block;
    font-size: 0.62rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

.support-option__btn {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.06);
    padding: 3px 14px;
    border-radius: 50px;
    text-decoration: none;
    transition: all 0.3s ease;
    white-space: nowrap;
    flex-shrink: 0;
}

.support-option__btn:hover {
    background: var(--color-purple);
    color: var(--color-white);
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.2);
}

/* ============================================================
   COMMUNITY RESOURCES
   ============================================================ */
.support-hub__community {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.support-hub__community:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.community-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px 12px;
}

.community-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    text-decoration: none;
    color: var(--color-charcoal);
}

.community-item:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.community-item__icon {
    font-size: 0.95rem;
    color: var(--color-lime);
    flex-shrink: 0;
}

.community-item__label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    line-height: 1.2;
}

/* ============================================================
   SUPPORT METRICS
   ============================================================ */
.support-hub__metrics {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
}

.support-hub__metrics .metrics-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
}

.support-hub__metrics .metric-stat {
    text-align: center;
    padding: 4px 8px;
    transition: all 0.3s ease;
}

.support-hub__metrics .metric-stat:hover {
    transform: translateY(-3px);
}

.support-hub__metrics .metric-stat__number {
    font-size: 2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 2px;
}

.support-hub__metrics .metric-stat__number .stat-number {
    display: inline-block;
}

.support-hub__metrics .metric-stat__number .stat-suffix {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.support-hub__metrics .metric-stat__label {
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ============================================================
   CTA BUTTON
   ============================================================ */
.support-hub__cta {
    text-align: center;
}

.btn-visit-help-center {
    padding: 14px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
}

.btn-visit-help-center:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-3px);
    box-shadow: 0 8px 36px rgba(192, 227, 74, 0.45);
}

/* ----- Focus States ----- */
.support-search__input:focus-visible,
.faq-item__trigger:focus-visible,
.trouble-card__btn:focus-visible,
.support-option__btn:focus-visible,
.community-item:focus-visible,
.btn-visit-help-center:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Developer FAQ, Troubleshooting & Support Hub
================================================== */

/* ==================================================
START: Documentation CTA & Developer Community
================================================== */

/* ----- Container ----- */
#dev-community {
    padding: 80px 0 60px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.dev-community__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.dev-community__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.dev-community__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.dev-community__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.dev-community__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
