    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.contact-channels__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.contact-channels__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.contact-channels__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.contact-channels__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.contact-channels__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.contact-channels__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.contact-channels__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#contact-channels .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#contact-channels .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#contact-channels .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#contact-channels .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#contact-channels .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#contact-channels .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#contact-channels .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.contact-channels__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.contact-channels__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.contact-channels__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.contact-channels__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.contact-channels__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.contact-channels__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   SECTION HEADER (Reusable)
   ============================================================ */
.section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.section-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.section-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.section-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

/* ============================================================
   FEATURED CONTACT CARD
   ============================================================ */
.contact-channels__featured {
    margin-bottom: 48px;
}

.featured-contact {
    display: grid;
    grid-template-columns: 60fr 40fr;
    gap: 0;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.featured-contact:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.featured-contact__content {
    padding: 36px 40px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.featured-contact__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.featured-contact__title {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin: 0;
}

.featured-contact__desc {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0;
}

.featured-contact__status {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 2px;
}

.status-indicator {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

.status-indicator--available {
    background: #059669;
    box-shadow: 0 0 12px rgba(5, 150, 105, 0.3);
    animation: pulseDot 2s ease-in-out infinite;
}

.status-text {
    font-size: 0.8rem;
    font-weight: var(--font-weight-medium);
    color: #059669;
}

.featured-contact__details {
    display: flex;
    flex-wrap: wrap;
    gap: 16px 32px;
    padding: 12px 0 4px;
}

.detail-item {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.detail-item__label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-gray-mid);
}

.detail-item__value {
    font-size: 0.9rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

.detail-item__value i {
    color: #25D366;
    margin-right: 4px;
}

.featured-contact__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 4px;
}

.btn-whatsapp {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: #25D366;
    color: var(--color-white);
    box-shadow: 0 4px 20px rgba(37, 211, 102, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
}

.btn-whatsapp:hover {
    background: #1ebe5c;
    color: var(--color-white);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(37, 211, 102, 0.45);
}

.btn-email-featured {
    padding: 10px 28px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-email-featured:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- Featured Visual ----- */
.featured-contact__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    position: relative;
    overflow: hidden;
    min-height: 240px;
}

.featured-illustration {
    position: relative;
    width: 160px;
    height: 160px;
}

.fi-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 1.2rem;
    color: rgba(255, 255, 255, 0.5);
    transition: all 0.3s ease;
}

.fi-icon--1 { top: 0; left: 50%; transform: translateX(-50%); }
.fi-icon--2 { top: 35%; right: 0; }
.fi-icon--3 { bottom: 0; left: 50%; transform: translateX(-50%); }
.fi-icon--4 { top: 35%; left: 0; }

.fi-icon:hover {
    background: rgba(255, 255, 255, 0.15);
    color: var(--color-lime);
    transform: translateX(-50%) scale(1.1);
}

.fi-icon--2:hover {
    transform: scale(1.1);
}
.fi-icon--4:hover {
    transform: scale(1.1);
}

.fi-ring {
    position: absolute;
    border-radius: 50%;
    border: 1px solid rgba(255, 255, 255, 0.04);
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.fi-ring--1 {
    width: 120px;
    height: 120px;
    animation: pulseRing 4s ease-in-out infinite;
}

.fi-ring--2 {
    width: 160px;
    height: 160px;
    animation: pulseRing 4s ease-in-out infinite 1s;
}

.fi-ring--3 {
    width: 200px;
    height: 200px;
    animation: pulseRing 4s ease-in-out infinite 2s;
}

@keyframes pulseRing {
    0%, 100% {
        opacity: 0.2;
        transform: translate(-50%, -50%) scale(1);
    }
    50% {
        opacity: 0.6;
        transform: translate(-50%, -50%) scale(1.05);
    }
}

/* ============================================================
   COMMUNICATION CHANNELS
   ============================================================ */
.contact-channels__grid {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.contact-channels__grid:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.channels-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
}

.channel-card {
    display: grid;
    grid-template-columns: auto 1fr auto;
    gap: 8px 12px;
    padding: 14px 16px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    align-items: center;
}

.channel-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.channel-card--highlight {
    border-color: rgba(124, 58, 237, 0.12);
    background: rgba(124, 58, 237, 0.02);
}

.channel-card--highlight:hover {
    border-color: rgba(124, 58, 237, 0.2);
    background: rgba(124, 58, 237, 0.04);
}

.channel-card__icon {
    font-size: 1.4rem;
    color: var(--color-purple);
    flex-shrink: 0;
    grid-row: 1 / 4;
    align-self: center;
}

.channel-card__info {
    flex: 1;
    min-width: 0;
    grid-column: 2;
}

.channel-card__name {
    display: block;
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.channel-card__value {
    display: block;
    font-size: 0.75rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

.channel-card__tags {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.channel-card__tags .tag {
    font-size: 0.55rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    background: rgba(0, 0, 0, 0.03);
    padding: 1px 8px;
    border-radius: 50px;
}

.channel-card__socials {
    display: flex;
    gap: 4px;
    margin-top: 4px;
    flex-wrap: wrap;
}

.social-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-size: 0.65rem;
    transition: all 0.3s ease;
    text-decoration: none;
}

.social-link:hover {
    background: var(--color-purple);
    color: var(--color-white);
    transform: translateY(-2px);
}

.channel-card__availability {
    font-size: 0.6rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    padding: 2px 10px;
    border-radius: 50px;
    grid-column: 3;
    grid-row: 1;
    align-self: start;
    white-space: nowrap;
}

.channel-card__availability--available {
    background: rgba(5, 150, 105, 0.08);
    color: #059669;
}

.channel-card__availability--high {
    background: rgba(124, 58, 237, 0.08);
    color: var(--color-purple);
}

.channel-card__availability--info {
    background: rgba(37, 99, 235, 0.08);
    color: #2563eb;
}

.channel-card__btn {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.06);
    padding: 3px 14px;
    border-radius: 50px;
    text-decoration: none;
    transition: all 0.3s ease;
    white-space: nowrap;
    grid-column: 3;
    grid-row: 2;
    text-align: center;
    align-self: center;
}

.channel-card__btn--primary {
    background: var(--color-lime);
    color: var(--color-charcoal);
}

.channel-card__btn--primary:hover {
    background: var(--color-lime-dark);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.3);
}

.channel-card__btn:hover {
    background: var(--color-purple);
    color: var(--color-white);
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.2);
}

/* ============================================================
   INQUIRY CATEGORIES
   ============================================================ */
.contact-channels__inquiries {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.contact-channels__inquiries:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.inquiries-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 10px 14px;
}

.inquiry-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 4px;
    padding: 14px 12px 12px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.inquiry-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateY(-4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.inquiry-card__icon {
    font-size: 1.4rem;
    color: var(--color-purple);
}

.inquiry-card__name {
    font-size: 0.75rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.inquiry-card__desc {
    font-size: 0.6rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

.inquiry-card__btn {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.06);
    padding: 2px 14px;
    border-radius: 50px;
    text-decoration: none;
    transition: all 0.3s ease;
    margin-top: 4px;
}

.inquiry-card__btn:hover {
    background: var(--color-purple);
    color: var(--color-white);
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.2);
}

/* ============================================================
   BUSINESS INFORMATION PANEL
   ============================================================ */
.contact-channels__info-panel {
    max-width: 900px;
    margin: 0 auto 40px;
}

.info-panel {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    padding: 32px 36px;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.info-panel:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
    border-color: rgba(124, 58, 237, 0.06);
}

.info-panel__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.info-panel__title {
    font-size: 1.2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 8px 0 4px;
    letter-spacing: -0.02em;
}

.info-panel__desc {
    font-size: 0.88rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0 0 16px;
}

.info-panel__grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px 20px;
}

.info-item {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 8px 0;
}

.info-item__icon {
    font-size: 1rem;
    color: var(--color-lime);
    flex-shrink: 0;
    margin-top: 2px;
}

.info-item__label {
    display: block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.info-item__value {
    display: block;
    font-size: 0.82rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.3;
}

/* ============================================================
   CONTACT METRICS
   ============================================================ */
.contact-channels__metrics {
    max-width: 900px;
    margin: 0 auto 20px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
}

.contact-channels__metrics .metrics-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
}

.contact-channels__metrics .metric-stat {
    text-align: center;
    padding: 4px 8px;
    transition: all 0.3s ease;
}

.contact-channels__metrics .metric-stat:hover {
    transform: translateY(-3px);
}

.contact-channels__metrics .metric-stat__number {
    font-size: 1.8rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 2px;
}

.contact-channels__metrics .metric-stat__number .stat-number {
    display: inline-block;
}

.contact-channels__metrics .metric-stat__number .stat-suffix {
    font-size: 1.3rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.contact-channels__metrics .metric-stat__number .stat-label--hours {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
}

.contact-channels__metrics .metric-stat__number .stat-label--global {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
}

.contact-channels__metrics .metric-stat__number .stat-label--stars {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: #f59e0b;
}

.contact-channels__metrics .metric-stat__number .stat-label--stars .stat-suffix {
    color: #f59e0b;
    font-size: 1.3rem;
}

.contact-channels__metrics .metric-stat__label {
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ----- Focus States ----- */
.btn-whatsapp:focus-visible,
.btn-email-featured:focus-visible,
.channel-card__btn:focus-visible,
.inquiry-card__btn:focus-visible,
.social-link:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Multiple Contact Options & Communication Channels
================================================== */

/* ==================================================
START: Smart Contact Form & Project Inquiry
================================================== */

/* ----- Container ----- */
#contact-form {
    padding: 80px 0 60px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.contact-form__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.contact-form__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.contact-form__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.contact-form__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.contact-form__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.contact-form__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.contact-form__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.contact-form__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.contact-form__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.contact-form__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.contact-form__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.contact-form__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#contact-form .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#contact-form .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#contact-form .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#contact-form .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#contact-form .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#contact-form .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#contact-form .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.contact-form__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.contact-form__header {
    text-align: center;
    max-width: 700px;
    margin: 0 auto 48px;
}

.contact-form__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.contact-form__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.contact-form__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.contact-form__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   LAYOUT
   ============================================================ */
.contact-form__layout {
    display: grid;
    grid-template-columns: 60fr 40fr;
    gap: 40px;
    align-items: start;
}

/* ============================================================
   FORM CONTAINER
   ============================================================ */
.contact-form__form-wrapper {
    position: relative;
}

.form-container {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    padding: 32px 32px 28px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.form-container:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
    border-color: rgba(124, 58, 237, 0.06);
}

/* ----- Progress ----- */
.form-progress {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 28px;
    padding-bottom: 18px;
    border-bottom: 1px solid var(--color-gray-light);
}

.form-progress__bar {
    flex: 1;
    height: 4px;
    background: var(--color-gray-light);
    border-radius: 4px;
    overflow: hidden;
}

.form-progress__fill {
    height: 100%;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    border-radius: 4px;
    transition: width 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.form-progress__label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    min-width: 72px;
    text-align: right;
}

/* ----- Form Sections ----- */
.form-section {
    display: none;
    animation: fadeUp 0.5s ease;
}

.form-section--active {
    display: block;
}

.form-section__title {
    font-size: 1.1rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin-bottom: 20px;
    padding-bottom: 8px;
    border-bottom: 2px solid var(--color-lime);
    display: inline-block;
}

/* ----- Form Rows & Groups ----- */
.form-row {
    display: flex;
    gap: 16px;
    margin-bottom: 16px;
    flex-wrap: wrap;
}

.form-group {
    position: relative;
    margin-bottom: 4px;
}

.form-group--full {
    flex: 1 1 100%;
    min-width: 0;
}

.form-group--half {
    flex: 1 1 calc(50% - 8px);
    min-width: 200px;
}

.form-label {
    display: block;
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    margin-bottom: 6px;
}

.form-label .required {
    color: #dc2626;
    margin-left: 2px;
}

.form-input,
.form-select,
.form-textarea {
    width: 100%;
    padding: 10px 14px;
    font-size: 0.88rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-charcoal);
    background: var(--color-white);
    border: 1.5px solid var(--color-gray-light);
    border-radius: 12px;
    transition: all 0.3s ease;
    font-family: inherit;
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
    border-color: var(--color-purple);
    box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.08);
    outline: none;
}

.form-input:hover,
.form-select:hover,
.form-textarea:hover {
    border-color: rgba(124, 58, 237, 0.2);
}

.form-input.error,
.form-select.error,
.form-textarea.error {
    border-color: #dc2626;
    box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.08);
}

.form-textarea {
    resize: vertical;
    min-height: 100px;
}

.form-char-counter {
    text-align: right;
    font-size: 0.65rem;
    color: var(--color-gray-mid);
    margin-top: 4px;
}

.form-char-counter .char-count {
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

.form-error {
    display: none;
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: #dc2626;
    margin-top: 4px;
}

.form-error.visible {
    display: block;
}

/* ----- Radio & Checkbox Groups ----- */
.form-radio-group {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 14px;
    padding: 4px 0;
}

.form-radio-group--inline {
    gap: 4px 12px;
}

.radio-option,
.checkbox-option {
    display: flex;
    align-items: center;
    gap: 6px;
    cursor: pointer;
    font-size: 0.82rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-charcoal);
    transition: all 0.2s ease;
}

.radio-option:hover,
.checkbox-option:hover {
    color: var(--color-purple);
}

.radio-option input[type="radio"],
.checkbox-option input[type="checkbox"] {
    width: 16px;
    height: 16px;
    accent-color: var(--color-purple);
    cursor: pointer;
    flex-shrink: 0;
}

.radio-option input[type="radio"]:disabled,
.checkbox-option input[type="checkbox"]:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.radio-option .radio-label {
    display: flex;
    align-items: center;
    gap: 4px;
}

.radio-option .radio-label i {
    font-size: 0.85rem;
}

.checkbox-option--consent {
    font-size: 0.8rem;
    color: var(--color-gray-mid);
    line-height: 1.5;
}

.checkbox-option--consent .checkbox-label a {
    color: var(--color-purple);
    text-decoration: none;
}

.checkbox-option--consent .checkbox-label a:hover {
    text-decoration: underline;
}

/* ----- File Upload ----- */
.file-upload-area {
    position: relative;
    border: 2px dashed var(--color-gray-light);
    border-radius: 16px;
    padding: 32px 20px;
    text-align: center;
    transition: all 0.3s ease;
    cursor: pointer;
    min-height: 120px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.3);
}

.file-upload-area:hover {
    border-color: var(--color-purple);
    background: rgba(124, 58, 237, 0.02);
}

.file-upload-area.dragover {
    border-color: var(--color-lime);
    background: rgba(192, 227, 74, 0.04);
}

.file-upload-placeholder i {
    font-size: 2.4rem;
    color: var(--color-purple);
    opacity: 0.5;
    display: block;
    margin-bottom: 8px;
}

.file-upload-text {
    font-size: 0.88rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.file-upload-hint {
    font-size: 0.7rem;
    color: var(--color-gray-mid);
    margin-top: 4px;
}

.file-upload-input {
    position: absolute;
    inset: 0;
    opacity: 0;
    cursor: pointer;
}

.file-upload-list {
    margin-top: 12px;
    width: 100%;
    text-align: left;
}

.file-upload-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 12px;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 8px;
    font-size: 0.78rem;
    color: var(--color-charcoal);
    margin-top: 4px;
    border: 1px solid var(--color-gray-light);
}

.file-upload-item__name {
    display: flex;
    align-items: center;
    gap: 6px;
}

.file-upload-item__name i {
    color: var(--color-purple);
}

.file-upload-item__remove {
    background: none;
    border: none;
    color: #dc2626;
    cursor: pointer;
    font-size: 0.8rem;
    padding: 0 4px;
}

/* ----- Form Navigation ----- */
.form-navigation {
    display: flex;
    gap: 12px;
    margin-top: 20px;
    padding-top: 16px;
    border-top: 1px solid var(--color-gray-light);
}

.btn-form-next,
.btn-form-prev {
    padding: 8px 24px;
    font-size: 0.82rem;
    font-weight: var(--font-weight-medium);
    border: none;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    gap: 8px;
}

.btn-form-next {
    background: var(--color-purple);
    color: var(--color-white);
    margin-left: auto;
}

.btn-form-next:hover {
    background: #5b2fbf;
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(124, 58, 237, 0.3);
}

.btn-form-prev {
    background: rgba(0, 0, 0, 0.04);
    color: var(--color-gray-mid);
}

.btn-form-prev:hover {
    background: rgba(0, 0, 0, 0.06);
    transform: translateY(-2px);
}

/* ----- Submit Area ----- */
.form-submit-area {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 20px;
}

.btn-submit-form {
    padding: 12px 36px;
    font-size: 0.95rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
    cursor: pointer;
    transition: all 0.3s ease;
    position: relative;
    min-width: 200px;
    justify-content: center;
}

.btn-submit-form:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(192, 227, 74, 0.45);
}

.btn-submit-form .btn-loading,
.btn-submit-form .btn-success {
    display: none;
}

.btn-submit-form.loading .btn-text,
.btn-submit-form.loading .btn-success,
.btn-submit-form.loading i {
    display: none;
}

.btn-submit-form.loading .btn-loading {
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-submit-form.success .btn-text,
.btn-submit-form.success .btn-loading,
.btn-submit-form.success i {
    display: none;
}

.btn-submit-form.success .btn-success {
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-consult-form {
    padding: 12px 28px;
    font-size: 0.9rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-consult-form:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- Review Section ----- */
.form-review {
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.06);
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 16px;
}

.form-review__text {
    font-size: 0.85rem;
    color: var(--color-gray-mid);
    margin-bottom: 12px;
}

.form-review__summary {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4px 16px;
}

.review-item {
    font-size: 0.82rem;
    padding: 4px 0;
    border-bottom: 1px solid rgba(0, 0, 0, 0.03);
}

.review-label {
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin-right: 6px;
}

.review-value {
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

/* ----- Success & Error States ----- */
.form-success {
    text-align: center;
    padding: 40px 20px;
}

.form-success__icon {
    font-size: 4rem;
    color: #059669;
    margin-bottom: 16px;
}

.form-success__title {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin-bottom: 8px;
}

.form-success__desc {
    font-size: 0.95rem;
    color: var(--color-gray-mid);
    max-width: 400px;
    margin: 0 auto 8px;
}

.form-success__note {
    font-size: 0.85rem;
    color: var(--color-gray-mid);
    margin-bottom: 20px;
}

.btn-success-reset {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-purple);
    color: var(--color-white);
    box-shadow: 0 4px 20px rgba(124, 58, 237, 0.3);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-success-reset:hover {
    background: #5b2fbf;
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.4);
}

.form-error-global {
    display: flex;
    align-items: center;
    gap: 10px;
    background: rgba(220, 38, 38, 0.06);
    border: 1px solid rgba(220, 38, 38, 0.12);
    border-radius: 12px;
    padding: 12px 18px;
    color: #dc2626;
    font-size: 0.85rem;
    margin-top: 16px;
}

.form-error-global i {
    font-size: 1.2rem;
}

/* ============================================================
   INFO PANEL
   ============================================================ */
.contact-form__info-panel {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.info-card {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    padding: 24px 24px 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.info-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.06);
    border-color: rgba(124, 58, 237, 0.06);
}

.info-card--highlight {
    border-color: rgba(192, 227, 74, 0.2);
    background: rgba(192, 227, 74, 0.03);
}

.info-card--highlight:hover {
    border-color: rgba(192, 227, 74, 0.3);
}

.info-card__icon {
    font-size: 1.6rem;
    color: var(--color-purple);
    display: block;
    margin-bottom: 8px;
}

.info-card__title {
    font-size: 1.05rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 12px;
    letter-spacing: -0.02em;
}

.info-card__list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.info-card__list li {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 5px 0;
    font-size: 0.85rem;
    color: var(--color-gray-mid);
    line-height: 1.4;
}

.info-card__list li i {
    color: var(--color-lime);
    font-size: 0.8rem;
    flex-shrink: 0;
}

.info-card__list--compact li {
    font-size: 0.82rem;
    padding: 4px 0;
}

.info-card__list--compact li strong {
    color: var(--color-charcoal);
}

/* ----- Process Steps ----- */
.process-steps {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6px 12px;
}

.process-step {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 4px 0;
}

.step-number {
    font-size: 0.7rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.08);
    padding: 1px 8px;
    border-radius: 50px;
    min-width: 28px;
    text-align: center;
}

.step-label {
    font-size: 0.8rem;
    color: var(--color-charcoal);
}

/* ----- Focus States ----- */
.form-input:focus-visible,
.form-select:focus-visible,
.form-textarea:focus-visible,
.btn-submit-form:focus-visible,
.btn-consult-form:focus-visible,
.btn-form-next:focus-visible,
.btn-form-prev:focus-visible,
.btn-success-reset:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Smart Contact Form & Project Inquiry
================================================== */

/* ==================================================
START: Office Location, Interactive Map & Global Presence
================================================== */

/* ----- Container ----- */
#office-location {
    padding: 80px 0 60px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.office-location__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.office-location__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.office-location__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.office-location__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.office-location__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.office-location__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.office-location__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.office-location__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.office-location__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.office-location__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.office-location__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.office-location__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#office-location .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#office-location .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#office-location .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#office-location .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#office-location .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#office-location .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#office-location .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.office-location__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.office-location__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.office-location__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.office-location__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.office-location__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.office-location__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   SECTION HEADER (Reusable)
   ============================================================ */
.section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.section-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.section-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.section-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

/* ============================================================
   TWO-COLUMN LAYOUT
   ============================================================ */
.office-location__layout {
    display: grid;
    grid-template-columns: 40fr 60fr;
    gap: 32px;
    margin-bottom: 48px;
    align-items: stretch;
}

/* ============================================================
   OFFICE CARD
   ============================================================ */
.office-card {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    padding: 32px 32px 28px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    height: 100%;
    display: flex;
    flex-direction: column;
}

.office-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
    border-color: rgba(124, 58, 237, 0.06);
}

.office-card__header {
    margin-bottom: 18px;
}

.office-card__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.office-card__title {
    font-size: 1.4rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin: 4px 0 0;
}

.office-card__address {
    display: flex;
    gap: 14px;
    padding: 16px 0;
    border-top: 1px solid var(--color-gray-light);
    border-bottom: 1px solid var(--color-gray-light);
    margin-bottom: 16px;
}

.office-card__address i {
    font-size: 1.4rem;
    color: var(--color-purple);
    flex-shrink: 0;
    margin-top: 2px;
}

.address-details {
    display: flex;
    flex-direction: column;
    gap: 1px;
}

.address-line {
    font-size: 0.92rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.4;
}

.office-card__details {
    display: flex;
    flex-direction: column;
    gap: 12px;
    flex: 1;
}

.detail-item {
    display: flex;
    gap: 12px;
    align-items: flex-start;
}

.detail-item__icon {
    font-size: 1.1rem;
    color: var(--color-lime);
    flex-shrink: 0;
    margin-top: 2px;
}

.detail-item__label {
    display: block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--color-gray-mid);
}

.detail-item__value {
    display: block;
    font-size: 0.88rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.3;
}

.detail-item__value--open {
    display: flex;
    align-items: center;
    gap: 6px;
}

.status-dot {
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #059669;
    box-shadow: 0 0 12px rgba(5, 150, 105, 0.3);
    animation: pulseDot 2s ease-in-out infinite;
}

.detail-item__note {
    display: block;
    font-size: 0.7rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
}

.office-card__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 20px;
    padding-top: 16px;
    border-top: 1px solid var(--color-gray-light);
}

.btn-directions {
    padding: 10px 24px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
}

.btn-directions:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.45);
}

.btn-schedule-visit {
    padding: 10px 24px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-schedule-visit:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ============================================================
   MAP CONTAINER
   ============================================================ */
.map-container {
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    height: 100%;
    min-height: 380px;
}

.map-container:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
    border-color: rgba(124, 58, 237, 0.06);
}

.map-container__placeholder {
    width: 100%;
    height: 100%;
    min-height: 380px;
    position: relative;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    overflow: hidden;
}

.map-placeholder {
    position: relative;
    width: 100%;
    height: 100%;
    min-height: 380px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.map-placeholder__content {
    position: relative;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ----- Map Pin ----- */
.map-pin {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    z-index: 10;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
}

.pin-icon {
    font-size: 2.8rem;
    color: var(--color-lime);
    filter: drop-shadow(0 4px 16px rgba(192, 227, 74, 0.4));
    animation: floatBubble 3s ease-in-out infinite;
}

.pin-label {
    font-size: 0.8rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-white);
    background: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    padding: 4px 14px;
    border-radius: 50px;
    border: 1px solid rgba(255, 255, 255, 0.08);
}

.pin-pulse {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: rgba(192, 227, 74, 0.15);
    animation: pingPulse 2s ease-in-out infinite;
}

@keyframes pingPulse {
    0% {
        transform: translate(-50%, -50%) scale(0.8);
        opacity: 1;
    }
    100% {
        transform: translate(-50%, -50%) scale(2);
        opacity: 0;
    }
}

/* ----- Map Grid ----- */
.map-grid {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-columns: repeat(8, 1fr);
    grid-template-rows: repeat(6, 1fr);
    pointer-events: none;
    opacity: 0.06;
}

.grid-line {
    border: 1px solid rgba(255, 255, 255, 0.15);
}

.grid-line:nth-child(-n+6) {
    border-top: none;
    border-left: 1px solid rgba(255, 255, 255, 0.1);
}

/* ----- Map Controls ----- */
.map-controls {
    position: absolute;
    right: 16px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    flex-direction: column;
    gap: 6px;
    z-index: 5;
}

.map-control {
    width: 36px;
    height: 36px;
    border: none;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.15);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    color: rgba(255, 255, 255, 0.7);
    font-size: 0.9rem;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}

.map-control:hover {
    background: rgba(255, 255, 255, 0.25);
    color: var(--color-white);
    transform: scale(1.05);
}

.map-control--fullscreen {
    margin-top: 4px;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
}

/* ----- Nearby Places ----- */
.map-nearby {
    position: absolute;
    bottom: 16px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    gap: 6px;
    background: rgba(0, 0, 0, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    padding: 6px 14px;
    border-radius: 50px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    z-index: 5;
    flex-wrap: wrap;
    justify-content: center;
}

.nearby-label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: rgba(255, 255, 255, 0.5);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.nearby-tag {
    font-size: 0.65rem;
    font-weight: var(--font-weight-regular);
    color: rgba(255, 255, 255, 0.7);
    padding: 2px 10px;
    border-radius: 50px;
    background: rgba(255, 255, 255, 0.06);
}

/* ----- Embed Placeholder ----- */
.map-embed-placeholder {
    position: absolute;
    bottom: 60px;
    right: 16px;
    text-align: right;
    z-index: 3;
}

.embed-text {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: rgba(255, 255, 255, 0.3);
    margin: 0;
}

.embed-subtext {
    font-size: 0.55rem;
    font-weight: var(--font-weight-regular);
    color: rgba(255, 255, 255, 0.15);
    margin: 0;
}

.embed-icon {
    font-size: 1.4rem;
    color: rgba(255, 255, 255, 0.06);
    display: block;
    margin-top: 2px;
}

/* ============================================================
   GLOBAL PRESENCE
   ============================================================ */
.office-location__global {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.office-location__global:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.global-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px 16px;
}

.global-card {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.global-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.global-card__icon {
    font-size: 1.4rem;
    color: var(--color-lime);
    flex-shrink: 0;
    width: 32px;
    text-align: center;
}

.global-card__title {
    display: block;
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.global-card__desc {
    display: block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

/* ============================================================
   SERVICE REGIONS
   ============================================================ */
.office-location__regions {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.office-location__regions:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.regions-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 12px;
}

.region-badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px;
    background: rgba(255, 255, 255, 0.4);
    border: 1px solid var(--color-gray-light);
    border-radius: 50px;
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    transition: all 0.3s ease;
    cursor: default;
}

.region-badge:hover {
    border-color: var(--color-purple);
    background: rgba(124, 58, 237, 0.04);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.04);
}

/* ============================================================
   OFFICE HIGHLIGHTS
   ============================================================ */
.office-location__highlights {
    max-width: 900px;
    margin: 0 auto 20px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.office-location__highlights:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.highlights-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 8px 12px;
}

.highlight-card {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.highlight-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.highlight-card__icon {
    font-size: 1.1rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.highlight-card__label {
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.2;
}

/* ----- Focus States ----- */
.btn-directions:focus-visible,
.btn-schedule-visit:focus-visible,
.map-control:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Office Location, Interactive Map & Global Presence
================================================== */

/* ==================================================
START: Business Hours, Response Time & Customer Support Availability
================================================== */

/* ----- Container ----- */
#support-availability {
    padding: 80px 0 60px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.support-availability__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.support-availability__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.support-availability__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.support-availability__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.support-availability__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.support-availability__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.support-availability__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.support-availability__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.support-availability__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.support-availability__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.support-availability__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.support-availability__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
