   SUPPORT PROCESS TIMELINE
   ============================================================ */
.support-availability__process {
    max-width: 900px;
    margin: 0 auto 20px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.support-availability__process:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.process-timeline {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 0;
    position: relative;
    padding: 12px 0 8px;
}

.process-timeline::before {
    content: '';
    position: absolute;
    top: 44px;
    left: 8%;
    right: 8%;
    height: 2px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.2;
}

.timeline-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    position: relative;
    padding: 0 8px;
}

.timeline-step__number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: var(--color-white);
    border: 2px solid var(--color-lime);
    font-size: 0.7rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-bottom: 10px;
    position: relative;
    z-index: 2;
    transition: all 0.3s ease;
}

.timeline-step:hover .timeline-step__number {
    background: var(--color-lime);
    color: var(--color-charcoal);
    transform: scale(1.1);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.3);
}

.timeline-step__content {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.timeline-step__label {
    font-size: 0.78rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.timeline-step__desc {
    font-size: 0.62rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.3;
}

.timeline-step__connector {
    display: none;
}

