    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ============================================================
   DEPARTMENTS GRID
   ============================================================ */
.team-directory__departments {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.team-directory__departments:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.departments-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px 16px;
}

.department-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 14px 12px 12px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.department-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateY(-4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.department-card__icon {
    font-size: 1.6rem;
    color: var(--color-purple);
    margin-bottom: 4px;
}

.department-card__name {
    font-size: 0.8rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.department-card__desc {
    font-size: 0.65rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
    margin: 2px 0 4px;
}

.department-card__size {
    font-size: 0.6rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin-bottom: 6px;
}

.department-card__size i {
    margin-right: 4px;
}

.department-card__btn {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.06);
    padding: 2px 16px;
    border-radius: 50px;
    text-decoration: none;
    transition: all 0.3s ease;
}

.department-card__btn:hover {
    background: var(--color-purple);
    color: var(--color-white);
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.2);
}

/* ============================================================
   DEPARTMENT RESPONSIBILITIES (ACCORDION)
   ============================================================ */
.team-directory__responsibilities {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.team-directory__responsibilities:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.responsibilities-accordion {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.resp-item {
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: rgba(255, 255, 255, 0.3);
    overflow: hidden;
    transition: all 0.3s ease;
}

.resp-item:hover {
    background: rgba(255, 255, 255, 0.6);
    border-color: rgba(124, 58, 237, 0.06);
}

.resp-item__trigger {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 20px;
    background: transparent;
    border: none;
    cursor: pointer;
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: left;
    transition: all 0.3s ease;
}

.resp-item__trigger:hover {
    background: rgba(124, 58, 237, 0.02);
}

.resp-item__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.resp-item__title {
    flex: 1;
}

.resp-item__toggle {
    font-size: 0.8rem;
    color: var(--color-gray-mid);
    transition: transform 0.3s ease;
}

.resp-item__trigger[aria-expanded="true"] .resp-item__toggle {
    transform: rotate(180deg);
}

.resp-item__content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s ease, padding 0.4s ease;
}

.resp-item__trigger[aria-expanded="true"] + .resp-item__content {
    max-height: 600px;
    padding: 0 20px 18px;
}

.resp-item__grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 16px;
}

.resp-detail__label {
    display: block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--color-gray-mid);
    margin-bottom: 4px;
}

.resp-detail__label i {
    margin-right: 4px;
}

.resp-detail__list {
    margin: 0;
    padding: 0 0 0 16px;
    font-size: 0.78rem;
    color: var(--color-gray-mid);
    line-height: 1.6;
}

.resp-detail__list li {
    margin-bottom: 2px;
}

.resp-detail__value {
    display: block;
    font-size: 0.82rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.4;
}

.resp-detail__value--available {
    color: #059669;
}

.resp-detail__value--available::before {
    content: '● ';
}

/* ============================================================
   COMMUNICATION FLOW
   ============================================================ */
.team-directory__flow {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.team-directory__flow:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.flow-timeline {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 0;
    position: relative;
    padding: 12px 0 8px;
}

.flow-timeline::before {
    content: '';
    position: absolute;
    top: 44px;
    left: 8%;
    right: 8%;
    height: 2px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.2;
}

.flow-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    position: relative;
    padding: 0 4px;
}

.flow-step__number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: var(--color-white);
    border: 2px solid var(--color-lime);
    font-size: 0.65rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-bottom: 8px;
    position: relative;
    z-index: 2;
    transition: all 0.3s ease;
}

.flow-step:hover .flow-step__number {
    background: var(--color-lime);
    color: var(--color-charcoal);
    transform: scale(1.1);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.3);
}

.flow-step__label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.flow-step__desc {
    font-size: 0.58rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.3;
    margin-top: 2px;
}

.flow-step__arrow {
    display: none;
}

/* ============================================================
   TEAM VALUES
   ============================================================ */
.team-directory__values {
    max-width: 900px;
    margin: 0 auto 20px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.team-directory__values:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.values-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px 12px;
}

.value-card {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.value-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.value-card__icon {
    font-size: 1rem;
    color: var(--color-lime);
    flex-shrink: 0;
}

.value-card__label {
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.2;
}

/* ----- Focus States ----- */
.btn-contact-leader:focus-visible,
.btn-linkedin:focus-visible,
.department-card__btn:focus-visible,
.resp-item__trigger:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

