    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.contact-faq-final__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.contact-faq-final__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   SECTION HEADER (Reusable)
   ============================================================ */
.section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.section-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.section-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.section-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

/* ============================================================
   TWO-COLUMN LAYOUT
   ============================================================ */
.contact-faq-final__layout {
    display: grid;
    grid-template-columns: 55fr 45fr;
    gap: 32px;
    margin-bottom: 48px;
    align-items: start;
}

/* ============================================================
   FAQ ACCORDION
   ============================================================ */
.contact-faq-final__faq {
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    padding: 28px 28px 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.contact-faq-final__faq:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.faq-final-accordion {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.faq-final-item {
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: rgba(255, 255, 255, 0.3);
    overflow: hidden;
    transition: all 0.3s ease;
}

.faq-final-item:hover {
    background: rgba(255, 255, 255, 0.6);
    border-color: rgba(124, 58, 237, 0.06);
}

.faq-final-item__trigger {
    width: 100%;
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 10px 14px;
    padding: 12px 16px;
    background: transparent;
    border: none;
    cursor: pointer;
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: left;
    transition: all 0.3s ease;
}

.faq-final-item__trigger:hover {
    background: rgba(124, 58, 237, 0.02);
}

.faq-final-item__category {
    font-size: 0.55rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.08);
    padding: 1px 10px;
    border-radius: 50px;
    white-space: nowrap;
}

.faq-final-item__question {
    font-size: 0.82rem;
}

.faq-final-item__toggle {
    font-size: 0.75rem;
    color: var(--color-gray-mid);
    transition: transform 0.3s ease;
}

.faq-final-item__trigger[aria-expanded="true"] .faq-final-item__toggle {
    transform: rotate(180deg);
}

.faq-final-item__content {
    max-height: 0;
    overflow: hidden;
    padding: 0 16px;
    transition: max-height 0.4s ease, padding 0.4s ease;
    color: var(--color-gray-mid);
    font-size: 0.82rem;
    line-height: 1.6;
}

.faq-final-item__trigger[aria-expanded="true"] + .faq-final-item__content {
    max-height: 300px;
    padding: 0 16px 14px;
}

.faq-final-item__content p {
    margin: 0 0 8px;
}

.faq-final-item__actions {
    display: flex;
    gap: 12px;
    margin-top: 4px;
}

.faq-final-item__vote,
.faq-final-item__copy {
    background: transparent;
    border: none;
    font-size: 0.65rem;
    color: var(--color-gray-mid);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border-radius: 6px;
    transition: all 0.2s ease;
}

.faq-final-item__vote:hover,
.faq-final-item__copy:hover {
    background: rgba(124, 58, 237, 0.04);
    color: var(--color-purple);
}

/* ============================================================
   CONSULTATION PROCESS
   ============================================================ */
.contact-faq-final__process {
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    padding: 28px 28px 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.contact-faq-final__process:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.process-cards {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.process-card {
    display: flex;
    gap: 14px;
    padding: 10px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.process-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.process-card__number {
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 28px;
    height: 28px;
    border-radius: 50%;
    background: var(--color-lime);
    color: var(--color-charcoal);
    font-size: 0.65rem;
    font-weight: var(--font-weight-bold);
    flex-shrink: 0;
    margin-top: 2px;
}

.process-card__content {
    flex: 1;
    min-width: 0;
}

.process-card__title {
    display: block;
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.process-card__desc {
    display: block;
    font-size: 0.7rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

.process-card__time {
    display: inline-block;
    font-size: 0.6rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin-top: 2px;
}

.process-card__time i {
    margin-right: 3px;
}

/* ============================================================
   PROJECT JOURNEY TIMELINE
   ============================================================ */
.contact-faq-final__journey {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.contact-faq-final__journey:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.journey-timeline {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 0;
    position: relative;
    padding: 16px 0 8px;
}

.journey-timeline::before {
    content: '';
    position: absolute;
    top: 38px;
    left: 8%;
    right: 8%;
    height: 2px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.2;
}

.journey-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    position: relative;
    padding: 0 4px;
}

.journey-step__icon {
    font-size: 1.4rem;
    color: var(--color-purple);
    margin-bottom: 6px;
    position: relative;
    z-index: 2;
    background: var(--color-white);
    padding: 4px 8px;
    border-radius: 8px;
    transition: all 0.3s ease;
}

.journey-step:hover .journey-step__icon {
    color: var(--color-lime);
    transform: scale(1.1);
}

.journey-step__label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.journey-step__connector {
    display: none;
}

/* ============================================================
   TRUST & GUARANTEE CARDS
   ============================================================ */
.contact-faq-final__trust {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.contact-faq-final__trust:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.trust-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px 12px;
}

.trust-card {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.trust-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.trust-card__icon {
    font-size: 1rem;
    color: var(--color-lime);
    flex-shrink: 0;
}

.trust-card__label {
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.2;
}

/* ============================================================
   FINAL PREMIUM CTA BANNER
   ============================================================ */
.contact-faq-final__cta {
    max-width: 1000px;
    margin: 0 auto 0;
}

.final-cta-banner {
    display: grid;
    grid-template-columns: 60fr 40fr;
    gap: 0;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.final-cta-banner:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.final-cta-banner__content {
    padding: 40px 40px 36px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.final-cta-banner__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.final-cta-banner__title {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.2;
    margin: 0;
}

.final-cta-banner__desc {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    max-width: 520px;
    margin: 0;
}

.final-cta-banner__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 4px;
}

.btn-cta-start {
    padding: 12px 32px;
    font-size: 0.9rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
}

.btn-cta-start:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(192, 227, 74, 0.45);
}

.btn-cta-consult {
    padding: 12px 32px;
    font-size: 0.9rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-cta-consult:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- CTA Visual ----- */
.final-cta-banner__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    position: relative;
    overflow: hidden;
    padding: 30px 20px;
    min-height: 220px;
}

.cta-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 1.2rem;
    color: rgba(255, 255, 255, 0.3);
    transition: all 0.3s ease;
}

.cta-icon--1 {
    top: 20%;
    left: 15%;
    animation: floatIcon 4s ease-in-out infinite;
}
.cta-icon--2 {
    top: 20%;
    right: 15%;
    animation: floatIcon 4s ease-in-out infinite 1s;
}
.cta-icon--3 {
    bottom: 20%;
    left: 25%;
    animation: floatIcon 4s ease-in-out infinite 2s;
}
.cta-icon--4 {
    bottom: 20%;
    right: 25%;
    animation: floatIcon 4s ease-in-out infinite 0.5s;
}

.cta-icon:hover {
    background: rgba(255, 255, 255, 0.12);
    color: var(--color-lime);
    transform: scale(1.1);
}

.cta-shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.03);
}

.cta-shape--1 {
    width: 120px;
    height: 120px;
    top: -40px;
    right: -30px;
}

.cta-shape--2 {
    width: 80px;
    height: 80px;
    bottom: -20px;
    left: -20px;
}

.cta-shape--3 {
    width: 50px;
    height: 50px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

@keyframes floatIcon {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-10px);
    }
}

/* ----- Focus States ----- */
.faq-final-item__trigger:focus-visible,
.faq-final-item__vote:focus-visible,
.faq-final-item__copy:focus-visible,
.btn-cta-start:focus-visible,
.btn-cta-consult:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Contact FAQ, Consultation Process & Final CTA
================================================== */

/* ==================================================
START: Services Hero Banner
================================================== */

/* ----- Container ----- */
#services-hero {
    padding: 40px 0 60px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
    min-height: 100vh;
    display: flex;
    align-items: center;
}

/* ----- Background Decorations ----- */
.services-hero__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
