    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.services-hero__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.services-hero__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.services-hero__orb {
    position: absolute;
    border-radius: 50%;
