    font-size: 0.9rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-services-consult:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- Trust Badges ----- */
.services-hero__trust {
    display: flex;
    flex-wrap: wrap;
    gap: 6px 14px;
    margin-top: 4px;
}

.trust-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.75rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    padding: 4px 14px 4px 10px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    box-shadow: var(--shadow-glass);
    transition: all 0.3s ease;
}

.trust-badge i {
    color: var(--color-lime);
    font-size: 0.8rem;
}

.trust-badge:hover {
    transform: translateY(-2px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 4px 16px rgba(124, 58, 237, 0.04);
}

/* ----- Hero Highlights ----- */
.services-hero__highlights {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-top: 4px;
}

.highlight-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 14px 12px;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 14px;
    box-shadow: var(--shadow-glass);
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.highlight-card:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.04);
}

.highlight-card__number {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    letter-spacing: -0.02em;
    line-height: 1.2;
}

.highlight-card__number i {
    font-size: 1.4rem;
    color: var(--color-lime);
}

.highlight-card__label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin-top: 2px;
}

/* ============================================================
   HERO VISUAL
   ============================================================ */
.services-hero__visual {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 500px;
}

.hero-visual {
    position: relative;
    width: 100%;
    max-width: 520px;
    height: 500px;
    margin: 0 auto;
}

/* ----- Browser Mockup ----- */
.visual-card {
    position: absolute;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-radius: 16px;
    border: 1px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.04);
    transition: all 0.3s ease;
}

.visual-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.06);
}

.visual-card--browser {
    top: 5%;
    left: 10%;
    width: 220px;
    border-radius: 12px;
    overflow: hidden;
    animation: floatCard 5s ease-in-out infinite;
}

.browser-header {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 12px;
    background: rgba(0, 0, 0, 0.02);
    border-bottom: 1px solid var(--color-gray-light);
}

.browser-header .dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
}

.dot--red { background: #ef4444; }
.dot--yellow { background: #f59e0b; }
.dot--green { background: #059669; }

.browser-url {
    font-size: 0.55rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin-left: 4px;
    background: rgba(0, 0, 0, 0.03);
    padding: 1px 8px;
    border-radius: 4px;
}

.browser-body {
    padding: 10px 12px 12px;
}

.browser-chart {
    display: flex;
    align-items: flex-end;
    gap: 4px;
    height: 50px;
    margin-bottom: 6px;
}

.bar {
    flex: 1;
    background: var(--color-purple);
    border-radius: 3px 3px 0 0;
    opacity: 0.4;
    transition: all 0.3s ease;
    min-height: 8px;
}

.bar--1 { opacity: 0.5; }
.bar--2 { opacity: 0.7; background: var(--color-lime); }
.bar--3 { opacity: 0.4; }
.bar--4 { opacity: 0.9; background: var(--color-lime); }
.bar--5 { opacity: 0.6; }
.bar--6 { opacity: 0.4; }

.browser-stats {
    display: flex;
    justify-content: space-between;
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
}

.browser-stats .stat:first-child {
    color: #059669;
}

/* ----- Mobile Mockup ----- */
.visual-card--mobile {
    bottom: 15%;
    right: 8%;
    width: 80px;
    border-radius: 14px;
    padding: 6px 6px 10px;
    background: rgba(255, 255, 255, 0.8);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.06);
    animation: floatCard 6s ease-in-out infinite 1.5s;
}

.mobile-notch {
    width: 24px;
    height: 4px;
    background: var(--color-gray-light);
    border-radius: 4px;
    margin: 0 auto 6px;
}

.mobile-screen {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 4px;
    padding: 4px;
}

.mobile-app-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    aspect-ratio: 1;
    border-radius: 6px;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-size: 0.6rem;
    transition: all 0.3s ease;
}

.mobile-app-icon:hover {
    background: rgba(124, 58, 237, 0.12);
    transform: scale(1.05);
}

.mobile-app-icon:nth-child(2) { background: rgba(192, 227, 74, 0.06); color: var(--color-lime-dark); }
.mobile-app-icon:nth-child(4) { background: rgba(192, 227, 74, 0.06); color: var(--color-lime-dark); }

/* ----- Analytics Card ----- */
.visual-card--analytics {
    bottom: 30%;
    left: 5%;
    width: 150px;
    padding: 12px 14px;
    animation: floatCard 5.5s ease-in-out infinite 2.5s;
}

.analytics-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
}

.analytics-title {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

.analytics-trend {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: #059669;
}

.analytics-trend i {
    font-size: 0.5rem;
}

.analytics-row {
    display: flex;
    justify-content: space-between;
    font-size: 0.65rem;
    padding: 2px 0;
    border-bottom: 1px solid rgba(0, 0, 0, 0.02);
}

.analytics-row .label {
    color: var(--color-gray-mid);
}

.analytics-row .value {
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

.analytics-progress {
    margin-top: 6px;
    height: 3px;
    background: var(--color-gray-light);
    border-radius: 3px;
    overflow: hidden;
}

.analytics-progress .progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    border-radius: 3px;
}

/* ----- AI Node ----- */
.visual-card--ai {
    top: 45%;
    right: 5%;
    width: 70px;
    height: 70px;
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: rgba(124, 58, 237, 0.04);
    border: 1px solid rgba(124, 58, 237, 0.08);
    animation: floatCard 4.5s ease-in-out infinite 1s;
}

.ai-icon {
    font-size: 1.4rem;
    color: var(--color-purple);
}

.ai-label {
    font-size: 0.5rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin-top: 2px;
}

.ai-pulse {
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.04);
    animation: pulseRing 3s ease-in-out infinite;
}

/* ----- Cloud Node ----- */
.visual-card--cloud {
    top: 15%;
    right: 20%;
    width: 56px;
    height: 56px;
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: rgba(192, 227, 74, 0.04);
    border: 1px solid rgba(192, 227, 74, 0.08);
    animation: floatCard 5s ease-in-out infinite 3s;
}

.cloud-icon {
    font-size: 1.2rem;
    color: var(--color-lime-dark);
}

.cloud-label {
    font-size: 0.5rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin-top: 1px;
}

/* ----- Connection Lines ----- */
.connection-lines {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
}

/* ----- Floating Orbs ----- */
.orb {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.04);
    border: 1px solid rgba(124, 58, 237, 0.04);
    animation: pulseGlow 4s ease-in-out infinite;
}

.orb--1 {
    width: 50px;
    height: 50px;
    top: 20%;
    right: 30%;
    animation-delay: 0s;
}

.orb--2 {
    width: 30px;
    height: 30px;
    bottom: 40%;
    left: 20%;
    background: rgba(192, 227, 74, 0.04);
    border-color: rgba(192, 227, 74, 0.04);
    animation-delay: 1.5s;
}

.orb--3 {
    width: 20px;
    height: 20px;
    top: 60%;
    right: 40%;
    background: rgba(192, 227, 74, 0.03);
    border-color: rgba(192, 227, 74, 0.03);
    animation-delay: 3s;
}

/* ----- Animations ----- */
@keyframes floatCard {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-10px);
    }
}

@keyframes pulseRing {
    0%, 100% {
        transform: scale(1);
        opacity: 0.4;
    }
    50% {
        transform: scale(1.3);
        opacity: 0;
    }
}

@keyframes pulseGlow {
    0%, 100% {
        opacity: 0.4;
        transform: scale(1);
    }
    50% {
        opacity: 1;
        transform: scale(1.1);
    }
}

/* ----- Focus States ----- */
.btn-services-start:focus-visible,
.btn-services-consult:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Services Hero Banner
================================================== */

/* ==================================================
START: Services Categories Overview
================================================== */

