    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    margin-bottom: 40px;
}

.category-card {
    display: flex;
    flex-direction: column;
    padding: 28px 24px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    height: 100%;
}

.category-card:hover {
    transform: translateY(-6px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.category-card__header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
}

.category-card__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    border-radius: 14px;
    background: linear-gradient(135deg, rgba(124, 58, 237, 0.08), rgba(192, 227, 74, 0.08));
    font-size: 1.4rem;
    color: var(--color-purple);
    flex-shrink: 0;
    transition: all 0.3s ease;
}

.category-card:hover .category-card__icon {
    background: linear-gradient(135deg, var(--color-purple), var(--color-lime));
    color: var(--color-white);
    transform: scale(1.05);
}

.category-card__title {
    font-size: 1.05rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
    letter-spacing: -0.02em;
}

.category-card__desc {
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0 0 14px;
    flex: 1;
}

.category-card__chips {
    display: flex;
    flex-wrap: wrap;
    gap: 6px 8px;
    margin-bottom: 16px;
}

.chip {
    font-size: 0.68rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    background: rgba(255, 255, 255, 0.4);
