    background: rgba(255, 255, 255, 0.4);
    border: 1px solid var(--color-gray-light);
    padding: 4px 16px;
    border-radius: 50px;
    transition: all 0.3s ease;
    cursor: default;
}

.tech-preview-item i {
    font-size: 0.9rem;
    color: var(--color-purple);
}

.tech-preview-item:hover {
    border-color: var(--color-purple);
    background: rgba(124, 58, 237, 0.04);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.04);
}

/* ============================================================
   BOTTOM CTA
   ============================================================ */
.featured-services__cta {
    max-width: 1000px;
    margin: 0 auto 0;
}

.services-cta-bottom {
    display: grid;
    grid-template-columns: 60fr 40fr;
    gap: 0;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.services-cta-bottom:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.services-cta-bottom__content {
    padding: 36px 40px 32px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.services-cta-bottom__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.services-cta-bottom__title {
    font-size: 1.4rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin: 0;
}

.services-cta-bottom__desc {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    max-width: 480px;
    margin: 0;
}

.services-cta-bottom__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 4px;
}

.btn-cta-start-project {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
}

.btn-cta-start-project:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.45);
}

.btn-cta-contact-sales {
    padding: 10px 28px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-cta-contact-sales:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- Bottom CTA Visual ----- */
.services-cta-bottom__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    position: relative;
    overflow: hidden;
    padding: 30px 20px;
    min-height: 180px;
}

.services-cta-bottom__visual .cta-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 1.1rem;
    color: rgba(255, 255, 255, 0.3);
    transition: all 0.3s ease;
}

.services-cta-bottom__visual .cta-icon--1 {
    top: 20%;
    left: 15%;
    animation: floatIcon 5s ease-in-out infinite;
}
.services-cta-bottom__visual .cta-icon--2 {
    top: 20%;
    right: 15%;
    animation: floatIcon 5s ease-in-out infinite 1.5s;
}
.services-cta-bottom__visual .cta-icon--3 {
    bottom: 20%;
    left: 20%;
    animation: floatIcon 5s ease-in-out infinite 3s;
}
.services-cta-bottom__visual .cta-icon--4 {
    bottom: 20%;
    right: 20%;
    animation: floatIcon 5s ease-in-out infinite 0.5s;
}

.services-cta-bottom__visual .cta-icon:hover {
    background: rgba(255, 255, 255, 0.12);
    color: var(--color-lime);
    transform: scale(1.1);
}

.services-cta-bottom__visual .cta-shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.03);
}

.services-cta-bottom__visual .cta-shape--1 {
    width: 120px;
    height: 120px;
    top: -40px;
    right: -30px;
}

.services-cta-bottom__visual .cta-shape--2 {
    width: 80px;
    height: 80px;
    bottom: -20px;
    left: -20px;
}

.services-cta-bottom__visual .cta-shape--3 {
    width: 50px;
    height: 50px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* ----- Focus States ----- */
.filter-btn:focus-visible,
.service-btn:focus-visible,
.btn-spotlight-discuss:focus-visible,
.btn-spotlight-schedule:focus-visible,
.btn-cta-start-project:focus-visible,
.btn-cta-contact-sales:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Featured Services Grid
================================================== */

/* ==================================================
START: Detailed Service Showcase
================================================== */

/* ----- Container ----- */
#service-showcase {
    padding: 80px 0 60px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.service-showcase__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.service-showcase__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.service-showcase__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.service-showcase__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.service-showcase__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.service-showcase__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.service-showcase__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.service-showcase__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.service-showcase__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.service-showcase__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.service-showcase__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.service-showcase__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#service-showcase .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#service-showcase .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#service-showcase .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#service-showcase .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#service-showcase .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#service-showcase .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#service-showcase .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.service-showcase__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.service-showcase__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.service-showcase__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.service-showcase__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.service-showcase__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.service-showcase__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   SHOWCASE BLOCKS
   ============================================================ */
.showcase-block {
    display: grid;
    gap: 40px;
    padding: 40px 0;
    border-bottom: 1px solid rgba(0, 0, 0, 0.03);
    align-items: center;
}

.showcase-block:last-of-type {
    border-bottom: none;
}

.showcase-block--left {
    grid-template-columns: 40fr 60fr;
}

.showcase-block--right {
    grid-template-columns: 60fr 40fr;
}

.showcase-block--right .showcase-block__visual {
    order: 2;
}

.showcase-block--right .showcase-block__content {
    order: 1;
}

/* ----- Visual ----- */
.showcase-block__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 300px;
}

.showcase-illustration {
    position: relative;
    width: 100%;
    max-width: 420px;
    aspect-ratio: 1 / 1;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    overflow: hidden;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.showcase-illustration:hover {
    transform: translateY(-4px) scale(1.01);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.showcase-illustration .ill-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 12px;
    background: rgba(124, 58, 237, 0.06);
    border: 1px solid rgba(124, 58, 237, 0.06);
    font-size: 1.1rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.showcase-illustration .ill-icon--1 {
    top: 15%;
    left: 12%;
    animation: floatIcon 5s ease-in-out infinite;
}
.showcase-illustration .ill-icon--2 {
    top: 15%;
    right: 12%;
    animation: floatIcon 5s ease-in-out infinite 1.2s;
}
.showcase-illustration .ill-icon--3 {
    bottom: 20%;
    left: 15%;
    animation: floatIcon 5s ease-in-out infinite 2.4s;
}
.showcase-illustration .ill-icon--4 {
    bottom: 20%;
    right: 15%;
    animation: floatIcon 5s ease-in-out infinite 3.6s;
}

.showcase-illustration .ill-icon:hover {
    background: rgba(124, 58, 237, 0.12);
    transform: scale(1.1);
}

.showcase-illustration .ill-shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
}

.showcase-illustration .ill-shape--1 {
    width: 140px;
    height: 140px;
    top: -40px;
    right: -30px;
}

.showcase-illustration .ill-shape--2 {
    width: 90px;
    height: 90px;
    bottom: -20px;
    left: -20px;
}

.showcase-illustration .ill-shape--3 {
    width: 60px;
    height: 60px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* ----- Illustration: Development ----- */
.showcase-illustration--dev .ill-code-block {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: rgba(0, 0, 0, 0.3);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    padding: 16px 20px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-family: 'Courier New', monospace;
    z-index: 2;
}

.ill-code-block .code-line {
    display: block;
    font-size: 0.65rem;
    color: rgba(255, 255, 255, 0.6);
    line-height: 1.6;
    white-space: nowrap;
}

.ill-code-block .code-line:first-child {
    color: var(--color-lime);
    opacity: 0.7;
}
.ill-code-block .code-line:nth-child(2) {
    color: rgba(255, 255, 255, 0.5);
    padding-left: 4px;
}
.ill-code-block .code-line:nth-child(3) {
    color: var(--color-lime);
    padding-left: 4px;
}
.ill-code-block .code-line:last-child {
    color: rgba(255, 255, 255, 0.4);
}

/* ----- Illustration: ERP ----- */
.showcase-illustration--erp .ill-dashboard {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: rgba(0, 0, 0, 0.2);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    padding: 14px 18px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    width: 180px;
    z-index: 2;
}

.ill-dashboard .dash-row {
    display: flex;
    justify-content: space-between;
    font-size: 0.7rem;
    padding: 2px 0;
    color: rgba(255, 255, 255, 0.6);
    border-bottom: 1px solid rgba(255, 255, 255, 0.03);
}

.ill-dashboard .dash-row .dash-value {
    color: var(--color-lime);
    font-weight: var(--font-weight-semibold);
}

.ill-dashboard .dash-progress {
    margin-top: 6px;
    height: 3px;
    background: rgba(255, 255, 255, 0.06);
    border-radius: 3px;
    overflow: hidden;
}

.ill-dashboard .dash-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    border-radius: 3px;
}

/* ----- Illustration: E-Commerce ----- */
.showcase-illustration--ecom .ill-ecom-card {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: rgba(0, 0, 0, 0.2);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    padding: 16px 20px;
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    text-align: center;
    z-index: 2;
    min-width: 140px;
}

.ill-ecom-card .ecom-product {
    display: block;
    font-size: 0.75rem;
    font-weight: var(--font-weight-medium);
    color: rgba(255, 255, 255, 0.7);
}

.ill-ecom-card .ecom-price {
    display: block;
    font-size: 1.2rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime);
    margin: 4px 0;
}

.ill-ecom-card .ecom-cart {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    background: var(--color-lime);
    padding: 4px 16px;
    border-radius: 50px;
    cursor: default;
}

/* ----- Illustration: AI ----- */
.showcase-illustration--ai .ill-ai-node {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    display: flex;
    flex-direction: column;
    align-items: center;
    z-index: 2;
}

.ill-ai-node .ai-node-icon {
    font-size: 2.4rem;
    color: var(--color-lime);
    opacity: 0.6;
}

.ill-ai-node .ai-node-label {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: rgba(255, 255, 255, 0.4);
    margin-top: 4px;
}

.ill-ai-node .ai-node-pulse {
    position: absolute;
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: rgba(192, 227, 74, 0.06);
    animation: pulseRing 3s ease-in-out infinite;
}

.showcase-illustration--ai .ill-ai-connections {
    position: absolute;
    inset: 0;
    display: flex;
    justify-content: space-around;
    align-items: center;
    padding: 20% 15%;
    opacity: 0.2;
}

.ill-ai-connections .conn-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.2);
    animation: pulseDot 2s ease-in-out infinite;
}

.ill-ai-connections .conn-dot:nth-child(2) { animation-delay: 0.5s; }
.ill-ai-connections .conn-dot:nth-child(3) { animation-delay: 1s; }
.ill-ai-connections .conn-dot:nth-child(4) { animation-delay: 1.5s; }

/* ----- Illustration: Marketing ----- */
.showcase-illustration--marketing .ill-marketing-chart {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    display: flex;
    align-items: flex-end;
    gap: 6px;
    height: 80px;
    z-index: 2;
}

.ill-marketing-chart .m-chart-bar {
    width: 16px;
    border-radius: 4px 4px 0 0;
    background: rgba(192, 227, 74, 0.2);
    min-height: 12px;
    transition: all 0.3s ease;
}

.ill-marketing-chart .m-chart-bar:nth-child(2) { background: rgba(124, 58, 237, 0.2); }
.ill-marketing-chart .m-chart-bar:nth-child(4) { background: rgba(124, 58, 237, 0.2); }

/* ----- Illustration: Design ----- */
.showcase-illustration--design .ill-design-grid {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    z-index: 2;
}

.ill-design-grid .design-box {
    width: 60px;
    height: 50px;
    border-radius: 8px;
    transition: all 0.3s ease;
    border: 1px solid rgba(255, 255, 255, 0.04);
}

.ill-design-grid .design-box:hover {
    transform: scale(1.05);
}

/* ============================================================
   SHOWCASE CONTENT
   ============================================================ */
.showcase-block__content {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.showcase-block__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-purple);
    background: rgba(124, 58, 237, 0.06);
    padding: 2px 14px;
    border-radius: 50px;
    width: fit-content;
}

.showcase-block__title {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin: 0;
}

.showcase-block__problem {
    font-size: 0.92rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    margin: 0;
    padding-left: 14px;
    border-left: 3px solid var(--color-purple);
}

.showcase-block__solution {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    margin: 0;
}

.showcase-block__features {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin: 2px 0;
}

.feature-group__title {
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--color-gray-mid);
    margin-bottom: 4px;
    display: block;
}

.feature-group ul {
    margin: 0;
    padding: 0;
    list-style: none;
}

.feature-group ul li {
    font-size: 0.8rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-charcoal);
    padding: 2px 0;
    padding-left: 16px;
    position: relative;
}

.feature-group ul li::before {
    content: '▸';
    position: absolute;
    left: 0;
    color: var(--color-lime);
    font-size: 0.7rem;
}

.tech-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 6px;
    margin-top: 2px;
}

.tech-chip {
