}

.btn-cta-expert {
    padding: 10px 28px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-cta-expert:hover {
    background: var(--color-purple);
    color: var(--color-white);
