}

/* ----- Enterprise CTA Visual ----- */
.enterprise-cta__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    position: relative;
    overflow: hidden;
    padding: 30px 20px;
    min-height: 180px;
}

.e-cta-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 1.1rem;
    color: rgba(255, 255, 255, 0.3);
    transition: all 0.3s ease;
}

.e-cta-icon--1 {
    top: 20%;
    left: 15%;
    animation: floatIcon 5s ease-in-out infinite;
}
.e-cta-icon--2 {
    top: 20%;
    right: 15%;
    animation: floatIcon 5s ease-in-out infinite 1.5s;
}
.e-cta-icon--3 {
    bottom: 20%;
    left: 20%;
    animation: floatIcon 5s ease-in-out infinite 3s;
}
.e-cta-icon--4 {
    bottom: 20%;
    right: 20%;
    animation: floatIcon 5s ease-in-out infinite 0.5s;
}

.e-cta-icon:hover {
    background: rgba(255, 255, 255, 0.12);
    color: var(--color-lime);
    transform: scale(1.1);
}

.e-cta-shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.03);
}

.e-cta-shape--1 {
    width: 120px;
    height: 120px;
    top: -40px;
    right: -30px;
}

.e-cta-shape--2 {
    width: 80px;
    height: 80px;
    bottom: -20px;
    left: -20px;
}

.e-cta-shape--3 {
    width: 50px;
    height: 50px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* ----- Focus States ----- */
.btn-showcase-learn:focus-visible,
.btn-showcase-proposal:focus-visible,
.btn-cta-strategy:focus-visible,
.btn-cta-expert:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

