    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

/* ============================================================
   PROCESS TIMELINE
   ============================================================ */
.delivery-process__timeline {
    max-width: 1100px;
    margin: 0 auto 48px;
    padding: 32px 28px 28px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.delivery-process__timeline:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.process-timeline {
    display: grid;
    grid-template-columns: repeat(8, 1fr);
    gap: 0;
    position: relative;
}

.process-timeline::before {
    content: '';
    position: absolute;
    top: 40px;
    left: 8%;
    right: 8%;
    height: 3px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.15;
    border-radius: 3px;
}

.timeline-phase {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    position: relative;
    padding: 0 4px;
}

.timeline-phase__dot {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: var(--color-white);
    border: 3px solid var(--color-lime);
    position: relative;
    z-index: 2;
    margin-bottom: 10px;
    transition: all 0.3s ease;
}

.timeline-phase:hover .timeline-phase__dot {
    background: var(--color-lime);
    border-color: var(--color-lime);
    transform: scale(1.1);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
}

.timeline-phase:hover .phase-number {
    color: var(--color-charcoal);
}

.phase-number {
    font-size: 0.65rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.timeline-phase__content {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.phase-label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.phase-details {
    display: none;
}

.timeline-phase__connector {
    display: none;
}

/* ============================================================
   PROCESS DETAIL CARDS (Accordion)
   ============================================================ */
.delivery-process__details {
    max-width: 900px;
    margin: 0 auto 48px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.delivery-process__details:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.process-details-accordion {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.phase-detail-card {
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: rgba(255, 255, 255, 0.3);
    overflow: hidden;
    transition: all 0.3s ease;
}

.phase-detail-card:hover {
    background: rgba(255, 255, 255, 0.6);
    border-color: rgba(124, 58, 237, 0.06);
}

.phase-detail-card__trigger {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 18px;
    background: transparent;
    border: none;
    cursor: pointer;
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: left;
    transition: all 0.3s ease;
}

.phase-detail-card__trigger:hover {
    background: rgba(124, 58, 237, 0.02);
}

.phase-detail-card__number {
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 28px;
    height: 28px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-size: 0.65rem;
    font-weight: var(--font-weight-bold);
    flex-shrink: 0;
}

.phase-detail-card__title {
    flex: 1;
    font-size: 0.82rem;
}

.phase-detail-card__toggle {
    font-size: 0.75rem;
    color: var(--color-gray-mid);
    transition: transform 0.3s ease;
}

.phase-detail-card__trigger[aria-expanded="true"] .phase-detail-card__toggle {
    transform: rotate(180deg);
}

.phase-detail-card__content {
    max-height: 0;
    overflow: hidden;
    padding: 0 18px;
    transition: max-height 0.4s ease, padding 0.4s ease;
}

.phase-detail-card__trigger[aria-expanded="true"] + .phase-detail-card__content {
    max-height: 800px;
    padding: 0 18px 18px;
}

.detail-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px 16px;
}

.detail-group__label {
    display: block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--color-gray-mid);
    margin-bottom: 4px;
}

.detail-group ul {
    margin: 0;
    padding: 0;
    list-style: none;
}

.detail-group ul li {
    font-size: 0.78rem;
    font-weight: var(--font-weight-regular);
