    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#industries-served .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#industries-served .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#industries-served .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#industries-served .particle--6 {
