/* ----- Browser Mockup ----- */
.visual-card {
    position: absolute;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-radius: 16px;
    border: 1px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.04);
    transition: all 0.3s ease;
}

.visual-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.06);
}

.visual-card--browser {
    top: 5%;
    left: 10%;
    width: 240px;
    border-radius: 12px;
    overflow: hidden;
    animation: floatCard 5s ease-in-out infinite;
}

.browser-header {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 12px;
    background: rgba(0, 0, 0, 0.02);
    border-bottom: 1px solid var(--color-gray-light);
}

.browser-header .dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
}

.browser-header .dot--red { background: #ef4444; }
.browser-header .dot--yellow { background: #f59e0b; }
.browser-header .dot--green { background: #059669; }

.browser-url {
    font-size: 0.55rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin-left: 4px;
    background: rgba(0, 0, 0, 0.03);
    padding: 1px 8px;
    border-radius: 4px;
}

.browser-body {
    padding: 10px 12px 12px;
}

.browser-chart {
    display: flex;
    align-items: flex-end;
    gap: 4px;
    height: 50px;
    margin-bottom: 6px;
}

.bar {
    flex: 1;
    background: var(--color-purple);
    border-radius: 3px 3px 0 0;
    opacity: 0.4;
    transition: all 0.3s ease;
    min-height: 8px;
}

.bar--1 { opacity: 0.5; }
.bar--2 { opacity: 0.7; background: var(--color-lime); }
.bar--3 { opacity: 0.4; }
.bar--4 { opacity: 0.9; background: var(--color-lime); }
.bar--5 { opacity: 0.6; }
.bar--6 { opacity: 0.4; }

.browser-stats {
    display: flex;
    justify-content: space-between;
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
}

.browser-stats .stat:first-child {
    color: #059669;
}

/* ----- Code Block ----- */
.visual-card--code {
    bottom: 25%;
    left: 5%;
    width: 140px;
    padding: 12px 14px;
    border-radius: 12px;
    animation: floatCard 6s ease-in-out infinite 1.5s;
}

.code-block .code-line {
    display: block;
    font-size: 0.55rem;
    font-family: 'Courier New', monospace;
    color: var(--color-gray-mid);
    line-height: 1.6;
    white-space: nowrap;
}

.code-block .code-line:first-child {
    color: var(--color-lime);
    opacity: 0.7;
}
.code-block .code-line:nth-child(2) {
    color: rgba(124, 58, 237, 0.6);
    padding-left: 4px;
}
.code-block .code-line:nth-child(3) {
    color: var(--color-lime);
    padding-left: 4px;
}
.code-block .code-line:last-child {
    color: rgba(0, 0, 0, 0.2);
}

/* ----- Mobile Device ----- */
.visual-card--mobile {
    bottom: 10%;
    right: 8%;
    width: 80px;
    border-radius: 14px;
    padding: 6px 6px 10px;
    background: rgba(255, 255, 255, 0.8);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.06);
    animation: floatCard 7s ease-in-out infinite 2.5s;
}

.mobile-notch {
    width: 24px;
    height: 4px;
    background: var(--color-gray-light);
    border-radius: 4px;
    margin: 0 auto 6px;
}

.mobile-screen {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 4px;
    padding: 4px;
}

.mobile-app-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    aspect-ratio: 1;
    border-radius: 6px;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    font-size: 0.6rem;
    transition: all 0.3s ease;
}

.mobile-app-icon:hover {
    background: rgba(124, 58, 237, 0.12);
    transform: scale(1.05);
}

.mobile-app-icon:nth-child(2) { background: rgba(192, 227, 74, 0.06); color: var(--color-lime-dark); }
.mobile-app-icon:nth-child(4) { background: rgba(192, 227, 74, 0.06); color: var(--color-lime-dark); }

/* ----- Code Icons ----- */
.code-icon {
    position: absolute;
    font-size: 0.85rem;
    font-weight: var(--font-weight-bold);
    color: rgba(124, 58, 237, 0.1);
    font-family: 'Courier New', monospace;
    animation: floatIcon 5s ease-in-out infinite;
}

.code-icon--1 {
    top: 15%;
    right: 15%;
    animation-delay: 0s;
    font-size: 1.4rem;
}

.code-icon--2 {
    bottom: 35%;
    left: 25%;
    animation-delay: 1.8s;
    font-size: 1.2rem;
}

.code-icon--3 {
    top: 55%;
    right: 30%;
    animation-delay: 3.2s;
    font-size: 1rem;
}

/* ----- Connection Lines ----- */
.connection-lines {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
}

/* ----- Floating Orbs ----- */
.orb {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.04);
    border: 1px solid rgba(124, 58, 237, 0.04);
    animation: pulseGlow 4s ease-in-out infinite;
}

.orb--1 {
    width: 50px;
    height: 50px;
    top: 20%;
    right: 30%;
    animation-delay: 0s;
}

.orb--2 {
    width: 30px;
    height: 30px;
    bottom: 40%;
    left: 20%;
    background: rgba(192, 227, 74, 0.04);
    border-color: rgba(192, 227, 74, 0.04);
    animation-delay: 1.5s;
}

.orb--3 {
    width: 20px;
    height: 20px;
    top: 60%;
    right: 40%;
    background: rgba(192, 227, 74, 0.03);
    border-color: rgba(192, 227, 74, 0.03);
    animation-delay: 3s;
}

/* ----- Animations ----- */
@keyframes floatCard {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-10px);
    }
}

@keyframes floatOrb {
    0%, 100% {
        transform: translateY(0) scale(1);
    }
    50% {
        transform: translateY(-12px) scale(1.05);
    }
}

@keyframes floatParticle {
    0%, 100% {
        transform: translateY(0) translateX(0);
        opacity: 0.3;
    }
    50% {
        transform: translateY(-20px) translateX(10px);
        opacity: 0.8;
    }
}

@keyframes pulseGlow {
    0%, 100% {
        opacity: 0.4;
        transform: scale(1);
    }
    50% {
        opacity: 1;
        transform: scale(1.1);
    }
}

@keyframes floatIcon {
    0%, 100% {
        transform: translateY(0) rotate(0deg);
    }
    50% {
        transform: translateY(-12px) rotate(3deg);
    }
}

/* ----- Focus States ----- */
.btn-webdev-start:focus-visible,
.btn-webdev-portfolio:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

