/* ==================================================
START: Our Web Development Process
================================================== */

/* ----- Container ----- */
#webdev-process {
    padding: 80px 0 60px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.webdev-process__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.webdev-process__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.webdev-process__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.webdev-process__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.webdev-process__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.webdev-process__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.webdev-process__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.webdev-process__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.webdev-process__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.webdev-process__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.webdev-process__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.webdev-process__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#webdev-process .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#webdev-process .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#webdev-process .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#webdev-process .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#webdev-process .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#webdev-process .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#webdev-process .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
