/* ============================================================
   TECHNOLOGY TABS
   ============================================================ */
.webdev-tech-stack__tabs {
    max-width: 850px;
    margin: 0 auto 36px;
    padding: 6px 8px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 50px;
    box-shadow: var(--shadow-glass);
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 2px;
