}

.webdev-tech-stack__tabs:hover {
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 8px 32px rgba(124, 58, 237, 0.04);
}

.tech-tab {
    padding: 6px 16px;
    border: none;
    border-radius: 50px;
