}

.tech-tab:hover {
    color: var(--color-charcoal);
    background: rgba(0, 0, 0, 0.02);
}

.tech-tab--active {
    background: var(--color-purple);
    color: var(--color-white);
}

.tech-tab--active:hover {
    background: #5b2fbf;
    color: var(--color-white);
}

/* ============================================================
   TECHNOLOGY GRID
   ============================================================ */
.webdev-tech-stack__grid {
    max-width: 1100px;
    margin: 0 auto 48px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.webdev-tech-stack__grid:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.tech-category {
    margin-bottom: 28px;
}

.tech-category:last-child {
    margin-bottom: 0;
}

.tech-category__title {
    font-size: 0.85rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    margin: 0 0 10px;
    letter-spacing: 0.02em;
}

.tech-cards {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px 14px;
}

.tech-card {
    display: flex;
    flex-direction: column;
    padding: 12px 14px 12px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    height: 100%;
}

.tech-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateY(-4px) scale(1.01);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.tech-card__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    margin-bottom: 4px;
}

.tech-card__name {
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.tech-card__desc {
    font-size: 0.7rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.3;
    margin: 2px 0 4px;
    flex: 1;
}

.tech-card__benefit {
    font-size: 0.62rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.06);
    padding: 2px 12px;
    border-radius: 50px;
    display: inline-block;
    width: fit-content;
}

/* ============================================================
   ARCHITECTURE FLOW
   ============================================================ */
.webdev-tech-stack__architecture {
    max-width: 1000px;
    margin: 0 auto 48px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    overflow-x: auto;
}

.webdev-tech-stack__architecture:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.architecture-flow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-width: 700px;
    gap: 6px;
    padding: 12px 8px 8px;
}

.arch-node {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    position: relative;
    flex: 1;
    min-width: 60px;
}

.arch-node__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    border: 2px solid rgba(124, 58, 237, 0.06);
    font-size: 1.1rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.arch-node:hover .arch-node__icon {
    background: linear-gradient(135deg, var(--color-purple), var(--color-lime));
    color: var(--color-white);
    border-color: transparent;
    transform: scale(1.1);
}

.arch-node__label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: center;
    line-height: 1.2;
}

.arch-node__connector {
    position: absolute;
    right: -8px;
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 2px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.2;
}

.arch-node__connector::after {
    content: '→';
    position: absolute;
    right: -6px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.6rem;
    color: var(--color-gray-mid);
}

.arch-node--end .arch-node__connector {
    display: none;
}

/* ============================================================
   DEVELOPMENT PRINCIPLES
   ============================================================ */
.webdev-tech-stack__principles {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.webdev-tech-stack__principles:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.principles-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px 12px;
}

.principle-card {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.principle-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.principle-card__icon {
    font-size: 1rem;
    color: var(--color-lime);
    flex-shrink: 0;
}

.principle-card__label {
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.2;
}

/* ============================================================
   TECHNOLOGY METRICS
   ============================================================ */
.webdev-tech-stack__metrics {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 24px 28px 20px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
}

.webdev-tech-stack__metrics .metrics-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
}

.webdev-tech-stack__metrics .metric-stat {
    text-align: center;
    padding: 4px 8px;
    transition: all 0.3s ease;
}

.webdev-tech-stack__metrics .metric-stat:hover {
    transform: translateY(-3px);
}

.webdev-tech-stack__metrics .metric-stat__number {
    font-size: 1.8rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 2px;
}

.webdev-tech-stack__metrics .metric-stat__number .stat-number {
    display: inline-block;
}

.webdev-tech-stack__metrics .metric-stat__number .stat-suffix {
    font-size: 1.3rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    margin-left: 2px;
}

.webdev-tech-stack__metrics .metric-stat__number .stat-label--modern {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-lime-dark);
}

.webdev-tech-stack__metrics .metric-stat__number .stat-label--secure {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
}

.webdev-tech-stack__metrics .metric-stat__number .stat-label--optimized {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: #2563eb;
}

.webdev-tech-stack__metrics .metric-stat__number .stat-label--scalable {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: #059669;
}

.webdev-tech-stack__metrics .metric-stat__label {
    font-size: 0.72rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    margin: 0;
}

/* ============================================================
   BOTTOM CTA
   ============================================================ */
.webdev-tech-stack__cta {
    max-width: 1000px;
    margin: 0 auto 0;
}

.tech-cta-banner {
    display: grid;
    grid-template-columns: 60fr 40fr;
    gap: 0;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.tech-cta-banner:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.tech-cta-banner__content {
    padding: 36px 40px 32px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.tech-cta-banner__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.tech-cta-banner__title {
    font-size: 1.4rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin: 0;
}

.tech-cta-banner__desc {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    max-width: 480px;
    margin: 0;
}

.tech-cta-banner__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 4px;
}

.btn-cta-tech-discuss {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
}

.btn-cta-tech-discuss:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.45);
}

.btn-cta-tech-architect {
    padding: 10px 28px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-cta-tech-architect:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- CTA Visual ----- */
.tech-cta-banner__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    position: relative;
    overflow: hidden;
    padding: 30px 20px;
    min-height: 180px;
}

.t-cta-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 1.1rem;
    color: rgba(255, 255, 255, 0.3);
    transition: all 0.3s ease;
}

.t-cta-icon--1 {
    top: 20%;
    left: 15%;
    animation: floatIcon 5s ease-in-out infinite;
}
.t-cta-icon--2 {
    top: 20%;
    right: 15%;
    animation: floatIcon 5s ease-in-out infinite 1.5s;
}
.t-cta-icon--3 {
    bottom: 20%;
    left: 20%;
    animation: floatIcon 5s ease-in-out infinite 3s;
}
.t-cta-icon--4 {
    bottom: 20%;
    right: 20%;
    animation: floatIcon 5s ease-in-out infinite 0.5s;
}

.t-cta-icon:hover {
    background: rgba(255, 255, 255, 0.12);
    color: var(--color-lime);
    transform: scale(1.1);
}

.t-cta-shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.03);
}

.t-cta-shape--1 {
    width: 120px;
    height: 120px;
    top: -40px;
    right: -30px;
}

.t-cta-shape--2 {
    width: 80px;
    height: 80px;
    bottom: -20px;
    left: -20px;
}

.t-cta-shape--3 {
    width: 50px;
    height: 50px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* ----- Focus States ----- */
.tech-tab:focus-visible,
.btn-cta-tech-discuss:focus-visible,
.btn-cta-tech-architect:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

