    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.webdev-solutions__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.webdev-solutions__glow--3 {
