/* ============================================================
   FAQ ACCORDION
   ============================================================ */
.webdev-faq-final__faq {
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    padding: 28px 28px 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.webdev-faq-final__faq:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.faq-accordion {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.faq-item {
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: rgba(255, 255, 255, 0.3);
    overflow: hidden;
    transition: all 0.3s ease;
}

.faq-item:hover {
    background: rgba(255, 255, 255, 0.6);
    border-color: rgba(124, 58, 237, 0.06);
}

.faq-item__trigger {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 18px;
    background: transparent;
    border: none;
    cursor: pointer;
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: left;
    transition: all 0.3s ease;
}

.faq-item__trigger:hover {
    background: rgba(124, 58, 237, 0.02);
}

.faq-item__question {
    flex: 1;
    font-size: 0.85rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.faq-item__toggle {
    font-size: 0.75rem;
    color: var(--color-gray-mid);
    transition: transform 0.3s ease;
    flex-shrink: 0;
}

.faq-item__trigger[aria-expanded="true"] .faq-item__toggle {
    transform: rotate(180deg);
}

.faq-item__content {
    max-height: 0;
    overflow: hidden;
    padding: 0 18px;
    transition: max-height 0.4s ease, padding 0.4s ease;
    color: var(--color-gray-mid);
    font-size: 0.82rem;
    line-height: 1.6;
}

.faq-item__trigger[aria-expanded="true"] + .faq-item__content {
    max-height: 400px;
    padding: 0 18px 18px;
}

.faq-item__content p {
    margin: 0 0 8px;
}

.faq-item__actions {
    display: flex;
    gap: 12px;
    margin-top: 4px;
}

.faq-item__vote,
.faq-item__copy {
    background: transparent;
    border: none;
    font-size: 0.65rem;
    color: var(--color-gray-mid);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border-radius: 6px;
    transition: all 0.2s ease;
}

.faq-item__vote:hover,
.faq-item__copy:hover {
    background: rgba(124, 58, 237, 0.04);
    color: var(--color-purple);
}

/* ============================================================
