    font-size: 0.7rem;
}

.contact-panel__actions {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.btn-contact-proposal {
    padding: 10px 24px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.3);
