}

.final-conversion-banner__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 4px;
}

.btn-cta-final-start {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
}

.btn-cta-final-start:hover {
