}

.hero-visual {
    position: relative;
    width: 100%;
    max-width: 480px;
    height: 480px;
    margin: 0 auto;
}

/* ----- Glass Shield ----- */
.glass-shield {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 180px;
    height: 200px;
    background: rgba(255, 255, 255, 0.15);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-radius: 30px 30px 50px 50px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    box-shadow: 0 20px 60px rgba(124, 58, 237, 0.1);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    animation: floatShield 6s ease-in-out infinite;
    z-index: 3;
}

.glass-shield .shield-icon {
    font-size: 4.5rem;
    color: rgba(124, 58, 237, 0.15);
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.glass-shield .lock-icon {
    font-size: 2.2rem;
    color: var(--color-lime);
    position: relative;
    z-index: 2;
    animation: pulseLock 3s ease-in-out infinite;
    margin-top: 10px;
}

.shield-pulse {
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: 30px 30px 50px 50px;
    border: 2px solid rgba(192, 227, 74, 0.15);
    animation: pulseRing 4s ease-in-out infinite;
}

@keyframes floatShield {
    0%, 100% {
        transform: translate(-50%, -50%) translateY(0);
    }
    50% {
        transform: translate(-50%, -50%) translateY(-12px);
    }
}

@keyframes pulseLock {
    0%, 100% {
        opacity: 0.8;
        transform: scale(1);
    }
    50% {
        opacity: 1;
        transform: scale(1.05);
    }
}

@keyframes pulseRing {
    0%, 100% {
        transform: scale(1);
        opacity: 0.4;
    }
    50% {
        transform: scale(1.1);
        opacity: 0.1;
    }
}

/* ----- Data Nodes ----- */
.data-node {
    position: absolute;
    color: var(--color-purple);
    opacity: 0.25;
    font-size: 0.5rem;
    animation: floatNode 5s ease-in-out infinite;
}

.data-node--1 {
    top: 10%;
    left: 10%;
    animation-delay: 0s;
    color: var(--color-lime);
}
.data-node--2 {
    top: 15%;
    right: 15%;
    animation-delay: 1.2s;
}
.data-node--3 {
    bottom: 25%;
    left: 8%;
    animation-delay: 2.4s;
}
.data-node--4 {
    bottom: 20%;
    right: 10%;
    animation-delay: 3.6s;
    color: var(--color-lime);
}
.data-node--5 {
    top: 50%;
    left: 5%;
    animation-delay: 0.6s;
}

@keyframes floatNode {
    0%, 100% {
        transform: translateY(0) scale(1);
        opacity: 0.2;
    }
    50% {
        transform: translateY(-15px) scale(1.2);
        opacity: 0.5;
    }
}

/* ----- Connection Lines ----- */
.visual-connections {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1;
}

/* ----- Floating Orbs ----- */
.orb {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.04);
    border: 1px solid rgba(124, 58, 237, 0.04);
    animation: pulseGlow 4s ease-in-out infinite;
}

.orb--1 {
    width: 60px;
    height: 60px;
    top: 15%;
    right: 20%;
    animation-delay: 0s;
}

.orb--2 {
    width: 40px;
    height: 40px;
    bottom: 30%;
    left: 15%;
    background: rgba(192, 227, 74, 0.04);
    border-color: rgba(192, 227, 74, 0.04);
    animation-delay: 1.5s;
}

.orb--3 {
    width: 25px;
    height: 25px;
    top: 55%;
    right: 30%;
    background: rgba(192, 227, 74, 0.03);
    border-color: rgba(192, 227, 74, 0.03);
    animation-delay: 3s;
}

/* ----- Focus States ----- */
