    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    overflow-x: auto;
}

.privacy-security-rights__process:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.request-flow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-width: 700px;
    gap: 6px;
    padding: 12px 8px 8px;
}

.request-node {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    position: relative;
    flex: 1;
    min-width: 60px;
}

.request-node__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    border: 2px solid rgba(124, 58, 237, 0.06);
    font-size: 1.1rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.request-node:hover .request-node__icon {
    background: linear-gradient(135deg, var(--color-purple), var(--color-lime));
    color: var(--color-white);
    border-color: transparent;
    transform: scale(1.1);
}

.request-node__label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: center;
    line-height: 1.2;
}

.request-node__connector {
    position: absolute;
    right: -8px;
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 2px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.2;
}

.request-node__connector::after {
    content: '→';
    position: absolute;
    right: -6px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.6rem;
    color: var(--color-gray-mid);
}

.request-node--end .request-node__connector {
    display: none;
}

