    padding: 30px 20px;
    min-height: 180px;
}

.r-cta-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 1.1rem;
    color: rgba(255, 255, 255, 0.3);
