}

.r-cta-shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.03);
}

.r-cta-shape--1 {
    width: 120px;
    height: 120px;
    top: -40px;
    right: -30px;
}

.r-cta-shape--2 {
    width: 80px;
    height: 80px;
    bottom: -20px;
