    height: 50px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* ============================================================
   POLICY TIMELINE
   ============================================================ */
.privacy-final__timeline {
    max-width: 900px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.privacy-final__timeline:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.policy-timeline {
    display: flex;
    flex-direction: column;
    gap: 0;
    position: relative;
    padding: 8px 0 4px;
}

.policy-timeline::before {
    content: '';
    position: absolute;
    top: 28px;
    left: 18px;
    bottom: 28px;
    width: 2px;
    background: linear-gradient(180deg, var(--color-lime), var(--color-purple));
    opacity: 0.15;
}

.policy-step {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    padding: 8px 0 8px 0;
    position: relative;
}

.policy-step__number {
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 34px;
    height: 34px;
    border-radius: 50%;
    background: var(--color-white);
    border: 2px solid var(--color-lime);
    font-size: 0.65rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-purple);
    flex-shrink: 0;
    position: relative;
    z-index: 2;
    transition: all 0.3s ease;
}

.policy-step:hover .policy-step__number {
    background: var(--color-lime);
    color: var(--color-charcoal);
    transform: scale(1.1);
}

.policy-step__content {
    flex: 1;
    padding-top: 2px;
}

.policy-step__label {
    display: block;
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.policy-step__desc {
    display: block;
    font-size: 0.72rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.4;
    margin-top: 2px;
}

.policy-step__connector {
    display: none;
}

/* ============================================================
   CONTACT INFORMATION CARDS
   ============================================================ */
.privacy-final__contact {
    max-width: 1100px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
