/* ----- Glass Document ----- */
.glass-document {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 180px;
    height: 220px;
    background: rgba(255, 255, 255, 0.15);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-radius: 16px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    box-shadow: 0 20px 60px rgba(124, 58, 237, 0.1);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    animation: floatDocument 6s ease-in-out infinite;
    z-index: 3;
    padding: 20px;
}

.glass-document .document-icon {
    font-size: 2.8rem;
    color: rgba(124, 58, 237, 0.15);
    margin-bottom: 8px;
}

.glass-document .document-lines {
    display: flex;
    flex-direction: column;
    gap: 6px;
    width: 80%;
}

.glass-document .document-lines .line {
    height: 3px;
    border-radius: 3px;
    background: rgba(124, 58, 237, 0.08);
}

.glass-document .document-lines .line:nth-child(1) { width: 90%; }
.glass-document .document-lines .line:nth-child(2) { width: 70%; }
.glass-document .document-lines .line:nth-child(3) { width: 80%; }
.glass-document .document-lines .line:nth-child(4) { width: 60%; }
.glass-document .document-lines .line:nth-child(5) { width: 75%; }

.glass-document .document-check {
    position: absolute;
    bottom: 16px;
    right: 16px;
    font-size: 1.4rem;
    color: var(--color-lime);
    opacity: 0.7;
}

.glass-document .document-shield {
    position: absolute;
    top: 16px;
    left: 16px;
    font-size: 1.4rem;
    color: var(--color-purple);
    opacity: 0.4;
}

.document-pulse {
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: 16px;
    border: 2px solid rgba(192, 227, 74, 0.1);
    animation: pulseRing 4s ease-in-out infinite;
}

@keyframes floatDocument {
    0%, 100% {
        transform: translate(-50%, -50%) translateY(0);
    }
    50% {
        transform: translate(-50%, -50%) translateY(-12px);
    }
}

/* ----- Floating Icons ----- */
.float-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.04);
    font-size: 1.1rem;
    color: var(--color-purple);
    animation: floatIcon 5s ease-in-out infinite;
    z-index: 2;
}

.float-icon--1 {
    top: 12%;
    left: 8%;
    animation-delay: 0s;
    color: var(--color-lime);
}
.float-icon--2 {
    top: 20%;
    right: 12%;
    animation-delay: 1.2s;
}
.float-icon--3 {
    bottom: 25%;
    left: 10%;
    animation-delay: 2.4s;
}
.float-icon--4 {
    bottom: 20%;
    right: 8%;
    animation-delay: 3.6s;
}

.float-icon:hover {
    transform: scale(1.1);
    background: rgba(255, 255, 255, 0.9);
}

@keyframes floatIcon {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-12px);
    }
}

/* ----- Connection Lines ----- */
.visual-connections {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1;
}

/* ----- Floating Orbs ----- */
.orb {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.04);
    border: 1px solid rgba(124, 58, 237, 0.04);
    animation: pulseGlow 4s ease-in-out infinite;
}

.orb--1 {
    width: 60px;
    height: 60px;
    top: 15%;
    right: 20%;
    animation-delay: 0s;
}

.orb--2 {
    width: 40px;
    height: 40px;
    bottom: 30%;
    left: 15%;
    background: rgba(192, 227, 74, 0.04);
    border-color: rgba(192, 227, 74, 0.04);
    animation-delay: 1.5s;
}

.orb--3 {
    width: 25px;
    height: 25px;
    top: 55%;
    right: 30%;
    background: rgba(192, 227, 74, 0.03);
    border-color: rgba(192, 227, 74, 0.03);
