}

.cl-shape--1 {
    width: 120px;
    height: 120px;
    top: -40px;
    right: -30px;
}

.cl-shape--2 {
    width: 80px;
    height: 80px;
    bottom: -20px;
    left: -20px;
}

.cl-shape--3 {
    width: 50px;
    height: 50px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

