    position: relative;
    z-index: 2;
}

.glass-cookie .cookie-shield {
    position: absolute;
    font-size: 1.8rem;
    color: rgba(124, 58, 237, 0.3);
    top: 10px;
    right: 10px;
    z-index: 2;
}

.cookie-pulse {
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    border: 2px solid rgba(192, 227, 74, 0.1);
    animation: pulseRing 4s ease-in-out infinite;
}

@keyframes floatCookie {
    0%, 100% {
        transform: translate(-50%, -50%) translateY(0);
    }
    50% {
        transform: translate(-50%, -50%) translateY(-12px);
    }
}

/* ----- Browser Window ----- */
.visual-browser {
    position: absolute;
    top: 10%;
    left: 8%;
    width: 160px;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.04);
    overflow: hidden;
    animation: floatBrowser 6s ease-in-out infinite 1.5s;
    z-index: 2;
}

.visual-browser .browser-bar {
    display: flex;
    align-items: center;
    gap: 5px;
    padding: 6px 10px;
    background: rgba(0, 0, 0, 0.02);
    border-bottom: 1px solid var(--color-gray-light);
}

.visual-browser .browser-bar .dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
}

.visual-browser .browser-bar .dot--red { background: #ef4444; }
.visual-browser .browser-bar .dot--yellow { background: #f59e0b; }
.visual-browser .browser-bar .dot--green { background: #059669; }

.visual-browser .browser-bar .browser-url {
    font-size: 0.45rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    margin-left: 4px;
    background: rgba(0, 0, 0, 0.03);
    padding: 1px 6px;
    border-radius: 3px;
    flex: 1;
    text-align: center;
}

.visual-browser .browser-content {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 10px 12px;
}

.visual-browser .browser-content .browser-cookie-icon {
    font-size: 1.2rem;
    color: rgba(192, 227, 74, 0.7);
}

.visual-browser .browser-content .browser-text {
    font-size: 0.65rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

@keyframes floatBrowser {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-10px);
    }
}

/* ----- Preference Toggles ----- */
.toggle-group {
    position: absolute;
    bottom: 15%;
    right: 10%;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.04);
    padding: 10px 14px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    animation: floatToggles 7s ease-in-out infinite 2.5s;
    z-index: 2;
    min-width: 110px;
}

.toggle-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
}

.toggle-label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
}

.toggle-switch {
    display: inline-block;
    width: 28px;
    height: 16px;
    border-radius: 10px;
    background: var(--color-gray-light);
    position: relative;
    transition: all 0.3s ease;
    cursor: default;
}

.toggle-switch::after {
    content: '';
    position: absolute;
    top: 2px;
    left: 2px;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: var(--color-white);
    transition: all 0.3s ease;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
}

.toggle-switch--on {
    background: var(--color-lime);
}

.toggle-switch--on::after {
    left: 14px;
}

.toggle-switch--off {
    background: #d1d5db;
}

.toggle-switch--off::after {
    left: 2px;
}

@keyframes floatToggles {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-8px);
    }
}

/* ----- Floating Icons ----- */
.float-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.04);
    font-size: 1rem;
    color: var(--color-purple);
    animation: floatIcon 5s ease-in-out infinite;
    z-index: 2;
}

.float-icon--1 {
    top: 12%;
    right: 12%;
    animation-delay: 0s;
    color: var(--color-lime);
}
.float-icon--2 {
    top: 25%;
    left: 10%;
    animation-delay: 1.2s;
}
.float-icon--3 {
    bottom: 30%;
    left: 6%;
    animation-delay: 2.4s;
}
.float-icon--4 {
    bottom: 18%;
    right: 6%;
    animation-delay: 3.6s;
}

.float-icon:hover {
    transform: scale(1.1);
    background: rgba(255, 255, 255, 0.9);
}

/* ----- Connection Lines ----- */
.visual-connections {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1;
}

/* ----- Floating Orbs ----- */
.orb {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.04);
    border: 1px solid rgba(124, 58, 237, 0.04);
    animation: pulseGlow 4s ease-in-out infinite;
}

.orb--1 {
    width: 60px;
    height: 60px;
    top: 15%;
    right: 20%;
    animation-delay: 0s;
}

.orb--2 {
    width: 40px;
    height: 40px;
    bottom: 30%;
    left: 15%;
    background: rgba(192, 227, 74, 0.04);
    border-color: rgba(192, 227, 74, 0.04);
    animation-delay: 1.5s;
}

.orb--3 {
    width: 25px;
    height: 25px;
    top: 55%;
    right: 30%;
    background: rgba(192, 227, 74, 0.03);
    border-color: rgba(192, 227, 74, 0.03);
    animation-delay: 3s;
}

/* ----- Focus States ----- */
.btn-cookie-preferences:focus-visible,
.btn-cookie-learn:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

