/* ============================================================
   HERO VISUAL
   ============================================================ */
.sitemap-hero__visual {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 500px;
}

.hero-visual {
    position: relative;
    width: 100%;
    max-width: 480px;
    height: 480px;
    margin: 0 auto;
}

/* ----- Structure Tree ----- */
.structure-tree {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 340px;
    height: 340px;
    background: rgba(255, 255, 255, 0.15);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-radius: 24px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    box-shadow: 0 20px 60px rgba(124, 58, 237, 0.08);
    padding: 24px;
    display: flex;
    flex-direction: column;
    align-items: center;
    z-index: 3;
    animation: floatTree 6s ease-in-out infinite;
}

@keyframes floatTree {
    0%, 100% {
        transform: translate(-50%, -50%) translateY(0);
    }
    50% {
        transform: translate(-50%, -50%) translateY(-8px);
    }
}

/* Tree Root */
.tree-root {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 14px 6px 10px;
    background: rgba(124, 58, 237, 0.06);
    border: 1px solid rgba(124, 58, 237, 0.08);
    border-radius: 50px;
    margin-bottom: 14px;
    flex-shrink: 0;
}

.root-icon {
    font-size: 0.9rem;
    color: var(--color-lime);
}

.root-label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

/* Branch Lines */
.tree-branches {
    position: relative;
    width: 100%;
    height: 30px;
    display: flex;
    justify-content: center;
    flex-shrink: 0;
}

.branch-line {
    position: absolute;
    height: 2px;
    background: rgba(124, 58, 237, 0.08);
    top: 50%;
    transform: translateY(-50%);
}

.branch-line--1 {
    left: 8%;
    right: 58%;
    width: 34%;
}

.branch-line--2 {
    left: 33%;
    right: 33%;
    width: 34%;
}

.branch-line--3 {
    left: 58%;
    right: 8%;
    width: 34%;
}

.branch-line::after {
    content: '';
    position: absolute;
    top: 50%;
    right: -4px;
    transform: translateY(-50%);
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.08);
}

/* Tree Nodes */
.tree-nodes {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 8px 12px;
    width: 100%;
    flex: 1;
    align-items: start;
    padding-top: 4px;
}

.tree-node {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    padding: 6px 4px 4px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    transition: all 0.3s ease;
    cursor: default;
}

.tree-node:hover {
    background: rgba(255, 255, 255, 0.6);
    transform: translateY(-2px);
    border-color: rgba(124, 58, 237, 0.06);
}

.tree-node .node-icon {
    font-size: 0.8rem;
    color: var(--color-purple);
}

.tree-node .node-label {
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.tree-node--1 .node-icon { color: var(--color-lime); }
.tree-node--2 .node-icon { color: #2563eb; }
.tree-node--3 .node-icon { color: var(--color-purple); }
.tree-node--4 .node-icon { color: #f59e0b; }
.tree-node--5 .node-icon { color: #ec4899; }
.tree-node--6 .node-icon { color: #059669; }

/* ----- Floating Icons ----- */
.float-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.04);
    font-size: 1rem;
    color: var(--color-purple);
    animation: floatIcon 5s ease-in-out infinite;
    z-index: 2;
}

.float-icon--1 {
    top: 8%;
    right: 10%;
    animation-delay: 0s;
    color: var(--color-lime);
}
.float-icon--2 {
    top: 18%;
    left: 8%;
    animation-delay: 1.2s;
}
.float-icon--3 {
    bottom: 25%;
    right: 8%;
    animation-delay: 2.4s;
}
