    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 1.1rem;
    color: rgba(255, 255, 255, 0.3);
    transition: all 0.3s ease;
}

.nb-icon:hover {
    background: rgba(255, 255, 255, 0.12);
    color: var(--color-lime);
    transform: scale(1.1);
}

.nb-icon--1 { top: 15%; left: 10%; animation: floatIcon 5s ease-in-out infinite; }
.nb-icon--2 { top: 15%; right: 10%; animation: floatIcon 5s ease-in-out infinite 1.2s; }
.nb-icon--3 { bottom: 20%; left: 8%; animation: floatIcon 5s ease-in-out infinite 2.4s; }
.nb-icon--4 { bottom: 20%; right: 8%; animation: floatIcon 5s ease-in-out infinite 3.6s; }

.nb-shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.03);
}

.nb-shape--1 {
    width: 120px;
    height: 120px;
    top: -40px;
    right: -30px;
}

.nb-shape--2 {
    width: 80px;
    height: 80px;
    bottom: -20px;
    left: -20px;
}

.nb-shape--3 {
    width: 50px;
    height: 50px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* ============================================================
   MAIN PAGES GRID
   ============================================================ */
.sitemap-pages__grid {
    max-width: 1100px;
    margin: 0 auto 48px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.sitemap-pages__grid:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.pages-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px 16px;
}

.page-card {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px 16px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    position: relative;
}

.page-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateY(-4px) translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.page-card__icon {
    font-size: 1.3rem;
    color: var(--color-purple);
    flex-shrink: 0;
    width: 32px;
    text-align: center;
}

.page-card__info {
    flex: 1;
    min-width: 0;
}

.page-card__title {
    display: block;
    font-size: 0.85rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.page-card__desc {
    display: block;
    font-size: 0.68rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

.page-card__badge {
    font-size: 0.5rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-charcoal);
    background: var(--color-lime);
    padding: 1px 10px;
    border-radius: 50px;
    flex-shrink: 0;
    position: absolute;
    top: -6px;
    right: -4px;
    box-shadow: 0 2px 8px rgba(192, 227, 74, 0.2);
}

.page-card__link {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    transition: all 0.3s ease;
    flex-shrink: 0;
    text-decoration: none;
}

.page-card__link:hover {
    background: var(--color-purple);
    color: var(--color-white);
    transform: translateX(2px);
}

/* ============================================================
   WEBSITE NAVIGATION FLOW
   ============================================================ */
.sitemap-pages__flow {
    max-width: 1000px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    overflow-x: auto;
}

.sitemap-pages__flow:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.nav-flow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-width: 700px;
    gap: 6px;
    padding: 12px 8px 8px;
}

.nav-flow-node {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    position: relative;
    flex: 1;
    min-width: 60px;
}

.nav-flow-node__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    border: 2px solid rgba(124, 58, 237, 0.06);
    font-size: 1.1rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.nav-flow-node:hover .nav-flow-node__icon {
    background: linear-gradient(135deg, var(--color-purple), var(--color-lime));
    color: var(--color-white);
    border-color: transparent;
    transform: scale(1.1);
}

.nav-flow-node__label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: center;
    line-height: 1.2;
}

.nav-flow-node__connector {
    position: absolute;
    right: -8px;
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 2px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.2;
}

.nav-flow-node__connector::after {
    content: '→';
    position: absolute;
    right: -6px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.6rem;
    color: var(--color-gray-mid);
}

.nav-flow-node--end .nav-flow-node__connector {
    display: none;
}

/* ============================================================
   QUICK NAVIGATION PANEL
   ============================================================ */
.sitemap-pages__quick {
    max-width: 900px;
    margin: 0 auto 40px;
}

.quick-panel {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.quick-panel:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.quick-panel__section {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.quick-panel__section--search {
    grid-column: 1 / -1;
}

.quick-panel__label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-gray-mid);
}

.quick-panel__list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.quick-panel__list li {
    padding: 3px 0;
}

.quick-panel__list li a {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.82rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-charcoal);
    text-decoration: none;
    transition: all 0.25s ease;
}

.quick-panel__list li a i {
    font-size: 0.55rem;
    color: var(--color-purple);
    transition: transform 0.25s ease;
}

.quick-panel__list li a:hover {
    color: var(--color-purple);
}

.quick-panel__list li a:hover i {
    transform: translateX(2px);
}

.quick-panel__list--inline {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 12px;
}

.quick-panel__list--inline li {
    padding: 2px 0;
}

.quick-panel__list--inline li a {
    font-size: 0.78rem;
}

/* Quick Search */
.quick-panel__search {
    display: flex;
    align-items: center;
    background: rgba(255, 255, 255, 0.4);
    border: 1px solid var(--color-gray-light);
    border-radius: 12px;
    padding: 0 4px 0 14px;
    transition: all 0.3s ease;
}

.quick-panel__search:focus-within {
    border-color: var(--color-purple);
    box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.06);
}

.quick-panel__search i {
    color: var(--color-gray-mid);
    font-size: 0.85rem;
}

.quick-panel__input {
    flex: 1;
    padding: 10px 12px;
    border: none;
    outline: none;
    background: transparent;
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-charcoal);
}

.quick-panel__input::placeholder {
    color: var(--color-gray-light);
}

.quick-panel__btn {
    padding: 6px 18px;
    border: none;
    border-radius: 8px;
    background: var(--color-lime);
    color: var(--color-charcoal);
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    cursor: pointer;
    transition: all 0.3s ease;
}

.quick-panel__btn:hover {
    background: var(--color-lime-dark);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(192, 227, 74, 0.2);
}

/* ============================================================
   INFORMATION BANNER
   ============================================================ */
.sitemap-pages__notice {
    max-width: 900px;
    margin: 0 auto 0;
}

.notice-banner-pages {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 20px 28px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    gap: 16px;
}

.notice-banner-pages:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.notice-banner-pages__content {
    display: flex;
    align-items: center;
    gap: 16px;
    flex: 1;
}

.notice-banner-pages__icon {
    font-size: 2rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.notice-banner-pages__title {
    font-size: 1rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 2px;
    letter-spacing: -0.02em;
}

.notice-banner-pages__desc {
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.5;
    margin: 0;
    max-width: 480px;
}

.notice-banner-pages__badge {
    flex-shrink: 0;
}

.notice-banner-pages__badge span {
    display: inline-block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.06);
    padding: 4px 16px;
    border-radius: 50px;
    border: 1px solid rgba(192, 227, 74, 0.12);
}

/* ----- Focus States ----- */
.btn-banner-pages-services:focus-visible,
.btn-banner-pages-contact:focus-visible,
.page-card__link:focus-visible,
.quick-panel__btn:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Main Website Pages
================================================== */

/* ==================================================
START: Services & Solutions
================================================== */

/* ----- Container ----- */
#sitemap-services {
    padding: 80px 0 60px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.sitemap-services__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.sitemap-services__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.sitemap-services__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.sitemap-services__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.sitemap-services__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.sitemap-services__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.sitemap-services__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.sitemap-services__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.sitemap-services__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.sitemap-services__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.sitemap-services__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.sitemap-services__grid-overlay {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#sitemap-services .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#sitemap-services .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#sitemap-services .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#sitemap-services .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#sitemap-services .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#sitemap-services .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#sitemap-services .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.sitemap-services__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.sitemap-services__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.sitemap-services__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.sitemap-services__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.sitemap-services__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.sitemap-services__title .highlight-text {
    color: var(--color-purple);
    position: relative;
    display: inline-block;
}

.sitemap-services__title .highlight-text::after {
    content: '';
    position: absolute;
    bottom: 4px;
    left: 0;
    right: 0;
    height: 4px;
    background: var(--color-lime);
    border-radius: 2px;
    opacity: 0.3;
}

.sitemap-services__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   SECTION HEADER (Reusable)
   ============================================================ */
.section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.section-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.section-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.section-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

/* ============================================================
   FEATURED SERVICES BANNER
   ============================================================ */
.sitemap-services__banner {
    margin-bottom: 48px;
}

.services-banner {
    display: grid;
    grid-template-columns: 60fr 40fr;
    gap: 0;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.services-banner:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.services-banner__content {
    padding: 36px 40px 32px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.services-banner__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.services-banner__title {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin: 0;
}

.services-banner__desc {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    max-width: 520px;
    margin: 0;
}

.services-banner__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 4px;
}

.btn-banner-services-all {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
}

.btn-banner-services-all:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.45);
}

.btn-banner-services-quote {
    padding: 10px 28px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-banner-services-quote:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- Banner Visual ----- */
.services-banner__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    position: relative;
    overflow: hidden;
    padding: 30px 20px;
    min-height: 180px;
}

.sv-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 1.1rem;
    color: rgba(255, 255, 255, 0.3);
    transition: all 0.3s ease;
}

.sv-icon:hover {
    background: rgba(255, 255, 255, 0.12);
    color: var(--color-lime);
    transform: scale(1.1);
