    align-items: center;
    gap: 10px;
    padding: 14px 16px 12px;
    cursor: pointer;
    user-select: none;
}

.resource-category-card__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.resource-category-card__title {
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    flex: 1;
}

.resource-category-card__toggle {
    width: 28px;
    height: 28px;
    border: none;
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.02);
    color: var(--color-gray-mid);
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    flex-shrink: 0;
}

.resource-category-card__toggle:hover {
    background: rgba(0, 0, 0, 0.04);
    color: var(--color-charcoal);
}

.resource-category-card__toggle[aria-expanded="true"] i {
    transform: rotate(180deg);
}

.resource-category-card__body {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s ease, padding 0.4s ease;
    padding: 0 16px;
}

.resource-category-card__body--open {
    max-height: 400px;
    padding: 0 16px 12px;
}

.resource-category-card__list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.resource-category-card__list li {
    padding: 4px 0;
}

.resource-category-card__list li a {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.75rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    text-decoration: none;
    transition: all 0.25s ease;
}

.resource-category-card__list li a::before {
    content: '▸';
    color: var(--color-purple);
    font-size: 0.6rem;
    opacity: 0.5;
}

.resource-category-card__list li a:hover {
    color: var(--color-purple);
    transform: translateX(4px);
}

.resource-category-card__list .badge-future {
    font-size: 0.55rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: rgba(0, 0, 0, 0.04);
    padding: 1px 8px;
    border-radius: 50px;
    margin-left: 4px;
    letter-spacing: 0.02em;
}

/* ============================================================
   CONTENT DISCOVERY FLOW
   ============================================================ */
.sitemap-resources__flow {
    max-width: 1000px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    overflow-x: auto;
}

.sitemap-resources__flow:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.discovery-flow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-width: 700px;
    gap: 6px;
    padding: 12px 8px 8px;
}

.discovery-flow-node {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    position: relative;
    flex: 1;
    min-width: 60px;
}

.discovery-flow-node__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    border: 2px solid rgba(124, 58, 237, 0.06);
    font-size: 1.1rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.discovery-flow-node:hover .discovery-flow-node__icon {
    background: linear-gradient(135deg, var(--color-purple), var(--color-lime));
    color: var(--color-white);
    border-color: transparent;
    transform: scale(1.1);
}

.discovery-flow-node__label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: center;
    line-height: 1.2;
}

.discovery-flow-node__connector {
    position: absolute;
    right: -8px;
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 2px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.2;
}

.discovery-flow-node__connector::after {
    content: '→';
    position: absolute;
    right: -6px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.6rem;
    color: var(--color-gray-mid);
}

.discovery-flow-node--end .discovery-flow-node__connector {
    display: none;
}

/* ============================================================
   QUICK RESOURCE CENTER
   ============================================================ */
.sitemap-resources__center {
    max-width: 900px;
    margin: 0 auto 40px;
}

.resource-center {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.resource-center:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.resource-center__section {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.resource-center__section--search {
    grid-column: 1 / -1;
}

.resource-center__label {
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-gray-mid);
}

.resource-center__list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.resource-center__list li {
    padding: 3px 0;
}

.resource-center__list li a {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.82rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-charcoal);
    text-decoration: none;
    transition: all 0.25s ease;
}

.resource-center__list li a i {
    font-size: 0.55rem;
    color: var(--color-purple);
    transition: transform 0.25s ease;
}

.resource-center__list li a:hover {
    color: var(--color-purple);
}

.resource-center__list li a:hover i {
    transform: translateX(2px);
}

/* Quick Search */
.resource-center__search {
    display: flex;
    align-items: center;
    background: rgba(255, 255, 255, 0.4);
    border: 1px solid var(--color-gray-light);
    border-radius: 12px;
    padding: 0 4px 0 14px;
    transition: all 0.3s ease;
}

.resource-center__search:focus-within {
    border-color: var(--color-purple);
    box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.06);
}

.resource-center__search i {
    color: var(--color-gray-mid);
    font-size: 0.85rem;
}

.resource-center__input {
    flex: 1;
    padding: 10px 12px;
    border: none;
    outline: none;
    background: transparent;
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-charcoal);
}

.resource-center__input::placeholder {
    color: var(--color-gray-light);
}

.resource-center__btn {
    padding: 6px 18px;
    border: none;
    border-radius: 8px;
    background: var(--color-lime);
    color: var(--color-charcoal);
    font-size: 0.78rem;
    font-weight: var(--font-weight-medium);
    cursor: pointer;
    transition: all 0.3s ease;
}

.resource-center__btn:hover {
    background: var(--color-lime-dark);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(192, 227, 74, 0.2);
}

/* ============================================================
   INFORMATION BANNER
   ============================================================ */
.sitemap-resources__notice {
    max-width: 900px;
    margin: 0 auto 0;
}

.notice-banner-resources {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 20px 28px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    gap: 16px;
}

.notice-banner-resources:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.notice-banner-resources__content {
    display: flex;
    align-items: center;
    gap: 16px;
    flex: 1;
}

.notice-banner-resources__icon {
    font-size: 2rem;
    color: var(--color-lime);
    flex-shrink: 0;
}

.notice-banner-resources__title {
    font-size: 1rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 2px;
    letter-spacing: -0.02em;
}

.notice-banner-resources__desc {
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.5;
    margin: 0;
    max-width: 480px;
}

.notice-banner-resources__badge {
    flex-shrink: 0;
}

.notice-banner-resources__badge span {
    display: inline-block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.06);
    padding: 4px 16px;
    border-radius: 50px;
    border: 1px solid rgba(192, 227, 74, 0.12);
}

/* ----- Focus States ----- */
.btn-banner-resources-docs:focus-visible,
.btn-banner-resources-blog:focus-visible,
.resource-category-card__toggle:focus-visible,
.resource-center__btn:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Resources & Legal Pages
================================================== */

/* ==================================================
START: Contact, Support & Social Links
================================================== */

/* ----- Container ----- */
#sitemap-contact {
    padding: 80px 0 60px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.sitemap-contact__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.sitemap-contact__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.sitemap-contact__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.sitemap-contact__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.sitemap-contact__glow--3 {
    width: 250px;
    height: 250px;
    top: 40%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.sitemap-contact__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.sitemap-contact__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.sitemap-contact__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 20%;
    left: 20%;
    animation-delay: 2s;
}

.sitemap-contact__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.sitemap-contact__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.sitemap-contact__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 30%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.sitemap-contact__grid-overlay {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.2;
    pointer-events: none;
}

/* Floating Particles */
#sitemap-contact .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#sitemap-contact .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#sitemap-contact .particle--2 {
    width: 12px;
    height: 12px;
    top: 75%;
    left: 88%;
    animation-delay: 1.2s;
}

#sitemap-contact .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#sitemap-contact .particle--4 {
    width: 10px;
    height: 10px;
    top: 82%;
    left: 12%;
    animation-delay: 0.6s;
}

#sitemap-contact .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#sitemap-contact .particle--6 {
    width: 9px;
    height: 9px;
    top: 55%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.sitemap-contact__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.sitemap-contact__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.sitemap-contact__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.sitemap-contact__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.sitemap-contact__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.sitemap-contact__title .highlight-text {
    color: var(--color-purple);
    position: relative;
    display: inline-block;
}

.sitemap-contact__title .highlight-text::after {
    content: '';
    position: absolute;
    bottom: 4px;
    left: 0;
    right: 0;
    height: 4px;
    background: var(--color-lime);
    border-radius: 2px;
    opacity: 0.3;
}

.sitemap-contact__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   SECTION HEADER (Reusable)
   ============================================================ */
.section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.section-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.section-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.section-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

/* ============================================================
   FEATURED CONTACT BANNER
   ============================================================ */
.sitemap-contact__banner {
    margin-bottom: 48px;
}

.contact-banner {
    display: grid;
    grid-template-columns: 60fr 40fr;
    gap: 0;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.contact-banner:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.contact-banner__content {
    padding: 36px 40px 32px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.contact-banner__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.contact-banner__title {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin: 0;
}

.contact-banner__desc {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    max-width: 520px;
    margin: 0;
}

.contact-banner__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 4px;
}

.btn-banner-contact-form {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
}

.btn-banner-contact-form:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.45);
}

.btn-banner-contact-quote {
    padding: 10px 28px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-banner-contact-quote:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- Banner Visual ----- */
.contact-banner__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    position: relative;
    overflow: hidden;
    padding: 30px 20px;
    min-height: 180px;
}

.ct-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 1.1rem;
    color: rgba(255, 255, 255, 0.3);
    transition: all 0.3s ease;
}

.ct-icon:hover {
    background: rgba(255, 255, 255, 0.12);
    color: var(--color-lime);
    transform: scale(1.1);
}

.ct-icon--1 { top: 15%; left: 10%; animation: floatIcon 5s ease-in-out infinite; }
.ct-icon--2 { top: 15%; right: 10%; animation: floatIcon 5s ease-in-out infinite 1.2s; }
.ct-icon--3 { bottom: 20%; left: 8%; animation: floatIcon 5s ease-in-out infinite 2.4s; }
.ct-icon--4 { bottom: 20%; right: 8%; animation: floatIcon 5s ease-in-out infinite 3.6s; }

.ct-shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.03);
}

.ct-shape--1 {
    width: 120px;
    height: 120px;
    top: -40px;
    right: -30px;
}

.ct-shape--2 {
    width: 80px;
    height: 80px;
    bottom: -20px;
    left: -20px;
}

.ct-shape--3 {
    width: 50px;
    height: 50px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* ============================================================
   CONTACT CATEGORIES GRID
   ============================================================ */
.sitemap-contact__categories {
    max-width: 1100px;
    margin: 0 auto 48px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.sitemap-contact__categories:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.contact-categories-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px 16px;
}

.contact-category-card {
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    overflow: hidden;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.contact-category-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateY(-4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.contact-category-card__header {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 14px 16px 12px;
    cursor: pointer;
    user-select: none;
}

.contact-category-card__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
    flex-shrink: 0;
}

.contact-category-card__title {
    font-size: 0.82rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    flex: 1;
}

.contact-category-card__toggle {
    width: 28px;
    height: 28px;
    border: none;
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.02);
    color: var(--color-gray-mid);
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    flex-shrink: 0;
}

.contact-category-card__toggle:hover {
    background: rgba(0, 0, 0, 0.04);
    color: var(--color-charcoal);
}

.contact-category-card__toggle[aria-expanded="true"] i {
    transform: rotate(180deg);
}

.contact-category-card__body {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s ease, padding 0.4s ease;
    padding: 0 16px;
}

.contact-category-card__body--open {
    max-height: 400px;
    padding: 0 16px 12px;
}

.contact-category-card__list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.contact-category-card__list li {
    padding: 4px 0;
}

.contact-category-card__list li a {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.75rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    text-decoration: none;
    transition: all 0.25s ease;
}

.contact-category-card__list li a i:first-child {
    width: 16px;
    text-align: center;
    color: var(--color-purple);
    font-size: 0.7rem;
    flex-shrink: 0;
}

.contact-category-card__list li a:hover {
    color: var(--color-purple);
    transform: translateX(4px);
}

.contact-category-card__list .badge-status {
    font-size: 0.5rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.08);
    padding: 1px 8px;
    border-radius: 50px;
    margin-left: 4px;
    letter-spacing: 0.02em;
}

.contact-category-card__list .badge-future {
    font-size: 0.5rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: rgba(0, 0, 0, 0.04);
    padding: 1px 8px;
    border-radius: 50px;
    margin-left: 4px;
    letter-spacing: 0.02em;
}

.contact-category-card__address {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.75rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    text-decoration: none;
    transition: all 0.25s ease;
}

.contact-category-card__address i {
    width: 16px;
    text-align: center;
    color: var(--color-purple);
    font-size: 0.7rem;
    flex-shrink: 0;
}

.contact-category-card__address:hover {
    color: var(--color-purple);
    transform: translateX(4px);
}

/* ============================================================
   COMMUNICATION JOURNEY FLOW
   ============================================================ */
.sitemap-contact__flow {
    max-width: 1000px;
    margin: 0 auto 40px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    overflow-x: auto;
}

.sitemap-contact__flow:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.comm-flow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-width: 700px;
    gap: 6px;
    padding: 12px 8px 8px;
}

.comm-flow-node {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    position: relative;
    flex: 1;
    min-width: 60px;
}

.comm-flow-node__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    border: 2px solid rgba(124, 58, 237, 0.06);
    font-size: 1.1rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.comm-flow-node:hover .comm-flow-node__icon {
    background: linear-gradient(135deg, var(--color-purple), var(--color-lime));
    color: var(--color-white);
    border-color: transparent;
    transform: scale(1.1);
}

.comm-flow-node__label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: center;
    line-height: 1.2;
}

.comm-flow-node__connector {
    position: absolute;
    right: -8px;
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 2px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.2;
}

.comm-flow-node__connector::after {
    content: '→';
    position: absolute;
    right: -6px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.6rem;
    color: var(--color-gray-mid);
}

.comm-flow-node--end .comm-flow-node__connector {
    display: none;
}

/* ============================================================
   SOCIAL MEDIA HUB
   ============================================================ */
.sitemap-contact__social {
    max-width: 1000px;
    margin: 0 auto 40px;
}

.social-hub {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 20px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.social-hub:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.social-card {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px 18px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    position: relative;
}

.social-card:hover {
    background: rgba(255, 255, 255, 0.7);
    transform: translateY(-4px) translateX(4px);
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.04);
}

.social-card__icon {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    color: var(--color-white);
    flex-shrink: 0;
    transition: all 0.3s ease;
}

.social-card:hover .social-card__icon {
    transform: scale(1.1);
}

.social-card__info {
    flex: 1;
    min-width: 0;
}

.social-card__name {
    display: block;
    font-size: 0.85rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.social-card__desc {
    display: block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

.social-card__link {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    transition: all 0.3s ease;
    flex-shrink: 0;
    text-decoration: none;
}

.social-card__link:hover {
    background: var(--color-purple);
    color: var(--color-white);
    transform: translateX(2px);
}

/* Social Card Colors */
.social-card--linkedin .social-card__icon {
    background: #0A66C2;
}
.social-card--facebook .social-card__icon {
    background: #1877F2;
}
.social-card--instagram .social-card__icon {
    background: linear-gradient(135deg, #F58529, #DD2A7B, #8134AF);
}
.social-card--twitter .social-card__icon {
    background: #000000;
}
.social-card--youtube .social-card__icon {
    background: #FF0000;
}
.social-card--github .social-card__icon {
    background: #333333;
}

/* Social Card Hover Glow */
.social-card--linkedin:hover {
    border-color: rgba(10, 102, 194, 0.15);
    box-shadow: 0 4px 16px rgba(10, 102, 194, 0.06);
}
.social-card--facebook:hover {
    border-color: rgba(24, 119, 242, 0.15);
    box-shadow: 0 4px 16px rgba(24, 119, 242, 0.06);
}
.social-card--instagram:hover {
    border-color: rgba(221, 42, 123, 0.15);
    box-shadow: 0 4px 16px rgba(221, 42, 123, 0.06);
}
.social-card--twitter:hover {
    border-color: rgba(0, 0, 0, 0.1);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.04);
}
.social-card--youtube:hover {
    border-color: rgba(255, 0, 0, 0.15);
    box-shadow: 0 4px 16px rgba(255, 0, 0, 0.06);
}
.social-card--github:hover {
    border-color: rgba(51, 51, 51, 0.1);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.04);
}

/* ============================================================
   SUPPORT INFORMATION BANNER
   ============================================================ */
.sitemap-contact__notice {
    max-width: 900px;
    margin: 0 auto 0;
}

.notice-banner-contact {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 20px 28px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 18px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    gap: 16px;
}

.notice-banner-contact:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.notice-banner-contact__content {
    display: flex;
    align-items: center;
    gap: 16px;
    flex: 1;
}

.notice-banner-contact__icon {
    font-size: 2rem;
    color: var(--color-lime);
    flex-shrink: 0;
}

.notice-banner-contact__title {
    font-size: 1rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    margin: 0 0 2px;
    letter-spacing: -0.02em;
}

.notice-banner-contact__desc {
    font-size: 0.85rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.5;
    margin: 0;
    max-width: 480px;
}

.notice-banner-contact__badge {
    flex-shrink: 0;
}

.notice-banner-contact__badge span {
    display: inline-block;
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-lime-dark);
    background: rgba(192, 227, 74, 0.06);
    padding: 4px 16px;
    border-radius: 50px;
    border: 1px solid rgba(192, 227, 74, 0.12);
}

/* ----- Focus States ----- */
.btn-banner-contact-form:focus-visible,
.btn-banner-contact-quote:focus-visible,
.contact-category-card__toggle:focus-visible,
.social-card__link:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Contact, Support & Social Links
================================================== */

/* ==================================================
START: Final CTA & Navigation Summary
================================================== */

/* ----- Container ----- */
#sitemap-final {
    padding: 80px 0 0;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.sitemap-final__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.sitemap-final__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.sitemap-final__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.sitemap-final__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.sitemap-final__glow--3 {
    width: 300px;
    height: 300px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: var(--color-purple);
    opacity: 0.02;
}

.sitemap-final__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.sitemap-final__orb--1 {
    width: 100px;
    height: 100px;
    top: 10%;
    right: 15%;
    animation-delay: 0s;
}

.sitemap-final__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 30%;
    left: 20%;
    animation-delay: 2s;
}

.sitemap-final__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.sitemap-final__shape--1 {
    width: 160px;
    height: 160px;
    top: 8%;
    left: 25%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.sitemap-final__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 40%;
    right: 8%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

/* Floating Particles */
#sitemap-final .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#sitemap-final .particle--1 {
    width: 8px;
    height: 8px;
    top: 12%;
    left: 8%;
    animation-delay: 0s;
}

#sitemap-final .particle--2 {
    width: 12px;
    height: 12px;
    top: 80%;
    left: 88%;
    animation-delay: 1.2s;
}

#sitemap-final .particle--3 {
    width: 6px;
    height: 6px;
    top: 25%;
    left: 82%;
    animation-delay: 2.4s;
}

#sitemap-final .particle--4 {
    width: 10px;
    height: 10px;
    top: 85%;
    left: 12%;
    animation-delay: 0.6s;
}

#sitemap-final .particle--5 {
    width: 7px;
    height: 7px;
    top: 45%;
    left: 5%;
    animation-delay: 3s;
}

#sitemap-final .particle--6 {
    width: 9px;
    height: 9px;
    top: 60%;
    left: 92%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.sitemap-final__inner {
    position: relative;
    z-index: 2;
}

/* ============================================================
   SECTION HEADER
   ============================================================ */
.sitemap-final__header {
    text-align: center;
    max-width: 760px;
    margin: 0 auto 48px;
}

.sitemap-final__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 16px 4px 14px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 12px;
}

.sitemap-final__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.sitemap-final__title {
    font-size: 2.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 12px;
}

.sitemap-final__title .highlight-text {
    color: var(--color-purple);
    position: relative;
    display: inline-block;
}

.sitemap-final__title .highlight-text::after {
    content: '';
    position: absolute;
    bottom: 4px;
    left: 0;
    right: 0;
    height: 4px;
    background: var(--color-lime);
    border-radius: 2px;
    opacity: 0.3;
}

.sitemap-final__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
}

/* ============================================================
   SECTION HEADER (Reusable)
   ============================================================ */
.section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.section-header__icon {
    font-size: 1.2rem;
    color: var(--color-purple);
}

.section-header__title {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    margin: 0;
}

.section-header__count {
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    background: var(--color-off-white);
    padding: 2px 12px;
    border-radius: 50px;
    border: 1px solid var(--color-gray-light);
    margin-left: auto;
}

/* ============================================================
   NAVIGATION SUMMARY BANNER
   ============================================================ */
.sitemap-final__banner {
    margin-bottom: 48px;
}

.final-banner {
    display: grid;
    grid-template-columns: 60fr 40fr;
    gap: 0;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.final-banner:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.final-banner__content {
    padding: 36px 40px 32px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.final-banner__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.final-banner__title {
    font-size: 1.5rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin: 0;
}

.final-banner__desc {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    max-width: 520px;
    margin: 0;
}

.final-banner__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 4px;
}

.btn-banner-final-services {
    padding: 10px 28px;
    font-size: 0.85rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 20px rgba(192, 227, 74, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
}

.btn-banner-final-services:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(192, 227, 74, 0.45);
}

.btn-banner-final-contact {
    padding: 10px 28px;
    font-size: 0.85rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.btn-banner-final-contact:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- Banner Visual ----- */
.final-banner__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    position: relative;
    overflow: hidden;
    padding: 30px 20px;
    min-height: 180px;
}

.fn-icon {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 1.1rem;
    color: rgba(255, 255, 255, 0.3);
    transition: all 0.3s ease;
}

.fn-icon:hover {
    background: rgba(255, 255, 255, 0.12);
    color: var(--color-lime);
    transform: scale(1.1);
}

.fn-icon--1 { top: 15%; left: 10%; animation: floatIcon 5s ease-in-out infinite; }
.fn-icon--2 { top: 15%; right: 10%; animation: floatIcon 5s ease-in-out infinite 1.2s; }
.fn-icon--3 { bottom: 20%; left: 8%; animation: floatIcon 5s ease-in-out infinite 2.4s; }
.fn-icon--4 { bottom: 20%; right: 8%; animation: floatIcon 5s ease-in-out infinite 3.6s; }

.fn-shape {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.03);
}

.fn-shape--1 {
    width: 120px;
    height: 120px;
    top: -40px;
    right: -30px;
}

.fn-shape--2 {
    width: 80px;
    height: 80px;
    bottom: -20px;
    left: -20px;
}

.fn-shape--3 {
    width: 50px;
    height: 50px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* ============================================================
   WEBSITE HIGHLIGHTS GRID
   ============================================================ */
.sitemap-final__highlights {
    max-width: 1100px;
    margin: 0 auto 48px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.sitemap-final__highlights:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.highlights-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px 16px;
}

.highlight-card {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px 16px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    position: relative;
}

.highlight-card:hover {
    background: rgba(255, 255, 255, 0.7);
    border-color: rgba(192, 227, 74, 0.15);
    transform: translateY(-4px) translateX(4px);
    box-shadow: 0 4px 16px rgba(192, 227, 74, 0.04);
}

.highlight-card__icon {
    font-size: 1.3rem;
    color: var(--color-purple);
    flex-shrink: 0;
    width: 32px;
    text-align: center;
}

.highlight-card__info {
    flex: 1;
    min-width: 0;
}

.highlight-card__title {
    display: block;
    font-size: 0.85rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
    line-height: 1.2;
}

.highlight-card__desc {
    display: block;
    font-size: 0.68rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.2;
}

.highlight-card__link {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    color: var(--color-purple);
    transition: all 0.3s ease;
    flex-shrink: 0;
    text-decoration: none;
}

.highlight-card__link:hover {
    background: var(--color-purple);
    color: var(--color-white);
    transform: translateX(2px);
}

/* ============================================================
   NAVIGATION JOURNEY TIMELINE
   ============================================================ */
.sitemap-final__timeline {
    max-width: 1000px;
    margin: 0 auto 48px;
    padding: 28px 32px 24px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid var(--color-gray-light);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    overflow-x: auto;
}

.sitemap-final__timeline:hover {
    transform: translateY(-4px);
    border-color: rgba(124, 58, 237, 0.06);
    box-shadow: 0 12px 40px rgba(124, 58, 237, 0.04);
}

.journey-timeline {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-width: 700px;
    gap: 6px;
    padding: 12px 8px 8px;
}

.timeline-node {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    position: relative;
    flex: 1;
    min-width: 60px;
}

.timeline-node__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.06);
    border: 2px solid rgba(124, 58, 237, 0.06);
    font-size: 1.1rem;
    color: var(--color-purple);
    transition: all 0.3s ease;
}

.timeline-node:hover .timeline-node__icon {
    background: linear-gradient(135deg, var(--color-purple), var(--color-lime));
    color: var(--color-white);
    border-color: transparent;
    transform: scale(1.1);
}

.timeline-node__label {
    font-size: 0.6rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-charcoal);
    text-align: center;
    line-height: 1.2;
}

.timeline-node__connector {
    position: absolute;
    right: -8px;
    top: 50%;
    transform: translateY(-50%);
    width: 16px;
    height: 2px;
    background: linear-gradient(90deg, var(--color-lime), var(--color-purple));
    opacity: 0.2;
}

.timeline-node__connector::after {
    content: '→';
    position: absolute;
    right: -6px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.6rem;
    color: var(--color-gray-mid);
}

.timeline-node--end .timeline-node__connector {
    display: none;
}

/* ============================================================
   FINAL CTA BANNER
   ============================================================ */
.sitemap-final__cta {
    max-width: 1100px;
    margin: 0 auto 48px;
}

.final-cta {
    display: grid;
    grid-template-columns: 60fr 40fr;
    gap: 0;
    background: linear-gradient(135deg, rgba(124, 58, 237, 0.04), rgba(192, 227, 74, 0.04));
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(124, 58, 237, 0.08);
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 8px 32px rgba(124, 58, 237, 0.04);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.final-cta:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.08);
}

.final-cta__content {
    padding: 40px 44px 36px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.final-cta__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.final-cta__title {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin: 0;
}

.final-cta__desc {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    max-width: 520px;
    margin: 0;
}

.final-cta__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 4px;
}

.btn-cta-final-getstarted {
    padding: 12px 32px;
    font-size: 0.9rem;
    background: linear-gradient(135deg, var(--color-lime), #5bcf4e);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.4);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
    font-weight: var(--font-weight-semibold);
}

.btn-cta-final-getstarted:hover {
    background: linear-gradient(135deg, var(--color-lime-dark), #4ab83e);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(192, 227, 74, 0.5);
}

.btn-cta-final-services {
    padding: 12px 32px;
    font-size: 0.9rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-weight: var(--font-weight-semibold);
}

.btn-cta-final-services:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- Final CTA Visual ----- */
.final-cta__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    position: relative;
    overflow: hidden;
    padding: 30px 20px;
    min-height: 200px;
}

.final-cta__icon-ring {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    position: relative;
    z-index: 2;
}

.final-cta__icon-ring span {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 52px;
    height: 52px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.08);
    font-size: 1.3rem;
    color: rgba(255, 255, 255, 0.25);
    transition: all 0.3s ease;
}

.final-cta__icon-ring span:hover {
    background: rgba(255, 255, 255, 0.12);
    color: var(--color-lime);
    transform: scale(1.1);
}

.final-cta__pulse {
    position: absolute;
    width: 160px;
    height: 160px;
    border-radius: 50%;
    border: 1px solid rgba(255, 255, 255, 0.04);
    animation: pulseRing 3s ease-in-out infinite;
}

.final-cta__pulse::before {
    content: '';
    position: absolute;
    inset: 20px;
    border-radius: 50%;
    border: 1px solid rgba(255, 255, 255, 0.03);
    animation: pulseRing 3s ease-in-out infinite 1s;
}

@keyframes pulseRing {
    0% {
        transform: scale(0.8);
        opacity: 0.6;
    }
    50% {
        transform: scale(1.2);
        opacity: 0.2;
    }
    100% {
        transform: scale(0.8);
        opacity: 0.6;
    }
}

/* ============================================================
   FOOTER TRANSITION
   ============================================================ */
.sitemap-final__transition {
    max-width: 1100px;
    margin: 0 auto 0;
    padding-bottom: 0;
}

.footer-transition {
    position: relative;
    padding: 30px 0 10px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
}

.footer-transition__line {
    width: 1px;
    height: 60px;
    background: linear-gradient(to bottom, rgba(124, 58, 237, 0.15), rgba(124, 58, 237, 0.01));
    position: relative;
}

.footer-transition__line::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 50%;
    transform: translateX(-50%);
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--color-purple);
    opacity: 0.2;
}

.footer-transition__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(60px);
    pointer-events: none;
}

.footer-transition__glow--1 {
    width: 200px;
    height: 200px;
    top: -60px;
    left: 20%;
    background: var(--color-purple);
    opacity: 0.04;
}

.footer-transition__glow--2 {
    width: 200px;
    height: 200px;
    top: -60px;
    right: 20%;
    background: var(--color-lime);
    opacity: 0.03;
}

.footer-transition__nodes {
    display: flex;
    gap: 20px;
    justify-content: center;
}

.ft-node {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--color-purple);
    opacity: 0.08;
    animation: nodePulse 2s ease-in-out infinite;
}

.ft-node:nth-child(1) { animation-delay: 0s; }
.ft-node:nth-child(2) { animation-delay: 0.4s; }
.ft-node:nth-child(3) { animation-delay: 0.8s; }
.ft-node:nth-child(4) { animation-delay: 1.2s; }
.ft-node:nth-child(5) { animation-delay: 1.6s; }

@keyframes nodePulse {
    0%, 100% { opacity: 0.08; transform: scale(1); }
    50% { opacity: 0.25; transform: scale(1.3); }
}

.footer-transition__text {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

.footer-transition__text i {
    font-size: 0.6rem;
    animation: bounceDown 2s ease-in-out infinite;
}

@keyframes bounceDown {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(4px); }
}

/* ----- Focus States ----- */
.btn-banner-final-services:focus-visible,
.btn-banner-final-contact:focus-visible,
.highlight-card__link:focus-visible,
.btn-cta-final-getstarted:focus-visible,
.btn-cta-final-services:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Final CTA & Navigation Summary
================================================== */

/* ==================================================
START: 404 Hero Section
================================================== */

/* ----- Container ----- */
#error-hero {
    padding: 60px 0 80px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
    min-height: 100vh;
    display: flex;
    align-items: center;
}

/* ----- Background Decorations ----- */
.error-hero__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.error-hero__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.error-hero__glow--1 {
    width: 500px;
    height: 500px;
    top: -150px;
    right: -100px;
    background: var(--color-purple);
    opacity: 0.05;
}

.error-hero__glow--2 {
    width: 450px;
    height: 450px;
    bottom: -100px;
    left: -80px;
    background: var(--color-lime);
    opacity: 0.04;
}

.error-hero__glow--3 {
    width: 300px;
    height: 300px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: var(--color-purple);
    opacity: 0.03;
}

.error-hero__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.02);
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: floatOrb 8s ease-in-out infinite;
}

.error-hero__orb--1 {
    width: 100px;
    height: 100px;
    top: 15%;
    right: 12%;
    animation-delay: 0s;
}

.error-hero__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 25%;
    left: 15%;
    animation-delay: 2s;
}

.error-hero__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.error-hero__shape--1 {
    width: 160px;
    height: 160px;
    top: 10%;
    left: 20%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.error-hero__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 35%;
    right: 10%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

/* Floating Particles */
#error-hero .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#error-hero .particle--1 {
    width: 8px;
    height: 8px;
    top: 10%;
    left: 6%;
