/* ----- Container ----- */
#error-nav {
    padding: 60px 0 80px;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
}

/* ----- Background Decorations ----- */
.error-nav__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.error-nav__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.06;
    pointer-events: none;
}

.error-nav__glow--1 {
    width: 450px;
    height: 450px;
    top: -120px;
    right: -80px;
    background: var(--color-purple);
    opacity: 0.04;
}

.error-nav__glow--2 {
    width: 400px;
    height: 400px;
    bottom: -100px;
    left: -60px;
    background: var(--color-lime);
    opacity: 0.03;
}

.error-nav__glow--3 {
