.final-cta-banner__content {
    padding: 40px 44px 36px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.final-cta-banner__badge {
    font-size: 0.65rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.final-cta-banner__title {
    font-size: 1.6rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin: 0;
}

.final-cta-banner__desc {
    font-size: 0.92rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.6;
    max-width: 520px;
    margin: 0;
}

.final-cta-banner__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 4px;
}

.btn-cta-final-project {
    padding: 12px 32px;
    font-size: 0.9rem;
    background: linear-gradient(135deg, var(--color-lime), #5bcf4e);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.4);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
    font-weight: var(--font-weight-semibold);
}

.btn-cta-final-project:hover {
    background: linear-gradient(135deg, var(--color-lime-dark), #4ab83e);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(192, 227, 74, 0.5);
}

.btn-cta-final-project i:last-child {
    margin-left: 2px;
    transition: transform 0.3s ease;
}

.btn-cta-final-project:hover i:last-child {
    transform: translateX(4px);
}

.btn-cta-final-team {
    padding: 12px 32px;
    font-size: 0.9rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-weight: var(--font-weight-semibold);
}

.btn-cta-final-team:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- Final CTA Visual ----- */
.final-cta-banner__visual {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #1A2A4A, #4F46E5);
    position: relative;
    overflow: hidden;
    padding: 30px 20px;
    min-height: 200px;
}

.final-cta-banner__icon-ring {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    position: relative;
    z-index: 2;
}

.final-cta-banner__icon-ring span {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 52px;
    height: 52px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.08);
    font-size: 1.3rem;
    color: rgba(255, 255, 255, 0.25);
    transition: all 0.3s ease;
}

.final-cta-banner__icon-ring span:hover {
    background: rgba(255, 255, 255, 0.12);
    color: var(--color-lime);
    transform: scale(1.1);
}

.final-cta-banner__pulse {
    position: absolute;
    width: 160px;
    height: 160px;
    border-radius: 50%;
    border: 1px solid rgba(255, 255, 255, 0.04);
    animation: pulseRing 3s ease-in-out infinite;
}

.final-cta-banner__pulse::before {
    content: '';
    position: absolute;
    inset: 20px;
    border-radius: 50%;
    border: 1px solid rgba(255, 255, 255, 0.03);
    animation: pulseRing 3s ease-in-out infinite 1s;
}

/* ============================================================
   FOOTER TRANSITION
   ============================================================ */
.error-final__transition {
    max-width: 1100px;
    margin: 0 auto 0;
    padding-bottom: 0;
}

.footer-transition-final {
    position: relative;
    padding: 30px 0 10px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
}

.footer-transition-final__line {
    width: 1px;
    height: 60px;
    background: linear-gradient(to bottom, rgba(124, 58, 237, 0.15), rgba(124, 58, 237, 0.01));
    position: relative;
}

.footer-transition-final__line::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 50%;
    transform: translateX(-50%);
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--color-purple);
    opacity: 0.2;
}

.footer-transition-final__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(60px);
    pointer-events: none;
}

.footer-transition-final__glow--1 {
    width: 200px;
    height: 200px;
    top: -60px;
    left: 20%;
    background: var(--color-purple);
    opacity: 0.04;
}

.footer-transition-final__glow--2 {
    width: 200px;
    height: 200px;
    top: -60px;
    right: 20%;
    background: var(--color-lime);
    opacity: 0.03;
}

.footer-transition-final__nodes {
    display: flex;
    gap: 20px;
    justify-content: center;
}

.ftf-node {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--color-purple);
    opacity: 0.08;
    animation: nodePulse 2s ease-in-out infinite;
}

.ftf-node:nth-child(1) { animation-delay: 0s; }
.ftf-node:nth-child(2) { animation-delay: 0.4s; }
.ftf-node:nth-child(3) { animation-delay: 0.8s; }
.ftf-node:nth-child(4) { animation-delay: 1.2s; }
.ftf-node:nth-child(5) { animation-delay: 1.6s; }

.footer-transition-final__text {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-medium);
    color: var(--color-gray-mid);
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

.footer-transition-final__text i {
    font-size: 0.6rem;
    animation: bounceDown 2s ease-in-out infinite;
}

/* ----- Focus States ----- */
.btn-final-home:focus-visible,
.btn-final-services:focus-visible,
.recovery-card__link:focus-visible,
.btn-cta-final-project:focus-visible,
.btn-cta-final-team:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

/* ==================================================
END: Final CTA & Recovery Section
================================================== */

/* ==================================================
START: Super Admin Sign Up Hero & Registration
================================================== */

/* ----- Section Container ----- */
#admin-signup {
    min-height: 100vh;
    display: flex;
    align-items: center;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
    padding: 40px 0;
}

/* ----- Background ----- */
.admin-signup__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.admin-signup__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(120px);
    opacity: 0.04;
    pointer-events: none;
}

.admin-signup__glow--1 {
    width: 600px;
    height: 600px;
    top: -200px;
    right: -150px;
    background: var(--color-purple);
}

.admin-signup__glow--2 {
    width: 500px;
    height: 500px;
    bottom: -150px;
    left: -100px;
    background: var(--color-lime);
}

.admin-signup__glow--3 {
    width: 300px;
    height: 300px;
    top: 40%;
    left: 30%;
    background: var(--color-purple);
    opacity: 0.02;
}

.admin-signup__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.015);
    border: 1px solid rgba(124, 58, 237, 0.02);
    animation: floatOrb 8s ease-in-out infinite;
}

.admin-signup__orb--1 {
    width: 120px;
    height: 120px;
    top: 15%;
    right: 25%;
    animation-delay: 0s;
}

.admin-signup__orb--2 {
    width: 80px;
    height: 80px;
    bottom: 25%;
    left: 15%;
    animation-delay: 2.5s;
}

.admin-signup__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.15;
    pointer-events: none;
}

.admin-signup__grid svg {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* ----- Particles ----- */
#admin-signup .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.02);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#admin-signup .particle--1 {
    width: 10px;
    height: 10px;
    top: 10%;
    left: 8%;
    animation-delay: 0s;
}

#admin-signup .particle--2 {
    width: 14px;
    height: 14px;
    top: 80%;
    left: 85%;
    animation-delay: 1.2s;
}

#admin-signup .particle--3 {
    width: 7px;
    height: 7px;
    top: 20%;
    left: 80%;
    animation-delay: 2.4s;
}

#admin-signup .particle--4 {
    width: 11px;
    height: 11px;
    top: 85%;
    left: 10%;
    animation-delay: 0.6s;
}

#admin-signup .particle--5 {
    width: 8px;
    height: 8px;
    top: 45%;
    left: 4%;
    animation-delay: 3s;
}

#admin-signup .particle--6 {
    width: 10px;
    height: 10px;
    top: 55%;
    left: 90%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.admin-signup__container {
    position: relative;
    z-index: 2;
    display: grid;
    grid-template-columns: 45% 55%;
    gap: 40px;
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 24px;
    width: 100%;
    align-items: stretch;
}

/* ============================================================
   LEFT PANEL — Brand Experience
   ============================================================ */
.admin-signup__brand {
    display: flex;
    align-items: center;
    padding: 40px 32px;
    background: rgba(255, 255, 255, 0.25);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 28px;
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
}

.admin-signup__brand::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(145deg, rgba(122, 77, 255, 0.02), rgba(110, 220, 95, 0.015));
    border-radius: 28px;
    pointer-events: none;
}

.admin-signup__brand-inner {
    position: relative;
    z-index: 1;
    width: 100%;
}

/* Badge */
.admin-signup__badge {
    display: inline-block;
    padding: 4px 16px;
    background: rgba(122, 77, 255, 0.08);
    border: 1px solid rgba(122, 77, 255, 0.12);
    border-radius: 50px;
    font-size: 0.65rem;
    font-weight: 600;
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin-bottom: 20px;
}

.admin-signup__badge::before {
    content: '◆';
    margin-right: 6px;
    font-size: 0.45rem;
    color: var(--color-lime);
}

/* Brand Title */
.admin-signup__brand-title {
    font-size: 2.2rem;
    font-weight: 700;
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 16px;
}

.admin-signup__brand-title .highlight-text {
    color: var(--color-purple);
    position: relative;
    display: inline-block;
}

.admin-signup__brand-title .highlight-text::after {
    content: '';
    position: absolute;
    bottom: 2px;
    left: 0;
    right: 0;
    height: 4px;
    background: var(--color-lime);
    border-radius: 2px;
    opacity: 0.3;
}

.admin-signup__brand-subtitle {
    font-size: 0.95rem;
    color: var(--color-gray-mid);
    line-height: 1.7;
    margin-bottom: 28px;
}

/* Feature Cards */
.admin-signup__features {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-bottom: 28px;
}

.admin-signup__feature {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    transition: all 0.3s ease;
    cursor: default;
}

.admin-signup__feature:hover {
    background: rgba(255, 255, 255, 0.6);
    border-color: rgba(122, 77, 255, 0.08);
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.02);
}

.admin-signup__feature-icon {
    font-size: 0.9rem;
    color: var(--color-purple);
    width: 24px;
    text-align: center;
    flex-shrink: 0;
}

.admin-signup__feature-label {
    font-size: 0.78rem;
    font-weight: 500;
    color: var(--color-charcoal);
}

/* Quote */
.admin-signup__quote {
    font-size: 0.9rem;
    font-weight: 400;
    color: var(--color-gray-mid);
    font-style: italic;
    padding: 16px 20px;
    background: rgba(255, 255, 255, 0.15);
    border-left: 3px solid var(--color-lime);
    border-radius: 8px;
    margin-bottom: 24px;
    position: relative;
}

.admin-signup__quote-icon {
    font-size: 1.6rem;
    color: var(--color-purple);
    opacity: 0.15;
    position: absolute;
    top: -4px;
    left: 8px;
    font-family: Georgia, serif;
    line-height: 1;
}

/* Abstract Dashboard Illustration */
.admin-signup__illustration {
    margin-top: 8px;
}

.admin-signup__dashboard {
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 16px;
    padding: 12px 14px;
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
}

.admin-signup__dashboard-header {
    display: flex;
    align-items: center;
    gap: 6px;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.admin-signup__dashboard-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.04);
}

.admin-signup__dashboard-dot:nth-child(1) { background: rgba(239, 68, 68, 0.2); }
.admin-signup__dashboard-dot:nth-child(2) { background: rgba(245, 158, 11, 0.2); }
.admin-signup__dashboard-dot:nth-child(3) { background: rgba(34, 197, 94, 0.2); }

.admin-signup__dashboard-url {
    font-size: 0.55rem;
    font-weight: 500;
    color: rgba(255, 255, 255, 0.15);
    font-family: 'Inter', monospace;
    margin-left: 8px;
    letter-spacing: 0.02em;
}

.admin-signup__dashboard-body {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 8px;
    padding-top: 10px;
}

.admin-signup__dashboard-stat {
    background: rgba(255, 255, 255, 0.02);
    border-radius: 8px;
    padding: 8px 10px;
}

.admin-signup__dashboard-stat-label {
    display: block;
    font-size: 0.5rem;
    font-weight: 500;
    color: rgba(255, 255, 255, 0.2);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.admin-signup__dashboard-stat-value {
    display: block;
    font-size: 0.9rem;
    font-weight: 700;
    color: rgba(255, 255, 255, 0.4);
    letter-spacing: -0.02em;
}

.admin-signup__dashboard-stat-change {
    font-size: 0.5rem;
    font-weight: 600;
    color: var(--color-lime);
    opacity: 0.5;
}

.admin-signup__dashboard-chart {
    grid-column: 1 / -1;
    display: flex;
    align-items: flex-end;
    gap: 4px;
    height: 40px;
    padding-top: 4px;
}

.admin-signup__dashboard-chart-bar {
    flex: 1;
    background: rgba(255, 255, 255, 0.03);
    border-radius: 2px 2px 0 0;
    min-height: 4px;
    transition: height 0.6s ease;
}

.admin-signup__dashboard-chart-bar:nth-child(1) { background: rgba(122, 77, 255, 0.15); }
.admin-signup__dashboard-chart-bar:nth-child(2) { background: rgba(122, 77, 255, 0.20); }
.admin-signup__dashboard-chart-bar:nth-child(3) { background: rgba(122, 77, 255, 0.12); }
.admin-signup__dashboard-chart-bar:nth-child(4) { background: rgba(110, 220, 95, 0.20); }
.admin-signup__dashboard-chart-bar:nth-child(5) { background: rgba(122, 77, 255, 0.15); }
.admin-signup__dashboard-chart-bar:nth-child(6) { background: rgba(110, 220, 95, 0.25); }
.admin-signup__dashboard-chart-bar:nth-child(7) { background: rgba(122, 77, 255, 0.18); }

.admin-signup__dashboard:hover .admin-signup__dashboard-chart-bar {
    animation: chartBounce 1s ease forwards;
}

.admin-signup__dashboard-chart-bar:nth-child(1) { animation-delay: 0.05s; }
.admin-signup__dashboard-chart-bar:nth-child(2) { animation-delay: 0.10s; }
.admin-signup__dashboard-chart-bar:nth-child(3) { animation-delay: 0.15s; }
.admin-signup__dashboard-chart-bar:nth-child(4) { animation-delay: 0.20s; }
.admin-signup__dashboard-chart-bar:nth-child(5) { animation-delay: 0.25s; }
.admin-signup__dashboard-chart-bar:nth-child(6) { animation-delay: 0.30s; }
.admin-signup__dashboard-chart-bar:nth-child(7) { animation-delay: 0.35s; }

@keyframes chartBounce {
    0% { transform: scaleY(0); transform-origin: bottom; }
    60% { transform: scaleY(1.05); transform-origin: bottom; }
    100% { transform: scaleY(1); transform-origin: bottom; }
}

/* ============================================================
   RIGHT PANEL — Registration Form
   ============================================================ */
.admin-signup__form-wrapper {
    display: flex;
    align-items: center;
}

.admin-signup__form-card {
    width: 100%;
    padding: 40px 44px;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 28px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.admin-signup__form-card:hover {
    box-shadow: 0 16px 48px rgba(122, 77, 255, 0.06);
}

.admin-signup__form-badge {
    display: inline-block;
    padding: 3px 14px;
    background: rgba(110, 220, 95, 0.08);
    border: 1px solid rgba(110, 220, 95, 0.12);
    border-radius: 50px;
    font-size: 0.6rem;
    font-weight: 600;
    color: var(--color-lime-dark);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin-bottom: 16px;
}

.admin-signup__form-badge::before {
    content: '◆';
    margin-right: 6px;
    font-size: 0.4rem;
    color: var(--color-lime);
}

.admin-signup__form-title {
    font-size: 1.6rem;
    font-weight: 700;
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin-bottom: 4px;
}

.admin-signup__form-desc {
    font-size: 0.9rem;
    color: var(--color-gray-mid);
    margin-bottom: 28px;
}

/* ----- Form Fields (Floating Labels) ----- */
.admin-signup__form {
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.admin-signup__form-group {
    position: relative;
    display: flex;
    flex-direction: column;
}

.admin-signup__form-group--floating {
    position: relative;
}

.admin-signup__form-input {
    width: 100%;
    padding: 16px 14px 8px;
    background: rgba(255, 255, 255, 0.3);
    border: 1.5px solid var(--color-gray-light);
    border-radius: 12px;
    font-family: var(--font-family);
    font-size: 0.95rem;
    color: var(--color-charcoal);
    outline: none;
    transition: all 0.3s ease;
    height: 56px;
}

.admin-signup__form-input:focus {
    border-color: var(--color-purple);
    box-shadow: 0 0 0 4px rgba(122, 77, 255, 0.06);
    background: rgba(255, 255, 255, 0.5);
}

.admin-signup__form-input:focus + .admin-signup__form-label,
.admin-signup__form-input:not(:placeholder-shown) + .admin-signup__form-label {
    transform: translateY(-8px) scale(0.85);
    color: var(--color-purple);
}

.admin-signup__form-label {
    position: absolute;
    left: 14px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.9rem;
    color: var(--color-gray-mid);
    pointer-events: none;
    transition: all 0.25s ease;
    font-weight: 400;
    background: transparent;
    padding: 0 2px;
    transform-origin: left center;
}

.admin-signup__form-input:focus + .admin-signup__form-label,
.admin-signup__form-input:not(:placeholder-shown) + .admin-signup__form-label {
    top: 14px;
    transform: translateY(0) scale(0.75);
    color: var(--color-purple);
}

.admin-signup__form-optional {
    font-weight: 400;
    color: var(--color-gray-light);
    font-size: 0.7rem;
}

/* Password Toggle */
.admin-signup__toggle-password {
    position: absolute;
    right: 14px;
    top: 50%;
    transform: translateY(-50%);
    background: none;
    border: none;
    color: var(--color-gray-mid);
    cursor: pointer;
    padding: 4px;
    font-size: 0.9rem;
    transition: color 0.3s ease;
    z-index: 2;
}

.admin-signup__toggle-password:hover {
    color: var(--color-charcoal);
}

/* Error Messages */
.admin-signup__form-error {
    font-size: 0.7rem;
    color: var(--color-error);
    min-height: 18px;
    display: block;
    margin-top: 2px;
}

/* ----- Password Strength ----- */
.admin-signup__password-strength {
    margin: 4px 0 2px;
    padding: 14px 16px;
    background: rgba(255, 255, 255, 0.2);
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.05);
}

.admin-signup__password-bar {
    height: 4px;
    background: rgba(0, 0, 0, 0.04);
    border-radius: 4px;
    overflow: hidden;
    margin-bottom: 8px;
}

.admin-signup__password-fill {
    height: 100%;
    width: 0%;
    background: var(--color-error);
    border-radius: 4px;
    transition: width 0.4s ease, background 0.4s ease;
}

.admin-signup__password-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 6px;
}

.admin-signup__password-label {
    font-size: 0.75rem;
    color: var(--color-gray-mid);
}

.admin-signup__password-label strong {
    color: var(--color-charcoal);
}

.admin-signup__password-requirements-toggle {
    font-size: 0.7rem;
    color: var(--color-gray-mid);
    cursor: pointer;
    transition: color 0.3s ease;
    display: flex;
    align-items: center;
    gap: 4px;
    user-select: none;
}

.admin-signup__password-requirements-toggle:hover {
    color: var(--color-charcoal);
}

.admin-signup__password-requirements-toggle i {
    font-size: 0.55rem;
    transition: transform 0.3s ease;
}

.admin-signup__password-requirements-toggle.active i {
    transform: rotate(180deg);
}

.admin-signup__password-requirements {
    list-style: none;
    display: flex;
    flex-wrap: wrap;
    gap: 6px 14px;
    padding: 0;
    margin: 0;
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
    opacity: 0;
}

.admin-signup__password-requirements.open {
    max-height: 120px;
    opacity: 1;
    padding-top: 8px;
}

.admin-signup__password-requirements li {
    font-size: 0.7rem;
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    gap: 4px;
}

.admin-signup__password-requirements li i {
    font-size: 0.45rem;
    color: var(--color-gray-light);
    transition: color 0.3s ease;
}

.admin-signup__password-requirements li.valid i {
    color: var(--color-success);
}

.admin-signup__password-requirements li.invalid i {
    color: var(--color-error);
}

/* ----- Checkbox ----- */
.admin-signup__form-group--checkbox {
    flex-direction: row;
    align-items: flex-start;
    gap: 10px;
    margin-top: 2px;
}

.admin-signup__form-checkbox {
    width: 18px;
    height: 18px;
    accent-color: var(--color-purple);
    cursor: pointer;
    flex-shrink: 0;
    margin-top: 2px;
}

.admin-signup__form-checkbox-label {
    font-size: 0.85rem;
    color: var(--color-gray-mid);
    cursor: pointer;
    line-height: 1.4;
}

.admin-signup__form-checkbox-label a {
    color: var(--color-purple);
    text-decoration: none;
    font-weight: 500;
}

.admin-signup__form-checkbox-label a:hover {
    text-decoration: underline;
}

/* ----- Submit Button ----- */
.admin-signup__submit {
    width: 100%;
    padding: 14px 24px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-lime-dark));
    color: var(--color-charcoal);
    border: none;
    border-radius: 12px;
    font-size: 1rem;
    font-weight: 600;
    font-family: var(--font-family);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: 0 4px 24px rgba(110, 220, 95, 0.3);
    position: relative;
    overflow: hidden;
    margin-top: 4px;
}

.admin-signup__submit:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(110, 220, 95, 0.4);
}

.admin-signup__submit:active {
    transform: scale(0.98);
}

.admin-signup__submit i {
    transition: transform 0.3s ease;
}

.admin-signup__submit:hover i {
    transform: translateX(4px);
}

.admin-signup__submit:disabled {
    opacity: 0.7;
    cursor: not-allowed;
    transform: none !important;
}

/* Button Ripple */
.admin-signup__submit .ripple {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.3);
    transform: scale(0);
    animation: rippleAnim 0.6s linear;
    pointer-events: none;
}

@keyframes rippleAnim {
    to { transform: scale(4); opacity: 0; }
}

/* ----- Login Link ----- */
.admin-signup__login-link {
    text-align: center;
    font-size: 0.85rem;
    color: var(--color-gray-mid);
    margin-top: 12px;
}

.admin-signup__login-link a {
    color: var(--color-purple);
    text-decoration: none;
    font-weight: 500;
}

.admin-signup__login-link a:hover {
    text-decoration: underline;
}

/* ----- Future Placeholders ----- */
.admin-signup__future {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 6px;
    padding-top: 12px;
    border-top: 1px solid rgba(0, 0, 0, 0.02);
}

.admin-signup__future-item {
    font-size: 0.6rem;
    color: var(--color-gray-light);
    background: rgba(0, 0, 0, 0.01);
    padding: 2px 10px;
    border-radius: 50px;
    border: 1px solid rgba(0, 0, 0, 0.02);
    letter-spacing: 0.02em;
}

.admin-signup__future-item::before {
    content: '⚡';
    margin-right: 4px;
    font-size: 0.5rem;
}

/* ----- Focus States ----- */
.admin-signup__submit:focus-visible,
.admin-signup__form-input:focus-visible,
.admin-signup__toggle-password:focus-visible,
.admin-signup__form-checkbox:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 3px;
}

/* ==================================================
END: Super Admin Sign Up Hero & Registration
================================================== */

/* ==================================================
START: Super Admin Sign In Hero & Login Form
================================================== */

/* ----- Section Container ----- */
#admin-signin {
    min-height: 100vh;
    display: flex;
    align-items: center;
    background: var(--color-white);
    position: relative;
    overflow: hidden;
    padding: 40px 0;
}

/* ----- Background ----- */
.admin-signin__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
}

.admin-signin__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(120px);
    opacity: 0.04;
    pointer-events: none;
}

.admin-signin__glow--1 {
    width: 600px;
    height: 600px;
    top: -200px;
    right: -150px;
    background: var(--color-purple);
}

.admin-signin__glow--2 {
    width: 500px;
    height: 500px;
    bottom: -150px;
    left: -100px;
    background: var(--color-lime);
}

.admin-signin__glow--3 {
    width: 300px;
    height: 300px;
    top: 40%;
    left: 30%;
    background: var(--color-purple);
    opacity: 0.02;
}

.admin-signin__orb {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(124, 58, 237, 0.015);
    border: 1px solid rgba(124, 58, 237, 0.02);
    animation: floatOrb 8s ease-in-out infinite;
}

.admin-signin__orb--1 {
    width: 120px;
    height: 120px;
    top: 15%;
    right: 25%;
    animation-delay: 0s;
}

.admin-signin__orb--2 {
    width: 80px;
    height: 80px;
    bottom: 25%;
    left: 15%;
    animation-delay: 2.5s;
}

.admin-signin__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.15;
    pointer-events: none;
}

.admin-signin__grid svg {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* ----- Particles ----- */
#admin-signin .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.02);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#admin-signin .particle--1 {
    width: 10px;
    height: 10px;
    top: 10%;
    left: 8%;
    animation-delay: 0s;
}

#admin-signin .particle--2 {
    width: 14px;
    height: 14px;
    top: 80%;
    left: 85%;
    animation-delay: 1.2s;
}

#admin-signin .particle--3 {
    width: 7px;
    height: 7px;
    top: 20%;
    left: 80%;
    animation-delay: 2.4s;
}

#admin-signin .particle--4 {
    width: 11px;
    height: 11px;
    top: 85%;
    left: 10%;
    animation-delay: 0.6s;
}

#admin-signin .particle--5 {
    width: 8px;
    height: 8px;
    top: 45%;
    left: 4%;
    animation-delay: 3s;
}

#admin-signin .particle--6 {
    width: 10px;
    height: 10px;
    top: 55%;
    left: 90%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.admin-signin__container {
    position: relative;
    z-index: 2;
    display: grid;
    grid-template-columns: 45% 55%;
    gap: 40px;
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 24px;
    width: 100%;
    align-items: stretch;
}

/* ============================================================
   LEFT PANEL — Brand Experience
   ============================================================ */
.admin-signin__brand {
    display: flex;
    align-items: center;
    padding: 40px 32px;
    background: rgba(255, 255, 255, 0.25);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 28px;
    box-shadow: var(--shadow-glass);
    position: relative;
    overflow: hidden;
}

.admin-signin__brand::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(145deg, rgba(122, 77, 255, 0.02), rgba(110, 220, 95, 0.015));
    border-radius: 28px;
    pointer-events: none;
}

.admin-signin__brand-inner {
    position: relative;
    z-index: 1;
    width: 100%;
}

/* Badge */
.admin-signin__badge {
    display: inline-block;
    padding: 4px 16px;
    background: rgba(122, 77, 255, 0.08);
    border: 1px solid rgba(122, 77, 255, 0.12);
    border-radius: 50px;
    font-size: 0.65rem;
    font-weight: 600;
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin-bottom: 20px;
}

.admin-signin__badge::before {
    content: '◆';
    margin-right: 6px;
    font-size: 0.45rem;
    color: var(--color-lime);
}

/* Brand Title */
.admin-signin__brand-title {
    font-size: 2.2rem;
    font-weight: 700;
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.15;
    margin-bottom: 16px;
}

.admin-signin__brand-title .highlight-text {
    color: var(--color-purple);
    position: relative;
    display: inline-block;
}

.admin-signin__brand-title .highlight-text::after {
    content: '';
    position: absolute;
    bottom: 2px;
    left: 0;
    right: 0;
    height: 4px;
    background: var(--color-lime);
    border-radius: 2px;
    opacity: 0.3;
}

.admin-signin__brand-subtitle {
    font-size: 0.95rem;
    color: var(--color-gray-mid);
    line-height: 1.7;
    margin-bottom: 28px;
}

/* Feature Cards */
.admin-signin__features {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-bottom: 28px;
}

.admin-signin__feature {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    background: rgba(255, 255, 255, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    transition: all 0.3s ease;
    cursor: default;
}

.admin-signin__feature:hover {
    background: rgba(255, 255, 255, 0.6);
    border-color: rgba(122, 77, 255, 0.08);
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.02);
}

.admin-signin__feature-icon {
    font-size: 0.9rem;
    color: var(--color-purple);
    width: 24px;
    text-align: center;
    flex-shrink: 0;
}

.admin-signin__feature-label {
    font-size: 0.78rem;
    font-weight: 500;
    color: var(--color-charcoal);
}

/* Quote */
.admin-signin__quote {
    font-size: 0.9rem;
    font-weight: 400;
    color: var(--color-gray-mid);
    font-style: italic;
    padding: 16px 20px;
    background: rgba(255, 255, 255, 0.15);
    border-left: 3px solid var(--color-lime);
    border-radius: 8px;
    margin-bottom: 24px;
    position: relative;
}

.admin-signin__quote-icon {
    font-size: 1.6rem;
    color: var(--color-purple);
    opacity: 0.15;
    position: absolute;
    top: -4px;
    left: 8px;
    font-family: Georgia, serif;
    line-height: 1;
}

/* Abstract Dashboard Illustration */
.admin-signin__illustration {
    margin-top: 8px;
}

.admin-signin__dashboard {
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 16px;
    padding: 12px 14px;
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
}

.admin-signin__dashboard-header {
    display: flex;
    align-items: center;
    gap: 6px;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.admin-signin__dashboard-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.04);
}

.admin-signin__dashboard-dot:nth-child(1) { background: rgba(239, 68, 68, 0.2); }
.admin-signin__dashboard-dot:nth-child(2) { background: rgba(245, 158, 11, 0.2); }
.admin-signin__dashboard-dot:nth-child(3) { background: rgba(34, 197, 94, 0.2); }

.admin-signin__dashboard-url {
    font-size: 0.55rem;
    font-weight: 500;
    color: rgba(255, 255, 255, 0.15);
    font-family: 'Inter', monospace;
    margin-left: 8px;
    letter-spacing: 0.02em;
}

.admin-signin__dashboard-body {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 8px;
    padding-top: 10px;
}

.admin-signin__dashboard-stat {
    background: rgba(255, 255, 255, 0.02);
    border-radius: 8px;
    padding: 8px 10px;
}

.admin-signin__dashboard-stat-label {
    display: block;
    font-size: 0.5rem;
    font-weight: 500;
    color: rgba(255, 255, 255, 0.2);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.admin-signin__dashboard-stat-value {
    display: block;
    font-size: 0.9rem;
    font-weight: 700;
    color: rgba(255, 255, 255, 0.4);
    letter-spacing: -0.02em;
}

.admin-signin__dashboard-stat-change {
    font-size: 0.5rem;
    font-weight: 600;
    color: var(--color-lime);
    opacity: 0.5;
}

.admin-signin__dashboard-chart {
    grid-column: 1 / -1;
    display: flex;
    align-items: flex-end;
    gap: 4px;
    height: 40px;
    padding-top: 4px;
}

.admin-signin__dashboard-chart-bar {
    flex: 1;
    background: rgba(255, 255, 255, 0.03);
    border-radius: 2px 2px 0 0;
    min-height: 4px;
    transition: height 0.6s ease;
}

.admin-signin__dashboard-chart-bar:nth-child(1) { background: rgba(122, 77, 255, 0.15); }
.admin-signin__dashboard-chart-bar:nth-child(2) { background: rgba(122, 77, 255, 0.20); }
.admin-signin__dashboard-chart-bar:nth-child(3) { background: rgba(122, 77, 255, 0.12); }
.admin-signin__dashboard-chart-bar:nth-child(4) { background: rgba(110, 220, 95, 0.20); }
.admin-signin__dashboard-chart-bar:nth-child(5) { background: rgba(122, 77, 255, 0.15); }
.admin-signin__dashboard-chart-bar:nth-child(6) { background: rgba(110, 220, 95, 0.25); }
.admin-signin__dashboard-chart-bar:nth-child(7) { background: rgba(122, 77, 255, 0.18); }

.admin-signin__dashboard:hover .admin-signin__dashboard-chart-bar {
    animation: chartBounce 1s ease forwards;
}

.admin-signin__dashboard-chart-bar:nth-child(1) { animation-delay: 0.05s; }
.admin-signin__dashboard-chart-bar:nth-child(2) { animation-delay: 0.10s; }
.admin-signin__dashboard-chart-bar:nth-child(3) { animation-delay: 0.15s; }
.admin-signin__dashboard-chart-bar:nth-child(4) { animation-delay: 0.20s; }
.admin-signin__dashboard-chart-bar:nth-child(5) { animation-delay: 0.25s; }
.admin-signin__dashboard-chart-bar:nth-child(6) { animation-delay: 0.30s; }
.admin-signin__dashboard-chart-bar:nth-child(7) { animation-delay: 0.35s; }

@keyframes chartBounce {
    0% { transform: scaleY(0); transform-origin: bottom; }
    60% { transform: scaleY(1.05); transform-origin: bottom; }
    100% { transform: scaleY(1); transform-origin: bottom; }
}

/* ============================================================
   RIGHT PANEL — Login Form
   ============================================================ */
.admin-signin__form-wrapper {
    display: flex;
    align-items: center;
}

.admin-signin__form-card {
    width: 100%;
    padding: 40px 44px;
    background: rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 28px;
    box-shadow: var(--shadow-glass);
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.admin-signin__form-card:hover {
    box-shadow: 0 16px 48px rgba(122, 77, 255, 0.06);
}

.admin-signin__form-badge {
    display: inline-block;
    padding: 3px 14px;
    background: rgba(122, 77, 255, 0.08);
    border: 1px solid rgba(122, 77, 255, 0.12);
    border-radius: 50px;
    font-size: 0.6rem;
    font-weight: 600;
    color: var(--color-purple);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin-bottom: 16px;
}

.admin-signin__form-badge::before {
    content: '◆';
    margin-right: 6px;
    font-size: 0.4rem;
    color: var(--color-lime);
}

.admin-signin__form-title {
    font-size: 1.6rem;
    font-weight: 700;
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    margin-bottom: 4px;
}

.admin-signin__form-desc {
    font-size: 0.9rem;
    color: var(--color-gray-mid);
    margin-bottom: 28px;
}

/* ----- Form Fields (Floating Labels) ----- */
.admin-signin__form {
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.admin-signin__form-group {
    position: relative;
    display: flex;
    flex-direction: column;
}

.admin-signin__form-group--floating {
    position: relative;
}

.admin-signin__form-input {
    width: 100%;
    padding: 16px 14px 8px;
    background: rgba(255, 255, 255, 0.3);
    border: 1.5px solid var(--color-gray-light);
    border-radius: 12px;
    font-family: var(--font-family);
    font-size: 0.95rem;
    color: var(--color-charcoal);
    outline: none;
    transition: all 0.3s ease;
    height: 56px;
}

.admin-signin__form-input:focus {
    border-color: var(--color-purple);
    box-shadow: 0 0 0 4px rgba(122, 77, 255, 0.06);
    background: rgba(255, 255, 255, 0.5);
}

.admin-signin__form-input:focus + .admin-signin__form-label,
.admin-signin__form-input:not(:placeholder-shown) + .admin-signin__form-label {
    transform: translateY(-8px) scale(0.85);
    color: var(--color-purple);
}

.admin-signin__form-label {
    position: absolute;
    left: 14px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.9rem;
    color: var(--color-gray-mid);
    pointer-events: none;
    transition: all 0.25s ease;
    font-weight: 400;
    background: transparent;
    padding: 0 2px;
    transform-origin: left center;
}

.admin-signin__form-input:focus + .admin-signin__form-label,
.admin-signin__form-input:not(:placeholder-shown) + .admin-signin__form-label {
    top: 14px;
    transform: translateY(0) scale(0.75);
    color: var(--color-purple);
}

/* Password Toggle */
.admin-signin__toggle-password {
    position: absolute;
    right: 14px;
    top: 50%;
    transform: translateY(-50%);
    background: none;
    border: none;
    color: var(--color-gray-mid);
    cursor: pointer;
    padding: 4px;
    font-size: 0.9rem;
    transition: color 0.3s ease;
    z-index: 2;
}

.admin-signin__toggle-password:hover {
    color: var(--color-charcoal);
}

/* Error Messages */
.admin-signin__form-error {
    font-size: 0.7rem;
    color: var(--color-error);
    min-height: 18px;
    display: block;
    margin-top: 2px;
}

/* ----- Options Row ----- */
.admin-signin__options {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: -4px 0 2px;
}

.admin-signin__remember {
    display: flex;
    align-items: center;
    gap: 8px;
}

.admin-signin__form-checkbox {
    width: 16px;
    height: 16px;
    accent-color: var(--color-purple);
    cursor: pointer;
    flex-shrink: 0;
}

.admin-signin__form-checkbox-label {
    font-size: 0.85rem;
    color: var(--color-gray-mid);
    cursor: pointer;
}

.admin-signin__forgot-link {
    font-size: 0.85rem;
    color: var(--color-purple);
    text-decoration: none;
    font-weight: 500;
    transition: color 0.3s ease;
}

.admin-signin__forgot-link:hover {
    text-decoration: underline;
    color: var(--color-purple-dark);
}

/* ----- Submit Button ----- */
.admin-signin__submit {
    width: 100%;
    padding: 14px 24px;
    background: linear-gradient(135deg, var(--color-lime), var(--color-lime-dark));
    color: var(--color-charcoal);
    border: none;
    border-radius: 12px;
    font-size: 1rem;
    font-weight: 600;
    font-family: var(--font-family);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: 0 4px 24px rgba(110, 220, 95, 0.3);
    position: relative;
    overflow: hidden;
    margin-top: 4px;
}

.admin-signin__submit:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(110, 220, 95, 0.4);
}

.admin-signin__submit:active {
    transform: scale(0.98);
}

.admin-signin__submit i {
    transition: transform 0.3s ease;
}

.admin-signin__submit:hover i {
    transform: translateX(4px);
}

.admin-signin__submit:disabled {
    opacity: 0.7;
    cursor: not-allowed;
    transform: none !important;
}

/* Button Ripple */
.admin-signin__submit .ripple {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.3);
    transform: scale(0);
    animation: rippleAnim 0.6s linear;
    pointer-events: none;
}

@keyframes rippleAnim {
    to { transform: scale(4); opacity: 0; }
}

/* ----- Divider ----- */
.admin-signin__divider {
    display: flex;
    align-items: center;
    gap: 16px;
    margin: 4px 0 2px;
}

.admin-signin__divider-line {
    flex: 1;
    height: 1px;
    background: var(--color-gray-light);
    opacity: 0.3;
}

.admin-signin__divider-text {
    font-size: 0.75rem;
    color: var(--color-gray-mid);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    font-weight: 500;
}

/* ----- Social Login (disabled) ----- */
.admin-signin__social {
    width: 100%;
    padding: 12px 24px;
    background: rgba(255, 255, 255, 0.2);
    border: 1.5px solid var(--color-gray-light);
    border-radius: 12px;
    font-size: 0.9rem;
    font-weight: 500;
    font-family: var(--font-family);
    color: var(--color-gray-mid);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    cursor: not-allowed;
    opacity: 0.5;
    transition: all 0.3s ease;
    position: relative;
}

.admin-signin__social i {
    font-size: 1.1rem;
    color: var(--color-gray-mid);
}

.admin-signin__social-badge {
    font-size: 0.55rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-white);
    background: var(--color-purple);
    padding: 1px 10px;
    border-radius: 50px;
    margin-left: 4px;
    opacity: 0.6;
}

.admin-signin__social[disabled] {
    cursor: not-allowed;
}

/* ----- Sign Up Link ----- */
.admin-signin__signup-link {
    text-align: center;
    font-size: 0.85rem;
    color: var(--color-gray-mid);
    margin-top: 4px;
}

.admin-signin__signup-link a {
    color: var(--color-purple);
    text-decoration: none;
    font-weight: 500;
}

.admin-signin__signup-link a:hover {
    text-decoration: underline;
}

/* ----- Future Placeholders ----- */
.admin-signin__future {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 6px;
    padding-top: 12px;
    border-top: 1px solid rgba(0, 0, 0, 0.02);
}

.admin-signin__future-item {
    font-size: 0.6rem;
    color: var(--color-gray-light);
    background: rgba(0, 0, 0, 0.01);
    padding: 2px 10px;
    border-radius: 50px;
    border: 1px solid rgba(0, 0, 0, 0.02);
    letter-spacing: 0.02em;
}

.admin-signin__future-item::before {
    content: '⚡';
    margin-right: 4px;
    font-size: 0.5rem;
}

/* ----- Focus States ----- */
.admin-signin__submit:focus-visible,
.admin-signin__form-input:focus-visible,
.admin-signin__toggle-password:focus-visible,
.admin-signin__form-checkbox:focus-visible,
.admin-signin__forgot-link:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 3px;
}

