}

.brand-hero__orb--2 {
    width: 70px;
    height: 70px;
    bottom: 25%;
    left: 15%;
    animation-delay: 2s;
}

.brand-hero__shape {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    background: rgba(192, 227, 74, 0.015);
    border: 1px solid rgba(192, 227, 74, 0.015);
}

.brand-hero__shape--1 {
    width: 160px;
    height: 160px;
    top: 10%;
    left: 20%;
    border-radius: 40% 60% 60% 40% / 40% 40% 60% 60%;
}

.brand-hero__shape--2 {
    width: 110px;
    height: 110px;
    bottom: 35%;
    right: 10%;
    border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
}

.brand-hero__grid {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0.15;
    pointer-events: none;
}

.brand-hero__grid svg {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Particles */
#brand-hero .particle {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.03);
    pointer-events: none;
    animation: floatParticle 6s ease-in-out infinite;
}

#brand-hero .particle--1 {
    width: 8px;
    height: 8px;
    top: 10%;
    left: 6%;
    animation-delay: 0s;
}

#brand-hero .particle--2 {
    width: 12px;
    height: 12px;
    top: 78%;
    left: 90%;
    animation-delay: 1.2s;
}

#brand-hero .particle--3 {
    width: 6px;
    height: 6px;
    top: 20%;
    left: 85%;
    animation-delay: 2.4s;
}

#brand-hero .particle--4 {
    width: 10px;
    height: 10px;
    top: 85%;
    left: 10%;
    animation-delay: 0.6s;
}

#brand-hero .particle--5 {
    width: 7px;
    height: 7px;
    top: 40%;
    left: 4%;
    animation-delay: 3s;
}

#brand-hero .particle--6 {
    width: 9px;
    height: 9px;
    top: 50%;
    left: 94%;
    animation-delay: 1.8s;
}

/* ----- Container ----- */
.brand-hero__inner {
    position: relative;
    z-index: 2;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: center;
}

/* ----- Hero Content ----- */
.brand-hero__badge {
    display: inline-flex;
    align-items: center;
    padding: 4px 18px 4px 16px;
    background: rgba(124, 58, 237, 0.08);
    border: 1px solid rgba(124, 58, 237, 0.12);
    border-radius: 50px;
    font-size: 0.7rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-purple);
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin-bottom: 20px;
}

.brand-hero__badge::before {
    content: '◆';
    margin-right: 8px;
    font-size: 0.5rem;
    color: var(--color-lime);
}

.brand-hero__title {
    font-size: 3rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 16px;
}

.brand-hero__title .highlight-text {
    color: var(--color-purple);
    position: relative;
    display: inline-block;
}

.brand-hero__title .highlight-text::after {
    content: '';
    position: absolute;
    bottom: 4px;
    left: 0;
    right: 0;
    height: 4px;
    background: var(--color-lime);
    border-radius: 2px;
    opacity: 0.3;
}

.brand-hero__subtitle {
    font-size: 1.05rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
    line-height: 1.7;
    max-width: 520px;
    margin-bottom: 28px;
}

.brand-hero__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
}

.btn-brand-services {
    padding: 12px 28px;
    font-size: 0.9rem;
    background: var(--color-lime);
    color: var(--color-charcoal);
    box-shadow: 0 4px 24px rgba(192, 227, 74, 0.35);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
    font-weight: var(--font-weight-semibold);
}

.btn-brand-services:hover {
    background: var(--color-lime-dark);
    color: var(--color-charcoal);
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(192, 227, 74, 0.45);
}

.btn-brand-services i:last-child {
    margin-left: 2px;
    transition: transform 0.3s ease;
}

.btn-brand-services:hover i:last-child {
    transform: translateX(4px);
}

.btn-brand-contact {
    padding: 12px 28px;
    font-size: 0.9rem;
    border-color: var(--color-purple);
    color: var(--color-purple);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-weight: var(--font-weight-semibold);
}

.btn-brand-contact:hover {
    background: var(--color-purple);
    color: var(--color-white);
    border-color: var(--color-purple);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(124, 58, 237, 0.2);
}

/* ----- Logo Visual ----- */
.brand-hero__visual {
    display: flex;
    align-items: center;
    justify-content: center;
}

.brand-hero__logo-container {
    position: relative;
    width: 380px;
    height: 380px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.15);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-radius: 50%;
    border: 1px solid rgba(255, 255, 255, 0.05);
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.02);
}

/* Logo */
.brand-hero__logo {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    z-index: 5;
    text-align: center;
    animation: floatLogo 6s ease-in-out infinite;
}

@keyframes floatLogo {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-8px); }
}

.brand-hero__logo-icon {
    font-size: 2.8rem;
    color: var(--color-lime);
    font-weight: 800;
    line-height: 1;
    margin-bottom: 4px;
}

.brand-hero__logo-text {
    font-size: 2.6rem;
    font-weight: 700;
    color: var(--color-charcoal);
    letter-spacing: -0.02em;
    line-height: 1;
}

.brand-hero__logo-solutions {
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--color-gray-mid);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-top: 2px;
}

/* Glow Ring */
.brand-hero__glow-ring {
    position: absolute;
    inset: 0;
    border-radius: 50%;
    border: 1px solid rgba(124, 58, 237, 0.03);
    animation: pulseRing 4s ease-in-out infinite;
}

.brand-hero__glow-ring::before {
    content: '';
    position: absolute;
    inset: 20px;
    border-radius: 50%;
    border: 1px solid rgba(192, 227, 74, 0.02);
    animation: pulseRing 4s ease-in-out infinite 1s;
}

@keyframes pulseRing {
    0%, 100% { transform: scale(1); opacity: 0.3; }
    50% { transform: scale(1.05); opacity: 0.8; }
}

/* Circuits */
.brand-hero__circuit {
    position: absolute;
    display: flex;
    align-items: center;
    gap: 6px;
    opacity: 0.3;
}

.brand-hero__circuit--1 {
    top: 12%;
    right: 8%;
    transform: rotate(25deg);
    animation: circuitPulse 3s ease-in-out infinite;
}

.brand-hero__circuit--2 {
    bottom: 18%;
    left: 6%;
    transform: rotate(-15deg);
    animation: circuitPulse 3s ease-in-out infinite 1s;
}

.brand-hero__circuit--3 {
    top: 45%;
    right: 2%;
    transform: rotate(80deg);
    animation: circuitPulse 3s ease-in-out infinite 2s;
}

@keyframes circuitPulse {
    0%, 100% { opacity: 0.15; }
    50% { opacity: 0.4; }
}

.brand-hero__circuit-line {
    width: 16px;
    height: 1.5px;
    background: linear-gradient(90deg, var(--color-purple), var(--color-lime));
    border-radius: 1px;
}

.brand-hero__circuit-dot {
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--color-purple);
    flex-shrink: 0;
}

.brand-hero__circuit-dot:nth-child(2) { background: var(--color-lime); }

/* Connection Nodes */
.brand-hero__node {
    position: absolute;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.04);
    border: 1px solid rgba(124, 58, 237, 0.04);
    animation: nodeFloat 5s ease-in-out infinite;
}

.brand-hero__node--1 {
    width: 12px;
    height: 12px;
    top: 5%;
    left: 10%;
    animation-delay: 0s;
}
.brand-hero__node--2 {
    width: 8px;
    height: 8px;
    top: 8%;
    right: 20%;
    animation-delay: 1.2s;
}
.brand-hero__node--3 {
    width: 10px;
    height: 10px;
    bottom: 8%;
    left: 15%;
    animation-delay: 2.4s;
}
.brand-hero__node--4 {
    width: 14px;
    height: 14px;
    bottom: 12%;
    right: 12%;
    animation-delay: 0.6s;
}
.brand-hero__node--5 {
    width: 6px;
    height: 6px;
    top: 40%;
    left: 4%;
    animation-delay: 3s;
}
.brand-hero__node--6 {
    width: 8px;
    height: 8px;
    top: 55%;
    right: 4%;
    animation-delay: 1.8s;
}

@keyframes nodeFloat {
    0%, 100% { transform: translate(0, 0) scale(1); opacity: 0.2; }
    50% { transform: translate(6px, -8px) scale(1.3); opacity: 0.6; }
}

/* ----- Focus States ----- */
.btn-brand-services:focus-visible,
.btn-brand-contact:focus-visible {
    outline: 3px solid var(--color-lime);
    outline-offset: 4px;
}

