}

.brand-story__quote-card {
    position: relative;
    padding: 40px 36px;
    background: rgba(255, 255, 255, 0.3);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 24px;
    box-shadow: var(--shadow-glass);
    width: 100%;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.brand-story__quote-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(124, 58, 237, 0.06);
}

.brand-story__quote-icon {
    font-size: 4rem;
    font-family: Georgia, serif;
    color: var(--color-purple);
    opacity: 0.08;
    position: absolute;
    top: 8px;
    left: 20px;
    line-height: 1;
}

.brand-story__quote-text {
    font-size: 1.3rem;
    font-weight: 500;
    color: var(--color-charcoal);
    line-height: 1.5;
    letter-spacing: -0.01em;
    margin-bottom: 24px;
    position: relative;
    z-index: 1;
    padding-top: 4px;
}

.brand-story__quote-author {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.brand-story__quote-name {
    font-size: 0.95rem;
    font-weight: var(--font-weight-semibold);
    color: var(--color-charcoal);
}

.brand-story__quote-title {
    font-size: 0.8rem;
    font-weight: var(--font-weight-regular);
    color: var(--color-gray-mid);
}

.brand-story__quote-decoration {
    position: absolute;
    bottom: 0;
    right: 0;
    width: 80px;
    height: 80px;
    border-radius: 50% 0 24px 0;
    background: linear-gradient(135deg, rgba(124, 58, 237, 0.02), rgba(192, 227, 74, 0.02));
    pointer-events: none;
